-- WoW Forever: French (frFR) quest titles, objectives, story, progress and reward text as live shows them.
-- Source: Wowhead's WoW Forever database (www.wowhead.com/forever), French pages. Changed: compared with our world; only
-- rows we lacked or that differ from live are written, and only the fields that differ. Left out: text that is the same
-- as our English (the client already falls back to it), empty fields, and quest 1 (a developer test quest).
-- Fills or updates the frFR rows of quest_template_locale, quest_request_items_locale and quest_offer_reward_locale; other
-- locales and fields are not touched. Safe to run more than once.

-- quest_template_locale: 1232 quests
ON DUPLICATE KEY UPDATE `LogDescription`=VALUES(`LogDescription`);
ON DUPLICATE KEY UPDATE `LogDescription`=VALUES(`LogDescription`), `LogTitle`=VALUES(`LogTitle`), `QuestDescription`=VALUES(`QuestDescription`);
ON DUPLICATE KEY UPDATE `LogDescription`=VALUES(`LogDescription`), `QuestDescription`=VALUES(`QuestDescription`);
ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`), `QuestDescription`=VALUES(`QuestDescription`);
ON DUPLICATE KEY UPDATE `QuestDescription`=VALUES(`QuestDescription`);
ON DUPLICATE KEY UPDATE `QuestDescription`=VALUES(`QuestDescription`);
ON DUPLICATE KEY UPDATE `QuestDescription`=VALUES(`QuestDescription`);
ON DUPLICATE KEY UPDATE `QuestDescription`=VALUES(`QuestDescription`);

-- quest_request_items_locale: 265 quests
ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);

-- quest_offer_reward_locale: 814 quests
ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
