INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`) VALUES
(172,'frFR','Utiliser le sifflet d''orphelin orc pour parler à l''enfant que vous protégez durant la Semaine des enfants.'),
(243,'frFR','Parler à l''Ingénieur en chef Bilgewhizzle à Gadgetzan afin d''obtenir une source d''énergie pour la trousse d''analyse.'),
(337,'frFR','Rendre le livre « l''Histoire de Stormwind » à la Bibliothèque de Stormwind.'),
(340,'frFR','Rapporter les pages 10, 11, 14 et 16 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Stonepot pour achever le Chapitre II.'),
(341,'frFR','Rapporter les pages 18, 20, 21 et 24 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Stonepot pour achever le Chapitre III.'),
(342,'frFR','Rapporter les pages 25, 26 et 27 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Stonepot pour achever le Chapitre IV.'),
(474,'frFR','Tuer le Chef Nek''rosh$B$BRapporter la tête de Nek''rosh au capitaine Stoutfist.'),
(592,'frFR','Apporter la Gemme d''âme remplie à Nimboya.'),
(635,'frFR','Trouver le cristal de votre vision.'),
(651,'frFR','Collecter la Clé ardente, la Clé armoriée et la Clé de tonnerre aux lieux suivants : la Pierre de lien occidentale, la Pierre de lien orientale et la Pierre de lien extérieure.$B$BLes apporter à la Pierre de lien intérieure.'),
(656,'frFR','Aller aux Eclats de Myzrael, l''invoquer et la battre.$B$BPrendre ses Chaînes indicibles et les attacher aux Eclats de Myzrael.'),
(735,'frFR','Rapporter les Objets écrits sur le mot de Bonegrip à Gerrig Bonegrip dans Ironforge.'),
(739,'frFR','Tuer l''assassin d''Agmond : Murdaloc.$B$BTuer 12 Briseurs d’os Cavepierre.$B$BEt revenir voir le Prospecteur Ironband au Loch Modan.'),
(770,'frFR','Trouver quelqu''un qui puisse vous en apprendre davantage au sujet du Hurleur fantomatique.'),
(772,'frFR','Consommer l''Eau des Prophètes devant le feu tribal, au village Bloodhoof et suivre la vision quand elle apparaîtra.'),
(877,'frFR','Retourner voir Tonga Runetotem à la Croisée, après avoir enquêté à l''Oasis stagnante.'),
(881,'frFR','Apporter la Peau d''Echeyakee à Sergra Darkthorn à la Croisée.'),
(894,'frFR','Accéder à la Console de contrôle au Centre de recherches de la KapitalRisk.'),
(921,'frFR','Remplir la Fiole de cristal et la rapporter à Tenaron Stormgrip au sommet d''Aldrassil.'),
(929,'frFR','Remplir la Fiole de jade et la rapporter à Corithras Moonrage à Dolanaar.'),
(933,'frFR','Remplir la Fiole de tourmaline et la rapporter à Corithras Moonrage à Dolanaar.'),
(934,'frFR','Remplir la Fiole d''améthyste et la rapporter à Corithras Moonrage à Dolanaar.'),
(940,'frFR','Remettre le rapport de l''arbre-oracle à l''archidruide Fandral Staghelm à Darnassus.'),
(944,'frFR','Trouver des informations, puis utiliser la Fiole de divination pour créer une Coupe de divination. Utiliser la coupe pour parler à Onu.'),
(957,'frFR','Détruire l''Ancien sceau de pierre de lune à la flamme antique qui se trouve dans Ameth''Aran, puis retourner voir Asterion à Bashal''Aran.'),
(971,'frFR','Apporter le « Manuscrit de Lorgalis » à Gerrig Bonegrip à Ironforge.'),
(992,'frFR','Utiliser la Fiole de sourcier vide à la mare près du Guet de Tristesable. Une fois l''échantillon récolté, remettre la Fiole de sourcier pleine au grand géomètre Fizzledowser à Gadgetzan.'),
(1016,'frFR','Récolter 5 Bracelets élémentaires intacts et utiliser le Parchemin de divination sur eux. Ensuite, apporter le Parchemin de divination à la Sentinelle Velene Starstrike au Refuge de Vent-argent.'),
(1023,'frFR','Trouver la Gemme luminescente et retourner voir Raene Wolfrunner dans Astranaar avec le Journal de Teronis.'),
(1030,'frFR','Trouver un furbolg non corrompu et lui parler en utilisant le pouvoir du Bâtonnet de transformation de Dartol.'),
(1057,'frFR','Le Gardien Albagorm du pic des Serres-Rocheuses veut que vous tuiez 7 Harpies, 7 Embusqués, 7 Tueuses et 7 Volplumes Rougefuries.'),
(1080,'frFR','Récupérer les Notes de la KapitalRisk dans la mine des Cisailles à l''extrémité est de la Combe des Cisailles.'),
(1086,'frFR','Apporter le Brouillard toxique à l''aéroport de la KapitalRisk, puis retourner voir l''Apothicaire Zamah.'),
(1197,'frFR','Retrouver le Sabot fendu pour Rau Cliffrunner du Poste de Librevent.'),
(1222,'frFR','Escorter Ignatz "Puant" puis discuter avec Morgan Stern à Theramore.'),
(1468,'frFR','Utilisez le Sifflet d''orphelin humain pour parler à l''enfant que vous protégerez pendant la Semaine des enfants.'),
(1517,'frFR','Trouver le Rocher des esprits et boire le Sapta de terre.'),
(1520,'frFR','Trouver le Rocher des kodos et boire le Sapta de terre.'),
(1534,'frFR','Remplir l''Outre bleue vide aux Ruines de Chimétoile à Ashenvale et la rapporter à Brine dans les Tarides.'),
(1535,'frFR','Remplir l''Outre marron vide au trou d’eau, derrière la hutte de Brine, puis rapportez-lui la, dans les Tarides.'),
(1536,'frFR','Remplir l''Outre rouge vide au puits de Moulin-de-Tarren et retourner voir Brine dans les Tarides.'),
(1654,'frFR','Utiliser les Notes sur les armes de Jordan, trouver du Bois de chêne de blanchepierre, la Cargaison de Minerai raffiné de Bailor, le Marteau de forge de Jordan et une Gemme de Kor, puis revenir voir Jordan Stilwell à Ironforge.'),
(1838,'frFR','Apporter à Thun''grim Firegaze 15 Lingots de Fer cendré, 10 Azurites en poudre, 10 Barres de Fer et une Fiole de Phlogiston.'),
(1861,'frFR','Apporter un Echantillon d''Eau du lac Miroir à Jennea Cannon à Stormwind.'),
(1948,'frFR','Apporter un Jade et le Roncier de foudre à Tabetha, dans le marécage d''Âprefange.'),
(2118,'frFR','Capturer vivant un Ours des chardons enragé, puis le ramener à Tharnariun.'),
(2200,'frFR','Chercher des indices sur le Collier de Talvash à Uldaman. Le paladin dont il a parlé est la dernière personne à l''avoir porté.'),
(2282,'frFR','Ouvrir le Coffret de Lucius, récupérer le Gage de voleur et le rapporter à Lucius à Lakeshire.'),
(2318,'frFR','Trouver quelqu''un qui puisse traduire le journal du paladin. L''endroit le plus proche est Kargath, dans les Terres ingrates.'),
(2339,'frFR','Récupérer, dans Uldaman, les trois gemmes et une source d’énergie pour le collier, puis les rapporter à Jarkal Mossmeld, à Kargath. Jarkal pense que vous pouvez trouver une source d’énergie sur la machine la plus puissante d’Uldaman.$B$BC''est dans le journal, vous savez...$B* Le rubis a été caché dans une zone barricadée des Ombreforge.$B* La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de Alliance.$B* Le saphir est possession du chef trogg, Grimlok.'),
(2458,'frFR','Aller à la tour de la KapitalRisk, au nord de la Videfange, et contacter l''agent secret de la Main brisée, le sous-chef Fizzule.$B$BUne fois la tour en vue, utiliser le lance-fusées pour se signaler au sous-chef Fizzule. Tirer DEUX fusées, puis s''approcher du sous-chef Fizzule et faire le Salut brisé (/salut).$B$BRespecter l''ordre de ces actions, car Fizzule attaque et tue toute personne qu''il ne peut pas identifier.'),
(2501,'frFR','Utiliser les Récipients thaumaturgiques vides sur des dragons gardiens des terres brûlées dans les Terres ingrates. Une fois remplis, les rapporter à Ghak Healtouch à Thelsamar.'),
(2520,'frFR','Sur ordre de la prêtresse A''moora, placer les Filières d''argent de dame Sathrah dans la fontaine du Temple, puis retourner la voir.'),
(2561,'frFR','Sur ordre d''Oben Grifferage, tuer son Corps privé d''âme et utiliser ensuite le Charme vaudou.'),
(2879,'frFR','Dynamiser le Bâton de Troyas et trouver le Monolithe d''Equinex.'),
(2926,'frFR','Utiliser la Fiole de collecte plombée vide sur les Envahisseurs ou les Pilleurs irradiés pour recueillir des retombées radioactives. Une fois pleine, rapportez-la à Ozzie Togglevolt à Kharanos.'),
(2932,'frFR','Collecter les Crânes de Witherbark, et les mettre en place sur la Pique de Nimboyae. Placer la Pique de Nimboya préparée dans l’un des Villages Witherbark, dans les Hinterlands, puis retourner voir Nimboya, à Strangleronce.'),
(2937,'frFR','Terrasser Shadra, à l''autel de Shadra''Alor, puis rapporter son venin à l''Apothicaire Lydon, au Moulin-de-Tarren.'),
(2969,'frFR','A l’aide de la Clé de la cage en bambou, libérer les Fées fléchetteuses de l’enclos dans le Camp du Totem sinistre. Au moins 6 Fées fléchetteuses et Kindal Moonweaver doivent survivre.$B$BVous avez 6 minutes avant que Kindal décide qu’il est temps de battre en retraite et que vous échouiez dans votre quête.'),
(3441,'frFR','Écouter le récit de Velarok Lamevent.'),
(3442,'frFR','Réunir 4 Cœurs des flammes et 4 globes d’Huile de golem puis rapporter ces objets à Velarok Lamevent.'),
(3449,'frFR','À l''aide de la Trousse de dessin, effectuer des reproductions de la Rune de Beth''Amara, de la Rune de Jin''yael, de la Rune de Markri, de la Rune de Sael''hai, puis se diriger vers la petite île près de la Péninsule méridionale d''Azshara et signaler au Pilote Xiggs Fuselighter de venir les prendre.'),
(3452,'frFR','Trouver et apporter un Symbole de Ragnaros à Velarok Lamevent.'),
(3463,'frFR','Mettre le feu aux Tours de garde nord, sud, est, et ouest en utilisant la Torche de vindicte à l''intérieur de chaque tour.'),
(3514,'frFR','Tuer le chef de l''Antre des Serres, Rynthariel le Maître des clés.'),
(3528,'frFR','Apporter l''Oeuf Rempli d''Hakkar à Yeh''kinya dans Tanaris.'),
(3568,'frFR','Avant de retourner voir le Chimiste Cuely, remplir les 4 Fioles vides aux étangs des marées, le long de la côte des Ruines d''Eldarath, à Azshara.'),
(3602,'frFR','Trouver 20 Azsharites cristallisées au sud d''Azshara. Utiliser éventuellement le gangrechien pour ‘renifler’ l''emplacement où sont intelligemment cachés les dépôts.$B$BRetourner voir Loramus une fois votre tâche accomplie.'),
(3638,'frFR','Pour devenir un Ingénieur gobelin, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore Nixx Sprocketspring dans Gadgetzan.'),
(3640,'frFR','Pour devenir un Ingénieur gnome, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore le maître-artisan Overspark, à Ironforge.'),
(3642,'frFR','Pour devenir un Ingénieur gnome, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore Oglethrope Obnoticus à Baie-du-Butin.'),
(3785,'frFR','Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendis et deux Echantillons d''Humus d''Un''Goro pour essayer de cultiver des Fibres d''aurore.$B$BApporter 10 Fibres d''aurore à Mathrengyl Bearwalker à Darnassus.'),
(3786,'frFR','Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendis et deux Echantillons d''Humus d''Un''Goro pour essayer de cultiver des Fibres d''aurore.$B$BApporter 10 Fibres d''aurore à Bashana Runetotem à Thunder Bluff.'),
(3791,'frFR','Apporter 10 Fibres d''aurore à Quintis Jonespyre au bastion de Feathermoon.'),
(3825,'frFR','Prendre la Tête coupée de Gor''tesh et la placer au sommet du Rocher des Cognepeurs. Chercher un monticule de terre meuble pour planter la pique.'),
(3845,'frFR','Examiner les objets du paquet et les apporter à leur propriétaire.'),
(3883,'frFR','Utiliser la Fiole de raclement pour récolter un Echantillon de paroi de la ruche dans une des nurseries de la ruche Gorishi, à l’intérieur du cratère d''Un''Goro. Chercher les chambres qui contiennent des larves suspendues.$B$BApporter l’Echantillon de paroi de la ruche à Hol''anyee Marshal dans le cratère d''Un''Goro.'),
(3912,'frFR','Se rendre au cimetière au-dehors de Gadgetzan et boire l''élixir de Videre. Suivre le reste des instructions de Donova pour trouver Gaeriyan.'),
(4005,'frFR','Apporter le Livre d''Aquor, les Griffes argentées et le Coeur d''Arbrefer à Tanaris.$B$BUtiliser le Livre d''Aquor pour invoquer Aquementas.$B$BAprès avoir terminé le totem, l’apporter à J.D. Collie au refuge des Marshal.'),
(4022,'frFR','Montrer à Cyrus Therepentous le Cuir de dragon noir que vous avez reçu de Velarok Lamevent.'),
(4024,'frFR','Partir pour les Profondeurs de Blackrock et tuer Bael''Gar.$B$BVous savez seulement que le géant demeure à l''intérieur des Profondeurs de Blackrock. Se souvenir d''utiliser l''Ecaille des dragons noirs altérée pour capturer l''Essence ardente.$B$BApporter l''Essence ardente recouverte à Cyrus Therepentous.'),
(4122,'frFR','Partez pour les Steppes ardentes et trouvez Grark Lorkrub. Lexlort a mentionné le fait que la dernière fois où on l''a vu, il se trouvait dans une imposante forteresse des Blackrock.$B$BUne fois Grark Lorkrub découvert, l''enchaîner avec les chaînes en thorium, puis le ramener par le mont Blackrock jusque dans la gorge des Vents brûlants. Des hommes de Lexlort attendront de l''autre côté de la gorge et le mettront sous bonne garde.'),
(4132,'frFR','Voyagez jusqu''aux Profondeurs de Blackrock et tuez le général Forgehargne ! Une fois votre mission accomplie, retournez voir le seigneur de guerre Goretooth.'),
(4135,'frFR','À présent que la dernière destination connue de Raschal est découverte, continuez à le rechercher, lui ou ses restes, dans le Gouffre grouillant. D''après le message, il se trouve au sud des camps des gnolls Griffebois.'),
(4201,'frFR','Apporter 4 Gromsang, 10 Veines d''argent de géant et la Fiole de Nagmara remplie à la gouvernante Nagmara dans les Profondeurs de Blackrock.'),
(4292,'frFR','En utilisant le contenu de la Sacoche de Torwa, appeler Lar''korwi et le vaincre. Puis apporter la Tête de Lar''korwi à Torwa Pathfinder près de l''entrée du Cratère d''Un''Goro.'),
(4299,'frFR','[Place the PX83-Enigmatron in the Tomb of the Seven, then return to Maxwort Uberglint.]'),
(4441,'frFR','Aller à Darnassus et utiliser la Fiole d''Eridan dans le Temple de la Lune, pour obtenir une Fiole d''eau bénite. Retourner voir Eridan avec la Fiole pleine.'),
(4491,'frFR','Conduire Ringo à Spraggle Frock, au refuge des Marshal.$B$BSi Ringo s’évanouit, utiliser la Gourde de Spraggle pour le réanimer.'),
(4505,'frFR','Collecter un échantillon d’eau corrompue dans le Puits de lune des satyres Jadefeu, puis le rapporter à Winna Hazzard, au Poste de la Vénéneuse.'),
(4506,'frFR','Amener le chaton de Winna au Puits de lune corrompu, le relâcher, puis le rapporter à Winna.$B$BUne fois de retour auprès de Winna, cliquer sur le chat pour le lui rendre.'),
(4507,'frFR','Invoquer la Reine gorishi et la vaincre.$B$BApporter le Cerveau de reine gorishi à l’alchimiste Pestlezugg, à Gadgetzan.'),
(4512,'frFR','Apporter 6 Pots de Limons maudits remplis et 6 Pots de Limons corrompus remplis à Laris Geardawdle, à Ironforge.'),
(4513,'frFR','Apporter 10 Pots remplis d''échantillon pur à Laris Geardawdle, à Ironforge.$B$BSi vous éprouvez des difficultés à les trouver, allez voir Laris pour obtenir plus d’indices.'),
(4642,'frFR','Apporter un Echantillon de Limon mélangé au chimiste Fuely à Undercity.'),
(4729,'frFR','Aller au Pic Blackrock et trouver de Jeunes worgs Bloodaxe. Utiliser la cage pour transporter ces petites bêtes féroces. Rapporter un Jeune worg en cage à Kibler.'),
(4743,'frFR','Allez à la tourbière du Ver dans le marécage d''Âprefange. Trouvez l''ancien drake, Brandeguerre, et frappez-le sans merci jusqu''à ce que sa volonté soit brisée.$B$BA cet instant précis, vous devez placer le Sceau d''ascension brut devant l''énorme bête. Vous devez ensuite utiliser rapidement l''Orbe d''énergie draconique sur sa forme affaiblie et prendre possession de ses facultés mentales. Contrôlez la bête et dirigez les flammes du Vol noir sur le Sceau d''ascension brut !'),
(4762,'frFR','Aller au nord d’Auberdine, à la première chute d’eau, le long de la Bondissante et prélever un échantillon de l’eau de l’étang.$B$BRetourner voir Thundris Windweaver, à Auberdine, avec le Prélèvement de la Bondissante.'),
(4763,'frFR','Remplir le Bol de purification vide au Puits de lune d’Auberdine.$B$BCollecter un échantillon de fruit, de noix et de céréales dans les camps nord des furbolgs Noirbois.$B$BMélanger les échantillons de nourriture à l’eau du bol et le placer à proximité du feu le plus proche de la rivière Bondissante, au camp nord. Cela fera venir le satyre corrupteur.$B$BPrendre son Talisman de corruption et l''apporter à Thundris Windweaver, à Auberdine.'),
(4771,'frFR','Placer le Gambit de l''aube dans la Chambre des visions de Scholomance. Vaincre Vectus, puis retourner auprès de Betina Bigglezink.'),
(4812,'frFR','Remplir le Tube d''eau vide au Puits de lune d’Auberdine, puis chercher le cristal rouge le long des falaises des montagnes à l’est de Sombrivage.'),
(4867,'frFR','Lire le Parchemin de Warosh. Apporter le Mojo de Warosh à Warosh.'),
(5063,'frFR','Pour créer la Coiffe du savant écarlate, il faut rapporter les éléments suivants à Malyfous Darkhammer : 1 Peau de la Bête en parfait état ; 5 Coutures d''Abomination effilochées ; 8 Cristaux des arcanes ; 5 Fils écarlates enchantés.$B$BIl faudra aussi payer 50 pièces d’or pour le travail de fabrication.'),
(5067,'frFR','Pour fabriquer les Jambières d''Arcana, il faut rapporter les éléments suivants à Malyfous Darkhammer : 1 Peau de la Bête en parfait état ; 5 Coutures d''Abomination effilochées ; 5 Barres d''arcanite ; 5 Fluides d''embaumement de Murmegivre.$B$BIl faudra également payer 50 pièces d’or pour le travail de fabrication.'),
(5068,'frFR','Pour fabriquer la Cuirasse carnassière, il faut rapporter les éléments suivants à Malyfous Darkhammer : 1 Peau de la Bête en parfait état ; 10 Coutures d''Abomination effilochées ; 5 Barres d''arcanite ; 5 Peaux des ombres.$B$BIl faudra également payer 50 pièces d’or pour le travail de fabrication.'),
(5096,'frFR','Se rendre au camp de base de la Croisade écarlate situé entre le Champ de Felstone et les Larmes de Dalson et détruire leur tente d’état-major.$B$BPlacer la bannière du Fléau sur le camp, puis revenir auprès du Grand exécuteur Derrington à la Barricade, dans les Maleterres de l’ouest.'),
(5127,'frFR','Se rendre au pic Blackrock et trouver Goraluk Anvilcrack. Le tuer puis utiliser la Pique tachée de sang sur son cadavre. Après avoir siphonné son âme, la pique sera devenue Tachée d''âme.$B$BTrouver aussi la Cuirasse couverte de runes inachevée.$B$BRapporter la Pique tachée d''âme et la Cuirasse couverte de runes inachevée à Lorax au Berceau-de-l''Hiver.'),
(5157,'frFR','Amener la Gourde vide au Puits de lune au centre de Jaedenar et la remplir avant de retourner voir Greta Mosshoof dans Gangrebois.'),
(5165,'frFR','Avec de l’Eau de Puits de lune purifiée, éteindre les flammes des quatre braseros de protection à l’intérieur du Fort des ombres dans Gangrebois.'),
(5243,'frFR','Se rendre à Stratholme, au nord. Fouiller les caisses de fournitures qui encombrent la cité et récupérer 5 Eaux sacrées de Stratholme. Retourner auprès de Leonid Barthalomew le Révéré quand vous avez récolté assez de liquide béni.'),
(5245,'frFR','Utiliser la Pique de Jaron pour trouver les quatre Fragments de relique des Bien-nés. Les apporter à Aurora Skycaller dans les Maleterres de l’est.'),
(5247,'frFR','Apporter une Barre de thorium enchanté, 5 Cristaux de restauration et une Fiole d''eau redoutable à Aurora Skycaller à la tour du Col du nord, dans les Maleterres de l’est.'),
(5282,'frFR','Se servir du Libérateur d''Egan sur les citoyens fantomatiques et spectraux de Stratholme. Quand les esprits sans repos se libèrent de leur enveloppes fantomatiques, utiliser de nouveau le Libérateur – ils seront enfin libres !$B$BLibérer 15 Esprits sans repos puis retourner auprès d’Egan.'),
(5341,'frFR','S’aventurer jusqu’à Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété de Southshore. Revenir auprès d’Alexi Barov quand la tâche est accomplie.'),
(5342,'frFR','Voyagez jusqu’au Camp du Noroît, dans le territoire de l’Alliance, et y assassiner Weldon Barov. Prenez sa tête et revenez auprès d’Alexi Barov.$B$BAttention : Weldon sera probablement bien protégé par la racaille de l’Alliance.'),
(5343,'frFR','S’aventurer jusqu’à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété de Southshore. Revenir auprès de Weldon Barov quand la tâche est accomplie.'),
(5344,'frFR','Voyager jusqu’à la Barricade - territoire de la Horde - et assassiner Alexi Barov. Prendre sa tête et revenir auprès de Weldon Barov.$B$BAttention : Alexi sera probablement bien protégé par les vandales de la Horde.'),
(5384,'frFR','Revenir à Scholomance avec le Sang des innocents. Trouver le porche et placer le Sang des innocents dans le brasero. Kirtonos viendra dévorer votre âme.$B$BCombattre vaillamment, sans perdre un pouce de terrain ! Détruire Kirtonos et revenir auprès d’Eva Sarkhoff.'),
(5466,'frFR','Trouver Ras Murmegivre dans Scholomance. Après l’avoir trouvé, utiliser le Souvenir lié sur son visage mort-vivant. Si sa transformation en mortel réussit, l’abattre et prendre la Tête humaine de Ras Murmegivre. Apporter la tête au Magistrat Marduke.'),
(5526,'frFR','Trouvez la Gangrevigne à Hache-tripes et prenez-en un fragment. Il est probable que vous ne pourrez vous en emparer qu’après la mort d’Alzzin le Modeleur. Servez-vous du Reliquaire de Pureté pour conserver le fragment, et retournez à Reflet-de-Lune voir Rabine Saturna au village de Havrenuit.'),
(5727,'frFR','Apporter l''Insigne du Lieutenant à Neeru Fireblade et lui parler. Essayer de déterminer s''il vous croit membre de la Lame ardente puis retourner voir Thrall à Orgrimmar.'),
(5801,'frFR','Emporter le Moule de Clé squelette et 2 Barres de thorium au sommet de la crête de la Fournaise dans le cratère d’Un''Goro. Utiliser le Moule de Clé squelette au lac de lave pour forger la Clé squelette inachevée.$B$BApporter la Clé squelette inachevée à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest.'),
(5802,'frFR','Prendre le moule de la Clé squelette et deux barres de thorium au sommet de la crête de la Fournaise dans le cratère d''Un''Goro. Se servir du moule de la Clé squelette pour forger la Clé squelette inachevée.$B$BApporter la Clé squelette inachevée à l''Apothicaire Dithers à la Barricade, Maleterres de l''Ouest.'),
(5902,'frFR','Trouver un endroit judicieux, au centre de la scierie de la Crête du nord, dans les Maleterres de l’ouest, pour placer le Tonneau de Termites des Maleterres.'),
(5904,'frFR','Trouver un endroit propice, au centre de la scierie de la Crête du nord, dans les Maleterres de l’ouest, pour placer le Tonneau de Termites des Maleterres.'),
(6001,'frFR','Utiliser la Poussière de lune cénarienne sur la Pierre des séléniens d’Auberdine pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu’il possède.$B$BQuand cela est fait, parler à Mathrengyl Bearwalker, à Darnassus.'),
(6002,'frFR','Utiliser la Poussière lunaire cénarienne sur la Pierre des séléniens, entre Mulgore et les Tarides, pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu’il possède.$B$BQuand cela est fait, parler à Turak Runetotem, à Thunder Bluff.'),
(6041,'frFR','Aller à Pestebois, au nord-ouest de la chapelle de l''Espoir de Lumière. Détruire 8 Bâtiments du Fléau en utilisant le Mélange spécial de Smokey sur les Marques de détonation que portent les bâtiments destinés à être détruits. Smokey a fait marquer les ziggourats et les abattoirs.$B$BUne fois la bombe placée, quitter le bâtiment et contempler le résultat de votre opération.$B$BGarder en tête que le Mélange spécial de Smokey est très... instable.'),
(6122,'frFR','Utiliser une Fiole d''échantillon des Chutes de la Bondissante vide pour collecter un échantillon d’eau, à l’entrée de la grotte, à proximité des Chutes.$B$BApporter la Fiole d''échantillon des Chutes de la Bondissante remplie à Alanndarian Nightsong, à Auberdine, dans Sombrivage.'),
(6123,'frFR','Apporter 5 Terrestrines et 12 Champignons lunaires à Alanndarian Nightsong, à Auberdine ; elle pourra ainsi commencer à préparer son remède.'),
(6127,'frFR','Utiliser la Fiole d''échantillon vide du Pic de Brume-funeste pour collecter un échantillon de l’eau d’un bassin, au sommet du Pic de Brume-funeste.$B$BApporter ensuite la Fiole d''échantillon remplie à Tonga Runetotem, à la Croisée, dans les Tarides.'),
(6129,'frFR','Utiliser le Remède pour animaux sur 10 Gazelles malades qui se trouvent dans la partie nord des Tarides ; ceci les soignera. Les Gazelles malades ont été vues au nord de la route orientée est-ouest qui traverse la Croisée.'),
(6146,'frFR','Aller à la Main de Tyr, au sud-est de la ferme des Marris. Une fois sur place, mordre dans la Pomme pourrie. Profiter d’avoir revêtu l’apparence d’un membre de la Croisade écarlate pour apporter les Ordres du Grand Croisé au Grand maître Valdelmar.'),
(6187,'frFR','Montez une armée et portez-vous vers les Maleterres de l’est. Lancez un assaut total sur Nathanos le Flétrisseur et détruisez tout misérable élément de la Horde qui tenterait de le défendre.$B$BGardez votre présence d’esprit, $N : la Horde le défendra jusqu’à la mort.'),
(6481,'frFR','Ouvrir la Gangue de résonite avec le Cristal de résonite enchanté, puis tuer Goggeroc. Retourner voir Mor''rogal pour l''informer et lui rapporter le Cristal de résonite enchanté.'),
(6543,'frFR','Apporter les Rapports du clan Warsong à l’Eclaireur Warsong, au Messager Warsong et au Voltigeur Warsong. Rapporter leurs comptes rendus mis à jour à Kadrak, dans la tour de guet nord, dans les Tarides.'),
(6570,'frFR','Aller à la tourbière du Ver, dans le marécage d''Âprefange, et chercher la tanière de Brandeguerre. Une fois à l’intérieur, porter l’Amulette de subversion draconique, et parler à Brandeguerre.'),
(6621,'frFR','Placer la Bannière de Karang sur le Monticule du totem Vile-sylve. Ne pas laisser les furbolgs détruire la Bannière. Tuer le chef Murgut, et apporter le Totem de Murgut à Karang Amakkar, à Zoram''gar.'),
(6622,'frFR','Sauver des patients en utilisant des Bandages de Triage, afin de panser leurs blessures. Vous devez sauver 15 patients avant que 6 d’entre eux ne meurent de leurs blessures.$B$BRappelez-vous l’ordre du triage ! Les Soldats agonisants meurent les premiers, suivis des Soldats grièvement blessés. Les Soldats blessés sont ceux qui meurent les derniers, et ils doivent être soignés APRES ceux qui agonisent et ceux qui sont grièvement blessés ; selon le tri que vous avez fait.'),
(6624,'frFR','Sauver des patients en utilisant des Bandages de Triage, afin de panser leurs blessures. Vous devez sauver 15 patients avant que 6 d’entre eux ne meurent de leurs blessures.$B$BRappelez-vous l’ordre du triage ! Les Soldats agonisants meurent les premiers, suivis des Soldats grièvement blessés. Les Soldats blessés sont ceux qui meurent les derniers, et ils doivent être soignés APRES ceux qui agonisent et ceux qui sont grièvement blessés ; selon le tri que vous avez fait.'),
(7001,'frFR','Trouvez un Loup des glaces dans la vallée d’Alterac. Servez-vous de la Muselière de loup des glaces pour « dompter » la bête. Lorsque ce sera fait, le loup des glaces vous suivra jusqu’au Maître des écuries Frostwolf. Parlez au Maître des écuries Frostwolf pour être crédité de cette capture.'),
(7003,'frFR','Utilisez l''Ultra-réducteur de Zorbin sur des géants de n''importe quel type en Feralas afin les rendre plus faciles à gérer. Apportez 15 Résidus de miniaturisation que vous trouverez sur les versions rétrécies des géants à Zorbin Fandazzle aux docks de la Côte oubliée en Feralas.'),
(7029,'frFR','Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange, dans Maraudon.$B$BEn faire usage sur les Vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir.$B$BSoigner 8 plantes en tuant les Engeances de Noxxious, puis retourner voir Vark Battlescar, à Proie-de-l''Ombre.'),
(7041,'frFR','Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange dans Maraudon.$B$BEn faire usage sur les vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir.$B$BSoigner 8 plantes en tuant les Engeances, puis retourner voir Taliendra, à la Combe de Nijel.'),
(7067,'frFR','Lire les instructions du paria. Après cela, obtenir l''Amulette d''union de Maraudon et la ramener au centaure renégat, dans le sud de Désolace.'),
(7383,'frFR','Remplir la Fiole d''améthyste et la rapporter à Corithras Moonrage à Dolanaar.'),
(7462,'frFR','Retournez à l’Athenaeum et trouvez le Trésor des Shen’dralar. Prenez votre récompense !'),
(7507,'frFR','Rapporter « Le guide de Nostro du tueur de dragons » à l’Athenaeum.'),
(7509,'frFR','Vous devez amener Onyxia à cracher le feu sur la Lame ancienne brute. Lorsque ce sera fait, ramassez la Lame ancienne chauffée. Attention, elle ne restera pas chaude éternellement. Le temps est très important.$B$BAvant de revenir me voir, il vous faudra tuer la bête et plonger la Lame ancienne chauffée dans son cadavre.$B$BSi vous y parvenez, Quel’Serrar sera à vous.'),
(7603,'frFR','Fouillez le Val Grêlé pour trouver les restes de Kroshius. Quand vous les aurez localisés, utilisez le Gangrefeu à proximité et attendez le retour de Kroshius. Quand l''Infernal se sera réveillé, tuez-le et prenez le Noyau infernal sur son cadavre.$B$BRapportez le Noyau infernal de Kroshius à Niby le Tout-Puissant, à Gangrebois.'),
(7636,'frFR','Vous devez trouver et tuer quatre corrupteurs démoniaques :$B$BSimona la Séductrice.$B$BKlinfran l’Enragé.$B$BSolenor le Tueur.$B$BArtorius le Néfaste.$B$BDétruisez ces créatures et retournez voir l’Ancien Vartus à Gangrebois.$B$BVous trouverez des indices sur leurs faits et gestes sur l’Ecorce pétrifiée qui se trouve dans votre inventaire.$B$BVous DEVEZ agir seul.'),
(7725,'frFR','Utilisez l''Ultra-réducteur de Zorbin sur des géants de n''importe quel type en Feralas afin les rendre plus faciles à gérer. Apportez 10 Résidus de miniaturisation que vous trouverez sur les versions rétrécies des géants à Zorbin Fandazzle aux docks de la Côte oubliée en Feralas.'),
(7810,'frFR','Parler à Short John Mithril dans l’arène de Strangleronce.'),
(7877,'frFR','Retournez à l’Athenaeum et trouvez le Trésor des Shen’dralar. Prenez votre récompense !'),
(7908,'frFR','Parler à Short John Mithril dans l’arène de Strangleronce.'),
(8057,'frFR','Ramenez un Etançon primordial hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi être Amicale (au minimum).$B$BMaywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.'),
(8061,'frFR','Ramenez un Etançon primordial hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi être Amicale (au minimum).$B$BAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.'),
(8301,'frFR','Récupérez 200 Fragments de carapaces de silithides et retournez voir Baristolth.'),
(8303,'frFR','Chercher Anachronos dans les Grottes du temps à Tanaris.'),
(8315,'frFR','La géologue Larksbane, au Fort cénarien en Silithus, veut que vous récupériez le Mécanisme de déverrouillage du cristal sur le Maître des clés.$B$BElle vous a demandé de vous rendre près des Restes de Grakkarond, au sud du Fort cénarien, et d’y dessiner les glyphes d''appel dans le sable. Si le Maître des clés apparaît, tuez-le et récupérez le Mécanisme de déverrouillage du cristal. Ensuite, si vous avez réussi, retournez voir la géologue Larksbane.$B$BElle vous a conseillé d’emmener une armée, $N.'),
(8780,'frFR','Apportez 8 Renforts d’armure robustes et 8 Renforts d’armure louds à Janela Stouthammer, à l’avant-poste de la brigade d’Ironforge, près de la Ruche’Zora. Vous devez aussi apporter le Briefing logistique VII pour terminer cette quête.'),
(8781,'frFR','Apportez 2 Epées d’acier lunaire à Janela Stouthammer, à l’avant-poste de la brigade d’Ironforge, près de la Ruche’Zora. Vous devez aussi apporter le Briefing logistique VI pour terminer cette quête.'),
(8801,'frFR','Remettre l’œil de C’Thun à Caelastrasz, dans le temple d’Ahn’Qiraj.'),
(8929,'frFR','Utilisez le Révélateur de fantômes extradimensionnel à l’entrée de Stratholme et parlez au fantôme d’Anthion Harmon.'),
(8970,'frFR','Récupérez 20 Varechs de sang sur les nagas Strashaz, puis retournez voir Bodley au mont Blackrock.'),
(8994,'frFR','Collectez 40 Brassards blackrock et un Flacon de pouvoir suprême. Ensuite, retournez voir Bodley au mont Blackrock.'),
(9015,'frFR','Rendez-vous dans le Cercle de la loi, dans les profondeurs de Blackrock, et placez la Bannière de provocation en son centre lorsque vous serez $Gcondamné:condamnée; par le Juge supérieur Grimstone. Tuez Theldren et ses gladiateurs, puis retournez voir Anthion Harmon dans les Maleterres de l’est avec le premier morceau de l’amulette du seigneur Valthalak.'),
(9051,'frFR','Piquez un Diablosaure avec l''Aiguillon de diablosaure. Retournez voir Torwa Pathfinder au Cratère d''Un''goro lorsque vous aurez accompli cette tâche.')
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`LogTitle`,`QuestDescription`) VALUES
(236,'frFR','Le Maître de siège Rudemanche, à la Forteresse de Joug-d’Hiver, vous a demandé de récupérer 10 Braises éternelles sur des personnages-joueurs de la Horde, au Chaudron des flammes.','Alimenter les démolisseurs','$N ! Il était temps que vous arriviez. Cette bataille est peut-être terminée, mais nous devons nous préparer pour la prochaine. Rendez-vous au Chaudron des flammes, au sud-est de Joug-d’Hiver, et récupérez quelques braises éternelles.$B$BMélangées à du charbon, elles servent à alimenter les démolisseurs et les engins de siège.$B$BOh, et si vous voyez des membres de la Horde dans le Chaudron, n’hésitez pas à les tuer pour leur prendre leurs braises. Nous ne pouvons pas les laisser prendre l’avantage lors du prochain combat.'),
(260,'frFR','Rassembler 5 Dents et 5 Griffes de battrodon, puis les apporter à Kelt Thomasin.','<INUTILISÉ>','Bien, cela vous convaincra sans aucun doute que je suis, comme ils disent – et ne démentez pas, je sais ce qu''ils disent – un esprit confus, obsédé par une légende improbable. Il s''agit d''un vieux conte nain, qui parle d''un monstre gigantesque vivant dans les profondeurs du loch. J''ai passé une bonne partie de ma vie à essayer de le traquer, et je n''en étais pas loin, mais hélas mon âge avance plus vite que moi à présent. Si vous voulez chasser le monstre du loch, apportez-moi des dents et des griffes de battrodon.$B$B<Il sourit mystérieusement.>'),
(338,'frFR','Rassembler les pages manquantes du manuscrit des « Vertes collines de Strangleronce ». Une fois les quatre chapitres complétés, les rendre à Barnil.','« Les vertes collines de Strangleronce »','Maître Nesingwary va être tellement furieux s''il découvre ça !$B$BIl m''a fait confiance pour relire le manuscrit de son roman « Les vertes collines de Strangleronce ». Tout allait bien, mais une grande rafale de vent a soufflé sur le camp et a dispersé toutes les pages !$B$BJ''ai pu en ramasser la plupart, mais certaines sont toujours perdues dans la jungle. Retrouvez les pages qui manquent pour compléter les quatre chapitres.$B$BJe vous aiderai à les remettre dans l''ordre. Rendez-moi les chapitres une fois que vous les aurez tous les quatre.'),
(402,'frFR','Vérifier plus tard si Serra est toujours occupé.','Sirra est occupée','Je suis désolé, mais avec la ville dans cet état, j''ai d''autres tâches qui m''attendent. Peut-être plus tard, si nous survivons, je pourrai finir cette traduction.'),
(490,'frFR','Rapporter 20 Crocs de Pins-tordus à Shayla Nightbreeze, à l''extérieur de Darnassus.','<UNUSED>','By strict orders from the Council of Darnassus, I am commissioning a bounty on the Gnarlpine Tribe. They are no longer friends of the forest. Their corruption has left them mindless threats to our people and the creatures of the glade.$B$BAs decreed by the Council, you shall be rewarded for removing the furbolg menaces from Kalidar. Bring to me their fangs as proof of your deeds.'),
(612,'frFR','Rendre sa lame à Catelyn.','<INUTILISÉ>','J’ai peu d’espoir, mais essayez de convaincre Catelyn de se séparer de sa dague ? Le cœur d''un collectionneur, vous savez ce que c''est…$B$BPeut-être que si vous dites que c''est pour moi, elle sera plus disposée à me la vendre ?'),
(811,'frFR','Apporter 8 Carapaces de grand scorpide à Kor''ghan, au village de Sen''jin.','<INUTILISÉ>','Une autre caractéristique des scorpides est leur loyauté farouche les uns pour les autres. Ils protègeront infailliblement celui des leurs qui se trouve en danger - mais vous avez sûrement déjà « goûté » à cet aspect de leur comportement social, lors de votre première chasse.$B$BVous feriez bien d''adopter cette stratégie : nous sommes plus forts ensembles et solidaires que divisés.$B$BApportez-moi huit carapaces de grand scorpide que vous trouverez sur le cadavre des scorpides blindés que vous pourrez tuer. Vous apprendrez beaucoup de ce travail, et je vous en récompenserai.'),
(856,'frFR','Descendre la route à partir du Camp Taurajo.$B$BTourner à gauche à l''intersection en T et continuer vers le nord.$B$BSuivre le chemin jusqu''au Sage Ancestral à l’extérieur de la Croisée.','<INUTILISÉ>','Bien que vous ayez atteint les Tarides, votre voyage n''est pas terminé. Vous devez le poursuivre jusqu''à la Croisée, où l''on a beaucoup besoin de vous.$B$BSuivez la route sur laquelle vous étiez, et tournez à gauche lorsque le chemin vous laisse le choix. Continuez vers le nord jusqu''à voir les murs de la Croisée.$B$BJuste avant d''entrer, rencontrez le Sage Ancestral, il vous dispensera quelques mots de sagesse.'),
(988,'frFR','Parlez à Volcor.','<INUTILISÉ>','J''ai remarqué la cape que vous portez, $N. Si vous acceptez de la sacrifier, je peux utiliser sa magie pour m''échapper. Le problème, c''est que vous, vous resterez ici dans la caverne.$B$BPourrez-vous vous débrouiller pour sortir si nous choisissons cette solution ?$B$BJe peux vous assurer que Terenthis vous récompensera si vous faites le choix de m''aider.$B$BC''est à vous de trancher, mais j''ai vraiment besoin de votre aide.'),
(989,'frFR','Parlez à Volcor.','<INUTILISÉ>','Si nous décidons de nous battre pour sortir, le plan est simple : nous tracerons notre route en tuant tous les furbolgs qui seront sur notre chemin... Ou tout ce qui voudrait essayer de nous arrêter.$B$BJ''espère qu''il y a un autre moyen, mais tôt ou tard il faudra affronter les furbolgs. Autant le faire nous-mêmes, nous serons sûrs que le travail a été fait.$B$BPrenez le temps de préparer vos armes ou vos enchantements, puis revenez me voir.'),
(1289,'frFR','Retourner voir le capitaine Garran Vimaire à Theramore.','<nyi> Rapport de Vimaire','Bien, d''après ce que je déduis du rapport du capitaine Vimaire, vous avez été d''une aide capitale dans ces investigations, et de cela je vous remercie.$B$BJe peux avoir l''esprit en paix sachant que vous vous occupez de ce problème. Si vous acceptez, je vous suggère de retourner voir le capitaine Vimaire et de l''aider à résoudre l’affaire.'),
(1290,'frFR','On parle.','<nyi> Enquête sur Mosarn','Parler au Garde Komak. Poser des questions est mauvais pour votre santé.'),
(2000,'frFR','[Speak with Rokar Bladeshadow in Durotar.]','[Rokar Bladeshadow]','[Too much idle time for you, $N. It''s time that you learned more of our trade. Just last night, five of our number were found dead in one of the cracks in Orgrimmar, with few leads. There are those that oppose us, using our own methods against us.$B$BSo it is I''ve decided you should learn the art of lockpicking.$B$BUnfortunately, it is a skill that my hands are not well suited to. You should seek out Rokar, who lives in the hills near Durotar. Even in his old age, I suspect he still has the touch for it.]'),
(2018,'frFR','Tuer le Surveillant Glibby et apporter son Sifflet à Rokar Ombrelame en Durotar.','L''épreuve de Rokar','Ah ! Maintenant Therzok m''envoie ses étudiants boutonneux ! Eh bien, je suppose que je peux vous apprendre une ou deux choses. Ce n''est pas que je me soucie beaucoup de vos affaires, mais je ne voudrais pas avoir votre mort sur la conscience.$B$BMais vous devez d''abord me prouver que vous êtes digne de mon enseignement.$B$BJe vais vous dire, $N. Je n''aime pas beaucoup cette KapitalRisk. Cette région me rappelle Draenor et ça me dérange de voir les gobelins la dévaster. Peut-être qu''ils cesseraient leur travail si le surveillant de leur Videfange disparaissait...'),
(2019,'frFR','Retourner voir Therzok à la Faille de l''Ombre à Orgrimmar.','Les outils du métier','Vous voilà, $N. Ceci devrait bien vous servir. Fabrication personnelle, je vous jure que vous ne trouverez pas mieux.$B$BNe prenez pas la peine de m''expliquer ce que vous voulez en faire, cependant. Je ne m''intéresse pas aux arrangements de Therzok, je veux seulement vivre tranquillement ma retraite.$B$BSi jamais vous aviez besoin d''un autre jeu d''outils, revenez me voir et je vous en fournirai un. Mais prenez-en soin !'),
(2358,'frFR','Cette quête n''est plus disponible dans le jeu.','Cornes de Nez''ra','Il y a bien des lustres, les Cornes de Nez''ra ont été volées au manoir de Ravenholdt. Je les ai cherchées par le monde entier, sur terre comme sur mer. Et tout ce temps, ce sont ces bêtes immondes les avaient !$B$BExterminez tous les orcs Blackrock que vous croiserez jusqu''à ce que vous retrouviez les Cornes de Nez''ra.$B$BFaites ceci pour moi, $N, et votre renommée atteindra Ravenholdt.'),
(3111,'frFR','Parler à Marrek Stromnur à Courbenclume.','<INUTILISÉ> [PÉRIMÉ]','Il y a bien longtemps, les hauts-elfes nous ont appris les secrets de la magie ainsi qu’à nos alliés humains. Ils nous ont mis en garde sur les règles à suivre et contre la folie qu’elle peut provoquer ! Mais n’y croyez pas. Nous sommes différents des elfes ; nous n’avons pas les mêmes faiblesses. Restez sur le droit chemin et vous verrez que la magie est aussi puissante en tant qu’outil qu’en tant qu’arme.$B$BVenez me chercher à Courbenclume. Je vous y attendrai !$B$B- Marrek Stromnur, Maître des mages'),
(3581,'frFR','Retourner voir Saern Cours-avec-fierté pour apprendre la compétence de Course dans les plaines.','<INUTILISÉ>','Imaginez-vous en train de courir dans les plaines, les forêts et les montagnes, le visage dans le vent... De voyager en terres inconnues ; l''étonnement de la découverte de la route, votre destin lié au seul horizon.$B$BDites-vous que sur un sabot, on peut réaliser beaucoup de choses ; en tant que tauren, vous bénéficierez de la rapidité de la Course dans les plaines. Il n''y a aucune limite aux distances que vous pourrez parcourir.'),
(5214,'frFR','Trouver le magasin de tabac d’Ezra Grimm à Stratholme et récupérer une boîte de Tabac d’Ezra. Retourner auprès de Smokey LaRue quand ce sera fait.','Le grand Ezra Grimm','C’est terrible… ce qui est arrivé à Ezra. La ville était aux mains des pillards, mais il ne voulait pas abandonner sa précieuse marchandise. Je me souviens qu’il disait : « Je brûlerai tout jusqu’à la dernière feuille plutôt qu’ils mettent leurs sales mains dessus ! »$B$BJe donnerais presque n’importe quoi pour une bonne pipe, mais il y a des limites ! J’ai quitté Ezra et son magasin ce jour-là. J’imagine que tout a brûlé, mais s’il y avait ne serait-ce qu’une chance qu’une boîte de son délicieux tabac soit encore intacte…$B$BQu’en dites-vous, $N ? Vous iriez en chercher une boîte pour ce vieux Smokey ?'),
(5383,'frFR','Apportez le Sac des horreurs à Eva Sarkhoff, à Caer Darrow.','Sac des horreurs de Krastinov','Vous ouvrez le sac et découvrez divers instruments de torture. Au milieu de cet attirail, un objet insolite attire votre regard : une fiole de sang, encore chaude au toucher.$B$BVous pensez que les Sarkhoff pourraient être intéressés par votre découverte.'),
(5665,'frFR','Parler à la prêtresse Alathea à Darnassus.','<INUTILISÉ>','Un message est arrivé ici de Darnassus, $N. Il semble qu''une de vos prêtresses veut que vous retourniez chez vous. Parlez à la prêtresse Alathea au temple de la Lune dès que possible. Elle paraît être satisfaite de vos progrès. Elle est certainement très fière de voir un des serviteurs d''Élune s''avancer à si grands pas dans la foi.$B$BQue la Lumière soit avec vous.'),
(5666,'frFR','Parler à la prêtresse Alathea à Darnassus.','<INUTILISÉ>','Oh, $N, par bonheur je vous trouve ! J''ai entendu dire que vous étiez $Gprêt:prête; pour votre prochaine épreuve au temple de la Lune. La prêtresse Alathea en personne désire s''entretenir avec vous. À votre place, je retournerais à Darnassus aussi vite que possible. Finissez ce que vous avez à faire ici et puis filez.'),
(5667,'frFR','Parler à la prêtresse Alathea à Darnassus.','<INUTILISÉ>','Ah, je vois que vous vous débrouillez très bien dans votre formation, jeune $Gprêtre:prêtresse;. L''un des vôtres était là il y a peu, il vous cherchait. Il semble que l''on vous requiert à Darnassus. Quelque chose à propos de la prêtresse Alathea et du temple de la Lune. Cela semblait important. Vous devriez y aller rapidement.'),
(5669,'frFR','Parler à la Grande prêtresse Laurena à Hurlevent.','<NYI> Une bénédiction de Lumière','Ah, $N, vous avez bien fait de venir me parler. L’un de vos prêtres de la Lumière était là il y a quelques instants. Il vous cherchait. La grande prêtresse Laurena veut vous rencontrer dans la cathédrale de la Lumière. Il ne serait pas surprenant qu’il s’agisse des progrès que vous avez faits jusqu’à présent. Mon ordre aussi teste ses fidèles et leur donne de plus grandes responsabilités au fur et à mesure qu’ils progressent dans leurs études.'),
(5670,'frFR','Parler à la Grande prêtresse Laurena à Hurlevent.','<NYI> Une bénédiction de Lumière','Vous venez de manquer un messager venant de Hurlevent qui vous cherchait, $N. On dirait que vous avez bien œuvré. La grande prêtresse Laurena veut vous parler. Je crois que l’Église vous sent apte à continuer l’entraînement.$B$BLorsque vos affaires seront terminées ici, allez à Hurlevent, à la cathédrale de la Lumière et parlez-lui. Je suis sûr qu’elle vous attend.'),
(5671,'frFR','Parler à la Grande prêtresse Laurena à Hurlevent.','<NYI> Une bénédiction de Lumière','Jeune $Gprêtre:prêtresse;, votre Église a envoyé un message vous demandant de revenir à Hurlevent. La grande prêtresse Laurena veut s’entretenir avec vous. Il semble que vos supérieurs vous jugent apte à entamer une formation de niveau supérieur.$B$BJe pense que vous trouverez la grande prêtresse à la cathédrale de la Lumière. Partez en paix et qu’Élune vous accompagne sur votre route !'),
(5682,'frFR','Parler à la grande prêtresse Alathea à Darnassus.','<INUTILISÉ>','Le temps est venu pour vous de retourner à Darnassus, $N. Allez parler à la grande prêtresse Alathea au temple de la Lune. Elle vous dira ce que vous devez savoir.$B$BSi je ne me trompe pas, il s''agit de nouveaux vêtements symbolisant votre nouveau rang au sein de votre ordre. Que la Lumière soit avec vous.'),
(5683,'frFR','Parler à la grande prêtresse Alathea à Darnassus.','<INUTILISÉ>','Oh, $Gmon frère:ma sœur;, quelle chance ! Il est temps pour vous de retourner à Darnassus et de parler à la grande prêtresse Alathea une fois de plus. Son messager était presque sûr qu’il s’agit de vous remettre vos nouveaux habits de notre ordre.$B$BQuand vous le pourrez, retournez chez vous et transmettez mes meilleures salutations à notre ordre.$B$BQu''Élune soit avec vous.'),
(5684,'frFR','Parler à la grande prêtresse Alathea à Darnassus.','<INUTILISÉ>','Hmph, on se débrouille pas mal à ce que je vois, $Gprêtre:prêtresse;. Je parierais que vous vous demandez quand on vous rappellera chez vous à Darnassus pour célébrer votre grandeur, hein ? Eh bien, pas aujourd’hui... enfin, pas pour faire la fête en tout cas.$B$BLa grande prêtresse Alathea m’a fait savoir par message que je devais vous dire d’aller la voir si je vous rencontrais. Vous pouvez encore aller la voir au temple de la Lune… au cas où vous auriez oublié… Haha.'),
(5686,'frFR','Parler à la Grande prêtresse Laurena à Hurlevent.','<NYI> La Lumière vous protège','Le temps est venu pour vous de retourner à Hurlevent, jeune $Gprêtre:prêtresse;. La grande prêtresse Laurena veut vous récompenser pour votre dévouement au service de la Lumière. Elle est toujours dans la cathédrale de la Lumière, c’est là qu’il faut la chercher.$B$BEn attendant, vous pouvez rester ici et vous entraîner autant que vous voulez. S’il y a quelque chose que je puisse faire pour vous, demandez-moi.'),
(5687,'frFR','Parler à la Grande prêtresse Laurena à Hurlevent.','<NYI> La Lumière vous protège','Le temps est venu pour vous de retourner à la cathédrale de la Lumière à Hurlevent, $N. La grande prêtresse Laurena vous rencontrera. Il est normal de vous récompenser pour ce que vous avez fait pour votre peuple et la Lumière.$B$BBonne chance, et qu’Élune soit avec vous sur votre route.'),
(5689,'frFR','Parlez à Ur''kyo à Orgrimmar.','<NYI> La marque du vaudou','Hé, $R. Un messager était là il n’y a pas si longtemps, qui vous cherchait. Il a dit qu’il fallait que vous retourniez à Orgrimmar pour parler à Ur''kyo dans la vallée des Esprits. Il n’avait pas l’air en colère, mais ça avait l’air important. Ce serait peut-être une bonne idée d’y aller.'),
(5692,'frFR','Parler à Aelthalyste à Fossoyeuse.','<NYI> Né dans les ténèbres','Je vous apprendrais volontiers tout ce que vous avez besoin de savoir, $N, mais ce sont des choses que seuls les membres de votre propre tribu peuvent vous montrer, comme la confection d’une nouvelle robe… Une qui sera le juste reflet de votre foi.$B$BAelthalyste a demandé que vous la rejoigniez, à Fossoyeuse. Elle se trouve dans le quartier de la Guerre, et vous attend. Si vous refusez d’aller la voir, je crois qu’elle nous en voudra beaucoup.'),
(5693,'frFR','Parler à Aelthalyste à Fossoyeuse.','<NYI> Né dans les ténèbres','Bien, vous êtes toujours en... vie, $N.$B$BAelthalyste a demandé à ce que vous retourniez à Fossoyeuse dès que vos affaires seront terminées aux Pitons-du-Tonnerre. Il semble que vous avez suffisamment gagné de puissance pour changer de vêtements… et porter la robe j’imagine.$B$BElle vous attend dans le quartier de la Guerre.'),
(5695,'frFR','Parler à la prêtresse Alathea à Darnassus.','<INUTILISÉ>','Votre temple réclame votre présence à Darnassus, $N. Retournez au temple de la Lune et parlez à la prêtresse Alathea. Elle vous attendra là.$B$BLe temps est venu pour vous de gagner une robe de niveau supérieur.'),
(5696,'frFR','Parler à la prêtresse Alathea à Darnassus.','<INUTILISÉ>','C''est toujours une joie quand j''ai pour mission de renvoyer l''un des nôtres au pays pour qu''il reçoive une nouvelle robe.$B$BLa prêtresse Alathea est dans le temple de la Lune et souhaite vous parler. Dès que possible, retournez à Darnassus pour y passer votre épreuve. Qu''Élune vous accompagne, $N.'),
(5697,'frFR','Parler à la prêtresse Alathea à Darnassus.','<INUTILISÉ>','Si vous continuez à y arriver aussi bien que ça, vous allez me rendre jaloux et me faire penser qu''on a pas assez de jeunes $Gprêtres:prêtresses; comme vous ici à Forgefer, $N. Vous êtes la fierté de votre peuple.$B$BLa prêtresse Alathea voudrait vous parler de nouveau si vous avez le temps. Elle est dans le temple de la Lune à Darnassus. Allez là-bas, et que la Lumière soit avec vous.'),
(5699,'frFR','Parler à la Grande prêtresse Laurena à Hurlevent.','<NYI> Une lueur d’espoir','Haha ! En route pour Hurlevent, $N. La grande prêtresse Laurena veut que vous retourniez là-bas pour subir de nouvelles épreuves. Rendez-vous à la cathédrale de la Lumière et ne traînez pas en chemin. Il y a beaucoup de travail à abattre et il va y avoir de plus en plus de pression sur vos épaules au fur et à mesure que votre puissance augmentera. C’est dans la nature de notre ordre - plus vous faites vos preuves et plus les gens comptent sur vous.$B$BLa Lumière est avec vous, je ne vous l’apprends pas.'),
(5700,'frFR','Parler à la Grande prêtresse Laurena à Hurlevent.','<NYI> Une lueur d’espoir','Votre Église souhaite que vous retourniez lui rendre visite, $N. La grande prêtresse Laurena, à Hurlevent, plus précisément. Il y a beaucoup d’activité dans la cathédrale de la Lumière ces jours-ci, mais cela ne me surprend pas du tout. Tellement de choses se passent entre le Fléau, la Horde, et nos propres problèmes internes.$B$BPartez pour la cathédrale dès que vous serez $Gprêt:prête;.'),
(5702,'frFR','Parlez à Ur''kyo à Orgrimmar.','<NYI> Les anciens rites','Hé, là, $R ! Je vous enseignerai tout ce que vous voulez apprendre, mais vous devriez savoir qu''Ur''kyo - c''est son nom, n''est-ce pas ? - vous recherche. On a mentionné que vous retourniez dans la vallée des Épreuves… non, ce n''est pas ça. C''était la vallée des Esprits... en Orgrimmar. Oui, c''est ça !$B$BAlors, euh... Ur''kyo... vallée des Esprits. Il veut vous parler.'),
(5703,'frFR','Parlez à Ur''kyo à Orgrimmar.','<NYI> Les anciens rites','Votre chef spirituel Ur''Kyo vous mande, $N. Ne le faites pas attendre.$B$BVous le trouverez dans la vallée des Esprits dans la grande cité de la Horde d''Orgrimmar. Rendez votre peuple fier.'),
(5705,'frFR','Parler à Aelthalyste à Fossoyeuse.','<NYI> Plus une ombre','Bienvenue à nouveau dans la vallée des Esprits, $N, mais je dois vous dire qu’on vous réclame à Fossoyeuse. Votre grande prêtresse sur place aimerait vous parler.$B$BVous savez déjà qu’elle se trouve au quartier de la Guerre, au cœur de votre cité.$B$BRendez-vous là-bas mais n’oubliez pas que vous êtes toujours $Gle bienvenu:la bienvenue; pour vous entraîner ici avec mon peuple.'),
(5706,'frFR','Parler à Aelthalyste à Fossoyeuse.','<NYI> Plus une ombre','C’est bon de vous revoir, $N. Mais je vais devoir raccourcir notre réunion : Aelthalyste a envoyé un message demandant que vous retourniez la voir à Fossoyeuse. Elle est toujours dans les Quartiers de guerre.$B$BNe vous en faites pas cependant, je pense que c’est une bonne chose. Elle a mentionné qu’elle était contente de vos progrès, aussi ne vous tourmentez pas trop.'),
(5708,'frFR','Parler à Aelthalyste à Fossoyeuse.','<NYI> Trop près des ténèbres','J’ai entendu dire que votre foi entreprend de plus en plus de choses pour protéger et guider les Réprouvés. On dirait qu’Aelthalyste sait quelque chose que Sylvanas ne sait pas, ou que votre Dame noire aimerait qu’Aelthalyste soit un peu moins patiente dans ses mesures.$B$BLe mieux est que vous vous rendiez à Fossoyeuse pour lui parler. Elle se trouve dans le quartier de la Guerre, comme d’habitude.'),
(5709,'frFR','Parler à Aelthalyste à Fossoyeuse.','<NYI> Trop près des ténèbres','L''heure est venue, $N. On a de nouveau besoin de vous à Fossoyeuse. Aelthalyste s’est… entichée de certains des prêtres Réprouvés ; et dans le but de protéger dame Sylvanas, elle veut s’assurer que nous sommes tous aussi bien préparés que possible.$B$BAllez la trouver dans le quartier de la Guerre et soyez $Gprêt:prête; à vous charger de la tâche qu’elle vous réserve.'),
(5711,'frFR','Parlez à Ur''kyo à Orgrimmar.','<NYI> Les voies perdues','Je me demande combien de fois j''ai vu votre race par ici. Mais je ne vous ai jamais véritablement parlé. J''en ai entraînés quelques-uns, ai indiqué quelques directions, mais je ne crois pas que quiconque soit resté suffisamment longtemps dans les environs pour que nous ayons le temps de bavarder.$B$BOh, de toute façon, ce n''est pas le bon moment pour ça, je dois vous dire qu''Ur''kyo veut vous parler à Orgrimmar. Il est dans la vallée des Esprits et vous attend.'),
(5712,'frFR','Parlez à Ur''kyo à Orgrimmar.','<NYI> Les voies perdues','Que la chance vous accompagne, jeune $Ghomme:femme;.$B$BDes messagers trolls sont arrivés à Fossoyeuse il n''y a pas plus d''un jour ou deux. Ils ont parlé de jeunes prêtres retournant dans la vallée des Esprits afin de parler à Ur''Kyo. Je suggérerais que vous enquêtiez sur cette affaire au cas où elle se rattacherait à vous. Je n''ai aucun doute que vous vous souvenez du chemin du retour vers Orgrimmar.'),
(6221,'frFR','[Nafien would like you to kill 5 Deadwood Den Watchers, 5 Deadwood Avengers, and 5 Deadwood Shamans.]','[Deadwood of the North]','[There is a camp of Deadwood furbolgs directly to our southwest. Corruption permeates the camp, and I wish to put an end to it before they become a problem.$B$BThe Deadwood tribe is evil, but it is the effects of the fel that pollutes their minds. Their hostility is not truly an innate quality, yet they cannot be helped. For this reason, I am deeply saddened by having to fight my own brethren.$B$BPlease, $N, do what must be done, and do not mention the details; they upset me far too much.]'),
(6241,'frFR','Cette quête n''est plus disponible dans le jeu.','Les Tombe-hiver s''agitent','Les Grumegueules ont tendance à rester entre eux, $N. Bien que nous laissions passer ceux en qui nous avons toute confiance, nous essayons d''éviter les autres tribus de furbolgs, si cela est possible.$B$BDernièrement, j''ai remarqué que la tribu Tombe-hiver montrait des signes d''hostilité à notre égard. Ils semblent être dans un étrange état de rage, rendus furieux par tout ce qui les effraie et qu''il ne comprennent pas.$B$BSi vous pouviez en réduire le nombre, cela nous aiderait grandement, $N.'),
(7361,'frFR','Vous avez été $Gchargé:chargée; de tuer les personnages Elfes de la nuit présents dans la vallée d’Alterac.$B$BTuez un Elfe de la nuit et présentez-vous à Najak Maléficas avec une Tête coupée d’Elfe de la nuit.','En faveur auprès des Sombrelances','<Najak grogne.>$B$BAvant les Elfes de la nuit, il y avait les Trolls. Les Elfes de la nuit viennent des Trolls.$B$BLeurs attaques indisciplinées contre mon peuple ne sont pas tolérables. Forteramure cherche à nous éradiquer, à effacer toute trace de ceux qui lui ont donné naissance, à lui et aux siens. Cela ne sera pas !$B$BPour chaque Elfe de la nuit que vous tuez et que vous décapitez, Najak vous accordera une faveur parmi les Sombrelances. Le récit de vos exploits se répandra dans tout Kalimdor et dans les Royaumes de l’est. Allez et servez les Sombrelances !'),
(7362,'frFR','Vous avez été $Gchargé:chargée; de tuer les personnages gnomes présents dans la vallée d’Alterac.$B$BTuez un Gnome et présentez-vous à Ravak Totem-Sinistre au donjon Loup-de-givre avec une Touffe de cheveux de Gnome.','Allié des Taurens','L’Ancienne m’envoie dans cette zone de guerre pour étudier les autres peuples. Je suis là pour ramasser des échantillons de Gnomes. Magatha s’intéresse à leur potentiel de survie. En vérité, les Gnomes sont minuscules et ridiculement faibles, mais ils font preuve d’une résistance considérable, en combat ou autrement.$B$BHeureusement pour vous, je suis à la recherche de forbans pour accomplir la volonté de Magatha. Rapportez-moi des touffes de cheveux de Gnome, et les Taurens vous considèreront comme $Gun allié:une alliée;.'),
(7363,'frFR','Vous avez été $Gchargé:chargée; de tuer les personnages humains présents dans la vallée d’Alterac.$B$BTuez un Humain et présentez-vous au commandant Louis Philips (qui fait la navette entre le front et le donjon Loup-de-givre) avec un Bout d’os humain.$B$BUn remède à la condition humaine est à portée de main !','La condition humaine','Les Humains sont détestables.$B$B<Le commandant Philips grimace.>$B$BJe suis un soldat des Loups-de-givre, mais je reste un serviteur de Sylvanas.$B$BJe profite de mon service ici pour rendre service aux sombres apothicaires de Fossoyeuse.$B$BJ’ai commencé à rassembler des bouts d’os qui pourraient servir à soigner la condition humaine.$B$BJe suis autorisé à sous-traiter cette tâche à mes subordonnés.$B$BTrouvez-les. Tuez-les. Rapportez-moi des bouts d’os.'),
(7364,'frFR','Vous avez été $Gchargé:chargée; de tuer les personnages taurens présents dans la vallée d’Alterac.$B$BTuez un Tauren et présentez-vous à Dirk Lembrouille à Dun Baldar avec un Sabot de Tauren.','Au service de Gnomeregan','Le Grand Bricoleur lui-même m’envoie sur ce champ de bataille pour défendre mes frères et sœurs gnomes. Nous avons entendu dire que les Taurens s’en prennent aux Gnomes, et pire que tout, ils arrachent des poignées de cheveux aux corps de ceux qui sont tombés. Il faut mettre un terme à ces atrocités. Nous allons répliquer !$B$BSoulagez-les de leurs sabots, $C. Apportez-moi leurs sabots ! Montrez que vous êtes $Gun allié:une alliée; des Gnomes.'),
(7365,'frFR','Vous avez été $Gchargé:chargée; de tuer les personnages trolls présents dans la vallée d’Alterac.$B$BTuez un Troll et présentez-vous à Athramanis à Dun Baldar avec un Mojo de Troll sombrelance.','Le requiem de Forteramure','Forteramure a donné l’ordre. Tous les Trolls sur le champ de bataille doivent être exterminés. Leur ridicule prétention à avoir donné naissance aux Elfes de la nuit ne doit recevoir qu’une seule réponse : la force.$B$BTuez-les et rapportez-moi leur mojo. Je répète : je veux que vous voliez leur mojo.'),
(7366,'frFR','Vous avez été $Gchargé:chargée; de tuer les personnages Réprouvés présents dans la vallée d’Alterac.$B$BTuez un Réprouvé et présentez-vous au commandant Karl Philips (qui fait la navette entre le scierie et la mine) avec un Cœur de Réprouvé.','La pitié de l''archevêque','L’archevêque est aussi bon que sage. Il faut être quelqu’un d’exceptionnel pour avoir pitié de tels misérables…$B$B<Le commandant Philips hoche la tête, incrédule.>$B$BIl est trop bon… trop bon.$B$BL’archevêque insiste pour que nous prenions les Morts-vivants en pitié. Nous devons leur octroyer une mort rapide et miséricordieuse. Pour cela, il nous faut leurs cœurs noirs et malades.$B$BRapportez-moi le cœur des Réprouvés pour que nous puissions les incinérer à la cathédrale de la Lumière en grande cérémonie. Hâtez-vous, $N !'),
(7381,'frFR','Si Korrak le Ragesang devait réapparaître dans le Champ sanglant, traquez-le et tuez-le.$B$BApportez le Crâne de Korrak au Maître de guerre Laggrond dans les contreforts de Hautebrande.','Le retour de Korrak','Korrak a été tué, certes, mais une question demeure : restera-t-il mort ? Les Trolls sont réputés pour leurs étranges sorcelleries tribales. Je ne serais pas surpris que leur chef défunt ne se relève d’entre les morts pour reprendre les rênes de son clan.$B$BVous savez quoi faire si cela se produit.$B$B<Le maître de guerre Laggrond passe son index sur son cou, un geste très éloquent.>$B$BEt cette fois, je veux sa tête. Gardez les yeux ouverts, soldat.$B$BVous pouvez disposer !'),
(7382,'frFR','Si Korrak le Ragesang réapparaît dans le Champ sanglant, traquez-le et tuez-le.$B$BApportez le Crâne de Korrak au lieutenant Haggerdin dans les Contreforts de Hautebrande.','Korrak l''Indestructible','Quelque chose cloche dans cette affaire… Est-ce que quelqu’un a pensé à brûler le corps de Korrak ? Ces Trolls sont prêts à tout pour ressusciter leur chef. C’est une pratique courante chez ces païens semi-humains à la peau bleue.$B$BGardez les yeux ouverts, $N. Ne paniquez pas si Korrak réapparaît. Si cela se produit, je veux qu''on l''exécute et qu''on le réduise en cendres.$B$BEt pour faire bonne mesure, avant d’allumer le feu, coupez-lui la tête et rapportez-la-moi.'),
(7401,'frFR','Vous avez été $Gchargé:chargée; de tuer les personnages nains présents dans la vallée d’Alterac.$B$BTuez des Nains et arrachez-leur la colonne vertébrale. Apportez les Colonnes vertébrales de Nains au sergent Yazra Gronde-Sang au donjon Loup-de-givre.','ON RECHERCHE : des Nains !','Par ordre du sergent Yazra Gronde-Sang, tous les nains rencontrés sur le champ de bataille doivent être abattus à vue.$B$BSi vous en tuez un, arrachez sa colonne vertébrale et laissez pourrir le reste – ce tas de déchets mous servira d’avertissement à tous ceux qui oseraient s’opposer à la puissance des Loups-de-givre.$B$BAllez voir le sergent Yazra Gronde-Sang avec la preuve de vos exploits.'),
(7402,'frFR','Vous avez été chargé de tuer les personnages orcs présents dans la Vallée d’Alterac.$B$BTuez un Orc et remettez les Dents d’Orc au caporal Noreg Foudrepique à Dun Baldar.','ON RECHERCHE : des Orcs !','Par ordre du caporal Noreg Foudrepique, tous les soldats valides doivent abattre sans faire de quartier tous les Orcs qu’ils rencontrent sur le champ de bataille.$B$BLes soldats doivent prélever une défense ou une dent sur la mâchoire de leurs victimes et présenter ladite dent comme preuve de leur exploit.$B$BIl est recommandé de porter des gants épais.'),
(7521,'frFR','Pour libérer Tonneraan le Cherchevent de sa prison, vous devez présenter au généralissime Demitrian les moitiés droite et gauche des Liens du Cherchevent, 10 barres d''élémentium, et l''Essence du seigneur du Feu.','Tonneraan le Cherchevent','Je vous ai dit tout ce que je sais, $N. C''est à vous de trouver l''élémentium. C''est à vous de détruire la forme physique du seigneur du Feu.$B$BSi vous y parvenez, vous recevrez la bénédiction de Tonneraan.'),
(7522,'frFR','Examiner le Calice de la renaissance et le rapporter au généralissime Demitrian.','Examiner le Calice','Examinez le Calice de la renaissance, $Gmortel:mortelle;. C''est grâce à lui que le Cherchevent reviendra !'),
(7561,'frFR','Présenter la Lame du baiser du vent dormante au généralissime Demitrian.','Éveille-toi, Lame-tonnerre !','Vous avez vaincu le Cherchevent. Prenez la lame endormie et obligez cet immonde menteur, Demitrian, à utiliser les matériaux que vous lui avez fourni pour sa trahison. Obligez-le à éveiller Lame-tonnerre.'),
(7702,'frFR','Loin dans les profondeurs de la fosse aux Scories, dans le Chaudron, vous trouverez le dortoir des nains Sombrefer.$B$BAllez dans leur dortoir et volez 20 Oreillers Sombrefer. Revenez voir Evonice Fumesuie dans la gorge des Vents brûlants quand vous aurez accompli cette tâche.','Privez-les de sommeil','Si nous voulons faire baisser la productivité des forces des Sombrefers qui travaillent dans la fosse aux Scories, il faut frapper là où ça va faire le plus mal.$B$BICe fait est peu connu, mais les nains, et tout particulièrement les Sombrefers, ont besoin de repos ! De beaucoup de repos !$B$BJe vous le demande : comment pourraient-ils dormir sans oreillers ? Exactement, $N, ils ne pourraient pas. Voilà pourquoi il faut que vous vous glissiez dans la Fosse aux scories et que vous voliez leurs oreillers.'),
(8325,'frFR','Tuez 6 Wyrms de mana. Ils se trouvent près des Cristaux ardents, non loin de la tour et du belvédère.','La reconquête de l''île de Haut-Soleil','Plus tôt vous commencerez votre éducation, $N, mieux ce sera pour nous tous. Nous n’avons guère de place pour l’erreur, alors écoutez-moi attentivement.$B$BLes cristaux ardents, les objets verts qui flottent à l’ouest de la Flèche solaire, nous ont longtemps servi à alimenter les expériences de l’île. Les wyrms de mana étaient leurs gardiens, mais lorsque le Fléau a envahi Quel’Thalas, nous en avons perdu le contrôle.$B$BAvant de le reprendre, nous devons diminuer leur nombre. Lorsque vous y serez $Gparvenu:parvenue;, revenez me voir.'),
(8326,'frFR','Collectez 8 Colliers de lynx sur des Lynx Preste-pattes et des Jeunes Preste-pattes. Lorsque vous aurez terminé, retournez voir la magistrice Erona sur l’île de Haut-Soleil.','Des mesures regrettables','Grâce à vos efforts, nous avons compris quelque chose qui, franchement, me désole. Le pouvoir incontrôlé des cristaux ardents a saccagé une part plus importante que je ne le pensais de l’équilibre naturel de l’île. Si nous voulons en récupérer le contrôle, nous devons nous résigner à prendre des mesures regrettables.$B$BLes lynx ont succombé à l’influence des cristaux. Nous allons devoir les abattre. Ramenez-moi leurs colliers, $N. Je parviendrai peut-être à fabriquer des entraves magiques qui en replaceront certains sous notre contrôle.'),
(8327,'frFR','Parlez à Lanthan Perilon sur l’île de Haut-Soleil. Il se tient près du sentier qui part de la Flèche solaire, vers l’ouest.','Se présenter à Lanthan Perilon','Vous allez vous présenter à mon assistant, Lanthan Perilon. Il vous expliquera ce que vous aurez à faire. À la Flèche solaire, nous allons continuer à nous concentrer sur les cristaux ardents. Quant à vous, vous allez vous charger d’un problème plus urgent, qui concerne l’académie de Falthrien. Lanthan vous expliquera tout lorsque vous irez lui parler.$B$BSuivez le sentier vers l’ouest, vous ne tarderez pas à le trouver.$B$BBonne chance, $N. Vos succès à venir auront leur récompense.'),
(8328,'frFR','Parlez à Julia Heurtesoleil, le maître des mages, à l’intérieur de la Flèche solaire de l’île de Haut-Soleil.','La formation de mage','Ne manquez pas de profiter de l’entraînement d’un maître si vous voulez progresser dans votre classe. Les jeunes mages de l’île de Haut-Soleil sont formés par Julia Heurtesoleil. Parlez-lui et voyez ce qu’elle peut vous apprendre. Tout ce qu’elle enseigne a un coût, n’oubliez donc pas d’emporter un peu d’argent.$B$BComme tous les maîtres de l’île de Haut-Soleil, Julia se trouve à l’intérieur de la Flèche solaire, au rez-de-chaussée.'),
(8329,'frFR','Parlez à Delios, le maître des guerriers, à la Flèche solaire sur l’Île de Haut-Soleil.','La formation de guerrier','Ne manquez pas de profiter de l’entraînement d’un maître si vous voulez progresser dans votre classe. Les jeunes guerriers de l’île de Haut-Soleil sont formés par Delios. Parlez-lui et voyez ce qu’il peut vous apprendre. Tout ce qu’il enseigne a un coût, n’oubliez donc pas d’apporter un peu d’argent.$B$BComme tous les maîtres de l’île de Haut-Soleil, Jesthenis se trouve à l’intérieur de la Flèche solaire, au rez-de-chaussée.'),
(8334,'frFR','Tuez 7 Sylveniers et 7 Sylveniers farouches, puis retournez voir Lanthan Perilon sur l’île de Haut-Soleil.','Agression','Avant de vous envoyer à l’académie, je veux que vous accomplissiez une autre tâche urgente. Autrefois, les sylveniers nous aidaient à faire de l’île de Haut-Soleil un vaste jardin. À présent, ils sont devenus incontrôlables. Ne tardez pas trop à éclaircir leurs rangs, mais méfiez-vous, depuis que nous ne les contrôlons plus, ils sont devenus agressifs. Pour cette raison, nous sommes forcés de nous débarrasser de ces vieux serviteurs.$B$BVous demander un tel service ne me fait pas plaisir, mais la survie est la survie. Je les pleurerai plus tard.'),
(8335,'frFR','Tuez 8 Âmes en peine arcaniques et 2 Âmes en peine arcaniques contaminées, ainsi que Felendren le Banni. Ils se trouvent à l’académie de Falthrien. Ramenez la Tête de Felendren à Lanthan Perilon sur l’île de Haut-Soleil.','Felendren le Banni','Un traître à notre peuple vit au sommet de l’académie de Falthrien au sud-ouest.$B$BFelendren est son nom. Banni des Elfes de sang pour avoir refusé d’écouter les avertissements de nos maîtres et de nos anciens, il ne vit plus que pour satisfaire sa dépendance à la magie. Il représente ce qu’il y a de pire dans notre société. Il a refusé d’apprendre à se maîtriser. Ce n’est plus qu’une coquille vide – un Déshérité – et il représente un danger pour la Flèche solaire.$B$BDétruisez-le, lui et les âmes en peine arcaniques qui l’entourent.'),
(8338,'frFR','Apportez l’Esquille arcanique contaminée à l’arcaniste Helion, au belvédère de la Flèche solaire, sur l’île de Haut-Soleil.','L''esquille arcanique contaminée','Vous avez trouvé une bizarre esquille de mana cristallisé sur le cadavre de l’âme en peine arcanique contaminée. Elle est différente de celles que vous avez sans doute déjà vues, et semble aussi sombre et sinistre que l’âme en peine sur laquelle vous l’avez prise. Le seul fait de la tenir vous donne de sinistres pressentiments.$B$BL’arcaniste Helion, au belvédère de l’île de Haut-Soleil, pourrait en avoir l’usage.'),
(8339,'frFR','Ramenez les trucs à Aurel Feuilledor au Fort cénarien.','La royauté du Conseil<NYI><TXT>INUTILISÉ','Pour fabriquer une Chevalière de sectateur du Crépuscule, il me faut un tas de trucs.'),
(8344,'frFR','Remettez 4 Essences d’âmes en peine et 1 Essence d’âme en peine contaminée à l’invocateur Teli''Larien, à la Flèche solaire de l’île de Haut-Soleil.','Des fenêtres vers la source','Écoutez-moi bien, $Gmon jeune ami:ma jeune amie;. Il y a quelque chose de pourri dans cette île, quelque chose de bien plus puissant que les séquelles du Fléau.$B$BJe soupçonne l’île d’abriter une véritable présence démoniaque.$B$BUn peu plus à l’ouest, vous trouverez les flèches de l’académie de Falthrien. Les âmes en peines arcaniques qui l’infestent nous donnent une ouverture vers la source de ce pouvoir démoniaque. Vous allez me remettre les essences de ces âmes, corrompues ou non.$B$BEn échange, je vous apprendrai comment invoquer un diablotin qui sera le premier des nombreux compagnons de votre carrière de démoniste.'),
(8347,'frFR','Parler à l’estafette Alarion, près du pont qui mène au sud de l’île de Haut-Soleil.','Aider les estafettes','La magistrice Erona souhaitait vous voir prendre la route de Lune-d’Argent pour y participer à nos efforts de reconquête… une fois la crise à l’académie de Falthrien résolue, bien sûr. Vous ne nous avez pas déçus, $N.$B$BEn vous dirigeant vers la place de l''Épervier, au sud d''ici, vous devriez parler à l’estafette Alarion. Elle se trouve non loin du pont.$B$BLes estafettes se chargent de transférer des marchandises entre ici et la terre ferme. Vous avez démontré que vous étiez $Gplein:pleine; de ressources. Elles pourraient avoir besoin de vous.'),
(8350,'frFR','Remettez le Paquet d’Erona à l’Aubergiste Delaniel, à l’auberge située sur la Place de l''Épervier, dans le Bois des Chants éternels.','Achever la livraison','La mort d''une nouvelle estafette est une réelle tragédie, mais c''est un risque que nous acceptons tous en même temps que ce métier. La magistrice Erona, à la Flèche solaire, a besoin que ce paquet soit livré à l’auberge de la place de l''Épervier, et ce le plus vite possible.$B$BNous sommes en effectifs réduits et je n''ai personne à part vous pour nous remplacer.$B$BJe ne vais pas vous mentir ; le chemin vers la place de l''Épervier peut être terriblement dangereux si vous vous écartez de la relative sécurité de l''allée du Point-du-jour. Vous sentez-vous à la hauteur de cette tâche, $N ?'),
(8458,'frFR','Apporter un Scalp de traqueur des ombres à Maurin Craquossement en Désolace.','<INUTILISÉ>','Je pense pouvoir trouver ce démon si j''ai les réactifs adéquats.$B$BS''il est effectivement aussi puissant que je le suspecte, je vais avoir besoin de certains objets disponibles sur des créatures mortelles. Mais vous agissez au nom du Chef de guerre, aussi je suis certain que vous accepterez ma quête.$B$BD''abord, je vais devoir briser toutes les protections qu''il aurait contre les visions. Pour cela, j''aurais besoin d''un scalp de satyre. Mais pas de n''importe quel satyre. Il doit provenir d''un traqueur des ombres Fielfurie.$B$BCherchez cette tribu dans les ruines anciennes au nord-est de Désolace.'),
(8463,'frFR','Rapportez 6 Cristaux de mana instables à Aeldon Signesol, sur la Place de l''Épervier.','Les cristaux de mana instables','Un groupe de Déshérités s’est emparé récemment d’une réserve de cristaux de mana instables dans l’un de nos sanctum des arcanes. S’ils ne sont pas manipulés correctement, ces cristaux peuvent exploser avec assez de violence pour faire un trou dans les murs de la ville.$B$BEn soi, le fait qu’ils se fassent tous vaporiser en essayant de ponctionner des sources arcaniques instables ne me dérange pas, $N, mais un tel incident serait mauvais pour l’image de mes hommes.$B$BRamenez-moi tous les cristaux volés que vous trouverez, ils seront peut-être encore dans leurs caisses.'),
(8468,'frFR','Apportez la Tête de Thaelis au Sergent Kan’ren sur la Place de l''Épervier, dans le Bois des chants éternels.','ON RECHERCHE : Thaelis l’Affameur','La cité de Lune-d’Argent offre par la présente une récompense pour la tête de Thaelis l’Affameur, le fameux chef de bande des Déshérités. Il s’est rendu coupable d’une multitude de crimes contre la population, dont le meurtre de deux gardes de la cité.$B$BPour toucher la récompense, présentez-vous au sergent Kan’ren.'),
(8472,'frFR','Récupérez 6 Noyaux arcaniques sur les Patrouilleurs des arcanes qui circulent dans les ruines de Lune-d’Argent et rapportez-les au magistère Jaronis, sur la Place de l''Épervier dans le bois des Chants éternels.','Un mauvais fonctionnement','Les patrouilleurs des arcanes fabriqués par nos ancêtres pour protéger la ville sont devenus dangereux à cause du manque d’entretien. Ils ne nous reconnaissent plus comme leurs maîtres et nous attaquent à vue !$B$BBien qu’ils aient été créés il y a de nombreuses années, les noyaux arcaniques qui les alimentent sont encore très utiles et précieux. Je veux que vous alliez récupérer ces noyaux et que vous me les rameniez, afin que je puisse les recycler là où ils nous serviront. Vous trouverez les patrouilleurs dans les quartiers en ruine de Lune-d’Argent, au nord-ouest.'),
(8473,'frFR','Tuez 10 Gardes verts flétris au Bosquet incendié, puis revenez voir Larianna Ruissevent à l''intérieur de la tour, juste au nord-ouest du Bosquet Incendié dans le Bois des Chants éternels.','Une triste tâche','Ces temps sont difficiles, $N. Décider de mettre le feu aux bois qui longent les terres Fantômes pour éviter que le Fléau ne s’étende a été très pénible.$B$BLes tréants, qui ont été nos amis pendant des années, tentent de faire repousser la forêt le long du Bosquet incendié.$B$BNous ne sommes pas parvenus à convaincre nos anciens alliés d’interrompre leurs efforts. C’est une tâche particulièrement douloureuse, $C, mais il va falloir que vous les arrêtiez par la force. C’est le seul moyen qui nous reste.'),
(8474,'frFR','Trouvez la personne qui a fabriqué le Pendentif du vieux Blanchécorce. Elle pourra peut-être vous parler de cet objet.','Le pendentif du vieux Blanchécorce','Les initiales L.R. sont gravées sur le pendentif. Ces lettres pourront peut-être vous aider à trouver la personne qui l’a fabriqué.'),
(8475,'frFR','Tuez 8 Pilleurs Ossepeste, puis présentez-vous au forestier Jaela à la Malebrèche dans le bois des Chants éternels.','La Malebrèche','La bande de sol souillé qui coupe les Chants éternels en deux est un rappel permanent du jour où Arthas a conduit le Fléau jusqu’à notre ville bien-aimée.$B$BCette horreur ne se contente pas de défigurer le paysage. Aujourd’hui encore, elle attire le Fléau des terres Fantômes à Lune-d’Argent.$B$BAllez prêter main-forte à mes hommes, $N. Tuez les Morts-vivants décérébrés qui arpentent la Malebrèche.'),
(8476,'frFR','Le lieutenant Coursaurore de la retraite des Pérégrins du bois des Chants éternels veut que vous tuiez 5 Berserkers amani et 5 Lanceurs de haches amani.','L''empiètement des Amani','Notre domaine n’est pas aussi étendu que les vastes royaumes des Orcs et des Humains. Vous pouvez embrasser d’un seul coup d’œil tout ce qui reste de nos terres en Azeroth, $N.$B$BEn attendant que nous puissions atteindre l’Outreterre et trouver un nouveau foyer, nous devons défendre à tout prix ce maigre territoire.$B$BHélas, nos voisins primitifs du sud-est, les Trolls Amani, s’imaginent qu’ils en sont propriétaires. Nous ne pouvons plus tolérer leurs raids quotidiens. Rendez-vous à Zeb’Watha et Tor''Watha, leurs villages, et donnez-leur une leçon.'),
(8477,'frFR','Fouillez Tor''Watha au sud-est de la retraite des Pérégrins à la recherche du Taille-épieux Otembe, puis apportez le Marteau d’Otembe à Arathel Solforge, à la retraite des Pérégrins du bois des Chants éternels.','Le marteau du Taille-épieux','Les Amani et les sin’dorei ont derrière eux une longue histoire faite d’aversion et d’hostilités, $N, mais cela ne m’empêche pas d’apprécier le travail d’un autre artisan.$B$BJ’ai eu l’occasion de voir les armes des Amani, et je dois admettre que le métal a été expertement travaillé. On prétend que le taille-épieux Otembe possède un marteau magique si léger et si bien équilibré qu’il lui permet de travailler très vite et très efficacement.$B$BSi vous me l’apportez, je m’en servirai pour vous fabriquer une arme.'),
(8480,'frFR','Rapporter 8 Armes sin’dorei à Velendris Blancmatin, dans le bois des Chants éternels.','Les armes perdues','Les Déshérités se font de plus en plus audacieux, $N. Ils ont réussi à se coordonner assez pour attaquer le mouillage des Voiles du soleil.$B$BC’est d’autant plus embarrassant que lorsqu’ils ont attaqué, nous avons laissé la plupart de nos armes derrière nous. Récupérez nos armes, que nous puissions montrer à cette racaille qui est le patron.'),
(8482,'frFR','Remettez les Documents compromettants à Aeldon Signesol sur la Place de l''Épervier, dans le bois des Chants éternels.','Les documents compromettants','Les documents contiennent des plans détaillés de différents bâtiments stratégiques du bois des Chants éternels. On y trouve également un croquis assez détaillé d’un sanctum des arcanes. Les abondantes notes qui les accompagnent sont dans une langue que vous ne reconnaissez pas.$B$BTout cela appartenait à un espion darnassien. Tout remettre au capitaine de la garde, Aeldon Signesol, vous semble une bonne idée.'),
(8483,'frFR','Aeldon Signesol, sur la Place de l''Épervier du Bois des Chants éternels, veut la Tête du prospecteur Garde-enclume.','L''espion des nains','Écoutez, $N. La situation est très délicate. Même si nous avons identifié l’espion, nous ne pouvons pas le tuer ouvertement. Impossible également de le capturer, le risque d’évasion est trop grand.$B$BAllez au sanctum septentrional, trouvez le prospecteur Garde-enclume et tuez-le. Procédez discrètement. Nous avons accueilli un espion en notre sein, mais il n’est pas question que cela se sache.$B$BRamenez-moi sa tête comme preuve. Forgefer devra apprendre à ne pas se mêler des affaires des sin’dorei.'),
(8486,'frFR','La telluriste Velania veut que vous tuiez 5 Âmes en peine de mana et 5 Traqueurs de mana.','L''instabilité arcanique','Il était temps que cet idiot borné de Caidanis nous envoie quelqu’un.$B$BJ’avais dit qu’il ne fallait surtout pas augmenter la charge du sanctum occidental ! Maintenant, l’un de nos convertisseurs d’énergie est détruit, et un flot d’âmes en peine arcaniques sort du sanctum ! Avant que nous puissions réparer, il va falloir s’occuper de ces créatures. Faites vite !'),
(8487,'frFR','L''apprentie Mirveda au Sanctum oriental dans le bois des Chants éternels veut que vous récupériez 8 Échantillons de terre contaminée.','Le sol contaminé','Ceci était un sanctum des arcanes entièrement fonctionnel avant qu''Arthas et son armée d''abominations du Fléau ne décident de le dévaster en se dirigeant vers Lune-d’Argent.$B$BIl nous est à présent aussi peu utile que n''importe quel endroit de la Malebrèche. La terre est contaminée, elle attire les Morts-vivants et l''énergie des lignes telluriques est complètement perturbée.$B$BCe que je veux savoir, $N, c''est si la contamination est réversible ou pas. Je veux que vous collectiez des échantillons de terre de cette zone afin que je puisse les étudier. Peut-être qu''avec le temps, nous pourrons ramener les choses à la normale.'),
(8488,'frFR','Parlez à l’Apprentie Mirveda, puis protégez-la de l’embuscade du Fléau.','Des résultats inattendus','Quelque chose ne va pas, $N. Je sens la présence du Fléau. Préparez-vous à l''affronter !'),
(8489,'frFR','Apportez le Convertisseur arcanique intact à la telluriste Velania.','Un convertisseur intact','Cet objet semble être l''un des convertisseurs arcaniques dont la telluriste Velania a parlé. Il n''a pas été endommagé par le feu, peut-être qu''il pourrait lui être utile.'),
(8490,'frFR','Placez le Cristal infusé contre la Pierre runique de l''est et protégez-le du Fléau pendant 1 minute. Rapportez le Cristal infusé au garderune Deryan dans le bois des Chants éternels pour recevoir votre récompense.','Renforcer nos défenses','D’antiques pierres runiques activaient autrefois une barrière protectrice le long de la frontière des Chants éternels. Nombre d’entre elles ont été détruites durant l’attaque d’Arthas ; d’autres ont été dérobées.$B$BSur les trois qui restent, celle-ci est la seule à avoir conservé ses pouvoirs. La pierre runique située à l’est est cependant peut-être récupérable.$B$BPrenez ce cristal et transférez son énergie à la pierre runique de l’est. Le transfert ne devrait pas prendre plus d’une minute. Restez tout de même sur vos gardes, car cela va attirer les créatures du Fléau aux alentours. Ne les laissez pas le détruire !'),
(8491,'frFR','Velan Brillechêne à Brise-Clémente dans le bois des Chants éternels veut que vous lui apportiez 6 Fourrures de Preste-patte.','Récupérer des fourrures','Les Preste-pattes qui peuplent la région sont renommés pour la qualité de leur fourrure. Nous avons même vu des racailles d''Elfes de la nuit voyager jusqu''ici rien que pour braconner !$B$BNos escarmouches avec les Amani pèsent sur nos réserves d''équipement et nos forestiers n''ont pas beaucoup de temps pour chasser. Si vous vouliez bien nous aider à collecter des fourrures de preste-pattes, j''aurais le plaisir de vous récompenser avec une pièce d''armure artisanale. Au nord d’ici, les bois regorgent de traqueurs Preste-pattes.'),
(8531,'frFR','Rapportez 50 Pierres du Magma roussies au commandant Fortmartel, à l’aérodrome de Dun Morogh.','L''Alliance a besoin de plus de pierres du Magma roussies !','Merci de revenir me voir, $N. Si vous en avez le courage, vous et vos amis, j’ai besoin que vous retourniez au Cœur du Magma pour récupérer d’autres pierres du magma roussies. Qu’en pensez-vous ?'),
(8547,'frFR','Apportez le bon-cadeau de la place de l’Épervier à Marsilla Aubétoile, place de l’Épervier.','Bienvenue !','Bienvenue dans le monde de World of Warcraft !$B$BPour vous remercier d’avoir acheté l’édition Collector de World of Warcraft, allez voir Marsilla Aubétoile sur la place de l''Épervier, et présentez-lui ce bon. Elle vous offrira un petit compagnon qui vous accompagnera dans vos quêtes d’aventure et de gloire.$B$BMerci encore, et bon séjour dans World of Warcraft !'),
(8563,'frFR','Parlez à l’invocateur Teli’Larien, le maître des démonistes, à l’intérieur de la Flèche solaire de l’île de Haut-Soleil.','La formation de démoniste','Ne manquez pas de profiter de l’entraînement d’un maître si vous voulez progresser dans votre classe. Les jeunes démonistes de l’île de Haut-Soleil sont formés par l’invocateur Teli’Larien. Parlez-lui et voyez ce qu’il peut vous apprendre. Tout ce qu’il enseigne a un coût, n’oubliez donc pas d’emporter un peu d’argent.$B$BComme tous les maîtres de l’île de Haut-Soleil, Teli’Larien se trouve à l’intérieur de la Flèche solaire, au rez-de-chaussée.'),
(8564,'frFR','Parlez à la matrone Arène, le maître des prêtres, à l’intérieur de la Flèche solaire de l’île de Haut-Soleil.','La formation de prêtre','Ne manquez pas de profiter de l’entraînement d’un maître si vous voulez progresser dans votre classe. Les jeunes prêtres de l’île de Haut-Soleil sont formés par la matrone Arène. Parlez-lui et voyez ce qu’elle peut vous apprendre. Tout ce qu’elle enseigne a un coût, n’oubliez donc pas d’emporter un peu d’argent.$B$BComme tous les maîtres de l’île de Haut-Soleil, la matrone Arène se trouve à l’intérieur de la Flèche solaire, au rez-de-chaussée.'),
(8884,'frFR','Collecter 8 Têtes de Murloc sinistrécaille et retourner voir Hathvelion Miresoleil dans le bois des Chants éternels sur le piton qui domine le Rivage paisible.','Des têtes de poisson à la pelle','Salutations, $C. Regardez vers la côte ; que voyez-vous ? En effet, notre plage... notre Rivage paisible, est infestée de cette nuisance connue sous le nom de Murlocs.$B$BNous devons la libérer de cette plaie !$B$BJ''ai une tâche à vous confier. Si vous pensez être à la hauteur, je souhaite avoir leurs têtes ! Voyons si nous parvenons à suffisamment réduire leur nombre pour qu''ils retournent dans les profondeurs troubles d''où ils sont venus, s''ils sont un tant soit peu raisonnables !'),
(8885,'frFR','Récupérez l''Anneau de Mmmrrrggglll sur la patte sans vie du chef des Sinistrécaille. Rapportez-le à Hathvelion Miresoleil dans le bois des Chants éternels sur le piton surplombant le Rivage paisible.','L''anneau de Mmmrrrggglll','Les Murlocs sinistrécaille n''ont pas été effrayés par vos efforts. Mais je crois savoir ce qui leur ferait plier bagage, et me donnerait l''occasion de me venger par la même occasion.$B$BIls ont un chef murloc qui se donne le nom de Mmmrrrggglll. Il parcourt la Grève dorée au sud du fleuve. Cette bête a un jour tué l''un de mes compatriotes et porte maintenant son anneau pour nous défier et se moquer de nous.$B$BExécutez Mmmrrrggglll et rapportez-moi l''anneau de mon ami. Voilà qui devrait suffisamment intimider ces monstres !'),
(8886,'frFR','Récupérez 6 caisses de la Cargaison du capitaine Kelisendra et rapportez-les à cette dernière au camp protégé juste à l''est du mouillage des Voiles du soleil dans le bois des Chants éternels.','Les pirates Sinistrécaille !','Heureusement que vous êtes là, $C ! Ces répugnants Murlocs sinistrécaille ont volé ma cargaison ! Comme si ça ne suffisait pas que les Déshérités aient pris le peu de marchandises magiques que j''avais, les Murlocs ont pris le reste ! Qu''est donc devenu cet endroit ?$B$BPourriez-vous récupérer ma cargaison ? Je ne m''attends pas à ce que vous puissiez tout rapporter, mais au point où j''en suis, je vous serais reconnaissante pour la moindre part. C''était ce groupe de Murlocs sinistrécaille dans les huttes juste à l''ouest et au sud du mouillage de la Grève dorée, j''en suis certaine !'),
(8887,'frFR','Rendez les Portulans perdus du capitaine Kelisendra à cette dernière au camp protégé, juste à l''est du mouillage des Voiles du soleil dans le bois des Chants éternels.','Les portulans perdus du capitaine Kelisendra','Intéressant… vous avez trouvé un tube de cuir étanche contenant un certain nombre de feuilles de parchemin. Il s’agit de toute évidence de cartes marines, et elles portent toutes la signature d’un certain capitaine Kelisendra.$B$BVous avez entendu parler d’un petit camp fortifié, juste à l’est du mouillage des Voiles du soleil. Le capitaine y est peut-être ?'),
(8888,'frFR','Parler à l''apprentie Loralthalis près de la Flèche de Ternesoir dans le bois des Chants éternels.','L''apprentie du magistère','$C, écoutez ma requête. Pour des raisons que je ne peux donner pour l''instant, j''ai décidé de fermer mon école, qui se trouve près d''ici. Il y a quelques jours, j''ai envoyé là-bas l''une de mes élèves, l''apprentie Loralthalis. Je n''ai cependant pas eu de ses nouvelles depuis.$B$BPourriez-vous s''il vous plaît vous rendre à la Flèche de Ternesoir et vous assurer qu''elle va bien ? Pour cela, dirigez-vous vers le nord à la sortie de la retraite des Pérégrins, puis allez à droite à l''embranchement.$B$BMerci.'),
(8889,'frFR','Désactiver les 3 Sources d''énergie de la Flèche de Ternesoir à l''intérieur de la flèche de Ternesoir. Puis rapporter le Joyau de désactivation à l''apprentie Loralthalis dans le bois des Chants éternels.','Désactiver la flèche','Comme vous le savez peut-être déjà, le magistère Ternesoir m''a envoyée pour désactiver les sources d''énergie qui alimentent la Flèche. Il y en a trois, chacune à un endroit différent à l''intérieur.$B$BMalheureusement, comme vous pouvez le constater, on dirait que je suis arrivée trop tard, et la flèche de Ternesoir est envahie d''étranges créatures magiques. Je n''ai pas les compétences pour mener à bien cette tâche, mais $Gun:une; $C comme vous pourrait sûrement le faire facilement, non ?'),
(8890,'frFR','Retourner voir le magistère Ternesoir à la retraite des Pérégrins dans le bois des Chants éternels.','Une communication de la flèche','$N, j''ai une dernière faveur à vous demander. Voudriez-vous tenir au courant de ce qui s''est passé ici le magistère Ternesoir à la retraite des Pérégrins ? Dites-lui que je vais bien, mais surtout faites en sorte qu''il sache que certains apprentis sont devenus des Déshérités.$B$BMerci pour votre aide !'),
(8891,'frFR','Rapporter le Journal du magistère Ternesoir au magistère Ternesoir à la retraite des Pérégrins dans le bois des Chants éternels.','Des recherches abandonnées','Vous avez découvert ce qui semble être un journal de recherches, laissé là par le magistère Ternesoir. Un bref examen de son contenu vous révèle de choquantes tentatives de filtration de flux magiques corrompus, ce qui pourrait expliquer ce qui s''est passé ici à la flèche de Ternesoir. Il est certain que le magistère voudrait qu''on le lui rapporte.'),
(8892,'frFR','Tuez 5 Nervis déshérités et 5 Voyous déshérités, puis allez faire votre rapport au forestier Degolien au bois des Chants éternels.','La situation au mouillage des Voiles du soleil','Le mouillage des Voiles du soleil a été conquis par des vermines de Déshérités. Dès que nous aurons des renforts, nous montrerons à ces brutes qui est le patron, $N.$B$BDans l’intervalle, ralentissez-les donc un peu tout en leur apprenant un peu de discipline. Allez-y, et montrez-leur qu’on ne se moque pas de nous impunément. Vous trouverez le mouillage des Voiles du soleil juste à l’ouest du village de Brise-clémente.'),
(8894,'frFR','Tuez 6 Serpents de mana et 6 Fieléthers, puis retournez voir le paysagiste Wyllithen, sur les Terres de Ternesoir, dans le bois des Chants éternels.','Corvée de nettoyage','C’est affreux ! Affreux ! Il se passe des choses étranges à la flèche, le magistère et ses apprentis s’enfuient, et juste après, voilà que tout le domaine est infesté de bestioles magiques ! Et qui s’est donné la peine de prévenir ce pauvre Wyllithen ? Personne, voilà qui !$B$BIl va falloir que vous m’aidiez à faire disparaître ces monstres, $C… Je ne peux pas entretenir le domaine avec ces « anomalies » qui galopent dans tous les coins !'),
(8895,'frFR','Remettre la Lettre sans marque au telluriste Caidanis, au Sanctum septentrional du bois des Chants éternels.','Une livraison au sanctum septentrional','Il est bon de découvrir que vous êtes au moins modérément $Gcompétent:compétente;, $N. Et comme vous semblez très $Gdésireux:désireuse; de faire vos preuves, je vais vous confier une autre tâche.$B$BVoici une lettre pour le telluriste Caidanis, l’arcaniste qui veille à ce que le sanctum septentrional continue à fonctionner. Lorsque vous quittez la place de l''Épervier, allez au sud-ouest et vous le trouverez. C’est une personne très importante. J’espère que vous ne l''importunerez pas trop avec des bavardages inutiles.'),
(8896,'frFR','Trouvez et tuez le prospecteur Garde-enclume au Sanctum septentrional, puis faites votre rapport à Aeldon Signesol, dans le bois des Chants éternels.','L''espion des nains','Vous êtes $Gsûr:sûre; que vous avez trouvé ces notes sur un elfe de la nuit ? Elles sont presque entièrement rédigées dans la langue des nains…$B$BLe prospecteur Garde-enclume ! Il nous est arrivé de Forgefer en mission diplomatique. J’aurais dû me douter qu’il s’intéressait d’un peu trop près à nos sanctum arcaniques. $N, il se trouve au sanctum septentrional. Trouvez-le et occupez-vous de lui. Discrètement.'),
(9030,'frFR','Allez voir Deliana à Forgefer.','Les adieux d''Anthion','L’âme de Valthalak était conservée dans cette amulette.$B$BAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.$B$BLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.$B$BQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !'),
(9031,'frFR','Allez voir Mokvar à Orgrimmar.','<TXT>Les adieux d''Anthion','L’âme de Valthalak était conservée dans cette amulette.$B$BAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.$B$BLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.$B$BQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !'),
(9251,'frFR','Anachronos, aux grottes du temps en Tanaris, veut la Tête d’Atiesh et le Talon d’Atiesh.','Atiesh, le grand bâton souillé','Vous vous demandez pourquoi vous êtes encore en vie. Après tout, vous avez en votre possession un objet hautement maléfique. La réponse est incertaine, $N. Je ne fais que ce que je dois.$B$BKel’Thuzad trône à Naxxramas, d’où il tisse ses complots... Il recherche ce que vous possédez et il possède ce que vous recherchez.$B$BEn ce qui concerne le talon du bâton, le nain Brann Bronzebeard le détenait quand il est entré dans Ahn’Qiraj. Il n’y est plus mais le talon du bâton y est resté.$B$BSi vous parvenez à en récupérer les morceaux, rapportez-les-moi.'),
(65593,'frFR','Apportez les Cœurs d’Avelina Lilly et d’Isaac Pearson à Carendin Halgar dans le Temple des Damnés.','Les cœurs des amoureux','Les incubes sont attirés par les cœurs des amoureux, en particulier par ceux qui se languissent l’un de l’autre.$B$BNous ne pourrions pas rêver mieux que les deux cœurs révélés par mes sorts de divination.$B$BDans la forêt des Pins argentés, Avelina Lilly habille les sorciers du Moulin-de-l’Ambre. Et dans les Tarides, Isaac Pearson espère se faire un nom dans la ville côtière de Ratchet.$B$BLe monde les sépare et pourtant, leurs cœurs se désirent ardemment. Remettez ces cœurs à Carendin.'),
(65597,'frFR','Utilisez les Cœurs des amoureux pour invoquer et soumettre un incube, puis rapportez les Cœurs des amoureux à Carendin Halgar, dans le Quartier de la magie d’Undercity.','Le lien','L’heure est enfin venue. Apportez les cœurs dans le cercle d’invocation, placez-les au centre et appelez l’incube.$B$BLe démon ne sera guère enchanté d’être tombé dans un piège, mais ne succombez pas à ses charmes, $N. Vous devrez en faire votre serviteur.$B$BJe vous apprendrai ensuite le sort qui le liera à votre volonté.'),
(65601,'frFR','Parlez à Magar, à Orgrimmar.','Les affres de l’amour','Un Sayaad mâle est un incube, une créature machiavélique à l’esprit très singulier. Ce démon ne vient dans notre monde que sous l’influence de la convoitise, par exemple attiré par un objet représentant l’amour et la dévotion. Si vous acceptez de vous laisser guider par un aveugle, écoutez-moi, $N : à la Herse d’Orgrimmar, à l’est de la faille de l’Ombre, se trouve Magar. Il attend le retour de son compagnon, Krilge. Allez lui parler. Il vous enverra à la recherche de quelque chose de précieux. Telle est la clé que vous devrez apporter à Gan’rul.'),
(65602,'frFR','Récupérez la Figurine en bois et rapportez-la à Gakin le Tisse-noir, au Quartier des mages de Stormwind.','Qu’est-ce que l’amour ?','Seul un composant puissant vous permettra d’attirer un incube. Il vous faut un objet incarnant tout à la fois l’amour et la dévotion. En scrutant les brumes du temps, j’ai repéré une figurine adaptée à votre rituel. Elle appartenait à un jeune couple ayant vécu il y a plusieurs millénaires. S’ils sont morts depuis longtemps, ce souvenir de leur histoire a survécu jusqu’à aujourd’hui. Suivez la route du nord jusqu’en Ashenvale, puis partez vers l’ouest. Passé le poste de Maestra, vous trouverez une maison nichée au milieu des arbres où vous attend l’artéfact dont vous avez besoin.'),
(65603,'frFR','Utilisez la Figurine en bois pour invoquer et asservir un incube, puis rapportez l’objet à Gakin le Tisse-noir à l’Agneau assassiné.','Le lien','L’heure est venue. Prenez la figurine et descendez dans les cryptes, où vous la placerez au centre du cercle d’invocation préparé à cet effet. Vous ouvrirez ainsi un portail permettant à un incube de passer dans notre monde. Prudence toutefois, car le Sayaad vous attaquera dès qu’il aura flairé le piège. Vous allez devoir déployer toutes les compétences que vous avez acquises pour le vaincre. Si vous réussissez, revenez et je soumettrai la créature à votre volonté. Dans le cas contraire, vous pourrez dire adieu à votre âme.'),
(65604,'frFR','Utilisez l’Écharpe flétrie pour invoquer et asservir un Incube, puis rapportez-la à Gan’rul Bloodeye, à Orgrimmar.','Le lien','Oui… Je vois. Je perçois les émotions résiduelles prises au piège de la trame. L’amour imprègne chacun de ces fils. L’incube sera incapable de résister. Apportez l’écharpe au cercle d’invocation de la tente de Neeru, $N. Appelez un incube maléfique, puis prouvez-lui votre supériorité, car il ne se laissera pas dominer aisément. Au contraire, préparez votre magie et attendez-vous à un combat acharné. De nombreux démonistes ont commis l’erreur fatale de sous-estimer un démon, ne les imitez pas. Une fois la créature vaincue, rapportez-moi l’étoffe. Et je raconterai tout à Magar.'),
(65610,'frFR','Explorez le Lac Tombeciel en Ashenvale et rendez compte de vos découvertes à Gan’rul Bloodeye, à Orgrimmar.','Comme tu me manques','J’ai rencontré Krilge alors que je travaillais de l’étoffe lunaire en Ashenvale. Il était en poste là-bas, pour protéger les civils de tout danger… jusqu’à sa disparition… Ses collègues ont mis un terme aux recherches, et il est accusé de désertion, mais je n’en crois pas un mot. Nous nous donnions souvent rendez-vous au lac Tombeciel, avant que l’endroit ne grouille de bêtes agressives. Je ne suis pas du genre à quémander des services, mais ma gratitude vous sera acquise si vous décidez de vous rendre en Ashenvale afin de retrouver sa trace.'),
(76156,'frFR','Faufilez-vous dans la mine de la KapitalRisk au sud-est des Pitons du Tonnerre et récupérez 5 charges excavatrices d’hydroglycérine dans les chariots de fournitures, puis retournez voir Boarton Ombre-Totem aux Pitons-du-Tonnerre.','La traque de la Terre-Mère','Je sens que vous possédez un talent caché pour la subtilité, $Gchaman:chamane;. Utilisez ce masque pour infiltrer la mine voisine de la KapitalRisk et voler des provisions. Le déguisement ne sera peut-être pas convainquant, mais un voleur ou une voleuse de talent peut échapper aux gardes avec un sourire conquérant et une diversion bien choisie. Je pense que vous en êtes également capable.'),
(76160,'frFR','Ramassez 8 pommes de Furie des vents au nord des Pitons-du-Tonnerre, utilisez-les avec le mortier et le pilon, puis rapportez le résultat à Boarton Ombre-Totem.','La traque de la Terre-Mère','Je m’adresse à vous depuis l’avenir, alors que la Horde affronte des périls que vous n’imaginez pas. Puisque les autres ne peuvent pas me voir, je compte sur vous pour apprendre mes techniques et les transmettre à la tribu. Votre talent porte peut-être sur le poison plutôt que sur les déguisements. Les harpies au nord nichent dans un arbre qui produit une résine à la toxicité puissante. Ramassez les pommes de résineux tombées autour des nids, puis broyez-les pour produire un onguent. Appliqué sur une lame, cet onguent brûlera les blessures de votre adversaire et transformera son sang en sel.'),
(76240,'frFR','Acheter ou attrapez un goujon brillant cru, puis utilisez l’ensemble de couteaux pour lever ses filets devant Boarton Ombre-Totem à Thunder Bluff.','La traque de la Terre-Mère','J’ai une dernière idée qui pourrait nous amener au succès. Je pense encore que vous cachez un certain talent, mais essayons de le révéler de manière moins directe. Allez vous procurer un goujon brillant cru, puis rapportez-le-moi. Utilisez ces dagues pour le nettoyer et lever ses filets. Ne réfléchissez pas trop, faites ce qui vous vient naturellement.'),
(78091,'frFR','Récupérez 14 sels d’invocateur sur les invocateurs Rochenoire des Carmines, puis retournez voir Ursula Deline à Hurlevent.','Avec une pincée de sels','Je vais étudier l’orbe, et je vous dirai ce que je découvrirai. Mais d’abord, vous devrez faire quelque chose pour moi. Les démonistes du clan Rochenoire utilisent des sels spéciaux pour renforcer leurs rituels d’invocation. Récupérez-en sur les orcs des Carmines. À votre retour, je vous ferai part du résultat de mes études.'),
(79008,'frFR','Vous n’avez pour vous guider que ce qui reste de la note calcinée.','… et cette note que vous avez trouvée','La lueur sourde des braises s’amenuise et vous arrivez sur les restes d’un feu récent. Parmi les provisions éparses, vous trouvez une note roussie. « Tout ce qui brûle n’est pas perdu. Trouvez la terre jumelle, trouvez le lieu. »'),
(79192,'frFR','Vous arrachez la note de la planche et lisez le reste du message.','Tort-tue','Le message commence par ces mots : « D’après la mission, ils accomplissaient tous les deux des livraisons pour le compte de la Peste nouvelle. Pour moi, ça a plutôt l’air de simples accidents d’un apothicaire. Trouvez mon petit nid douillet dans les montagnes, entre les Tarides et Désolace, si vous voulez discuter tranquillement. »'),
(79360,'frFR','Bien que de nombreux résidents et résidentes des Mille pointes soient nos ennemis, nous ne pouvons pas rester les bras croisés et les regarder être emportés par les flots. La note était claire : ils prévoient de lever une armée de morts-vivants dans la foulée, ce qui risque de tous nous menacer.$B$BNous sommes démunis pour y faire face, mais j’ai entendu parler d’un chaman des royaumes de l’Est qui maîtrise l’imprégnation élémentaire des armes, il pourrait peut-être nous venir en aide.$B$BTrouvez ce chaman et demandez-lui son aide.','Soutien élémentaire','J’ai entendu parler de Hirzek et de la barbarie avec laquelle ils manipulent les éléments.$B$B<Les yeux de Rau errent tandis qu’il étudie la note et il se parle à lui-même à haute voix.>$B$BLa tempête fera rage, le sol grondera et la marée montera…$B$B<Ses yeux, fixés sur vous, se dilatent au fur et à mesure qu’il prend conscience de la situation.>$B$BIls doivent utiliser un cruel sortilège qu’ils ont appris auprès de Hirzek. Ils prévoient d’inonder le canyon pour tous et toutes nous relever dans la non-mort.$B$BPour atteindre leur objectif, je crains qu’ils n’aient besoin de pouvoirs élémentaires dévastateurs.'),
(79361,'frFR','Collectez 5 essences tourbillonnantes sur des tourbillons élémentaires en Désolace et apportez-les à Bath’rah la Vigie des vents dans les montagnes d’Alterac.','La puissance du vent','Une tempête de cette taille nécessitera la puissance du vent pour se répandre sur la terre. Quel que soit ce rituel, on doit vous protéger contre cet élément.$B$BLes élémentaires tourbillonnants ont ravagé Désolace et sont l’un des seuls éléments encore capables de l’habiter. Apportez-moi leur essence.'),
(79362,'frFR','Collectez 5 essences grondantes sur des élémentaires de roche dans les terres Ingrates et apportez-les à Bath’rah la Vigie des vents dans les montagnes d’Alterac.','La puissance de la terre','Pour faire trembler le sol, il faut un lien solide avec la terre. Les terres Ingrates sont remplies de pierres et de rochers durcis par le temps. Des incarnations de la terre parcourent la région et s’y sentent chez elles.'),
(79363,'frFR','Collectez 5 essences impétueuses sur des élémentaires de flétrissure dans le marécage d’Âprefange et apportez-les à Bath’rah la Vigie des vents dans les montagnes d’Alterac.','La puissance de l’eau','Le pire, c’est l’inondation. Ce canyon est sec et l’eau peut couler pendant des jours sur ce sol dur et craquelé, et alors au revoir tout le bassin.$B$BJe connais peu d’élémentaires qui possèdent ce type de pouvoir, mais…$B$B<Bath’rah vous regarde avec un sourire narquois.>$B$BVous savez que j’assure vos arrières, $Gfrère:sœur;.$B$BVous devez aller dans les bourbiers du marécage d’Âprefange. C’est pas vraiment des élémentaires d’eau, mais ces flétrissures ont leurs petits secrets.'),
(79364,'frFR','Vous pensiez pas que j’allais fabriquer une arme de fou rien que pour vous ? Non, non, mon $Gami:amie; c’est une potion de protection.$B$BCombattre le feu par le feu, c’est pas toujours la bonne approche, $Gmon:ma; pote.$B$BApportez une fiole de cristal à Bath’rah la Vigie des vents dans les montagnes d’Alterac.','Un simple contenant','Bravo, $Gmon:ma; pote. Je sais pas à quoi vous devez faire face dans les Mille pointes, mais voilà qui vous protégera sûrement contre les éléments qui menacent la région.$B$B<Bath’rah commence à fouiller dans ses affaires, et vous le voyez légèrement frustré. Il cherche de plus en plus vite avant de lever les yeux vers vous d’un air penaud.>$B$BJ’ai encore besoin d’un truc de votre part.$B$B<Son sourire se creuse et il reprend la parole.>$B$BOn dirait que j’ai perdu mes fioles à potions…'),
(79974,'frFR','Vous époussetez une besace qui dépasse de la terre et trouvez un parchemin au milieu des provisions.','Travail humide','J’aime garder des vivres à proximité, au cas où je devrais fuir de manière urgente. Ce versant est si beau, on croirait presque qu’il a été sculpté dans les cascades du temps. C’est le nid de l’aigle, c’est ce que vous cherchez.'),
(79975,'frFR','Les embruns saturent l’air, et le panorama est saisissant.','Le poing de l’aigle','Vous trouvez dans la caisse à outils une lettre soigneusement pliée. En imaginant la voix de son auteur, vous lisez : « D’ici, avec les bons outils, vous pourrez tout contrôler. Excellent endroit pour lancer un planeur à parachute. Ma loyauté envers l’Aigle et le Poing m’impose de prendre des distances pour les servir au mieux. Cette barricade a connu des jours meilleurs, comme les Vieux royaumes qu’elle défendait autrefois, mais je ne l’abandonnerai jamais ».'),
(79976,'frFR','Vous avez raté de peu la personne qui se trouvait ici.','Ça doit être ici','« J’ai décidé de retourner travailler sous terre. Pour que mon œuvre ne tombe plus entre de mauvaises mains. » Le papier a été déchiré au plus près du message. Vous ne savez pas s’il s’agit des derniers mots que l’auteur aura laissés ou d’un indice pour trouver son repaire suivant. Un sac de couchage mal fixé se déroule tout seul jusque sur vos pieds…'),
(79980,'frFR','Trouvez ce qui vous attend.','Décaniller','Pas mal, hein ? Si vous lisez ça, ça veut dire que mon trésor est toujours là quelque part. Faites cent pas vers le nord et vous cassez pas les chevilles en descendant la pente. Vous devriez avoir de quoi faire.')
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`) VALUES
(90,'frFR','Récupérer 10 Steaks de loup et des Herbes aromatiques de Stormwind, puis retourner voir le chef Grual à Darkshire.','La spécialité de la maison est le kébab de loup assaisonné. Bien sûr, je peux vous en faire ! Mais j''ai besoin de différents ingrédients. Apportez-moi 10 Steaks de loup ainsi qu''un peu d''Herbes aromatiques de Stormwind. Il y a tellement de loups dans la forêt que cela ne devrait pas être un problème pour trouver la viande. Pour ce qui est des herbes, allez donc voir Felicia Gump, la fleuriste du quartier du canal à Stormwind.'),
(138,'frFR','Trouver le Tonneau à côté des cheminées en ruine. Le fouiller pour trouver l''indice suivant.','L''indice que vous trouvez est le suivant : « Bon travail, matelot ! Maintenant il va falloir cingler vers l''est. À l''est, vers le haut des falaises, à l''est vers la route. Cherchez les ruines des vieilles cheminées, au bord de la route. Là, vous trouverez un vieux tonneau qui contient l''indice suivant. »'),
(139,'frFR','Chercher la Cruche vide à côté du moulin à vent pour trouver le prochain indice.','En fouillant le tonneau, vous découvrez un autre parchemin. Il y est écrit : « À partir de ce tonneau, tournez-vous vers le nord. Marchez droit comme une bande de cadets qui va au réfectoire, jusqu''à ce que vous voyiez la cruche vide, à côté du moulin à vent solitaire, sur les falaises. Si vous farfouillez autour de cette cruche, vous pourrez bien trouver ce que vous cherchez. »'),
(140,'frFR','Localiser le Coffre au trésor du capitaine Sanders et prendre votre récompense.','Bien vu ! Il y a un autre indice au fond de la cruche. L''encre a coulé par endroits et le papier sent le whisky, mais vous arrivez à reconstituer une partie du texte. « Maintenant que vous avez trouvé la vieille cruche de whisky, vous êtes presque au trésor ! Tournez-vous vers l''ouest et descendez vers le rivage. Ne vous arrêtez pas au bord de l''eau, continuez ! Nagez vers l''ouest jusqu''à l''île où se trouve mon coffre au trésor ! »'),
(289,'frFR','Tuer 13 Marins maudits, 5 Soldats de marine maudits et le Premier Officier Snellig. Rapporter la Tabatière de Snellig au Premier Officier Fitzsimmons au port de Menethil.','<Revigoré, Fitzsimmons continue son histoire...>$B$BJe suis le seul survivant de l''infortunée IIIe flotte de Kul Tiras, détruite au large de la côte, vers le nord. Mais bien que je sois le seul membre d’équipage qui respire toujours, je ne suis pas le seul qui marche encore ! Car sur l''un de nos bateaux a été caché un trésor épouvantable, dont le pouvoir énorme maintient prisonnières les âmes de mes frères d''armes dans les épaves pourries de nos bateaux.$B$BMais si vous parveniez à libérer quelques-uns de mes frères, peut-être pourriez-vous briser la malédiction.'),
(293,'frFR','Apporter l''Oeil maudit de Paleth à l''archevêque Benedictus, à la cathédrale de la Lumière de la ville de Stormwind.','Je ne peux pas lever la malédiction de l''Oeil de Paleth. Ces Yeux ont été fabriqués par des prêtres humains, vous devez donc aller à Stormwind pour trouver quelqu''un qui pourra vous aider. Allez voir l''archevêque Benedictus, le maître de la cathédrale de la Lumière de Stormwind. Il vous aidera.$B$BJe l''espère pour vous.'),
(295,'frFR','Tuer 10 Faucheurs tachetés et 10 Tranchegueules tachetés pour Ormer Ironbraid, puis aller le voir à l''excavation de Whelgar.','Il est vraiment temps de faire payer à ces raptors leur soif sanguinaire. Un peu plus bas, il y a d’innombrables Faucheurs tachetés et Tranchegueules tachetés. Tuez 10 Faucheurs et 10 Tranchegueules !'),
(303,'frFR','Sur ordre de Motley Garmason à Dun Modr, tuer 15 nains Sombrefer : 5 Tunneliers Sombrefer, 5 Saboteurs Sombrefer et 5 Démolisseurs Sombrefer.','La guerre fait rage ici autant qu''à l''étranger. Tandis que nos valeureux nains donnent leur vie loin de chez eux au nom de l''Alliance, nos propres terres sont la proie des nains Sombrefer. Ils ont eu raison du viaduc de Thandol. Dun Modr est tombée peu après.$B$BNous avons besoin de vous pour reprendre des forces et repousser le front. Si vous pouvez tuer 15 nains Sombrefer, 5 Tunneliers, 5 Saboteurs et 5 Démolisseurs, nos réservistes pourront être là à temps pour conduire l''offensive.$B$BFaites vite !'),
(358,'frFR','Tuer des Profanateurs Poils-putrides et des Gnolls Poils-putrides.$B$BRapporter les Ichors d''embaumement au magistrat Sevren à Brill.','Dans le nord, les fosses communes, au sud-ouest de l''antre de Garren ont été construites pour accueillir les morts de Tirisfal lorsque la Peste frappa la première fois.$B$BLes corps qui s''y trouvent ont pu reposer en paix jusqu''ici mais le Fléau a envoyé des gnolls Poil-putride prendre les corps afin de les utiliser pour accroître leurs armées. Cela ne doit pas être !$B$BVotre mission comporte deux parties : tuer les Poils-putrides dans les fosses communes et dans l''Antre de Garren et récupérer sur eux l''ichor d''embaumement qui leur donne vie.'),
(429,'frFR','Recueillir six Cœurs de worg et les apporter à l''Apothicaire Renferrel au Sépulcre.','Mon frère Quinn a été gravement blessé par la goule Ivar l''Infect et je doute qu''il puisse guérir sans l''aide de la magie. Bien que je ne sois pas spécialiste de ces choses, je sais que nos Apothicaires savent concocter des remèdes à partir de cœurs décolorés de worgs.$B$BRecueillez quelques-uns de ces cœurs et portez-les à l''Apothicaire Renferrel au Sépulcre, au sud. Revenez ensuite avec la potion.$B$BVous trouverez des meutes de worgs entre ici et le verger de Malden, plus à l''est.'),
(484,'frFR','Collecter 4 Peaux de jeune crocilisque, pour James Halloran, au port de Menethil.','Je suis James Halloran, le tanneur. Mes peaux de crocilisque traitées sont prisées dans le monde entier.$B$BVous connaissez Einar ? C’est l’un des chasseurs qui m''approvisionne en peaux.$B$BJe suis en ce moment à court de ces peaux soyeuses qui proviennent des jeunes crocilisques.$B$BJe vous paierais grassement si vous pouviez me rapporter quelques-unes de ces peaux. Vous trouverez les jeunes crocilisques dans les marécages, à l’extérieur de la ville.'),
(540,'frFR','Apporter 5 Tomes retrouvés, ainsi que le Livre de cuir usé « Le Bras de Gri''lek » au Maître des traditions Dibbs, à Southshore.','Ces ogres répugnants résident à présent dans les ruines d''Alterac, et je frémis à l''idée de ce qu''ils peuvent faire des précieux livres qui s''y trouvent.$B$BPénétrez dans les ruines d''Alterac et récupérez des tomes sur les ogres. Prenez tout ce que vous trouverez, mais cherchez également le livre suivant : « Le Bras de Gri''lek ». C’est un recueil d’anciennes légendes trolls que je dois lire. Les ruines d''Alterac sont le dernier endroit où se trouve une copie intacte de cet ouvrage.'),
(578,'frFR','Localiser l''Ile hantée pour le baron Revilgaz de Baie-du-Butin.','Si un mage gobelin et des élémentaires d''eau hantent effectivement l''île, cela peut vouloir dire que la Pierre des marées peut être mienne !$B$BJe veux que vous localisiez cette île hantée… Découvrez ce qui s''y passe. Oh ! et si vous voulez en savoir plus sur la Pierre des marées, donnez ce titre à la bibliothèque de Stormwind, ils devraient être capables de vous trouver une copie du livre dans lequel j''ai eu vent pour la première fois de cette légende.$B$BSerait-ce possible que ce Gazban ait vraiment découvert la Pierre... ?'),
(662,'frFR','Le lieutenant Nilzlix veut que vous récupériez les Cartes et les Journaux de bord de la « Folie de la vierge » et de « L''Esprit des Pins argentés ».','O''Breen a conduit les bateaux dans la crique. Nous étions certains d''y trouver le trésor. Le « Noir messager » a accosté sans encombre, mais à mesure que la « Folie de la vierge » et « L''Esprit des Pins argentés » approchaient, le niveau de la mer a commencé à baisser. C''est la chose la plus étrange que j''aie jamais vue !$B$BLes deux bateaux se sont échoués sur quelque chose... Une sorte de temple dans les récifs. Puis ils ont coulé à pic ; une vraie tragédie.$B$BNous voulons récupérer leurs cartes maritimes et leurs journaux de bord avant de partir. Nous ne voulons pas que les autres puissent les récupérer !'),
(695,'frFR','Parler à Skuerto.','Et voilà, $N. Il suffit d''appuyer la gemme sur un des piédestaux près de la base de la tour, et ses défenses s''activeront. Utilisez-la pour rentrer dans la tour quand vous serez $Gprêt:prête; et allez chercher les autres objets de Trelane.$B$BBonne chance à vous ! Je vous attendrai au camp. Oh ! Parlez à Skuerto avant de partir. Il vous donnera tous les détails nécessaires.'),
(736,'frFR','Apporter les objets de la liste de Bel''dugur au Gardien Bel''dugur à Undercity.','Vous avez besoin du « Sommaire de Yagyin » ? Vous projetez donc de réunir une nouvelle cellule ? Bien sûr que c''est le cas... et bien sûr que je vais vous aider, $Gfrère:sœur;.$B$BMais vous devez m''aider aussi.$B$BJ''ai besoin de trois objets de puissance. Apportez-les-moi et je vous donnerai le livre.$B$BJe ne peux pas prononcer leurs noms, mais je peux vous les écrire.$B$BApportez-moi les objets de la liste. Si vous pouvez me les obtenir, alors vous méritez de créer une nouvelle branche de notre ordre.'),
(737,'frFR','Porter le « Sommaire de Yagyin » à Theldurin.','J''ai le livre pour vous, $N. Je n''ai pas besoin de vous prévenir de bien y faire attention. Et de le garder hors de portée de nos ennemis.$B$BCe livre contient de nombreuses vérités...$B$B... Et la vérité peut vous consumer.'),
(754,'frFR','Utiliser le Totem de purification de Winterhoof au puits Winterhoof, puis retourner voir Mull Thunderhorn.','J''ai réalisé le totem pour purifier le puits Winterhoof. Il vous faut maintenant l''apporter au puits et y pratiquer le Rituel de purification. Vous trouverez le puits dans le sud-est, gardé par d''infects gobelins !$B$BCe sera tout sauf une mission facile mais vous devez réussir, si nous voulons un jour pouvoir boire de nouveau l''eau précieuse de ce puits.$B$BBonne chance à vous, $N.'),
(758,'frFR','Utilisez le Totem de purification de Thunderhorn au puits Thunderhorn, puis retournez voir Mull.','Le totem est prêt, $N. Il vous faut encore pratiquer le Rituel de purification.$B$BAllez au puits Thunderhorn, au nord du village et utilisez le Totem de purification de Thunderhorn pour le rituel. Revenez me voir quand cela sera fait.$B$BQue les esprits soient avec vous.'),
(760,'frFR','Utiliser le Totem de purification de Wildmane au puits Wildmane, puis retournez voir Mull Thunderhorn.','Votre purification des puits Winterhoof et Thunderhorn est objet de discussion et de fierté parmi les esprits, jeune $N. Le totem de Wildmane est construit et le devoir vous appelle, encore une fois.$B$BLe puits Wildmane se trouve au nord de Thunder Bluff. Pratiquez-y le rituel ! Débarrassez le pays du poison des gobelins. Que l''eau claire coule de nouveau !'),
(849,'frFR','Détruire la Machine volante à Bael Modan et retourner voir Gann Stonespire.','En suivant les plans de Khazgorm, la fabrication d’une charge explosive ne devrait pas poser de problème.$B$BAh ! Nous y voilà.$B$BÀ présent, $N, je vais vous confier une tâche spéciale. Prenez ce Bâton explosif et utilisez-le pour faire sauter la machine volante à Bael Modan.$B$BNon seulement cette machine est une partie cruciale de l’infrastructure du site, mais elle sert également de machine de guerre. Plus important encore, c''est un symbole de pouvoir et une insulte portée à la mémoire de ma tribu.$B$BFaites ma fierté en concluant cette quête héroïque et vous serez $Grécompensé:récompensée;.'),
(915,'frFR','Aller chercher de la glace à la fraise pour votre protégé. Le gamin semble préférer la marque de glace Aguilor.','DE LA GLACE ! Oh, s’il vous plaaaaîîîîîît, je peux avoir de la glace ?! La glace à la fraise est ma glace préférée, et la meilleure glace à la fraise du monde, c’est celle d’Aguilor ! C’est ma glace préférée dans le monde entier !$B$BJ’en ai mangé il y a longtemps aux courses des Salines, mais il paraît qu’ils en vendent en ville ! S’il vous plaît ? S’il vous plaaaaîîîîîît ? Avec une deuxième boule sur le dessus ??!?!'),
(982,'frFR','Récupérer le Coffret de l’Aube argentée et le Coffret du Voile de brume, pour Gorbold Steelhand, à Auberdine. Ces deux objets se trouvent à bord des épaves des navires respectifs, au nord du village.','Au large de Sombrivage, plus au nord, il y a deux épaves de bateau : l’Aube argentée et le Voile de brume. Il y a quelque temps, ces deux bateaux sont tombés sur ces maudits murlocs, alors qu’ils faisaient voile à travers la vaste mer jusqu’à Auberdine. Ils reposent maintenant au fond des eaux, comme autant de trophées au crédit de ces démons.$B$BLes deux capitaines n’ont pas survécu et leurs journaux de bord et effets personnels sont toujours dans leurs coffrets. Je voudrais que vous les récupériez ; cela serait symboliquement très important pour tous les équipages de cette contrée.'),
(1022,'frFR','Se rendre au Val hurlant et étudier le « Tome de Mel''Thandris », puis retourner voir la Sentinelle Melyria Frostshadow au Sanctuaire d''Aessina.','Bien que nous ayons dépensé beaucoup d''énergie pour repousser les démons encore présents de Gangrebois jusqu''au nord, nous n''avons pas eu beaucoup de succès. Nous avons pu éviter toute présence démoniaque à Ashenvale.$B$BAu nord, près de la frontière de Gangrebois, de mystérieux hommes-loups ont investi le sanctuaire en ruine de Mel''Thandris. Leurs cris sont si terrifiants qu''on a surnommé ce secteur le Val hurlant. Le « Tome de Mel''Thandris » qui est gardé dans le sanctuaire peut faire la lumière sur la raison de la venue de ces hommes-loups.'),
(1029,'frFR','Retourner voir Raene Wolfrunner à Astranaar.','Je vous suggère d''aller trouver Raene pour lui dire que le bâtonnet est terminé. Elle saura vous dire quelle est votre prochaine mission.$B$BBonne chance, $N.'),
(1045,'frFR','Tuer Ran Dent-rouge et 4 Gardes de Dent-rouge, puis retourner voir Krolg près du lac Mystral.','Les elfes de la nuit sont aussi vieux que le temps, mais leur arrogance détruit leur monde même. Et maintenant elle détruit aussi nos vies. Mais on ne peut plus rien contrôler...$B$BJe blâme les elfes pour beaucoup de choses, mais nous sommes toujours responsables de nos actions. Même sans la corruption, nous sommes capables de mauvaises choses.$B$BRan Dent-rouge est de ce genre de créatures démoniaques. La soif de pouvoir, la luxure... La corruption n''a fait qu''aggraver les choses. Je brûle de haine pour les elfes, mais je n''appelle pas la maladie sur leurs enfants, parce que nous devons maintenir l''ordre chez les nôtres.'),
(1049,'frFR','Trouver le « Compendium des Déchus » au Monastère dans les Clairières de Tirisfal et retourner voir le Sage Truthseeker à Thunder Bluff.','Le Cercle terrestre avait des intentions pures envers nos frères tourmentés. Mais qui connaît les motivations de ceux qui chuchotent aux oreilles du Conseil des Anciens ?$B$BLes Réprouvés auxquels nous nous sommes alliés ont un lourd passé de duperie. Notre pacte a été trop hâtif. Peut-être Cairne aurait-il été sage de tenir compte des avertissements d''Orgrimmar.$B$BLe cœur du Monastère écarlate abrite le « Compendium des Déchus », gardé par des humains fanatiques et fous furieux. Ils tirent leur méthode de leur folie, mais leurs recherches pourraient s''avérer utiles.'),
(1050,'frFR','Reprendre « la Mythologie des Titans » au Monastère et le rapporter au Bibliothécaire Mae Paledust à Ironforge.','L''avenir est inévitable ! Nous nous lançons vers lui comme les gouttes de pluie tombent dans la Grande mer.$B$BMais peut-être qu''en étudiant le passé, nous pourrons savoir à quoi nous attendre pour mieux nous préparer.$B$BAvant que Lordaeron ne connaisse ces événements sinistres, il y avait un bastion de connaissance caché dans les Clairières de Tirisfal. La rumeur disait qu''un livre appelé « la Mythologie des Titans » avait été placé dans la bibliothèque du vieux Monastère.$B$BRetrouvez-le et peut-être qu''ensemble nous pourrons découvrir les secrets du passé !'),
(1079,'frFR','Récupérer les Plans d''ingénierie de la KapitalRisk dans la scierie de la Combe des Cisailles.','Ça y est, $N. Faites très attention ! Les dispositifs sont montés et prêts à fonctionner.$B$BPrenez ces explicatifs. Ils résument tout ce qu''il faut savoir sur les détonateurs et les explosifs, et indiquent également où vous devez les placer.$B$BRappelez-vous, le succès de votre mission ne dépend pas de la somme de destruction que vous provoquerez. Le succès du plan A dépend du fait que vous rapportiez les plans d''ingénierie de la KapitalRisk de l''intérieur de la scierie au sud du lac de la Combe.'),
(1136,'frFR','Rapporter la Crinière de Gueule-glacée à Melor Stonehoof à Thunder Bluff.','$N, il est temps pour vous de voyager vers de lointaines contrées. Le moment est venu.$B$BVous devez partir à la poursuite de Gueule-glacée, un yéti des montagnes d''Alterac. Il est très difficile à trouver, car sa fourrure blanche se confond avec la neige de ses montagnes maternelles.$B$BJe vais vous montrer comment attirer une telle créature à découvert. Prenez ce parchemin. Il vous indiquera la manière de débusquer Gueule-glacée.$B$BAllez, maintenant, $N. Votre voyage sera long et plein d''embûches. Votre quête sera accomplie lorsque vous rapporterez la crinière de Gueule-glacée.'),
(1148,'frFR','Apporter 1 Coeur de silithide, 5 Serres de silithide et 3 Carapaces de silithide intactes à Korran, à la Croisée.','Vous inspectez la carapace avec soin. Comme vous la tournez, vous comprenez que le placage est entrecroisé de telle manière qu''elle lui donne une dureté incroyable. Cela ne ressemble à rien que vous connaissiez. Vous inspectez le reste du corps et vous réalisez que ces créatures sont très puissantes et très évoluées.$B$BEn regardant de nouveau la carapace, vous vous dites que Korran apprécierait sûrement d''étudier ces créatures d''un peu plus près. Cela l''aiderait à découvrir ce qu''elles sont et d''où elles viennent.'),
(1160,'frFR','Trouver « Les commencements de la menace des morts-vivants » et le rapporter à Parqual Fintallas à Undercity.','Je vous dirai ce que vous devrez chercher, et je vous poserai même ma question, mais certainement pas parce que vous cherchez à vous prouver quelque chose à vous-même. La Connaissance est bien plus importante que la force. Même si d''autres vous surpassent en habileté, votre connaissance du monde vous sera précieuse.$B$BRendez-vous au Monastère au nord des Clairières de Tirisfal. Dans la bibliothèque, vous trouverez un livre intitulé « Les commencements de la menace des morts-vivants ». Il était utilisé par les paladins, désormais corrompus, pour leur entraînement contre ceux de ma race.$B$BApportez-le-moi.'),
(1194,'frFR','Apporter un Echantillon de Minerai d''Indurium à Pozzik dans les Salines.','Les schémas de Rizzle montrent le processus de raffinage de l''Indurium. D''après ses gribouillages, il apparaît que le minerai provient de la mine des nains d''Uldaman dans les Terres ingrates.$B$BLa plupart des autres notes évoquent ses propriétés de résistance à la chaleur.$B$BCe qui sert de presse-papiers pour les plans est vraisemblablement un gros morceau d''Indurium non raffiné.'),
(1318,'frFR','Trouvez le Gantelet de Puissance Gordok et rendez-le au capitaine Kromcrush à Hache-tripes.$B$BSelon Kromcrush, les histoires des « vieux » racontent que Tortheldrin – un « vilain » elfe qui se fait appeler prince – l’a volé à l’un des rois gordok.','Maintenant qu’z’êtes le roi, p’têt'' qu’vous pourrez récupérez l’objet précieux des Gordok que le sale elfe qui se dit Prince nous a pris. L’roi avant vous a pas réussi, et celui d’avant non plus, et aucun roi depuis que Tortheldrin – c’est le sale elfe – l’a volé à un vieux roi gordok d’il y a longtemps !$B$BC’est le Gantelet de puissance Gordok. Les vieux, ils disent que seul le vrai roi des Gordok pourra le ramener. Et puis, les vieux, ils disent aussi que le sale elfe est toujours là – si vous le trouvez, vous pourrez porter le gantelet de puissance pour toujours ! Ouais ! Je vais vous montrer !'),
(1476,'frFR','Apportez les Cœurs de Dalin Forgewright et de Corma Villard à Carendin Halgar dans le Temple des Damnés.','Forcer une succube à apparaître nécessite des cœurs purs. Mais existent-ils seulement ?$B$BGrâce à quelques fragments d’histoires entendues par-ci par-là, je suis parvenu à trouver deux êtres humains qui devraient faire l’affaire.$B$BLe premier se nomme Dalin Forgewright. Il a consacré sa vie aux réfugiés de Lordaeron, ceux qui sont rejetés par leurs pairs au mur de Greymane.$B$BL’autre s’appelle Corma Villard, une femme restée fidèle à son premier amour et qui arpente les Paluns à sa recherche.$B$BRemettez leurs cœurs à Carendin. Mais auparavant, laissez-moi vous montrer votre cible.'),
(1657,'frFR','Lancer trois Boules puantes des Réprouvés au milieu de Southshore en Hillsbrad, puis revenez voir la sombre imploratrice Yanka à la Fête de l’homme d’osier, aux Clairières de Tirisfal.','Nous allons célébrer la Sanssaint en grande pompe… en en faisant voir de toutes les couleurs à nos ennemis de Southshore !$B$BPrenez l’une de ces boules puantes conçues spécialement pour l’occasion. Elle est remplie d’une substance nauséabonde dont aucun humain - ou aucune bête à l’esprit simple, d’ailleurs - ne peut supporter l’odeur. Il faut la jeter au beau milieu de Southshore pour qu’elle agisse correctement, donc attendez-vous à combattre l’Alliance !$B$BQuand vous aurez accompli cette tâche… cet hommage à notre libération, revenez me voir !'),
(1701,'frFR','Réunir les matériaux dont Furen Longbeard a besoin et lui apporter à Stormwind.','Alors je vous ai donné un bon bouclier, mais on ne va pas s''arrêter là. Je connais le secret pour fabriquer une Cotte de mailles extrêmement résistante. C''est difficile à faire et demande des matériaux très rares, mais si vous voulez faire le travail sur le terrain, alors je vous en fabriquerais une.$B$BQu’en dites-vous, $N ? Vous relevez le défi ? Je vais donc vous donner la liste des éléments dont j''ai besoin et où les trouver.'),
(1712,'frFR','Apporter les objets du Parchemin de Bath''rah à Bath''rah la Vigie des vents à Alterac.','J''ai passé un temps considérable à observer ce site. J''observe… Je verrai peut-être tomber le Grand Cyclonien ! Mais je n''ai toujours pas trouvé un champion pour combattre le Seigneur des vents.$B$BPeut-être est-ce vous ?$B$BProuvez-le moi. Rassemblez les éléments dont j''ai besoin pour invoquer un Cyclonien, et je saurai que vous êtes $Gun grand guerrier:une grande guerrière;. Peut-être pouvez-vous le battre et récupérer son cœur de tourbillon.$B$BSi c''est le cas, alors je transmettrai le pouvoir du cœur dans une arme que je vous donnerai.$B$BVoilà le parchemin qui liste les objets dont j''ai besoin.'),
(1779,'frFR','Prendre le Symbole de vie et parler à Muiredon Battleforge à Ironforge.','Je veux que vous preniez ceci, $N. Cela s''appelle le Symbole de vie.$B$BVous avez montré que vous étiez charitable et $Gpatient:patiente;, maintenant je veux que vous me montriez votre pouvoir et vos talents au combat en tant qu''adepte.$B$BMuiredon, mon mari, a rencontré récemment des nains Sombrefer, et il s''en est sorti de justesse. Il est à Ironforge, aux bons soins d’un de nos prêtres.$B$BPrenez le Symbole et parlez-lui. Si vous pouvez l''aider, alors nous nous reparlerons bientôt. Que la Lumière soit avec vous !'),
(1781,'frFR','Porter le Symbole de vie à Gazin Tenorm à Stormwind.','Je veux que vous preniez ceci, $N. Cela s''appelle un Symbole de vie.$B$BVous avez montré que vous étiez charitable et $Gpatient:patiente;, et maintenant il est temps de savoir si vous avez la puissance nécessaire pour contrôler un des plus grands dons de la Lumière.$B$BMon ami Gazin a croisé récemment des Défias à Elwynn près de la Veillée des héros – il s''en est sorti de justesse. Il est près de l''autel en train de se faire soigner par un de nos prêtres.$B$BPrenez le Symbole et parlez-lui. Si vous pouvez l''aider, alors nous nous reparlerons bientôt. Que votre chemin soit éclairé par la Lumière !'),
(1858,'frFR','Voler la Clé de Tazan puis l''utiliser pour ouvrir sa Sacoche et livrer son contenu à Therzok dans la Faille de l''ombre à Orgrimmar.','Je vous le laisse pour ouvrir la sacoche de Tazan et me rapporter son contenu. Le mécanisme de verrouillage est complexe, ce serait sans doute plus facile si vous trouviez la clé.$B$BComme elle n''était pas sur le corps de Tazan, je ne peux que supposer qu''il a confié la clé à quelqu''un... Oh oui ! C''est ça ! Il avait un aide nommé Gamon. Un ivrogne, vous le trouverez probablement à la taverne. Peut-être que vous pourrez lui prendre la clé en douceur.'),
(1938,'frFR','Apporter le « Traité d''Ur sur la magie de l''Ombre » au Grand Sorcier Andromath à Stormwind.','Autrefois, trois mages étudiaient dans cette tour, jusqu''à ce que l''un d''entre eux tombe dans les travers de la magie noire. On l''a pressé de se détacher de ses travaux maléfiques, mais il n''a pas pu résister. Il fut alors banni.$B$BLe mage renégat a élu domicile dans la tour d''Ilgalar, dans les Carmines, et il a emporté avec lui un livre très puissant : le "Traité d''Ur sur la Magie de l''Ombre".$B$BNous, mages de Stormwind, voulons récupérer ce livre. Volez-le dans la tour d''Ilgalar et rapportez-le.'),
(1944,'frFR','Apporter l''Echantillon d''Eau de Xavian à Deino à Orgrimmar.','La ville légendaire de Xavian est enfouie au plus profond des terres orientales d''Ashenvale et les initiés connaissent bien son histoire. Il est dit que les eaux de Xavian ont des pouvoirs magiques énormes.$B$BJe voudrais un échantillon de ces eaux, pris à la source.$B$BPrenez cette fiole et allez à Xavian. Recueillez de l''eau en bas de la chute la plus haute et rapportez-la-moi. Et prenez garde en vous déplaçant dans la cité ancienne : les satyres se sont installés dans les ruines et ils n''aiment pas que les mages viennent fourrer leur nez dans leurs affaires.'),
(1951,'frFR','Apporter le livre des « Rituels du pouvoir » à Tabetha dans le marécage d''Âprefange.','Hum... Maintenant que j''y pense, je n''ai plus ce livre ! Vous voyez, j''avais quelques dettes de jeu et pour les régler, j''ai vendu ma dernière copie des « Rituels du pouvoir » à un membre du clergé...$B$BUn membre de la Croisade écarlate. Il a dû le mettre dans la bibliothèque du Monastère écarlate dans les Clairières de Tirisfal !$B$BSi vous voulez ce livre, il va falloir que vous alliez le chercher au monastère. Et désolé pour tout ce tracas. Je ne suis plus moi-même ces derniers temps...'),
(2078,'frFR','Trouver le Premier Officier de Gelkak, le Destructomembreur 4100, et le ramener à Gelkak.','Bouseux de terrien ! Tu dois me dégoter mon Premier Officier.$B$BPrends c''te clé, mets-y dans le bon trou, et ramèn'' le ici pour servir le cap''taine.$B$BCes murlocs et leur chef vont pas beaucoup aimer quand mon Premier Officier va leur mettre l''grappin dessus !'),
(2201,'frFR','Trouvez le rubis, le saphir et la topaze qui sont éparpillés à travers Uldaman. Une fois que vous les aurez, contactez Talvash del Kissel en utilisant la Fiole de divination qu’il vous a donnée précédemment.$B$BC''est dans le journal, vous savez...$B* Le rubis a été caché dans une zone barricadée des Ombreforge.$B* La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de Alliance.$B* Le saphir est en possession du chef trogg, Grimlok.','Le journal du paladin est sans doute le seul indice dans Uldaman qui puisse vous conduire aux gemmes. Si ce qu''il prétend est vrai, il va falloir traiter avec les nains Ombreforge et les troggs qui combattent pour le contrôle de l''excavation.$B$BLa traque des gemmes doit commencer immédiatement. Lorsqu''elles seront récupérées, il faudra prendre les instructions de Talvash à Ironforge en utilisant la Fiole de Divination.'),
(2203,'frFR','Utiliser les 3 Récipients thaumaturgiques vides sur des dragons gardiens des terres brûlées dans les Terres ingrates. Une fois remplis, les rapporter à Jarkal Mossmeld à Kargath.','Votre aide m''a été précieuse, merci, $C. Je vous récompenserai en vous donnant la recette de l''Elixir que vous avez testé un peu plus tôt... mais je vais d''abord vous confier une mission dangereuse. Écoutez bien.$B$BCe coffret contient trois Récipients thaumaturgiques vides. Ils sont entourés d''une Aura d''harmonie qui attire le Sang de Gardien dragon brûlé. Attention ! Si vous n''en utilisez qu''un, la bête deviendra enragée. Lorsque vous aurez rempli les trois, rapportez-les-moi.$B$BVous aurez la recette de mon Elixir en échange.'),
(2359,'frFR','Voler la Clé de la Tour défias, pénétrer dans la Tour et trouver ce que contient le Coffre du bois de la Pénombre. Rapporter les informations à Mathias Shaw à Stormwind. Lire le journal de Kearnen pour savoir ce qui se passe dans la Tour.','Je suis là, à surveiller cette tour depuis des semaines, $N. Récemment, un chargement important est arrivé du bois de la Pénombre, protégé par ces gardes.$B$BQue sont-ils ? Aucune idée. La seule chose que je puisse affirmer, c''est qu''ils ne sont pas humains.$B$BQuoiqu''il en soit, dans cette cargaison repose un coffre, et je suppose que ces abominations sont commises à sa garde. Le gros avec les piques, là, possède une clé dont nous aurons besoin.$B$BRécupérez cette clé, entrez dans la Tour et découvrez ce que contient ce coffre. Rapportez à Mathias le produit de votre recherche.'),
(3443,'frFR','Apporter 8 Dagues plaquées en thorium à Velarok Lamevent.','Pour porter la flamme parfaite, nous aurons besoin d’un manche et d’une enveloppe. Vous devez tout d’abord trouver un manche convenable.$B$BLes sous-chefs et les esclavagistes Sombrefer du Chaudron se servent d’armes en thorium enchanté, un alliage extrêmement solide. Si vous m’apportez huit dagues plaquées en thorium, je pourrai les fondre et utiliser le métal pour fabriquer le manche.'),
(3453,'frFR','Attendre que Velarok Lamevent termine la Torche de vindicte.','Laissez-moi un moment afin que je combine les différentes parties et que j’y applique les enchantements nécessaires.'),
(3910,'frFR','Escorter Petra et Dadanga jusqu''à Un''Goro.','Bienvenue à Gadgetzan ! Ramenez-nous à la maison...'),
(3911,'frFR','Partir pour les Profondeurs de Rochenoire et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d''élémentaires.','Il y a du travail pour ceux qui s''aventurent dans les Profondeurs, $N.$B$BLes Sombrefers peuvent créer des golems extrêmement puissants.$B$BLes premiers rapports de nos espions indiquent que les nains se servent d''une unique source de puissance pour donner à leurs créations une puissance de destruction incomparable.$B$BImaginez simplement ce que nous pourrions faire de nos abominations si nous mettions la main sur cette Essence des éléments ! Fouillez les moindres recoins de cette cité si cela est nécessaire, mais ne revenez pas tant que vous n''avez pas découvert cette essence ! Votre récompense sera à la mesure du risque encouru.'),
(4822,'frFR','Aller chercher de la glace à la fraise pour votre protégé. Le gamin semble préférer la marque de glace Aguilor.','DE LA GLACE ! Oh, s’il vous plaaaaîîîîîît, je peux avoir de la glace ?! La glace à la fraise est ma glace préférée, et la meilleure glace à la fraise du monde, c’est celle d’Aguilor ! C’est ma glace préférée dans le monde entier !$B$BJ’en ai mangé il y a longtemps aux courses des Salines, mais il paraît qu’ils en vendent en ville ! S’il vous plaît ? S’il vous plaaaaîîîîîît ? Avec une deuxième boule sur le dessus ??!?!'),
(5051,'frFR','Trouver l’autre moitié du Charme porte-bonheur quelque part dans le périmètre de la Ferme Felstone dans les Maleterres de l’ouest et le recoller.$B$BDonner le Charme porte-bonheur à Janice Felstone à la Ferme Felstone, dans les Maleterres de l’ouest.','Les divagations de ce pauvre fantôme continuent :$B$B"J''ai si froid, John. Apportez-moi votre charme et nous serons réunis à nouveau ! Vite John, avant que la peste ne nous transforme en créatures hideuses ! Je n''arrive pas à vous voir John…mais je sais que vous êtes proche. Je sens votre présence."$B$BPeut-être qu''en trouvant la deuxième moitié du charme et en le réassemblant, cela constituerait ce que l''esprit de Janice Felstone recherche."'),
(5097,'frFR','À l’aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l’embrasure de la porte de la tour pour pouvoir la marquer.$B$BQuand les quatre tours seront marquées, rapporter la Torche-balise au commandant Ashlam Valorfist au camp du Noroît, dans les Maleterres de l’ouest.','En utilisant l''objet magique connu sous le nom de torche-balise, nous pouvons marquer les cibles sur lesquelles interviendront nos troupes. À cette fin, nous pensons que le Fléau utilise les tours de guet d''Andorhal pour diriger les mouvements de leurs troupes.$B$BVotre mission : déjouer les défenses d''Andorhal pour poser des balises sur les quatre tours de guet. Vous devez être sur le pas de la porte pour poser la balise, ce qui assurera le marquage de la tour. Attention, la torche-balise ne contient que cinq charges. Utilisez-les à bon escient !'),
(5098,'frFR','À l’aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l’embrasure de la porte de la tour pour pouvoir la marquer.$B$BQuand les quatre tours seront marquées, rapporter la Torche-balise au Grand exécuteur Derrington à la Barricade, dans les Maleterres de l’ouest.','En utilisant l''objet magique connu sous le nom de torche-balise, nous pouvons marquer les cibles sur lesquelles interviendront nos troupes. À cette fin, nous pensons que le Fléau utilise les tours de guet d''Andorhal pour diriger les mouvements de leurs troupes.$B$BVotre mission : déjouer les défenses d''Andorhal pour poser des balises sur les quatre tours de guet. Vous devez être sur le pas de la porte pour poser la balise, ce qui assurera le marquage de la tour. Attention, la torche-balise ne contient que cinq charges. Utilisez-les à bon escient !'),
(5321,'frFR','Escorter Kerlonian Evershade jusqu’à Liladris Moonriver au Poste de Maestra à Ashenvale.','J''étais parti en direction du Poste de Maestra pour rencontrer Liladris Moonriver lorsque je décidai de m''arrêter et de me reposer un peu. Depuis que je me suis extirpé du Rêve d''émeraude, j''ai tout le temps sommeil…$B$B<bâille>$B$BAuriez-vous l''obligeance de me montrer le chemin ? Je crois que le Poste de Maestra est au sud, près de la route d''Ashenvale. Cela peut-être dangereux, j''espère que vous avez des amis pour nous accompagner.$B$BIl se peut que je m''endorme, alors pour me réveiller, utilisez ma corne, qui est dans ce coffre.'),
(5721,'frFR','Placer la Liasse de reliques sur la place centrale de Darrowshire.$B$BEmpêcher la mort de Davil Lightfire, jusqu’à la mort de Horgus.$B$BEmpêcher la mort du capitaine Redpath, jusqu’à ce que Redpath le Corrompu apparaisse.$B$BVaincre Redpath le Corrompu.$B$BParler à l’esprit de Joseph Redpath, quand il apparaît sur la place centrale, puis parler à Pamela, dans sa maison.','Maintenant, $N, vous allez participer à la bataille de Darrowshire, et vous allez sauver Joseph Redpath.$B$BPlacez cette Liasse de reliques sur la place centrale de Darrowshire ; alors les esprits de Darrowshire apparaîtront. Assurez-vous alors que les deux choses suivantes adviennent : Davil doit survivre à Horgus, et Redpath doit survivre pour être corrompu, puis être vaincu.$B$BQuand vous aurez vaincu Redpath, après qu’il a été corrompu, son esprit sera sauvé. Parlez-lui, puis retournez voir sa fille Pamela.'),
(6022,'frFR','Allez à l''est à la Croisée de Corin et détruisez les membres du Fléau qui habitent la ville. Rassemblez sept morceaux de Pourriture vivante en moins de dix minutes. Utilisez le Mortier et le pilon pour réduire la Pourriture vivante en Pourriture coagulée.','Tant que vous travaillerez pour moi, vous tuerez sur commande.$B$BVotre première tâche consiste à nourrir mes chiens.$B$BPrenez ce mortier et ce pilon, et allez à la Croisée de Corin. Une fois sur place, vous trouverez une belle brochette de membres du Fléau à tuer. Sur leurs carcasses encore tièdes, collectez de la Pourriture vivante ; vous la pulvériserez ensuite dans le mortier, puis laisserez le tout coaguler. Rapportez-moi la Pourriture coagulée.$B$BEt puis, imbécile, rappelez-vous que la Pourriture vivante, prélevée sur des morts-vivants, ne reste pas vivante bien longtemps ; aussi, faites vite !'),
(6124,'frFR','Utiliser le Remède pour animaux sur 10 Daims malades qui se trouvent dans Sombrivage ; ceci les soignera. Les Daims malades ont été aperçus d’abord entre le sud de la rivière Bondissante et le nord d’Auberdine ; on en trouve également tout au sud de Sombrivage, à la frontière d’Ashenvale.','La quantité de remède constituée à partir des ingrédients que vous m’avez apportés suffit tout juste pour dix doses, $N. Pendant que je travaille de concert avec ceux du village pour essayer d’en produire plus, je voudrais vous demander de nous aider à gagner du temps. Tout autour de Sombrivage vivent des daims malades ; utilisez le remède sur eux et guérissez-les de leur affection.$B$BDendrite Starblaze, à Reflet-de-Lune, voudra vous parler, quand vous en aurez fini. Veuillez également transmettre les remerciements d’Auberdine au Cercle cénarien... et laissez-moi vous remercier en personne pour l’aide que vous avez fournie !'),
(7027,'frFR','Trouvez un Bélier d''Alterac dans la vallée d''Alterac. Lorsque vous serez à proximité, servez-vous du Collier d''entraînement Stormpike pour le "dompter". Une fois dompté, le Bélier d''Alterac vous suivra jusqu''au Maître des écuries. Parlez au Maître des écuries pour être crédité de cette capture.','Regardez les écuries, $N ! Vides ! La brigade de Stormpike n’a plus de béliers à monter. Notre cavalerie n’existe plus.$B$BVous devez nous aider, soldat. Prenez ce collier d’entraînement et aventurez-vous dans la partie sauvage de la vallée. Trouvez les béliers d’Alterac qui y vagabondent et servez-vous du collier pour en capturer un. Lorsque vous l’aurez, amenez-le ici et je le mettrai à l’écurie.$B$BLorsque nous aurons assez de béliers, j’en informerai l’officier responsable. Avec votre aide, la cavalerie va ressusciter !'),
(7384,'frFR','Récupérez des écailles pour Karana du Havre boueux dans le marais des Chagrins.','Donnez-moi des écailles.'),
(7481,'frFR','Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les au Sage Korolusk du Camp Mojache.','Il y a plusieurs années, un maître elfe solitaire du nom de Telmius Cherche-Rêve a fui la destruction de sa terre natale avec plusieurs objets magiques elfiques antiques.$B$BNos recherches nous ont conduits aux ruines de Quel’Thalas, de l’autre côté des Steppes ardentes, à travers l’océan, jusqu’en Feralas.$B$BNous pensons que cet elfe a trouvé refuge dans les salles d’Eldre’Thalas, que l’on appelle aujourd’hui Hache-tripes.$B$BVous devez le trouver, $Gaventurier:aventurière;. Qu’il soit mort ou vif, il nous faut les connaissances qu’il détenait !'),
(7482,'frFR','Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les à l’Erudite Runethorn, à Feathermoon.','Il y a plusieurs années, un maître elfe solitaire du nom de Telmius Cherche-Rêve a fui la destruction de sa terre natale avec plusieurs objets magiques elfiques antiques.$B$BNos recherches nous ont conduits aux ruines de Quel’Thalas, de l’autre côté des Steppes ardentes, à travers l’océan, jusqu’en Feralas.$B$BNous pensons que cet elfe a trouvé refuge dans les salles d’Eldre’Thalas, que l’on appelle aujourd’hui Hache-tripes.$B$BVous devez le trouver, $Gaventurier:aventurière;. Qu’il soit mort ou vif, il nous faut les connaissances qu’il détenait !'),
(7631,'frFR','Lisez les Instructions de Mor’zul. Invoquez un Destrier de l’effroi xorothien, vainquez-le, et liez son esprit.','Tous les préparatifs sont terminés. À présent, vous devez accomplir le rituel qui créera un Cercle de lien supérieur, puis utiliser le Parchemin de Xoroth pour ouvrir un portail vers Xoroth.$B$BToutes les instructions figurent sur ce document. Étudiez-le attentivement, car vous ne devez en dévier sous aucun prétexte si vous voulez réussir.$B$BJe vous souhaite bonne fortune, $N. Et puisse l’âme de vos ennemis trouver le chemin de votre bourse !'),
(7647,'frFR','Utilisez le Clairvoyant au coeur du sous-sol du Grand ossuaire, dans la Scholomance. Cela attirera des esprits que vous devrez juger. Lorsqu’ils seront vaincus, le Chevalier de la mort Ravassombre apparaîtra. Vainquez-le et purifiez l’âme du destrier déchu.$B$BEnsuite, donnez l’Ame rachetée du destrier et le Caparaçon enchanté et béni au Destrier déchu de Ravassombre.','Prenez ce paquet, il contient tous les objets dont vous aurez besoin.$B$BServez-vous du Clairvoyant au centre des fondations du Grand ossuaire, afin d’attirer les esprits maudits qui doivent être jugés. Utilisez vos jugements avec sagesse au cours de cette épreuve, car les esprits risquent d’être plus puissants que vous ne le croyez. Lorsque ce sera terminé, le chevalier de la mort apparaîtra. Tuez-le et récupérez l’âme de son destrier. Lorsque ce sera fait, vous pourrez la purifier et placer votre caparaçon sur votre nouveau destrier.$B$BBonne chance, $N !'),
(7668,'frFR','Servez-vous du Clairvoyant au centre du sous-sol du Grand ossuaire de la Scholomance. Cela attirera des esprits que vous devrez combattre. Les vaincre fera apparaître le Chevalier de la mort Ravassombre. Tuez-le.$B$BRamenez la Tête de Ravassombre à Sagorne Crestrider de la vallée de la Sagesse, à Orgrimmar.','Le chevalier de la mort Ravassombre règne sur le Grand ossuaire de la Scholomance. Il se prépare à altérer le monde des esprits pour accomplir ses ténébreuses volontés. Il faut l’arrêter ! Ce sera le rôle du Clairvoyant que vous m’avez aidé à préparer.$B$BUtilisez-le au centre du sous-sol du Grand ossuaire pour appeler les esprits qui servent Ravassombre. Lorsque vous les aurez vaincus, le chevalier de la mort apparaîtra en personne. Ramenez-moi sa tête, $N ! Sa mort est la seule chose qui puisse annuler les ravages qu’il a commis dans le monde des esprits !'),
(7703,'frFR','Trouvez le Gantelet de Puissance Gordok et rendez-le au capitaine Kromcrush à Hache-tripes.$B$BSelon Kromcrush, les histoires des « vieux » racontent que Tortheldrin – un « vilain » elfe qui se fait appeler prince – l’a volé à l’un des rois gordok.','Maintenant qu’z’êtes le roi, p’têt qu’vous pourrez récupérez l’objet précieux des Gordok que le sale elfe qui se dit Prince nous a pris. L’roi avant vous a pas réussi, et celui d’avant non plus, et aucun roi depuis que Tortheldrin – c’est le sale elfe – l’a volé à un vieux roi gordok d’il y a longtemps !$B$BC’est le Gantelet de puissance Gordok. Les vieux, ils disent que seul le vrai roi des Gordok pourra le ramener. Et puis, les vieux, ils disent aussi que le sale elfe est toujours là – si vous le trouvez, vous pourrez porter le gantelet de puissance pour toujours ! Ouais ! Je vais vous montrer !'),
(7782,'frFR','Aller dans la Vallée des Héros de Stormwind et parler au Grand maréchal Pont-de-Pierre.','Aller dans la Vallée des Héros et parler au Grand maréchal Pont-de-Pierre.'),
(7840,'frFR','Lard, du village des Revantusk, dans les Hinterlands, veut que vous retrouviez le Repas de Lard. Retournez le voir lorsque ce sera fait.$B$BD’après Lard, il l’aurait laissé dans l’île, au nord. Prenez garde aux trolls Vilebranch !','Lard était dans son endroit secret spécial pour pique-nique quand vilains Vilebranch affreux sont venus et ont tapé sur la tête de Lard avec le gros bâton. Lard a couru jusqu’à village Revantusk, mais Lard a oublié son déjeuner. Lard a faim. Vous pouvoir aller dans endroit secret spécial et prendre déjeuner de Lard ? Lard a peur. C’est au nord ! L’endroit secret special être île au nord.'),
(7843,'frFR','Otho Moji''ko, du village des Revantusk dans les Hinterlands, vous demande de vous rendre au Nid-de-l’Aigle, à l’ouest des Hinterlands. Vous devez placer le Message final pour les Wildhammer près du puits, au cœur de la ville. Retournez le voir lorsque vous aurez accompli votre tâche.$B$BFaites attention aux nains Wildhammer, qui risquent de mal le prendre, et aux autres membres de l’Alliance.','<Otho vous tend une longue lance tachée de sang, ornée de plusieurs plumes de gryphon.>$B$BVous prenez ça, mon pote. Vous l’amenez au Nid-de-l’Aigle, pile au centre de la ville, près du puits. Et là, vous le plantez ! En plein dans le sol ! Faut montrer à ces nains que les trolls ne plaisantent pas ! Revenez quand vous l’aurez fait. Vivant, si possible.'),
(8059,'frFR','Ramenez un Etançon primordial hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi être Amicale (au minimum).$B$BAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.','Lorsqu’ils négocient avec les démons, les démonistes s’aventurent sur un terrain dangereux, mais nos démoniaques poussent le processus encore plus loin. Grâce à un ancien rituel des arcanes, ils permettent à un démon d’entrer dans leurs corps. Mais ils ne sont pas posssédés : ils réduisent le démon en esclave de l’intérieur, absorbant le pouvoir de la bête pour leurs propres fins. C’est un exploit que bien peu sont capables d’accomplir.$B$BSi vous voulez apprendre le pouvoir des démoniaques, il me faut un Parangon de puissance de Zul’Gurub. Allez-y, et ramenez-moi ce que je cherche.'),
(8149,'frFR','Rendez-vous au tombeau d’Uther dans les Maleterres de l’ouest, puis utilisez Offrande à Uther sur sa statue, avant de retourner voir Wagner Hammerstrike à l’extérieur d’Ironforge, avant la fin de la Fête des moissons.','Au cours de la Fête des moissons d’Azeroth, nous rendons grâces aux héros pour les sacrifices accomplis pour nous – y compris, dans certains cas, celui de leur vie. L’Alliance se souvient de nombreux héros, mais aucune histoire n’est plus tragique que celle d’Uther le Porteur de Lumière.$B$BAidez-nous à rendre hommage à Uther en allant déposer cette offrande sur sa tombe, dans les Maleterres de l’ouest. Placez-la aux pieds de sa statue, puis revenez me voir. Je ne serai là que jusqu’à la fin de la fête, alors ne perdez pas de temps pour rendre hommage à Uther !'),
(8150,'frFR','Rendez-vous au monument de Grom dans le canyon de la Malechute en Ashenvale, puis utilisez Offrande à Grom à la base du monument. Ensuite, retournez voir Javnir Nashak à l’extérieur d’Orgrimmar, avant la fin de la Fête des moissons.','Au cours de la Fête des moissons d’Azeroth, nous rendons grâces aux héros pour les sacrifices accomplis pour nous – y compris, dans certains cas, celui de leur vie. La Horde se souvient de nombreux héros, mais c’est Grom Hellscream qui personnifie le mieux la force et le sacrifice.$B$BS’il vous plaît, aidez-nous à honorer Grom en allant déposer cette offrande au pied de son monument, dans le canyon de la Malechute, en Ashenvale. Lorsque ce sera fait, revenez me voir. Je ne serai là que jusqu’à la fin de la fête, alors ne perdez pas de temps pour rendre hommage à Grom !'),
(8152,'frFR','Parlez à Ogtinc en Azshara.','$N, quand vous vous sentirez $Gprêt:prête;, un vieux chasseur furbolg du nom d''Ogtinc demeure en Azshara. Il pourrait poursuivre votre enseignement et vous montrer la voie.$B$BOgtinc se trouve au sommet des falaises au nord-est des ruines d''Eldarath en Azshara.'),
(8201,'frFR','Attachez 5 Têtes de canalistes, puis ramenez la Collection de têtes de Gurubashi à Exzhal sur l’île des Zandalar.','C’est vrai. Hakkar réside désormais dans Zul’Gurub, où il baigne dans le pouvoir de nos dieux. Des grands-prêtres asservis canalisent les énergies de nos plus puissantes divinités dans l’Ecorcheur d’âmes. Il sera bientôt plus redoutable que toutes les créatures d’Azeroth. Il faut l’arrêter !$B$BPrenez cette corde sacrée, et attachez-là aux têtes des grands-prêtres qui canalisent les énergies de nos dieux.$B$BLorsque ce sera fait, revenez me voir.'),
(8258,'frFR','Servez-vous du Clairvoyant au centre du sous-sol du Grand ossuaire de la Scholomance. Cela attirera des esprits que vous devrez combattre. Les vaincre fera apparaître le Chevalier de la mort Ravassombre. Tuez-le.$B$BRamenez la Tête de Ravassombre à Sagorne Crestrider de la vallée de la Sagesse, à Orgrimmar.','Le chevalier de la mort Ravassombre règne sur le Grand ossuaire de la Scholomance. Il se prépare à altérer le monde des esprits pour accomplir ses ténébreuses volontés. Il faut l’arrêter ! Ce sera le rôle du clairvoyant que vous m’avez aidé à préparer.$B$BUtilisez-le au centre du sous-sol du Grand ossuaire pour appeler les esprits qui servent Ravassombre. Lorsque vous les aurez vaincus, le chevalier de la mort apparaîtra en personne. Ramenez-moi sa tête, $N ! Sa mort est la seule chose qui puisse annuler les ravages qu’il a commis dans le monde des esprits !'),
(8330,'frFR','Récupérez l’Orbe de divination de Solanian, son Parchemin de magie du Fléau et son Journal. Ils se trouvent sur l’île de Haut-Soleil, non loin de l’étang, de la fontaine et de l’un des cristaux ardents. Lorsque vous les aurez tous, restituez-les au Veilleur du puits à la Flèche solaire de l’île de Haut-Soleil.','La Flèche solaire est en plein chaos. Du coup, je n’ai pas pu récupérer mes affaires. Je les ai laissées dans divers endroits de l’île. Je dois rester là, à surveiller le puits de soleil. Je vous demande donc de les ramasser pour moi.$B$BJ’ai besoin de mon orbe de divination, de mon parchemin de magie du Fléau et de mon journal. Prenez donc cette sacoche, elle vous sera utile, car tout cela est plutôt encombrant. Si vous me ramenez tout cela, je vous donnerai un petit quelque chose pour vous remercier de vos efforts. Et vous pourrez aussi garder la sacoche !'),
(8336,'frFR','Récupérer 6 Esquilles arcaniques sur n’importe quelle créature qui utilise du mana, puis retourner voir l’arcaniste Ithanas sur l’île de Haut-Soleil.','Quel dommage que tant de créatures de cette île aient échappé à notre contrôle. Autrefois, on pouvait tranquillement se livrer à l''étude et aux recherches ici. Maintenant, nous n''avons pas d''autre choix si nous voulons nous protéger de nos propres créations !$B$BJe vous donne une chance de recevoir un petit cadeau magique, à condition de vous livrer à un rapide travail de collecte pour mon compte. Ramenez-moi une pile d’esquilles arcaniques comme on en trouve sur toutes les créatures de l’île de Haut-Soleil qui utilisent du mana. En échange, je lancerai sur vous un sort qui vous aidera lors vos aventures sur l’île.'),
(8345,'frFR','Lisez la plaque au Sanctuaire de Dath''Remar puis retournez auprès du veilleur du puits Solanian, à la Flèche solaire de l’île de Haut-Soleil.','Jour après jour, je reste ici, à observer et à attendre. On m''accuse de trop rester attaché à notre passé, pendant que mes yeux scrutent l''horizon. Mais je suis fermement convaincu que chaque personne qui visite cette île doit rendre hommage à ceux qui ont tout sacrifié pour qu''ils puissent le faire.$B$BDath''Remar Haut-Soleil fut notre premier roi. Il nous a conduits ici depuis Kalimdor à travers le Maelström.$B$BRendez-vous à son sanctuaire à l''ouest et ne revenez pas avant d''avoir lu la plaque en son honneur.'),
(8346,'frFR','Servez-vous de votre compétence raciale Torrent arcanique sur un wyrm de mana, puis revenez voir l’arcaniste Helion.','Si vous ne devez retenir qu’une seule leçon de votre séjour sur l’île de Haut-Soleil, que ce soit celle-ci : contrôlez votre soif de magie. Elle est insatiable, $N. Pour survivre, l''énergie que vous absorbez doit être contrôlée et libérée grâce au Torrent arcanique. Si vous échouez, vous deviendrez l’un des Déshérités… dément, drogué et sans espoir de rédemption.$B$BPartez à la recherche d''un wyrm de mana et utilisez Torrent arcanique sur lui. Apprenez à maîtriser votre soif de puissance. Lorsque vous aurez libéré un Torrent arcanique suffisant, revenez me voir.'),
(8373,'frFR','Utilisez le Nettoyeur de boules puantes pour retirer les Boules puantes que les Réprouvés ont lancées sur Southshore. Retournez voir le sergent Hartman à Southshore quand vous aurez terminé.','La chose que je déteste le plus dans la Sanssaint sont les boules puantes que les Réprouvés lancent sur Southsore. Qui aurait cru que fêter leur libération impliquerait une pagaille aussi nauséabonde ?$B$BPendant la Sanssaint, servez-vous de ce nettoyeur pour retirer toutes les boules puantes immondes que la Horde aura déposées dans le village. Il utilise la puissance du pin pour chasser les odeurs pestilentielles.$B$BSi vous aidez Southsore à rester propre, je vous donnerai quelques bonbons de la Sanssaint. Je suis sûre que vous les aimerez. Marché conclu ?'),
(8479,'frFR','Ven''jashi, le prisonnier troll de Tor''Watha, veut que vous lui remettiez la Tête du chef Zul’Marosh. Le chef Zul''Marosh se trouve à Zeb''Watha, de l''autre côté du lac Elrendar.','Approchez, ayez pas peur, Ven’jashi, il ne va pas vous faire de mal.$B$BNous les Sombrelances, on est comme vous, ennemis mortels des Amani. Leur chef Zul’Marosh, mauvais Troll. Il me poisonne et me laissé dans cette cage pour mourir.$B$BJ’ai pas peur de mourir, $Gmon gars:ma p’tite;. Je regarde la mort dans les yeux, elle me fait rire.$B$BMais je ne vais pas mourir en paix, $Gmon gars:ma p’tite;. Pas si Zul’Marosh, il est pas mort aussi. Cherchez-le de l''aut'' côté du lac à Zeb''Watha. Je retiens le poison tant que vous m’apportez pas sa sale tête. Après, je meurs en paix.'),
(8507,'frFR','Présentez-vous au poste de la brigade d’Ironforge devant la Ruche’Zora. Préparez votre Ordre de mission et obtenez un Ordre de mission signé du capitaine Blackanvil. Ensuite, retournez voir l''Implorateur céleste Kaldon au Fort cénarien, en Silithus.$B$BNote : lancer un sort de soin, ou tout autre sort bénéfique, sur un membre de la brigade d’Ironforge vous infligera un marqueur JcJ.','Salutations, $N. Avant que je vous assigne des tâches plus vitales pour la guerre, vous devrez faire votre part dans la mise en place de la campagne.$B$BVous trouverez les forces de la brigade d’Ironforge commandée par le capitaine Blackanvil devant la Ruche’Zora.$B$BAllez vous présenter à lui ou à son lieutenant, Janela Stouthammer, et revenez me voir. Je vous aurai alors préparé des missions plus délicates.$B$BOh, et faites-nous une faveur. Ne restez pas à côté de la légion d’Orgrimmar. Nous avons été obligés de bien séparer les deux armées à cause de l’animosité mutuelle qu’elles se vouent…'),
(8606,'frFR','Narain Soothfancy, en Tanaris, veut que vous vous rendiez au Berceau-de-l’hiver et que vous posiez le Sac d''or à l’endroit indiqué par les voleurs de livres.','Eurêka ! Je sais ce que nous allons faire. Je vais remplir un sac de pierres, et vous allez vous charger de le remettre. Je sais que je suis censé le faire moi-même… et bien c’est ce qui va se passer. En quelque sorte.$B$B<Narain vous examine des pieds à la tête.>$B$BBon bon bon, ça ira. Prenez cette robe, ce turban et ce sac de cailloux, et filez au lieu du rendez-vous, au Berceau-de-l’hiver.$B$BJ’ai mis tout ce dont vous avez besoin dans cette panoplie spéciale. Lorsqu’ils se montreront pour récupérer l’argent… crac, vous leur tombez dessus ! Ça leur apprendra à s’en prendre à Narain !'),
(8620,'frFR','Retrouver les 8 chapitres perdus du "Draconique pour les nuls" et les combiner avec la Reliure magique, puis ramener l’exemplaire réparé du "Draconique pour les nuls, volume II" à Narain Soothfancy, en Tanaris.','J’aurais dû m’en douter ! Mon ennemi juré, le docteur Weavil, a récidivé ! Et maintenant, à cause de votre échec au Berceau-de-l’hiver, le docteur Weavil a détruit mon livre ! Comment allez-vous sauver le monde, maintenant ?$B$BD’après le message que j’ai reçu, l’unique exemplaire connu du "Draconique pour les nuls, volume II" a été divisé en huit morceaux et dispersé aux quatre vents ! Si par miracle vous parvenez à les récupérer, utilisez cette reliure magique pour les réunir et ramenez-les-moi.'),
(8729,'frFR','Utilisez la Bouée d’arcanite au Maelström tourbillonnant dans la Baie des tempêtes en Azshara.','Je ne vous ai pas encore dit qu’elle était la mauvaise nouvelle ? Elle s’appelle Crocs-de-la-mer : trente mètres de mort et de destruction. J’avais peut-être oublié de mentionner ce point de détail.$B$BD’après mon extraordinaire clairvoyance psycho-psionique, le meilleur endroit pour lancer cette bouée est la côte d’Azshara, dans la Baie des tempêtes.$B$BCherchez un maelström tourbillonnant, qui sera probablement encombré de débris.$B$Bau fait, j’espère que vous avez de bons amis.$B$BBon, si par miracle vous réussissez, apportez le fragment de sceptre à Anachronos.'),
(8731,'frFR','Allez vous présenter à Krug Skullsplit, au poste de la légion d’Orgrimmar devant la Ruche’Regal. Préparez votre Ordre de mission, obtenez un Ordre de mission signé et apportez-le à l’Implorateur céleste Kaldon au Fort cénarien$B$BNote : lancer un sort de soin, ou tout autre sort bénéfique, sur un membre de la légion d’Orgrimmar vous infligera un marqueur JcJ.','Salutations, $N. Avant que je vous assigne des tâches plus vitales pour la guerre, vous devrez faire votre part dans la mise en place de la campagne.$B$BVous trouverez la légion d’Orgrimmar, commandée par le capitaine Skullsplit, à l’extérieur de Ruche’Regal.$B$BAllez vous présenter à lui et revenez me voir avec une preuve de votre engagement. Je vous aurai alors préparé des missions plus délicates.$B$BOh, et ne restez pas à côté de la brigade d’Ironforge. Les tensions entre les volontaires de l’Alliance et de la Horde sont fortes.'),
(8746,'frFR','Trouvez Metzen le renne. Utilisez les notes qui vous ont été fournies comme indices pour découvrir son lieu de détention.$B$BQuand vous aurez trouvé Metzen, saupoudrez sur lui la Bourse de poudre de renne qui vous a été remise. Cela devrait mettre fin à sa captivité.$B$BRapportez la Bourse de poudre de renne à Kaymard Copperpinch à Orgrimmar quand Metzen aura été libéré.','C’est un DÉSASTRE ! Metzen le renne a été kidnappé !$B$BMetzen est l’un des huit rennes du Grand-père Hiver - et il appartient aux Gourmandises Fumebois. Nous n’avons pas reçu une, mais DEUX demandes de rançon de groupes qui prétendent détenir Metzen. Comme la saison des fêtes bat son plein, nous sommes enchaînés à la caisse enregistreuse ! Je vous en prie, trouvez Metzen et ramenez-le nous !$B$BLisez attentivement les lettres de rançon pour trouver des indices, et saupoudrez cette poudre de renne sur lui : elle le libéra de toutes ses entraves !$B$BJe vous en supplie, faites vite !'),
(8762,'frFR','Trouvez Metzen le renne. Utilisez les notes qui vous ont été fournies comme indices pour découvrir son lieu de détention.$B$BQuand vous aurez trouvé Metzen, saupoudrez sur lui la Bourse de poudre de renne qui vous a été remise. Cela devrait mettre fin à sa captivité.$B$BRapportez la Bourse de poudre de renne à Wulmort Jinglepocket à Ironforge quand Metzen aura été libéré.','C’est un DÉSASTRE ! Metzen le renne a été kidnappé !$B$BMetzen est l’un des huit rennes du Grandpère Hiver - et il appartient aux Gourmandises Fumebois. Nous n’avons pas reçu une, mais DEUX demandes de rançon de groupes qui prétendent détenir Metzen. Comme la saison des fêtes bat son plein, nous sommes enchaînés à la caisse enregistreuse ! Je vous en prie, trouvez Metzen et ramenez-le nous !$B$BLisez attentivement les lettres de rançon pour trouver des indices, et saupoudrez cette poudre de renne sur lui : elle le libéra de toutes ses entraves !$B$BJe vous en supplie, faites vite !'),
(8930,'frFR','Utilisez le Révélateur de fantômes extradimensionnel à l''entrée de Stratholme, et parlez au fantôme d''Anthion Harmon.','Très bien, $N. Nous n’avons plus qu’à tester l’invention du gobelin. J’ai entendu dire qu’Anthion avait tenté de pénétrer dans Stratholme. Il n’a même pas franchi les portes, les légions des morts-vivants l’ont tué avant.$B$BEssayez d’utiliser l’objet là-bas et voyez si vous pouvez effectivement voir les morts !'),
(8951,'frFR','Retournez voir Deliana à Ironforge avec des bottes du Cœur-sauvage, un Kilt du Cœur-sauvage et des Spallières du Cœur-sauvage.','L’âme de Valthalak était conservée dans cette amulette.$B$BAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.$B$BLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.$B$BQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !'),
