INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`) VALUES
(167,'frFR','Adieu mon frère…','Nous étions au plus profond d''une mine dans la marche de l''Ouest, cachés derrière un baraquement à Ruisselune. Impossible de savoir d''où viennent ces voleurs puants... Bref, la mine s''est effondrée sur nous. Je m''en suis sorti mais les autres... Enfin... On n''en a plus entendu parler.$B$BVous aurez peut-être plus de chance. Si vous arrivez à avoir des nouvelles de mon frère, je vous en serai reconnaissant. Il portait toujours son insigne de la Ligue des Explorateurs. Si vous ne le trouvez pas, mais que vous me rapportez cet insigne, cela me rendrait un peu de paix.'),
(305,'frFR','À la recherche de l''équipe de fouilles','Oh bon sang ! Vous devez être l''éclaireur que Longbraid a promis d''envoyer ! Vous ne pouvez pas imaginer mon inquiétude.$B$BMa femme, Merrin, m''envoie des lettres toutes les semaines depuis le mois dernier. Elle fait partie de l''équipe de fouilles de Whelgar. Mais il s''est écoulé presque deux semaines depuis sa dernière lettre. Il y a sûrement quelque chose qui ne va pas !$B$BLongbraid a dit qu''il enverrait un éclaireur aux nouvelles si nous n''avions pas rapidement du nouveau. Je suppose que l''éclaireur, c''est vous, $N. Allez voir Merrin à l''Excavation, à l''est !'),
(307,'frFR','Bas les pattes !','La mine du Ru d''argent à l''est est épuisée depuis longtemps. Elle a été convertie en dépôt de stockage par la Ligue des Mineurs, mais aujourd’hui les kobolds s''y sont installés, et ils mettent leurs pattes sales sur nos bons vieux outils !$B$BNous chasserons bientôt cette vermine de là, mais avant d''envoyer des guerriers qui feront forcément un peu de casse, la Ligue veut que quelqu''un aille chercher son équipement. Ce ne sera pas facile, vous pourriez avoir besoin de l''aide d''alliés.$B$BL''équipement de mineur est stocké dans les caisses de la Ligue des Mineurs un peu partout dans la mine. Bonne chance !'),
(728,'frFR','Pour le « Sommaire de Yagyin »','Les tablettes en disent long. Mais pas assez ! Vraiment pas assez !$B$BIl y a un livre, que Yagyin a écrit il y a des années. Les... gens que j''ai fuis... ils en ont toujours un exemplaire sous la main. Et ils l''étudient presque tous. Il comprend un immense savoir. Un savoir qui peut nous permettre de nous protéger !$B$BAllez voir le Gardien Bel''dugur à Undercity, Lordaeron. Montrez-lui ce glyphe et il pensera que vous êtes un des leurs. Demandez-lui le « Sommaire de Yagyin »... et rapportez-le-moi !'),
(740,'frFR','<INUTILISÉ>','Cette quête envoie les joueurs dans la Gorge des Vents brûlants.$B$BRestez sur vos gardes...'),
(1002,'frFR','Bigobox 323','La bigobox se tait un instant puis vous entendez Wizbang commencer à parler.$B$B"La-la bigobox suivante est la numéro 323. L''est au nord d''Auberdine mais... Où est la bière ? Hein ? Oh ! C''est sur-sur la route alo-lors ça ne devrait pas-pas être dif-difficile de la trou-trouver près du pont."$B$BWizbang marmonne quelque chose d''incohérent puis vous entendez un bruit de déglutition sonore.$B$B" Il f-f-faut des Crocs de traquelune... 6 cro-crocs."'),
(1003,'frFR','Bigobox 525','En plus du bruit de fond et des sons écœurants qui viennent de la machine, vous entendez la voix hésitante de Wizbang appeler.$B$B"Au-autre au s-sud en bas de l-la route. Ne devrait pa-pas trop dur à trouver... juste au b-bord... près d''une clôture. Je p-pense que je l''ai ca-cachée dans un beu-beu... buisson. Hé hé hé !... Ouais, la bigobox 525 a be-besoin de s-scalps vieillis de vieux ou-ours des chardons. Garçon, une autre ! Vi-vieillis... Hé hé hé !..."$B$BVous entendez déglutir tandis que la machine s''arrête. Puis soudain, elle éructe.$B$B"4 !"'),
(2020,'frFR','<INUTILISÉ>','Maintenant voilà la serrure fermée.'),
(2058,'frFR','<INUTILISÉ>','Vous allez tuer un type, un membre de la Ligue des assassins. Il a tué le vieux chef des nécrotraqueurs.'),
(2059,'frFR','<INUTILISÉ>','Bien supposé, vous nous intéressez.'),
(5047,'frFR','Pépin Preste-Jugeote, à votre service !','Vous trouverez Malyfous Darkhammer à Long-guet, $C. Dites-lui que « Pépin est très content » et que la tenue marche parfaitement.$B$BPuis donnez-lui ceci :$B$B<Pépin vous tend un morceau de chair rouge.>$B$BC’est un bout d’entrailles que j’ai arraché à une bête pendant mes « vacances».$B$BJe parie que Malyfous pourrait vous donner une idée précise de ce qu’il pourrait faire avec un morceau de bête comme celle-là !$B$BOh, mais vous ne savez peut-être pas où est Long-guet ? Direction le Berceau-de-l’Hiver, $Gmon bon monsieur:ma bonne dame; !'),
(7845,'frFR','L’Ancien Torntusk a été enlevé !','Mon compagnon a été capturé par les sauvages Vilebranch au cours d’un raid nocturne sur notre village. Nos espions m’ont informé qu’il était encore en vie. Ils le gardent prisonnier au sommet de Jintha’alor. Il semble que la vile prêtresse Maléficia soit en train de le préparer pour le sacrifier à un dieu sanglant et sans visage.$B$BVous devez le sauver, $N ! Notre village ne supporterait pas de le perdre.')
INSERT INTO `quest_template_locale` (`ID`,`locale`,`QuestDescription`) VALUES
(23,'frFR','La patte du puissant ours Ursangous représente votre trophée pour cette partie de la Chasse d''Ashenvale. Sur la patte figure un petit emblème en forme de croissant de lune, dont la signification reste mystérieuse.$B$BLa Patte doit être apportée à Senani Thunderheart, au Poste de Bois-brisé, comme preuve que vous avez abattu la puissante créature et terminé cette partie de la Chasse.'),
(34,'frFR','Mes jardins ont encore été saccagés. Et je connais le responsable. C''est ce satané sanglier, celui que le maréchal Marris appelle Fouailleventre.$B$BJe ne vais pas pouvoir replanter mes jonquilles avant la prochaine saison maintenant. Ruinée ! Je suis complètement ruinée à cause de ce sanglier ! Mettez un terme à cette nuisance ! Montrez-moi ses défenses et je serai heureuse de vous récompenser. Il semble qu''il passe son temps dans les champs au sud-ouest de Lakeshire, mais il vagabonde de temps en temps jusque dans mon jardin.'),
(36,'frFR','Je n''avais jamais pensé un jour quitter ma ferme. Mais les champs grouillent de voleurs, et cela devient vraiment trop dangereux pour nous. Dès que la charrette du Fermier Furlbrow sera réparée, nous partirons.$B$BVous pourriez peut-être me faire une faveur? Laissez-moi écrire la recette du ragoût de la marche de l''Ouest. S''il vous plaît, apportez-la à Salma Saldean à la ferme de l''autre côté, là-bas. La ferme des Saldean est un peu plus loin sur la route, juste après l''embranchement.'),
(38,'frFR','Aidez-moi à faire du ragoût de la marche de l''Ouest. Ramenez les ingrédients suivants :$B$B3 morceaux de Viande filandreuse de vautour ;$B3 Groins de Broche-tripes ;$B3 Yeux de murloc ;$B3 Okras.'),
(40,'frFR','$N, il y a une nouvelle menace dans la forêt d''Elwynn ! Les murlocs remontent le cours est de l''Elwynn, effrayant les poissons et attaquant des personnes innocentes !$B$BJ''ai averti le maréchal Dughan, mais il est plus préoccupé par les gnolls et les bandits. Il n''est pas convaincu que les murlocs représentent un réel danger.$B$BS''il vous plaît, $N, parlez à Dughan et persuadez-le d''envoyer des renforts à l''est !'),
(52,'frFR','Salutations, $N. Les animaux sauvages deviennent de plus en plus agressifs à mesure que l''on s''éloigne de Goldshire, et le camp de bûcherons du Val d''est subit de perpétuelles attaques de la part de loups et d''ours !$B$BNous pourrions avoir besoin de votre aide.'),
(54,'frFR','$N, vous êtes un $C indubitablement impliqué dans la sûreté de Northshire. Vous avez maintenant en charge la protection de la zone entourant la forêt d''Elwynn.$B$BSi vous acceptez cette responsabilité, j''ai préparé tous les documents qui doivent être apportés au maréchal Dughan à Goldshire. Goldshire se situe le long de la route sud, au-delà de la frontière.'),
(66,'frFR','La nuit dernière, j''ai eu un mauvais pressentiment concernant ma petite-fille Alyssa. Elle serait en grand danger. J''ai tiré les cartes et la lame de la Faucheuse est sortie.$B$BAprès une longue et sombre transe, j’ai obtenu un indice. Un nom est apparu : Stalvan.$B$BAllez voir un greffier de la mairie et trouvez plus de détails sur ce personnage. J''ai peur pour tout le monde…'),
(67,'frFR','Stalvan, hein ? Laissez-moi vérifier dans les registres de la ville.$B$BStalvan. Stalvan…Voyons voir. Ah ! nous y voilà. J''ai la trace d''un certain M. Stalvan Mistmantle. Sa dernière adresse connue est l''école de Ruisselune. Enfin, mon registre date un peu !$B$BFaites-moi une faveur, si vous allez à Ruisselune, renseignez-vous sur cette personne. Que je puisse mettre à jour mon registre.'),
(69,'frFR','Oh non ! J''ai dû manquer ça la première fois. Dans le registre, juste en dessous de l’adresse notée pour Stalvan, il y en a une autre partiellement effacée. Il semble qu’il s’agisse de l''auberge de la Fierté du lion à Goldshire. J''aimerais vérifier cela, $N.'),
(70,'frFR','Oui, effectivement, je me rappelle de Stalvan !$B$BIl y a quelques années, lors d''une nuit d''orage, un messager est venu, à la recherche d''un abri pour la nuit. Vers minuit, l''homme a dévalé les escaliers en hurlant, le visage terrifié. Il était toujours en pyjama quand il a disparu en courant sous la pluie torrentielle.$B$BDans sa précipitation, il a oublié ses lettres dans le coffre à l''étage. Il n''est jamais revenu. Une des lettres était adressée au quartier du Canal à Stormwind. Prenez-la si vous le voulez.'),
(91,'frFR','Un ennemi de Stormwind s''est installé dans les collines à l’est des Carmines. D’infâmes voleurs utilisent les Arcanes pour répandre la terreur et la misère sur notre ville et ses habitants. Derrière cela, il y a une personne, Morganth ; c''est lui qui dirige cette entreprise maléfique.$B$BMorganth contrôle maintenant le clan des gnolls Sombrepoil, qu’il utilise pour ses exactions. De par la loi de Lakeshire, aider un ennemi du royaume est passible de la peine de mort.$B$BCes infâmes gnolls doivent être tués !$B$BRapportez-moi 10 pendentifs sombrepoil, et vous serez $Grécompensé:récompensée;.'),
(93,'frFR','Je vais vous confier un petit secret : mon gâteau au "crabe" brun est en réalité fait de pattes d''araignée ! C''est vrai que cela semble un peu répugnant, mais leur goût est merveilleux ! Apportez-moi des Pattes d''araignées fondantes et je vous en préparerai quelques-uns.$B$BVous en trouverez sur les araignées Tisse-venin qui nichent au nord, entre les collines et la rivière.'),
(116,'frFR','Je suis dans une situation désespérée, $N. Mes réserves sont presque à sec. La dernière cargaison de boisson aurait dû arriver il y a bien longtemps. L''invasion des orcs a été un enfer.$B$BPeut-être pouvez-vous travailler pour moi ?$B$BJ''ai besoin que vous récupériez un tonneau de Thunderbrew de chez Grimbooze Thunderbrew dans les collines de la marche de l''Ouest, un tonneau de merlot de Stormwind, une bouteille de tord-boyaux de Darkshire et une outre de rhum doux de Goldshire. Rapportez-les-moi et je ferai en sorte que vous soyez $Grécompensé:récompensée;.'),
(119,'frFR','D''accord, je lui envoie 50 fers à cheval…$B$BLes voilà, tout empaquetés et prêts à emporter ! Dites à Verner que c’est un plaisir de faire affaire, et faites en sorte qu''il trouve la facture accrochée à la caisse !'),
(120,'frFR','Nous vivons un moment crucial, $C. Le bourg est assiégé. Sans renforts, nous allons succomber. Le rapport dont je vous charge est de la plus haute importance. Remettez-le au général Marcus Jonathan de Stormwind le plus rapidement possible. Dès que vous le lui aurez remis, revenez avec sa réponse, qu''elle soit bonne ou mauvaise.$B$BMaintenant hâtez-vous !'),
(123,'frFR','Cette note est un tableau des heures et des jours auxquels une personne – décrite comme le "Collecteur" – doit recevoir une livraison d''or en provenance des mines de la forêt d''Elwynn.$B$BD''après le tableau, il semblerait que le Collecteur habite près du Champ de potirons des Brackwell, à l''est d''Elwynn.$B$BC''est une information importante. Vous devriez en faire part au maréchal Dughan de Goldshire.'),
(137,'frFR','If you earn a commendation from one of our Marshals, then bring it to me. It will be good for one of our Lion Emblem gloves.'),
(143,'frFR','Il y a quelque chose d''étrange dans le comportement de l''armée de Stormwind. Elle devrait se trouver là en force à l''heure qu''il est. De toute façon, le temps est un luxe que nous ne pouvons pas nous offrir. Je ne resterai pas là à regarder couler le sang du peuple de Lakeshire sans essayer de trouver de l''aide. J''ai entendu dire qu''une milice populaire s''était formée dans la marche de l''Ouest.$B$BApportez cette demande d''aide à leur chef, Gryan Stoutmantle. Ses hommes pourront peut-être nous apporter leur soutien en attendant que le roi envoie ses réserves.'),
(148,'frFR','Oh ! Comment doit faire un pauvre vieillard ? J''ai besoin d''aller chercher des fournitures à Darkshire, mais le village est si loin et je suis si vieux, si faible... Je n''y arriverai jamais.$B$BPouvez-vous aller à Darkshire et me rapporter des mèches de cheveux fantômes ? Vous les obtiendrez chez Madame Eva, qui habite la place de Darkshire.'),
(156,'frFR','Si vous m''apportez des racines pourries, je pourrai vous préparer une tournée de suc de zombie.$B$BLes racines pourries poussent dans des endroits étranges. J''ai entendu dire qu''on pouvait les trouver à l''intérieur des crânes des Démons squelettes et des Squelettes infernaux... Cela dit, je ne me suis jamais approché pour vérifier !$B$BLe cimetière de Colline-aux-Corbeaux et celui des Jardins paisibles sont tous les deux pleins de ces squelettes. Vous pourriez nous en débarrasser tout en cherchant les racines pourries. Darkshire vous en serait infiniment reconnaissant.'),
(173,'frFR','Les ténèbres s''étendent inexorablement sur le bois de la Pénombre. La quête de maître Carevin est l''expulsion du mal et de l''hérésie. Nos efforts protègent le peuple de Darkshire.$B$BVous sentez-vous digne de nous rejoindre ?$B$BJe pensais comme vous, autrefois. Mais la suffisance des Veilleurs était pénible et j''ai rejoint maître Carevin. Si vous voulez prouver votre valeur, les mots ne suffiront pas.$B$BTestez votre habileté contre les tisseurs d''ombre Plaie-de-nuit, des worgens qui rôdent dans le Verger pourissant et dans le bosquet de Clairbois (clair, mon oeil !).'),
(174,'frFR','Mon ami Cog, un gnome, a promis de m''aider à construire un outil qui permet de voir les étoiles. Il semblerait qu''il existe une vérité, au-delà de la magie, qui explique les étranges changements survenus dans la forêt.$B$BApportez-moi un tube en bronze fabriqué par un ingénieur habile. C''est la première étape, si j''en crois le plan de Cog.'),
(178,'frFR','<Vous entendez une voix désincarnée...>$B$BNe soyez pas $Geffrayé:effrayée;. Je suis Theocritus, grand mage de la tour d''Azora de la forêt d''Elwynn. Le pendentif que vous avez en main est un moyen de communication entre les gnolls Sombrepoil et leur maître Morganth.$B$BAprès des mois de recherches, j''ai cru que moi aussi je pourrais communiquer grâce à ces pendentifs. Si vous pouvez entendre ce message, c''est que mon sortilège est un succès.$B$BApportez-moi ce pendentif et je vous récompenserai.'),
(181,'frFR','Il ne manque plus qu''un seul objet pour terminer cet appareil. Le plan de Cog mentionne une lentille ou quelque chose comme ça. La seule lentille qui soit assez large pour l''appareil risque d''être très difficile à acquérir.$B$BUn ogre du nom de Zzarc''Vul habite dans la colline au sud du bois de la Pénombre. Si vous le pouvez, rapportez-moi son monocle et je l''utiliserai comme lentille !'),
(184,'frFR','Voici un titre de propriété concernant une ferme de la marche de l''Ouest, signé par un certain Théodore Furlbrow et par sa femme, Verna. Au dos, il y a quelques mots hâtivement écrits :$B$B"Nous avons fait pression sur Furlbrow et avons récupéré son titre pensant que ça pourrait nous être utile au cas où nous voudrions nous installer.$B$BIls ne nous embêteront pas. La dernière fois que je les ai vus, ils étaient sur la route de la marche, avec un chariot cassé."$B$BLes Furlbrow aimeraient sans doute récupérer leur titre...'),
(187,'frFR','Bien... Nous allons relever la barre, et voir dans quel bois on vous a taillé. Prouvez-moi que vous êtes en mesure de tuer 10 Anciens tigres de Strangleronce. Si vous y arrivez, vous serez digne d''affronter la dernière épreuve avant d''être nommé maître-chasseur de tigres en présence de maître Nesingwary.$B$BLes Anciens tigres ne sont pas seulement les plus difficiles à débusquer, ils sont aussi les plus féroces.'),
(188,'frFR','Voici votre dernier défi. Cela fait des semaines que nous traquons un tigre particulièrement malin. Nous l''appelons Sin''Dall. Essayez de réussir ce qu''aucun $R n''a réussi avant vous : débusquer et tuer Sin''Dall. Apportez-moi sa patte comme preuve.$B$BÇa ne va pas être une tâche facile...'),
(189,'frFR','Saletés de trolls ! Ils massacrent tous nos agents dès qu''ils mettent un pied dans la jungle ! J''ai perdu beaucoup de mes meilleurs hommes dans de simples escarmouches ! Les pertes deviennent insupportables ! Comment vais-je pouvoir expliquer cela au baron Revilgaz ?$B$BIl faut une action décisive... Pense, Kebok, réfléchis... Tu n''as pas gagné tes galons et ton poste en rêvassant... J''y suis ! Vous... $N, c''est ça ? Vous allez m''aider, n''est-ce pas ? Il y a de l''argent à gagner.$B$BVoilà le marché : vous me rapportez les oreilles de 15 trolls Bloodscalp et vous recevrez une récompense.'),
(190,'frFR','Si vous voulez faire partie de la chasse avec ce groupe de cracks rassemblé par Hemet, il va falloir vous en montrer digne ! On va tester vos capacités de chasseur de panthères... En commençant par le plus facile, soyez tranquille. Voyons si vous êtes capable de tuer 10 jeunes panthères. Pour débuter.$B$BLes débusquer représente seulement la moitié de la difficulté...'),
(198,'frFR','Hum ! Oui, il y a quelque chose que vous pourriez faire. Le lieutenant Doren et ses partisans, dans le nord, ont besoin d''être réapprovisionnés.$B$BIls n''ont encore rien reçu, et avec les attaques des trolls, j''aurais besoin de quelqu''un pour le faire. Le campement de Doren se situe au nord-ouest de la route, à l''entrée de Strangleronce depuis le bois de la Pénombre. Donnez les provisions au soldat Thorsen ; s''il n''est pas dans le campement, c''est qu''il patrouille plus au sud du camp.$B$BAttention, si vous échouez, vous devrez me rembourser.'),
(207,'frFR','Le colonel Kurzen était jadis un homme grand et noble. Je dois découvrir la cause de sa déchéance ! Il est peut-être sous l''emprise de la magie des trolls. Pour étayer cette hypothèse, il me faut étudier certaines de leurs légendes.$B$BQuatre tablettes sont cachées dans les ruines des trolls de Strangleronce. Je dois en prendre connaissance ! Recopiez-les et ramenez vos transcriptions.$B$BLa première tablette est dans les Ruines de Bal''lal, la deuxième dans le Récif infâme, et vous trouverez les troisième et quatrième dans les ruines de Zul''Kunda.'),
(208,'frFR','$N, vos talents à la chasse sont dignes de notre compagnie. Des champs de bataille de Lordaeron aux jungles les plus denses, j''ai rarement été témoin de prouesses telles que les vôtres.$B$BVous avez tué le féroce Sin''Dall, l''insaisissable Bag''thera et le perfide Téthis. Mais le trophée ultime reste la tête du roi Bangalash. Ce tigre blanc est la raison de ma présence ici. Il occupe mes pensées depuis longtemps déjà. Tuez le roi Bangalash et vous n''aurez personne à envier.'),
(210,'frFR','Presque toute la cuisine se fait au camp. Et c''était beaucoup de travail, jusqu''à ce que j''achète une marmite à un marchand gobelin de Baie-du-Butin. Cette marmite est une pure merveille, le temps qu''elle m''a fait gagner est inimaginable… malheureusement elle est cassée !$B$BPourriez-vous la lui ramener afin qu''il la répare ? Son nom est Krazek.'),
(215,'frFR','Merci de m''avoir sauvé, $N. Je sais de quoi ça a l''air, mais… permettez-moi de m''expliquer.$B$BJ''ai été chargé par le lieutenant Doren de rejoindre les troupes de Kurzen, pour les espionner, et fournir des informations vitales aux renseignements rebelles. Vous avez vu ce que j''ai cru être ma chance de m''infiltrer dans la base de Kurzen. Je m''étais trompé et, encore une fois, merci de m''avoir sauvé.$B$BIl s''agissait d''une mission secrète, aussi n''en parlez à personne. Mais si vous en parlez à Doren, il vous expliquera.'),
(218,'frFR','Mon journal ! Ils l''ont emporté dans la caverne. Celui qui l''a pris ? C''était une grosse brute avec d''étranges inscriptions sur la peau et le visage. Je n''ai pas pu regarder plus précisément.$B$BVous avez déjà combattu des trolls, peut-être pourriez-vous tenter de me le rapporter ?'),
(219,'frFR','Enfin, des amis de l''Alliance !$B$BAu secours… Je vous en prie…$B$BLa dernière chose dont je me souviens est que les orcs ont submergé nos forces. La plupart des hommes ont été tués. J''ai reçu un coup terrible à la tête et tout s''est assombri. Je suis à présent prisonnier dans cette caverne. Au secours, je suis gravement blessé !$B$BJ''aurais besoin d''aide pour revenir jusqu''à la ville... par pitié... vous êtes mon seul espoir...'),
(222,'frFR','Vos victoires passées m''ont convaincu que vous êtes capable de vous mesurer aux plus forts des worgens infestant les bois.$B$BParmi ceux qui se sont établis en ces contrées, les Crocs noirs et les Contaminés se sont montrés les plus dangereux. On peut les trouver près de certaines cavernes et dans la mine, au sud.$B$BVous pourrez voir de loin la lumière des feux qu''ils font avec les os de leurs victimes...'),
(229,'frFR','J''aurais dû vous le dire plus tôt…$B$BComment puis-je m''exprimer…$B$BIl se peut que Morgan ait cru que sa famille tout entière était morte, mais en fait sa fille Sarah est Gardien à présent. Elle a toujours été troublée par les… circonstances... entourant la mort de son père. Peut-être pourriez-vous lui donner des nouvelles.'),
(237,'frFR','Le Montagnard Cobbleflint n''a pas tari d’éloges à votre égard, $N. Aussi, je vais vous confier une mission de la plus haute importance. Nous devons maintenir la pression sur les forces d''invasion des troggs jusqu''à ce que les nains, nos frères, reviennent du front de l''Alliance.$B$BMettez-vous en route pour les collines méridionales et tuez 10 Brise-crâne et 10 Prophètes Brisepierre. Vos attaques nous feront gagner un temps précieux. Revenez me voir une fois votre mission menée à bien.'),
(242,'frFR','Throm-ka, $C. Il n''y a pas de temps à perdre. Les orcs du clan Dragonmaw ont fortifié leurs positions dans la vallée au sud d''ici.$B$BIls n''ont pas reconnu le mandat du Chef de guerre, ne nous laissant d''autre solution que de les exterminer, afin qu''ils ne salissent pas plus longtemps le nom de la Horde.'),
(244,'frFR','Je vous salue, $C. On m''a chargé de patrouiller sur ce bout de route. Bien qu''elle soit sûre pour l''heure, j''ai vu des campements de gnolls au nord et à l''est d''ici.$B$BLakeshire doit être mise au courant de ce rassemblement de forces ! Allez voir l’Adjoint Feldon et informez-le. Faites-le, et je suis sûr qu’il vous offrira la prime d''un éclaireur.$B$BD''ordinaire, Feldon inspecte les lieux au sud du pont menant à Lakeshire.'),
(245,'frFR','Je vous salue, $C. Peut-être avez-vous vu ces araignées qui ont envahi la frontière ouest ? Nous n''avons pas les forces nécessaires à une attaque, et le commandant n''a pas suffisamment d''hommes pour en envoyer si loin de Darkshire.$B$BCela me gêne de vous le demander, mais il semble que vous êtes de taille à vous en occuper. Je ne peux rien vous promettre de grande valeur, mais je vous récompenserai si vous parvenez à déloger ces horribles bestioles.$B$BOh, un petit conseil : évitez leur venin...'),
(250,'frFR','Grâce au Ciel, quelqu''un s''inquiète pour le barrage ! D''abord la destruction du viaduc de Thandol, ensuite le pillage de Dun Modr ! Je suis sûr que le barrage est la prochaine cible des Sombrefer. La plus grande partie de mon détachement de sécurité a été dépêché sur le front de l''Alliance, y compris mon meilleur inspecteur.$B$BC''est pourquoi j''ai besoin de vous, $N. J''ai aperçu quelques Sapeurs Sombrefer près de la rampe est du barrage. Enquêtez sur place, et ramenez un indice.'),
(251,'frFR','Apportez la lettre que vous m''avez donnée à Sirra Von''Indi. C''est un érudit en lettres anciennes. Si quelqu’un ici peut traduire ce message, c''est lui !'),
(257,'frFR','Vous croyez pouvoir vous mesurer à Daryl l''Intrépide, hein ? Si j''étais vous, je n’y croirais pas ! Bien sûr, vous êtes libre d''essayer. Voilà un défi qui devrait être au-dessus de vos capacités, alors ne culpabilisez pas trop si vous n''êtes pas à la hauteur.$B$BUn groupe de Buses s''est établi ici à Loch Modan. Pourquoi ne pas essayer d''en désabuser certaines ? Voilà le marché : si vous parvenez à accomplir le défi en quinze minutes, je vous donne mon arc ou mon fusil.$B$B<Il vous jauge dédaigneusement.>$B$BVous n''avez pas grand-chose à perdre, de toute façon...'),
(259,'frFR','Hello there, $N. I''ve heard much about your exploits, and must say I''m honored to meet you. I don''t suppose you''ve heard the story of Ol'' Kelt? Ah, well, Ol'' Kelt--Kelt Thomasin, that is--was once considered one of the finest hunters in all the realm. There wasn''t much he hadn''t done, but then, one day, he became obsessed with an ancient story... a myth, really. Well, as the stories go, a huge threshadon lives in the waters of the lake. Hogwash, if you ask me. If you''re interested, you might talk to Kelt.'),
(261,'frFR','Je serai franc. Nous sommes en guerre contre le Fléau. C''est un mal qui corrompt notre peuple et pollue nos terres. Il faut l''arrêter avant qu''il ne nous prenne de vitesse et n''entraîne notre monde dans l''obscurité. Nous, la Croisade écarlate, avons juré de combattre le Fléau de toutes nos forces et de toute notre âme.$B$BSi vous êtes de notre bord, faites montre de votre courage et prouvez-nous votre allégeance en détruisant les Ravageurs morts-vivants de Désolace, dans la vallée des Ossements, plus au sud.$B$BFaites cela, et la Croisade vous portera en haute estime.'),
(264,'frFR','Ordure abjecte ! Me laisser pour cette maudite croisade. Parce que "la Lumière est notre bien le plus précieux contre la menace des morts-vivants."$B$BEt ses enfants alors ? Et MOI ? Nuit après nuit, je l''ai attendu… à toujours passer après son fichu devoir !$B$BEh bien ! Regardez ce que la "justice" apporte, $N ! Il est mort et je porte au cou ce qu''il essayait d''arrêter !$B$BPortez ce bout de ferraille sur sa tombe au Sépulcre. Je ne veux plus rien avoir à faire avec ça... et avec lui !'),
(265,'frFR','Je vous rends votre livre, $N, et vous souhaite bonne chance dans vos recherches. Si vous enquêtez auprès d''autres personnes en ville, elles seront peut-être en mesure de vous fournir d’autres indices.$B$BEn attendant, en voici un : bien que l''auteur de ce livre soit étranger à Darkshire, le livre lui-même a été acheté ici.'),
(275,'frFR','Je ne sais pas pourquoi, mais il y a une prolifération maligne dans les Paluns. Les Rampants des tourbières se manifestent. Ils sont malades et répandent leur fièvre partout. Pour circonscrire l’épidémie, ils doivent être dispersés et renvoyés dans les marécages.$B$BLes Rampants des tourbières divaguent dans les voies navigables des Paluns.'),
(276,'frFR','Les gnolls Poils-moussus ont vécu paisiblement dans les Paluns pendant longtemps, mais aujourd’hui leur nombre augmente. Les buissons et les fleurs du marais ne leur suffisent plus, et pour alimenter leurs feux, leurs haches crasseuses coupent trop de bois.$B$BL''équilibre naturel n''est plus respecté. Pour la survie des Paluns, le nombre de gnolls doit être réduit.$B$BTuez 15 Gnolls Poils-moussus et 10 Bâtards Poils-moussus. Chassez-les au sud, près des nains de la Porte d''Algaz. Lorsque vous aurez terminé, revenez me voir.'),
(277,'frFR','Les Poils-moussus coupent les arbres des Paluns et les brûlent pour se chauffer. Je ne le supporte plus !$B$BAllez leur prendre leurs silex bruts, les outils qu''ils utilisent pour faire du feu. A l''exception des simples gnolls et des bâtards, tous les Poils-moussus portent des silex.'),
(278,'frFR','Commencez à collecter les matériaux de désamorçage, $N. Le venin de rôdeuse peut être collecté sur les araignées de Loch Modan. Vous trouverez les larmes de crocilisque dans le Loch également. Mais le cristal Mo''Grosh sera plus difficile à obtenir. Les ogres dans le nord-est en exploitent dans leurs mines, mais c’est un minerai très rare.$B$BNous devons être prêts à enrayer l’attaque des Sombrefer ! Revenez quand vous aurez collecté les ingrédients requis.'),
(282,'frFR','Je projetais d''envoyer mon apprenti apporter mon rapport à mon frère Senir, mais je préférerais qu''il soit placé entre des mains plus... fiables. Enfin, si vous êtes d''accord, bien sûr !$B$BHum... Vous devrez prendre le tunnel pour arriver à Kharanos.$B$BAllez voir le Montagnard Thalos avant de traverser le tunnel. Il est complètement infesté de troggs maintenant.$B$BRetournez vers Anvilmar, puis continuez en prenant à l''est vers le tunnel, Thalos n''est pas loin.'),
(288,'frFR','J''étais autrefois le Premier Officier du « Maîtresse de l''onde », l''un des bateaux de la IIIe flotte de Kul Tiras. La Flotte perdue. Perdue parce qu''à son dernier voyage, elle a été attaquée par des dragons rouges. Des dragons conduits par des orcs !$B$BNous n''avions aucune chance contre le feu des dragons... Notre flotte a été brûlée et envoyée par le fond. Je suis le seul survivant de ces malheureux navires...$B$B... Oh ça cogne dans ma tête ! Il me faudrait un coup à boire pour supporter cette gueule de bois et continuer mon histoire.'),
(290,'frFR','Pour rompre la malédiction et libérer mes frères d''armes, la... chose... qui se trouve sur mon bateau doit être récupérée et nettoyée ! Je ne sais pas ce que c''est, mais je sais qu''elle est en lieu sûr dans le coffre-fort du bateau, dont seul le capitaine Halyndor avait la clé.$B$BMon vieux capitaine rôde toujours dans mes rêves. Je sais qu''il erre sur "l''Intrépide", mon bateau perdu. Obtenez de lui sa clé et utilisez-la pour ouvrir le coffre de "l''Intrépide".$B$BEnsuite, quand vous aurez cet objet maudit, apportez-le au prêtre Glorin Steelbrow en ville.'),
(292,'frFR','En ouvrant le coffre, on trouve une sphère noircie, qui irradie une lumière à faire frémir. C''est le trésor dont Fitzsimmons a parlé : un Oeil maudit de Paleth.$B$BApportez l''Oeil maudit de Paleth au prêtre Glorin Steelbrow, un nain qui se trouve au port de Menethil. Demandez-lui comment lever la malédiction de l''Oeil.'),
(294,'frFR','La situation est grave, c''est certain. Les raptors ont été attirés par les ossements. Ces sales bêtes ont tué mes compagnons et nous ont coincés ici, Merrin, le pauvre Prospecteur et moi.$B$BAidez-nous à nettoyer les Paluns de ces raptors, $N. Il y a des raptors tachetés et des Hurleurs tachetés à l''ouest. Tuez-en 10 de chaque, si vous le pouvez.$B$BCe sera un bon début à la vengeance que je leur réserve.'),
(296,'frFR','Lorsque vous étiez là-bas, j''ai remarqué qu''un de ces monstres se tenait à l''écart des autres. Il était plus grand et plus menaçant. Je parie que c''est lui qui a incité les autres à venir ici interrompre les fouilles.$B$BJ''ai une dernière chose à vous demander, $N. Faites en sorte que Grondecroc réponde de ses crimes à la justice. Et compte tenu de la gravité de ses crimes, la justice dans ce cas, c''est la mort ! Apportez-moi une de ses serres pour preuve de sa mort.'),
(297,'frFR','Récemment, juste avant que les troggs ne débarquent sur le site, nous avons découvert un grand nombre d''étranges idoles taillées. Mais nous n''avons pas eu le temps de les étudier, car les troggs nous ont chassés des ruines juste après ! Et ces idoles ont un curieux effet sur les troggs : elles les rendent fous furieux !$B$BRapportez-moi 8 de ces idoles. Je veux les étudier et il ne faut pas qu''elles restent aux mains des troggs ! Vous pouvez trouver les idoles sur les troggs qui infestent le site.'),
(299,'frFR','Avant l''invasion, j''ai découvert une tablette appelée la Pierre de Goaz. Elle s''est brisée en quatre morceaux. Elle parle d''un "plan divin" et d''une "prophétie damnée".$B$BJe crains que nous n''ayons pas beaucoup de temps. Je suis trop vieux pour aller affronter ces bêtes. Mais vous êtes solide.$B$BExplorez le site de fouilles et cherchez les 4 fragments : Ados, Modr, Golm et Neru. Cherchez dans les artefacts anciens, ou bien là où le sol est meuble. Apportez-les, que je puisse résoudre le mystère !'),
(306,'frFR','C''était horrible ! Nous avions découvert quelques artefacts rares et nous commencions à nous intéresser à ces grands ossements.$B$BAvant d''avoir compris ce qui se passait, ces raptors marbrés ont déboulé sur le site. Il y a eu beaucoup de morts.$B$BC''est Ormer – et avec quel courage ! – qui nous a sauvés, le Prospecteur et moi. Il nous a couverts pendant que nous courions nous mettre à l''abri. Maintenant nous sommes pris au piège. Et nous avons perdu le fruit de notre dur labeur.$B$BTenez, apportez cette lettre à mon cher Tarrel pour lui expliquer la situation.'),
(310,'frFR','Je dois admettre que ces Thunderbrew font quelques bonnes boissons. Mais il faut qu’ils comprennent qu''ils ne sont pas les seuls brasseurs ! Vous pouvez peut-être m''aider à faire passer le message...$B$BTenez, prenez ce tonneau de Barleybrew Scalder. Glissez-vous dans le sous-sol de la distillerie Thunderbrew, à Kharanos, et échangez-le avec un de leurs tonneaux de Thunder Ale. Nous verrons bien si leurs clients préfèrent leur recette ou la mienne !$B$BBien sûr, si les tonneaux sont gardés, il faudra peut-être distraire le garde...'),
(318,'frFR','Rejold Barleybrew fait des expériences de brassage. Certaines ont bon goût, d''autres sont mauvaises et certaines... Eh bien, certaines mettraient par terre les plus vaillants des nains !$B$BCe brasseur habite à Brassetout, à l''ouest de Kharanos, et j''ai besoin de l''une de ses boissons : l''Evershine. Ça me tiendra au chaud quand je serai sur les routes glacées.$B$BEt... ce liquide béni brûle si bien que je peux le jeter dans la chaudière du Crache-vapeur pour avoir un peu plus de puissance ! Cette petite tactique m''a servi plus d''une fois.'),
(320,'frFR','Voici votre tonneau d''Evershine, $N. Et merci encore pour la partie de chasse.'),
(325,'frFR','Voici l''arme pour combattre le démon dont vous avez parlé. Vous pouvez y aller, $N. Je vous souhaite bonne chance et j''attends avec impatience d''entendre raconter vos exploits !'),
(330,'frFR','La note que vous m''avez donnée est signée d''un " M "... Je ne sais pas ce que ça signifie.$B$BMais... La note dit aussi que cette personne a partagé les tours de patrouille de Thorsen la semaine dernière. Le traître doit être l''un de ceux qui ont patrouillé en même temps que Thorsen !$B$BAllez voir le caporal Sethman. C''est lui qui gère la composition des patrouilles, il vous dira qui était avec Thorsen la semaine dernière.'),
(333,'frFR','Nous avons fait pas mal d''affaires dernièrement. On dirait que tout le monde achète des armures et des vêtements résistants. Comme s''ils s''attendaient à une saison froide et dure...$B$BMais ce sont là des soucis pour plus tard. Mon souci aujourd''hui, c''est que je suis à court de vêtements tricotés à vendre. J''ai besoin d''un autre lot de mon fournisseur.$B$BSi vous pouviez en prendre livraison auprès de Rema Schneider, chez le tailleur et équipementier du canal, je vous en serais très reconnaissant.'),
(334,'frFR','Mon fils Thurman est apprenti chez les Couturiers Larson, dans le Quartier des mages. Il était pressé aujourd''hui et il a oublié ses ciseaux et ses aiguilles. Je sais qu''un grand $C comme vous a des tâches autrement plus importantes à accomplir, mais sans ses outils, Thurman ne peut pas faire son travail d''apprenti !$B$BS''il vous plaît, $N, pouvez-vous rapporter à mon fils son matériel de couture ? Les Couturiers Larson tiennent l''un des deux magasins de prêt-à-porter du Quartier des mages, c''est le plus éloigné, près de la Tour du mage.'),
(335,'frFR','Le seigneur Wishock sème le trouble à la Maison des Nobles. Il sait pour notre petit "établissement" et fait pression pour qu''une enquête soit ouverte. J’ai un plan pour « occuper » Wishock, mais je vais avoir besoin de votre aide.$B$BIl y a une fleur qui pousse dans le jardin de Stalvan aux environs de Darkshire. On appelle cette petite fleur blanche la larme de Tilloa. J''aurai aussi besoin d''une racine de musquash, qu''on ne trouve qu''en bas des chutes du barrage de Formepierre dans les Paluns.'),
(336,'frFR','Le seigneur Wishock est comme tous les hommes, il a ses faiblesses. Il se trouve que la sienne est un penchant prononcé pour la bouteille. Quelle sidérante hypocrisie. Ce pauvre imbécile passe ses journées à essayer de faire fermer notre petite « taverne », et ses nuits à l’étage à rallonger une ardoise qu’il ne payera jamais. Et bien nous allons voir comment Wishock apprécie la cuvée spéciale que je lui ai préparée : la bière brune de la Griffe noire. C’est du brutal, $N.$B$BApportez-lui et voyez comment il réagit. Probable que ce vieil idiot soit en train de traîner autour de la Chambre du Requérant.'),
(343,'frFR','Je fais un discours sur la fermeté de l''Esprit et je voudrais citer des passages d''un livre sur la métallurgie : "Les Tensions du fer". Un exemplaire de ce livre doit se trouver à la Bibliothèque royale, dans le Donjon de Stormwind. Pouvez-vous le récupérer pour moi ? Si vous le faites, que la bénédiction de la Lumière soit sur vous !$B$BLa Bibliothèque royale est très grande, mais le responsable, Milton Sheaf, connaît chaque étagère comme sa poche. Parlez-lui, il cherchera le livre pour vous.'),
(344,'frFR','« Les Tensions du fer » ? Oui, je connais ce livre. Excellent ouvrage, écrit par le mineur nain Margulf Blaggon il y a quelques décennies. Il a passé l''essentiel de sa vie au cœur des montagnes de Khaz Modan, à creuser pour trouver du minerai. Chic camarade !$B$BMais où en étais-je ? Ah oui ! « les Tensions du fer » ! J''ai bien peur que le livre ait été envoyé à l''abbaye du Northshire. Le bibliothécaire de l''abbaye, le frère Paxton, voulait faire une copie de l’ouvrage pour sa propre collection.$B$BMais c''était il y a plusieurs mois. Je me demande pourquoi ça lui prend si longtemps...'),
(345,'frFR','J''avais l''intention de finir ma copie des « Tensions du fer », mais...$B$BEh bien vous voyez, je fabrique ma propre encre pour les livres que je copie. C''est une recette personnelle : elle ne coule pas, ne tache pas et sèche très rapidement, voire trop rapidement ! Mon dernier lot a séché avant la fin de mon travail de copie et je n''ai pas eu la possibilité d''en refaire !$B$BPour en fabriquer davantage, j''ai besoin de minerai de rethban qui vient des Carmines. Le contremaître Oslow de Lakeshire est mon fournisseur habituel.'),
(346,'frFR','Maintenant que j''ai fini ma copie des « Tensions du fer », je vous rends l''original. Merci pour votre patience et si vous voyez Milton, dites-lui que je suis désolé pour ce long retard.'),
(352,'frFR','Great Mammoda. Enormous, she was, with claws and teeth like swords. Now, I was caught off my guard, but I don''t think being ready would have helped my cause much. One swipe and poof! Darkness. They say I''m lucky to walk now...$B$BWell, not much enjoyment to be had in hearing that old story now, is there? Anyways, $N, if you''d like to try yourself against her, the Lady of the Loch,'),
(356,'frFR','Les défenseurs de la Barricade protègent Tirisfal des Maleterres et sont en alerte permanente. Mais parfois, le Fléau arrive à s''infiltrer.$B$BNotre succès à la Barricade dépend d''un front uni. Nous ne pouvons nous permettre d''être attaqués par l''arrière ou de voir les lignes d''approvisionnement des défenseurs coupées.$B$BRenforcez la Barricade. Patrouillez à l''est et détruisez toutes forces du Fléau que vous rencontrerez. Portez un effort particulier sur la ferme des Balnir. C''est devenu un havre pour les forces du Fléau qui maraudent dans le secteur.'),
(359,'frFR','J''ai besoin d''un rapport récent sur notre base de la Garde noire dans l''est.$B$BJe dois savoir s''il y a encore des incursions des forces du Fléau au-delà de la Barricade et dans Tirisfal. Notre vigilance à la frontière des Maleterres doit être maintenue. Nous ne pouvons pas nous permettre que les forces du Fléau s''établissent ici !$B$BVoyagez vers le sud en suivant la route, puis vers l''est à l''embranchement jusqu''au poste. Demandez la Garde noire Linnea. Elle a les informations dont j''ai besoin.'),
(367,'frFR','Dame Sylvanas a fait appel à la Société royale des apothicaires. La Dame noire croit que notre savoir couplé à cette nouvelle magie nous donnera la clé de la défaite d''Arthas. Elle nous a mis au défi de créer une Peste nouvelle, une Peste plus puissante que celle qui a ravagé Azeroth. Cette nouvelle infection amènera la ruine des forces du Fléau.$B$BMes études montrent que le sang de bêtes en pourrait être la clé. Rapportez-moi 5 fioles de sang de sombredogues, que je puisse tester ma théorie.'),
(391,'frFR','Qu''une chose soit bien claire, $N : je n''ai pas confiance en vous. Mais la situation étant ce qu''elle est, ça ne change pas grand-chose.$B$BAlors voilà comment on va faire : descendez là-bas et parlez à Thredd. Et si vous êtes vraiment de notre côté, tuez-le et ramenez-moi sa tête. Et s''il se trouve que vous êtes de son côté, et que vous ne revenez pas... Je vous retrouve et vous périrez comme un rat. Compris ?'),
(432,'frFR','Ces satanés troggs sont en train de démolir mon lieu de travail, que la Lumière les brûle ! Regardez-moi ça : un nouveau baril de poudre qui part en fumée !$B$BOh ! Si seulement je pouvais y aller moi-même et tordre, l''un après l''autre, leurs petits cous décharnés ! J''aimerais les tuer tous !$B$BTout ce stress, cette colère... Cela n''est pas bon pour ma santé. Et qu''ont-ils laissé d''intact ? Rien !$B$BJe les massacrerais volontiers, mais je ne sais plus viser ! Allez donc dans la carrière et tuez quelques-uns de ces salopiauds ! Je vous paierai, mais faites-leur mal, détruisez-les !'),
(440,'frFR','Si vous voulez retrouver le mari ou l''amant qui a donné cette bague à Deliah, parlez au Magistrat Sevren à Brill.$B$BMais je n''entretiendrais pas d''espoir à votre place : celui qui a offert la bague est certainement mort à ce jour. Et s''il est devenu mort-vivant, il a oublié Deliah depuis longtemps.'),
(458,'frFR','Louée soit la Nature, vous êtes là, $C ! D''étranges rumeurs sont parvenues jusqu''à moi par l''entremise des esprits de la forêt.$B$BLa mystérieuse Protectrice sylvestre, Tarindrella, est rentrée à Sombrevallon. Cette dryade n’est pas venue dans les forêts de Kalimdor depuis des années. Il y a sûrement quelque chose qui cloche pour motiver son retour.$B$BCherchez Tarindrella et voyez ce qui l''occupe en ce moment. Une des Sentinelles dit l''avoir vue au sud-ouest d''Aldrassil.'),
(459,'frFR','Quelque chose de malfaisant se développe dans les forêts de Teldrassil. Allez dans les collines où les paisibles furbolgs avaient habitude de vivre. Ils ont quitté leurs foyers et se regroupent maintenant, sous le nom de tribu des Pins-tordus.$B$BSeule la contamination par les pernicieuses gangremousses a pu provoquer ce changement. Les grells et les grellides ont infesté la zone et menacent les habitants de Sombrevallon.$B$BAttaquez ces grells et ces grellides, $N, et voyez s''ils sont tombés sous l’influence des Mousses corrompues.'),
(462,'frFR','Other than you, we sent two scouts through Algaz. Only one returned. Here''s what he discovered:$B$BThe Dragonmaws sent one of their Lieutenants, Maruk Wyrmscale, to organize a crew of orcs in Algaz and cut off the land route to Menethil Harbor!$B$BWe have to stop this, now. Take out Maruk, and then report to Valstag Ironjaw in Menethil Harbor.$B$BMaruk is headquartered in a small cave, across a pond between the second and third tunnels of Algaz. Menethil is through Algaz, then west along the road.'),
(463,'frFR','Avez-vous entendu parler du Gouverneur vert ? Vous ne le cherchez pas, n''est-ce pas ? Je dirais que vous êtes $Gfou:folle; si c''est le cas, mais qui suis-je pour empêcher $Gun illuminé:une illuminée; de courir à sa mort ?$B$BSi vous cherchez le monstre, je crois qu''il hante les marécages à l''est de la route où il y a l''embranchement pour Dun Modr. Il est tapi là-bas, parmi les crocilisques et de choses pires encore !$B$BEt puis, laissez donc votre argent ici ; il ne vous servira à rien où vous allez. Vous ne voulez pas non plus que le Verdâtre s''ébrèche les dents sur votre or quand il vous coupera en deux ?'),
(464,'frFR','Le clan des orcs Dragonmaw fut pratiquement anéanti à la fin de la Deuxième Guerre après qu''ils eurent perdu le contrôle de leurs dragons rouges. Les dragons n''étaient pas contents de leurs anciens maîtres et ont sauvagement traqué les Dragonmaw. Les quelques survivants ont fui de Grim Batol dans les montagnes jusqu’à l''est de l''Excavation de Whelgar.$B$BMaintenant ils ont repris des forces et campent au nord-est de Menethil.$B$BNous voulons que vous attaquiez leur campement. Vous rassemblerez et me rapporterez leurs bannières de guerre comme preuve de leur destruction.'),
(465,'frFR','Pendant que vous combattiez les Dragonmaw, nous avons percé à jour certains de leurs plans.$B$BNek''rosh a fait construire des catapultes et projette d''assiéger Menethil ! Et avec les combats à Dun Algaz, nous sommes coupés des renforts !$B$BVous devez détruire ces catapultes. Elles sont au campement des Dragonmaw.$B$BVoici, prenez ce combustible. Taillez-vous une route à coups d''épée jusqu''aux catapultes, puis brûlez-les à l''aide du combustible.$B$BAprès, trouvez et tuez Nek''rosh. Rien ne nous plairait plus que d''avoir la tête de cette engeance Dragonmaw au bout d''une pique...'),
(466,'frFR','J''ai appris qu''il existait un minerai rare, l''incendicite, dans les Paluns, dans une grotte au nord-ouest de la Porte d''Algaz. C’est un produit assez volatil, il explose à la moindre mauvaise manipulation ! Mais je suis sûr que correctement extrait, on pourrait l''utiliser pour donner un sacré punch aux obus de canon !$B$BApportez-moi de l''incendicite et je trouverai bien quelqu''un pour l''expérimenter.$B$BAh ! Et pour extraire ce minerai vous devez avoir la Compétence de Minage. Si vous ne l''avez pas, alors... amenez un ami qui la connaisse !'),
(472,'frFR','Dun Modr est tombé aux mains des nains Sombrefer !$B$BMes blessures sont sérieuses, $C. Mon régiment a été pratiquement décimé ! Ces brutes de Sombrefer nous ont attaqués avant que nous puissions nous regrouper après l''embuscade du viaduc de Thandol.$B$BNotre chef, Longbraid, a sonné la retraite. Comme nous quittions la ville, j’ai reçu une hache dans le dos. Un voile noir s''est abattu devant mes yeux.$B$BJe me suis réveillé ici, en sécurité à Menethil, mais j''ai peur pour mes compagnons. L''espoir ne m''a pas encore abandonné. Peut-être Longbraid est-il encore vivant ! $N, voyez si vous pouvez le retrouver, pas loin du village de Dun Modr !'),
(473,'frFR','$N. Le clan des orcs Dragonmaw montre sa puissance bien au-delà d''Algaz. Le capitaine Stoutfist a demandé à parler à tous ceux qui sont prêts à s''engager contre ces orcs. Il est à l''intérieur du donjon, dans la salle de guerre.'),
(482,'frFR','Bien sûr ! Comment ai-je pu oublier ?$B$BMoulin-de-l''Ambre était l''un des sites de prédilection pour le Kirin Tor, célèbre pour abriter des nœuds dormants d''énergie Ley. Les Sorciers doivent projeter de réactiver les nœuds et d''utiliser cette énergie pour quelque grande œuvre.$B$BNous ne pouvons laisser faire...$B$BIls vont avoir besoin de beaucoup de puissance pour activer les zones d''énergie Ley et nous pouvons enrayer le processus en volant leurs Pendentifs aux Sorciers.$B$BRapportez cette information à Allister, il décidera de la suite.'),
(486,'frFR','Le temps est venu de sauver les druides de la Serre. Si nous échouons maintenant, $N, ils resteront à jamais captifs de leur sommeil.$B$BJe pourrais préparer les Reliques d''éveil et pratiquer le rituel, mais mon travail ne peut prendre effet tant que le responsable de cette horrible situation est en vie. Le rituel ne sera achevé que lorsqu''il aura été terrassé.$B$BC''est Ursal le Mutileur qui a perturbé notre cycle, c''est Ursal le Mutileur qui doit payer pour qu''ils puissent être libérés. Voyagez jusqu''au camp des Pins-tordus, au sud-ouest, et exécutez-le.'),
(496,'frFR','Ah ! Un autre jour misérable à Moulin-de-Tarren ! Tout cet air pur me rend fou, $N.$B$BPlus vite nous répandrons l''épidémie parmi les humains, mieux ce sera. Je fais d''importantes recherches pour découvrir des agents mortels à utiliser dans mes décoctions, mais je n''ai pas eu le temps de les collecter tous.$B$BSi vous voulez vous rendre utile, trouvez-moi 10 Langues d''ours gris et du très rare Ichor de Rampant. Vous trouverez ces ingrédients juste à l''extérieur de Moulin-de-Tarren.'),
(499,'frFR','Cela va prendre un petit moment d''associer ces ingrédients pour mettre au point ce qui s''appellera l''élixir de souffrance.$B$BNous y voilà ! Ah ! Rien de tel pour égayer une triste journée dans ces mornes contrées que d''insuffler un peu de souffrance dans le monde.$B$BVoyons voir si notre petite potion produit l''effet désiré.$B$BDonnez à mon assistant Umpi un avant-goût de ce que la Dame noire a prévu pour les humains et ceux du Fléau.'),
(501,'frFR','Oh ! $N… Les fleurs s’épanouissent à Hillsbrad et l''air est si pur et vif... Comme cela est triste et regrettable. Je regarde par ma fenêtre crasseuse et je me languis de voir notre Peste nouvelle se répandre et porter la mort à ce monde qui le mérite tant.$B$BBien sûr, je resterais bien à ruminer mes pensées morbides toute la journée, mais mon devoir envers la Dame noire ne peut attendre. Vous m''aiderez, n''est-ce pas ? Mes recherches m''ont permis de conclure que la plus mortelle des préparations s''obtient à partir du sang d''un lion des montagnes. Apportez m''en et vous verrez ce que je suis capable de faire.'),
(502,'frFR','Ah ! Rien de tel que l''odeur du sang frais dans les collines !$B$BMaintenant, nous allons mélanger tout cela et commencer à nous amuser pour de bon ! Ce que j''ai créé à partir de ce sang, je l''appellerai l''élixir de douleur. Si mes calculs sont exacts, cette mixture pourrait bien être le début de la grande œuvre que je veux offrir à dame Sylvanas. Mais avant tout, nous avons besoin de faire un test.$B$BPrenez cet élixir et allez à la ferme la plus au nord dans les champs d''Hillsbrad, au sud-ouest. Et voyons comment Stanley, le petit chien du fermier Ray, apprécie cette "douceur".'),
(504,'frFR','Maintenant que vous avez eu un avant-goût des ogres Cassecrête, je veux que vous leur rentriez dedans franchement...$B$BAllez dans les ruines d''Alterac et débusquez des Combattants Cassecrête. Je veux que vous en fauchiez le plus possible : c''est la seule façon de faire comprendre à ces brutes qu''il faut garder leurs distances avec le territoire de l''Alliance.'),
(506,'frFR','Il y a quelques jours, j''ai reçu la visite du leader de ce Syndicat. Son nom est Aliden Perenolde et il se prend pour le seigneur de ce pays. Il m''a confié qu''il voulait utiliser les orcs qui s''insurgent contre lui comme esclaves, exactement comme le voulait son père et mentor, le méprisable Blackmoore.$B$BPlus important : il est venu en compagnie de sa maîtresse, une petite femme nommée Elysa, qui portait autour du cou le pendentif que le Chef de guerre désire tant.$B$BPartez maintenant, je me débrouillerai pour régler mes affaires.'),
(513,'frFR','Alors que je me résignais à l''idée qu''un autre jour allait s''achever exempt de toute joie, vous m''apportez ces merveilleuses fleurs de fangemufle.$B$BJe vais d''abord les réduire en une fine poudre. Nous aurons alors besoin que le Maître Apothicaire Faranell à Undercity lui applique son colloïde de virulence. Après, on devrait plutôt s''amuser, je crois...$B$BTenez, prenez cette Poudre de fangemufle et courez immédiatement voir maître Faranell, $N.'),
(515,'frFR','Un composé à base de fangemufle ? Absolument merveilleux ! Pourquoi n''y ai-je pas pensé ? Laissez-moi appliquer de mon colloïde de virulence à cette diabolique mixture.$B$BAfin d''activer les agents contaminateurs de ce brouet de fangemufle, Lydon aura besoin d''une potion de sang de troll forte, d''écailles de Daguéchine et d''yeux d''Ailerons déchirés de la côte méridionale. Il saura quoi faire une fois que vous aurez réuni tous les ingrédients. Ah ! j''ai tellement hâte d''apprendre ce que l''expérience va donner.'),
(528,'frFR','La nouvelle de l''attaque sur les fermes situées au nord a semé la panique chez les gens de la ville. Merveilleux !$B$BNos Traqueurs noirs rapportent que les paysans fuient vers les champs au sud d''Hillsbrad. Ces imbéciles pensent qu''ils peuvent s’y cacher et ainsi échapper à leur sort.$B$BMontrez-leur qu''ils ont tort, $N. Retournez aux Champs d''Hillsbrad et traquez les paysans qui s''y tapissent. Apportez-leur le chaos au nom de la Dame noire.$B$BRompez !'),
(542,'frFR','J''ai besoin de temps pour étudier le livre « l''Arme de Gri''lek » que vous m''avez apporté, mais je suis sûr que Milton a hâte d''enrichir la collection des livres de Stormwind avec ceux que vous avez retrouvés aux Ruines d''Alterac.$B$BLes voici, empaquetés et catalogués. Amenez-les à Milton Sheaf à Stormwind et je suis certain qu''il sera reconnaissant.'),
(544,'frFR','Je suis venu à Moulin-de-Tarren pour effectuer des recherches, mais je dois à présent résoudre une crise. Voyez-vous, quatre Réprouvés se sont enfuis d''Undercity il y a quelques mois. Ils ont trahi leurs semblables, mais pire encore : ils ont volé la Dame noire.$B$BCes voleurs ont forcé un coffre et se sont emparés de quatre artefacts, des objets dont nos apothicaires ont besoin pour leurs études. Dame Sylvanas veut récupérer ces artefacts.$B$BLes voleurs ont fui à Dalaran, et là-bas les sorciers les ont placés en quarantaine dans le Camp d''internement de Lordamere.'),
(551,'frFR','Ce parchemin est sous l’effet d’un sort qui le rend indéchiffrable. Mais un mot peut être lu, en haut du papier :$B$B$BNagaz'),
(559,'frFR','Le croirez-vous, $N ? Redpath n''était pas satisfait, en dépit de tous les murlocs que nous avons tués. Ah ! ne soyez pas modeste, vous y avez participé. À présent il veut que je lui apporte la preuve de leur mort, en allant chercher les têtes refroidies de ces misérables murlocs, pour les soumettre à sa validation.'),
(565,'frFR','Moi, le Grand Bartolo, je confectionnerai pour vous ma fameuse cape en fourrure de yéti, célèbre dans le monde entier, et qui fait la renommée de l''Alliance !$B$BJe vous mets au défi de parcourir le monde pour trouver meilleure cape. Oh ! attendez, qu''est-ce que vous dites, $Gpetit:petite; $N ? "Bartolo, il n''existe pas de meilleure cape !" Oui, oui, je sais, j''ai entendu ça des milliers de fois déjà.$B$BBartolo demande une pelote de laine, une cape d''homme des collines confectionnée par un habile tanneur, du fil fin et bien sûr de la fourrure de yéti. Apportez-moi tout cela et vous serez $Gun client satisfait:une cliente satisfaite;.'),
(575,'frFR','“Le meilleur artisan du cuir des mers du Sud et des deux mondes, Ancien et Nouveau”. C’est comme ça qu’on m’appelle. Moi ! Drizzlik ! Le meilleur artisan… Hem. Bon.$B$BMes objets en cuir sont réputés dans le monde entier pour leur perfection – le vrai choix des connaisseurs !$B$BJe viens de recevoir une commande du directeur Riddlevox du Syndicat des Artisans. Il veut une douzaine de ses bottes préférées, le modèle Excelsior (notre meilleure vente, soit dit en passant.)$B$BPour mettre en place la forme, j’ai besoin de peaux de crocilisques. Vous trouverez les meilleurs spécimens le long des rivières, dans le nord de Strangleronce.'),
(584,'frFR','La tête de Yenniku n’était pas parmi celles que vous avez apportées, et je remercie le Grand Serpent pour cela. Mais nous n''avons pas progressé dans nos recherches pour le retrouver.$B$BNous devons connaître la vérité, et je crains que seuls le Chef du clan Bloodscalp et son Sorcier la connaissent. Ce sont les ennemis de la tribu Darkspear et ils n''avoueront rien d''eux-mêmes, aussi nous devons extraire la vérité de leurs lèvres mortes.$B$BApportez-moi les têtes de Gan''zulah et de Nezzliok le Redoutable, et placez-les dans ce chaudron.$B$BIls sont loin dans les profondeurs de Zul''Kunda. Apportez-moi leurs têtes... nous les ferons alors parler.'),
(587,'frFR','Ah ! La vie en mer. Je ne vais pas dire que c''est la bonne vie, mais c''est ma vie.$B$BLorsque j''arrive au port, j''aime me trouver une bonne bouteille de tafia et du tabac à priser de qualité. Des habitudes dégoûtantes, mais que serait un pirate sans ses vices, pas vrai ?$B$BAlors vous pouvez imaginer mon dépit lorsque j''ai découvert que l''herboriste de la ville était parti et avait vendu sa marchandise. Dire que son chargement a été détourné par ces fichus Ecumeurs de la Voile sanglante.$B$BJe parie, $C, que vous pourriez les convaincre de partager, non ?'),
(590,'frFR','Quoi ?$B$BQuoi ?$B$BVous voulez de l''argent ? Je ne vous dois pas un sou.$B$BUne lettre ? Quelle lettre ? Oh ! Vous voulez vous battre, alors ? Très bien, $Gmon pote:ma fille;… Allons-y ! Je vous dois de l''argent…'),
(599,'frFR','Bon sang ! Ainsi les boucaniers de la Voile sanglante préparent une attaque contre Baie-du-Butin ? Eh bien ! Ces crapules ne manquent pas d''air. Mais Baie-du-Butin restera dirigée par les Ecumeurs des Flots noirs !$B$BC''est plus grave que je ne le croyais. Allez dire ce que vous avez appris à l''amiral Seahorn immédiatement ! Ce vieux loup de mer est quelque part en ville...'),
(611,'frFR','Ainsi vous recherchez un autel d''un certain genre ? Eh bien ! Je ne suis pas experte en ruines de trolls comme peut l''être mon père, mais j''ai entendu parler d''une cité troll engloutie près de cette île que vous cherchez. Peut-être devriez-vous essayer là-bas ?$B$BVous avez récupéré mon couteau, alors je suppose que vous pouvez l''emprunter... Mais je veux que vous me le rendiez quand vous aurez fini !'),
(621,'frFR','Zanzil le Paria demeure avec ses partisans dans les Ruines de Jubuwai et dans celles d''Aboraz, au nord-est de Baie-du-Butin. Il a été banni de sa tribu. Pourquoi ? Eh bien !…$B$BZanzil a le pouvoir de soumettre la volonté des autres, et ses chefs ont peur de lui. Il utilise un mélange de plantes tropicales pour supprimer la volonté et endurcir le corps de ses partisans.$B$BCette préparation intéresse beaucoup ceux qui voudraient contrôler les autres.$B$BApportez-moi des échantillons de ce mélange, et je leur trouverai une utilité.'),
(622,'frFR','Pendant que vous étiez $Gparti:partie; j''ai réparé la cocotte que vous m''aviez apportée. J''y ai même ajouté un autre sifflet à vapeur, et regardez : il y a un hachoir au fond pour réduire les os de pattes en bouillie ! Oui ! La Cocotte ébréchée de Krazek ravira tout cuisinier à 100% ! Je suis sûr que son propriétaire en sera satisfait.'),
(623,'frFR','$N, puisque vous êtes là : j''ai reçu un message de Groy pendant que vous étiez $Gparti:partie;. Il dit être satisfait de la dernière livraison, mais il a un client qui en désire plus, et tout de suite.$B$BJe ne vais pas à Theramore avant une semaine, mais si vous faites le voyage, vous pourriez transporter la marchandise pour moi.$B$BUn peu d''aventure vous tente ? Vous savez où se trouve Âprefange, n''est-ce pas ? Je ferais attention quand même, Theramore peut être dangereuse si vous n’avez pas le bon profil.'),
(627,'frFR','Il y a une caverne dans la montagne, dans la gorge des Sèches-moustaches, loin au nord dans les hautes-terres d''Arathi. Cette caverne abrite un minerai rare : la pierre de sang. Celle de cette caverne n''est pas de la meilleure qualité, mais elle a quand même une certaine valeur...$B$BJ''en aimerais un peu.$B$BJe vais réparer votre cocotte, mais pendant que j''y travaille, allez chercher des fragments de pierre de sang. Apportez-m''en assez, et je vous donnerai un bonus.$B$BEt si vous n''avez pas la capacité de l''extraire... trouvez quelqu''un qui le peut !'),
(628,'frFR','Maintenant que l''intérieur est terminé, tout ce qui reste à faire est la couche extérieure. Pour ça, je n''utilise que les meilleures peaux de vieux crocis. Elles sont plus souples et solides, avec de belles écailles ; toutes les qualités qui définissent la gamme Excelsior de Drizzlik.$B$BIl est difficile de trouver des peaux parfaites, et celles qui me conviennent le mieux proviennent des vieux crocilisques marins. Les vieux ne sortent que pour défendre les autres crocis marins, alors il faudra en occire quelques-uns avant d’attirer un vieux.'),
(631,'frFR','Une explosion monstrueuse a grondé à travers les collines. C''tait horrible, j''vous l''dis !$B$BDe bons soldats sont morts en défendant le viaduc de Thandol. Longbraid dit que nous prendrons notre revanche sur les Sombrefer avant que tout cela ne soit fini.$B$BIci, il n’y a que des blessés, et je ne vois aucun renfort arriver à l''horizon. Longbraid a envoyé le vieux Rustlocke en reconnaissance au pont à l''est, pour voir si nous pouvions le sécuriser.$B$BC''était il y a plusieurs jours. Avec Dun Modr en état de siège, nous n''avons pas les ressources d’aller le chercher.$B$BPeut-être pourriez-vous le trouver...'),
(633,'frFR','Par le Ciel, non ! Pauvre Rustlocke ! C''est une tragédie !$B$BNous ne devons pas laisser sa mort impunie. Le parchemin qu’il tenait indique que Kam Deepfury, le cerveau derrière la première attaque, a fait entreposer des explosifs dans une cache, juste de l''autre côté du viaduc de Thandol, dans les hautes-terres d''Arathi.$B$BSi ces explosifs atteignent le pont, notre principale ligne d''approvisionnement vers le nord sera très compromise. La cache doit être détruite, $N. Revenez me voir lorsque votre mission sera accomplie.$B$BVous êtes notre seul espoir.'),
(645,'frFR','Qu''est-ce donc ? Les quatre Glyphes une fois réunis, ils se sont rassemblés pour n''en former qu''un seul : le Glyphe d''Ignaeus. Celui-ci pourra sans aucun doute désactiver la garde placée sur la tombe de Trollbane.$B$BSes restes sont ensevelis dans le Sanctuaire derrière la chapelle de Stromgarde. Rapportez Trol''kalar.'),
(663,'frFR','Lolo voit une minuscule personne ! Toujours Lolo faire le guet !$B$BBienvenue à la crique de Faldir, $N. Capitaine O''Breen a dit que nous resterions que quelques heures. Juste le temps de récupérer le trésor, puis nous revenir à Baie-du-Butin.$B$BMais Lolo pense que ça va durer plus longtemps. Notre groupe a perdu deux navires. Pauvres « Esprit des Pins argents » et « Folie de la vierge ». Au fond de la mer maintenant ils reposent !$B$BLolo propose de vous parler au capitaine O''Breen si vous voulez rester ici.'),
(664,'frFR','Argh, quelle horrible vie ! Je devrais être mort sous l''eau, et pas assis ici près d''un feu, respirant de l''air frais.$B$BL''équipage a tout fait pour sauver mon merveilleux « Folie de la Vierge ». Loué soit-il !$B$BO''Breen a réussi à atteindre la rive, nous on n''a pas été aussi chanceux. La mer s''est carrément défilée sous nous, je le jure.$B$BA un instant on naviguait, l''instant d''après on était échoué sur un récif. Et ces créatures ! Elles ont tué tous les survivants. Saleté de nagas ! Je me suis évanoui, puis je me suis réveillé ici.$B$BJe veux que ces créatures meurent !'),
(693,'frFR','Hé $N ! Désolé d''avoir été un peu bref, la dernière fois j''étais pris de court... euh, non ce n''est pas un jeu de mots.$B$BJ''ai découvert où le premier objet de Trelane a échoué : c''est Kor''gresh qui l''a au Hall Rochepoing. Pendant que j''y suis : il jette des éclairs de glace sur ses troupes pour qu''elles gardent leur position, ce qui prouve qu''il n''est pas loin de maîtriser tous les pouvoirs de l''objet.$B$BVous trouverez le Hall Rochepoing au sud d''ici puis à l''est du viaduc de Thandol. Trouvez cet ogre et ramenez-moi la baguette.$B$BPendant que vous serez en chemin, je vais voir ce que je peux faire pour Stromgarde.'),
(694,'frFR','Alors vous êtes d''attaque ?$B$BVoici la prochaine étape : il y a des ogres tout autour de la Tour d''Arathor à Stromgarde. Nous devons activer les défenses de la tour si nous voulons avoir une chance contre eux et sauvegarder les objets. Pour cela, nous avons besoin de ces gemmes que les chamans Rochepoings apprécient particulièrement. Ils les ont récupérées à la tour, mais ils ne vont pas les garder très longtemps.$B$BRécupérez une de ces gemmes, et portez-la à Kryten : il connaît le sort pour l''enchanter afin qu''elle serve de clef.'),
(703,'frFR','Oh oui ! Mes ailes de busard grillées sont les meilleures ! La sauce est savoureuse et la viande est épicée à souhait. Son odeur attirerait les gens à des kilomètres à la ronde !$B$BJ''ai tout ce qu''il faut pour en préparer. Tout... excepté des ailes de busard !$B$BDonc si vous en voulez, apportez-moi des ailes de busard. Apportez m''en assez, et je vous donnerai même la recette !'),
(705,'frFR','Les Terres ingrates sont inhospitalières. De dangereux prédateurs et de puissants charognards y pullulent. Effrayant, surtout pour un tout petit gobelin. Pour y survivre, il faut être astucieux !$B$BJe sais comment fabriquer des bombes éclairantes. Je les utilise pour éloigner les bêtes sauvages. Mais je commence à manquer d''un des ingrédients : de la poudre de perles bleues. Apportez-en et je vous récompenserai.$B$BHé ! J''espère que vous avez de bonnes bottes. Les perles bleues proviennent de palourdes qui vivent au Récif infâme.$B$BOuaip, le Récif infâme de Strangleronce !'),
(714,'frFR','$N, vous avez brillamment accompli votre travail.$B$B<Lotwil est visiblement obnubilé par son travail.>$B$BSi vous venez à Kharanos, n''hésitez pas à me rendre visite.$B$BOups ! Vite ! Rattrapez le... oui, ça là. Merci.$B$BMaintenant, j''ai juste besoin d''une dernière petite chose. C''est un petit truc, mais c''est indispensable, j''en ai peur : un Gyrochronatome.$B$BSi vous pouviez en récupérer un et me l''apporter, alors je pourrais finir ceci.'),
(718,'frFR','Dans notre précipitation pour quitter le site de fouilles d''Uldaman, nous avons été obligés d''abandonner de nombreux chariots et caisses de fournitures le long du chemin. Les ogres locaux du Camp Kosh se sont précipités sur notre équipement comme des vautours sur une charogne. Ils ne sentent pas meilleur d''ailleurs. Que la charogne je veux dire !$B$BEnfin bref, ils ont pris une caisse qui contenait toutes nos armes et notre... ben, c''est un peu embarrassant, nous n''avons pas pris de nourriture avec nous.$B$BNous sommes dans le pétrin maintenant, pourriez-vous nous aider ?'),
(720,'frFR','<Des mots sont grossièrement écrits à la craie sur la carte.>$B$B"Ryedol,$BIls m''emmènent à Uldaman. Envoie de l''aide.$B-Hammertoe"'),
(726,'frFR','<Le Conseiller Belgrum achève de lire la note, et ses yeux s''élargissent un moment.>$B$BHoula, très mauvaises nouvelles !$B$B$N, Retournez voir l''Historien Karnik et dites-lui qu''il agit sous l''autorité du roi, et qu''il s''occupe de cette affaire rapidement et avec fermeté. Il doit mettre un terme aux activités des Ombreforge dans les Terres ingrates.'),
(731,'frFR','Alors, Hollee... Oh c''est vrai ! Vous n''êtes pas Hollee. Où est Hollee ?$B$BBah, ce n''est pas le problème ! Nous devons trouver ce pinceau à pierre... enfin je veux dire ce mystérieux fossile ! Nous devons le trouver. La Ligue des Explorateurs à Darnassus veut savoir sur quoi je travaille.$B$BDites-moi quand vous serez d''accord et nous partirons à la recherche de ce pinceau.... je veux dire de ce fossile ! Nous trouverons peut-être quelque chose d''intéressant à écrire à la Ligue.$B$BAlors on y va ?'),
(734,'frFR','Merveilleux, merveilleux.$B$B<Lotwil lève les yeux vers vous un instant avant de reprendre son travail.>$B$BAllez parler à Lucien, $N. J''ai besoin d''un rouage n° 5. Voulez-vous bien me l''apporter ?'),
(743,'frFR','Merci de prendre le temps de me parler, $N. Je suis Ruul, guerrier et professeur.$B$BVous avez atteint l''âge où il vous faut vous préparer à de dures épreuves si vous comptez vous aventurer hors de Mulgore.$B$BSi vous voulez éprouver votre force, commencez par aller chasser les harpies Furie-des-vents au sud-est. Elles nichent le long des crêtes des montagnes, loin de la route.$B$BElles sont l''un de nos ennemis naturels, ici à Mulgore. Les affronter éprouvera vos compétences.'),
(744,'frFR','$N, mon frère doit bientôt se présenter devant le chef Bloodhoof et il est de mon devoir de lui faire une coiffe digne de ce nom.$B$BJe voudrais vous demander une faveur, pendant que je finis de tanner ces lanières de cuir. Je n''ai, hélas, pas eu le temps de collecter suffisamment de plumes et je me demandais si vous pouviez en rassembler quelques-unes pour moi ?$B$BVous pouvez trouver des plumes de bonne taille sur les harpies qui vivent loin au nord et au nord-ouest de Thunder Bluff. Je n''ai besoin que de 6 plumes d''azur et de 6 plumes de bronze.'),
(748,'frFR','Des gobelins et leurs serviteurs ont pollué nos puits sacrés ! Nous ne pouvons tolérer cela.$B$BPour assainir les puits, je dois créer un totem de purification que vous devrez porter au puits, afin de pratiquer le rituel de purification.$B$BD''abord nous allons fabriquer le totem de purification pour le puits Winterhoof. Pour ce faire, le pays doit offrir son aide. Chassez des loups des prairies pour leurs pattes et des trotteurs des plaines adultes pour leurs serres. Vous les trouverez au sud-ouest.$B$BRevenez avec les pattes et les serres, $N.'),
(756,'frFR','Pour créer le Totem de purification de Thunderhorn, vous devez collecter les griffes des prédateurs qui hantent les plaines de Mugore. Chassez les traqueurs des prairies et les pumas des basses plaines pour leurs griffes, puis revenez me voir.$B$BVous trouverez les traqueurs des prairies et les pumas des basses plaines à l''est et à l''ouest.'),
(759,'frFR','Il ne reste qu''un puits à purifier, appelé puits Wildmane, d''après le clan du même nom. Pour nettoyer ce puits, nous aurons besoin des dents d''un redoutable prédateur : le loup alpha des prairies. Allez chasser ces loups au nord, puis revenez me voir lorsque vous en aurez fini.$B$BLes alphas rôdent souvent autour de notre majestueuse cité de Thunder Bluff.'),
(821,'frFR','Voudriez-vous goûter à l''homonyme de Chen ? Ahhh ! La Stormstout est une puissante mixture. Chen a appris la recette à mon mentor, et mon mentor me l''a apprise. J''aurais besoin que vous me trouviez certaines choses, mais je vous assure : le choc en vaut la peine.$B$BApportez-moi 5 Canines de lion des savanes, de n’importe quel lion des savanes ; 5 Rognons de trotteur des plaines, de n''importe quel trotteur des plaines, et 1 Corne de lézard-tonnerre. Ça devrait parfaitement faire l''affaire.$B$BVous pouvez trouver ces ingrédients dans les Tarides.'),
(826,'frFR','Le sorcier-docteur Zalazane demeure sur les îles de l''Écho, à l''est. Ce sont les îles que nous appelions autrefois « maison ».$B$BDe là, il envoie ses trolls sur le continent et déchaîne ses maléfices sur notre peuple pour placer davantage des nôtres sous son emprise.$B$BIl faut l''arrêter.$B$BBattez Zalazane et ses serviteurs, d''anciens trolls Darkspear perdus pour notre cause. Apportez-moi sa tête, et je saurai que son règne maléfique est terminé.'),
(840,'frFR','Hum ! Vous avez l''air plutôt $Gfort:forte;.$B$BÉcoutez, mon bon ami Kargal a besoin de nouvelles recrues pour servir dans les Tarides. Je sais que vous voulez faire ce qui est bon pour la Horde. Eh bien, voici votre chance !$B$BApportez cette lettre de recrutement à Kargal et voyez s''il la signe...'),
(853,'frFR','J''ai fait une émulsion avec les spores que vous m''avez apportées. Je dois à présent l''envoyer à mon associée, l''Apothicaire Zamah. Si vous pouviez la lui apporter, elle pourra vous offrir quelque chose de nos magasins d''alchimie.$B$BElle est aux Bassins de la vision, une caverne qui se trouve sous les chamans de Thunder Bluff. Le chemin menant à cette caverne est bien caché, mais vous pourrez le trouver sur la Cime des Esprits.$B$BDépêchez-vous ! Cette émulsion ne restera pas puissante longtemps. Elle doit être livrée et utilisée au plus vite.'),
(860,'frFR','Si vous souhaitez suivre la voie du chasseur, alors votre voyage vous mène jusqu''aux Tarides. Ses créatures sont robustes et féroces. Vous y apprendrez beaucoup en les traquant, et votre volonté grandira.$B$BParlez à Sergra Darkthorn. Elle sera votre premier guide dans les Tarides.$B$BElle se trouve à la Croisée. Pour l''atteindre, allez à l''est en partant du village Bloodhoof et en vous rendant dans les Tarides, puis allez au nord lorsque le chemin se sépare. Et attention tandis que vous voyagez. Les Tarides réservent de grands dangers pour ceux qui manquent de préparation ou de prudence.'),
(868,'frFR','Hé $N ! On m''a fait venir à la Croisée pour surveiller la zone et noter ce qui s''y déroule, pour mes maîtres à Orgrimmar.$B$BL''un de mes sujets d''étude est cette créature, ressemblant à un insecte, et que nous avons découverte au sud dans le Champ des géants. Nous savons peu de choses sur ces bêtes, alors je me fais un point d''honneur d''en découvrir plus. Elles semblent posséder quelque intelligence, plus que la plupart des simples animaux.$B$BPrenez cette griffe d''excavation et récupérez quelques œufs dans les tertres où vivent ces bêtes. Mais attention, si elles sont alertées par quoi que ce soit, elles vous attaqueront.'),
(875,'frFR','Ha ha ha ! $N. Vous en voulez encore ? Bien. J''aime entendre ça.$B$BCette fois-ci je veux que vous tuiez certaines des lieutenants harpies des Collines arides. Seules les Tueuses Ensorçaile peuvent être lieutenants, et vous pouvez les reconnaître à la bague qu''elles portent. C''est une vilaine bande, qui dirige beaucoup de subalternes dans le secteur. Tuer 6 d''entre elles portera un coup décisif à leur matriarcat.$B$BFaites en sorte qu''elles meurent dans la douleur, $N. Nous voulons montrer à ces femelles qu''il n''est pas sage de choisir la Horde comme adversaire.'),
(892,'frFR','Tout a l''air correct selon mes registres, $N. Retournez-y et dites à Gazlowe que sa chance a tourné. Je ne serais pas surpris que les pirates aient pris ses marchandises.$B$BJe ne peux rien faire d''autre pour lui. Oh !… Vous pourriez lui dire quand même que j''ai quelque chose venant d''Undermine à son nom, s''il peut faire un saut pour le chercher.'),
(973,'frFR','Ilkrud Magthrull ? Oui, je le connais. Il s''agit d''un puissant démoniste orc qui s’est établi au Sanctuaire de Scarfeu, un endroit très maléfique dans le sud-ouest d''Ashenvale.$B$BIl n''a pas été plus qu''un simple désagrément jusqu''à présent, et je n''ai pas eu affaire à lui, mais il semble que le temps soit venu.'),
(997,'frFR','Vous allez vers le sud ? Au lac Al''Ameth ? Si c''est le cas, j''ai une tâche à vous confier...$B$BMon collègue Denalan campe le long du rivage oriental du lac, où il étudie la flore de Teldrassil. Il a demandé qu''on lui envoie un paquet de Terre rare de Darnassus, mais il y a eu du retard et le paquet vient seulement d''arriver à Dolanaar.$B$BPouvez-vous le lui apporter ?'),
(1008,'frFR','Il y a un endroit sur notre côte nord-ouest, connu sous le nom de grève de Zoram.$B$BC''est là que se trouve la cité perdue de Zoram, détruite pendant le Fractionnement et submergée par les eaux. Cela fait une éternité que les elfes de la nuit l''ont perdue. Perdue et presque oubliée.$B$BAujourd’hui, les nagas y sont retournés et nous ne savons pas pourquoi. Mais la raison importe peu : nous devons tuer ces démons et les rejeter dans les profondeurs !$B$BRevenez me voir quand votre mission sera achevée.'),
(1013,'frFR','$N, il y a un livre dans le donjon d''Ombrecroc, le « Livre d''Ur », qui ferait très bon effet dans ma collection. Ur était un grand mage de Dalaran avant l''arrivée du Fléau, les études qu''il a faites dans certains domaines ont beaucoup de valeur aux yeux de certains... parmi les Réprouvés.$B$BPénétrez dans le donjon d''Ombrecroc et trouvez ce livre. Apportez-le-moi et je ferai part de votre action à notre Dame noire.'),
(1024,'frFR','Vous devrez chercher par vous-même, mais d''après les notes de Teronis, il semble que la prochaine étape soit de trouver les autres morceaux du Bâtonnet que Dartol a créé. Je commencerais par me diriger vers le puits de lune à l''est du lac Iris. Suivez la route et prenez au nord lorsque vous atteindrez une petite zone de repos sur votre gauche.$B$BVotre meilleur guide sera une dryade du nom de Shael''dryn. Cherchez-la.$B$BPrenez la Gemme avec vous : Shael''dryn en aura besoin si elle doit vous aider à réparer le Bâtonnet.'),
(1031,'frFR','Anilia pose ses mains sur vos épaules et vous attire vers elle. Haletante, elle indique l''arche au nord, avant de fermer les yeux pour toujours. " Il l''a pris... Geltharis..." Au fond du cœur, vous comprenez que le dernier souhait d''Anilia est de voir la branche de Cénarius à nouveau entre les mains des dryades.'),
(1034,'frFR','La Larme d''Elune a un peu amélioré l''état de ma fille. Ses cauchemars ont diminué et je remercie la déesse pour sa bénédiction. Mais... la fièvre n''a pas baissé.$B$BOrendil m''a parlé d''une poussière dépolie que l''on trouve dans les Ruines de Chimétoile. Peut-être qu''elle diminuerait la fièvre de Relara. Trouvez un peu de cette poussière, et rapportez-la-moi, je vous en prie.$B$BLes Ruines de Chimétoile se trouvent au sud, $N. Puisse Elune vous faire revenir rapidement !'),
(1038,'frFR','Le « Tome de Mel''Thandris » vous a montré cela ? Je suppose qu''il n''y a pas grand mal à vous permettre d''examiner ses affaires. Cette clé ouvrira le coffre dans lequel nous avons stocké ses effets, dans le baraquement des Sentinelles. Elle a tenu un journal de sa mission, s''il y a quoi que ce soit à apprendre, ce sera là-dedans.$B$BJe dois ajouter que les Sentinelles croient qu''elle avait des raisons personnelles de partir et s''attendent à ce qu''elle revienne à tout moment. La prêtresse a fait beaucoup dans le passé pour gagner notre confiance.'),
(1040,'frFR','Oh oui ! Enfin trouvé. Z''auriez dû me dire qu''elle était passée il y a longtemps. Voyons.$B$BVelinde Starsong. Passage réservé à Baie-du-Butin sur le « Balbuzard noir ». Je n''ai rien d''autre là-dedans, donc je suppose qu''il est arrivé à bon port.$B$BJe ne peux pas faire grand''chose de plsu pour vous. Elle a cependant demandé comment voyager par voie de terre de l''autre côté et je lui ai indiqué Ruzzgot, un chef de caravane basé à Baie-du-Butin. Peut-être que cette Velinde a voyagé avec lui.$B$BMaintenant dégagez. Je n''ai pas toute la journée à vous consacrer.'),
(1054,'frFR','Les furbolgs Crins-de-Chardon sont au nord d''Astranaar. Mes éclaireurs m''ont appris que leur nombre a très fortement augmenté ces derniers mois. S''ils deviennent trop nombreux, ils pourraient bien trouver le courage d''attaquer Astranaar...$B$BTuez-en autant que possible, mais surtout apportez-moi le crâne de leur chef pour me prouver que vous les avez arrêtés... Au moins pour l''instant.$B$BJe vais rester à Astranaar pour attendre de vos nouvelles. Qu''Elune soit avec vous !'),
(1058,'frFR','Je suis surexcité !$B$BTrois petites cages pour trois petits elfes ! Mais qu''allons-nous faire de nos trois calinouilleurs d''arbre ? Eh bien ! Faisons-leur goûter à… comment appellent-ils cela ?… La magie de la forêt !$B$BJ''aurais besoin de pas mal de Sève des Serres-Rocheuses. Prenez également des Moustaches crépusculaires à ces affreux félins. Cela nous amène aux Yeux de coursier : on ne peut jamais en avoir trop sous la main. Et surtout n''oublions pas : une précieuse Ecaille de dragon-faë !$B$BHâtez-vous de rejoindre le pic des Serres-Rocheuses $N, que je puisse concocter une recette magique de la forêt.'),
(1073,'frFR','Ha ha ha ! Vous avez besoin de nitromirglyceronium pour empêcher les gobelins de détruire une forêt ?$B$BSavoir si vous connaissez Gaxim ou non ne m''intéresse pas… Je vais vous donner le matos juste histoire de vous voir ou de les voir exploser en petits confettis.$B$BIl y a un problème quand même : je n''en ai plus.$B$BMais je vais vous dire, vous m''apportez les bonnes potions, et je vous en fais tout de suite.$B$BLe moins que vous puissiez faire c''est de me montrer que vous avez des talents d''alchimiste avant que je vous donne un échantillon de ma grande œuvre.'),
(1075,'frFR','OK, maintenant à propos de l’explosion à distance… Oh ! Je n''ai pas encore expliqué cette partie de mon plan ?$B$BBien, alors voici la version courte : avec un peu de magie, on peut déclencher l’explosion sans avoir besoin de vous dans les parages. Je suis en train de peaufiner un système qui vous permettra d’appuyer simplement sur un bouton pour que le NG-5 explose, à votre commandement.$B$BMais j''ai besoin du sort d''un ami à Stormwind. Il s''appelle Collin Mauren. Vous le trouverez dans le quartier des mages, là-bas. C''est un humain, alors ça sera difficile de le rater.'),
(1076,'frFR','Ah ! Je pense que ça vient. Un sort de contrôle… Je crois que c''est l''effet qu''il recherche.$B$BJe vais devoir créer un parchemin pour y inscrire le sort. Pour cela, j’ai besoin de débris de Diable de poussière.$B$BTandis que je rassemble le reste des ingrédients, pourquoi n''iriez-vous pas dans la marche de l''Ouest me trouver une de ces ignobles créatures ? Elles sont dangereuses, mais je suis sûr que vous êtes $Gprêt:prête; à tout pour participer à une expérimentation de Gaxim.$B$BJe serai là quand vous reviendrez.'),
(1083,'frFR','Je ne sais pas exactement comment la KapitalRisk s’est comportée vis-à-vis de la vallée, mais une chose est sûre : elle a été submergée par des créatures locales.$B$BSes gens ont mis le feu à la forêt et utilisé leurs engins de destruction pour ravager la vallée.$B$BMais dans leur ignorance ils ont libéré des esprits ardents et des élémentaires de flamme, de roche et de rage.$B$BLa Terre n''a aucune chance de voir le sourire d''Elune tant que ces créatures la fouleront librement.$B$BApportez-moi leurs Braises ardentes pour me montrer que vous avez réduit leur nombre.'),
(1094,'frFR','Cette enveloppe contient toutes les informations que j''ai pu rassembler avant qu''ils me flanquent à la porte : des documents internes de la KapitalRisk, quelques manuels, des trucs techniques… Et bien entendu, le plan du Super-Découpeur 6000.$B$BSputtervalve a élu résidence à Ratchet dans les Tarides. Vous ne devriez pas avoir trop de mal à le trouver, c''est un type un peu vert.'),
(1103,'frFR','Bienvenue, $Gmon pote:m''dame; ! Vous êtes ici pour purifier l''eau et prouver votre compréhension de cet élément à Islen ? J''viens juste de vaincre l''esprit corrompu de l''eau, ouais, moi-même, et j''m''apprêtais à placer les bracelets et les gouttes d''eau restantes dans le brasero.$B$BQu''est-ce que c''est que ce machin ? Ahhh. Tiev comprend très bien quand quelque chose tourne mal. Eh bien, Tiev peut beaucoup vous aider si vous voulez voir de nouveau l''esprit pur de l''eau.$B$BApportez-moi un sapta d''eau d''Islen comme preuve de votre bonne préparation, et j''vous attendrai pour faire ma part du travail.'),
(1110,'frFR','Eh ! Avec toutes les courses qui ont lieu ici, il n''est pas surprenant que quelques incidents surviennent le long du chemin.$B$BSi vous regardez tout autour des Salines, vous verrez des traces d’accidents. On trouve des pièces de chariots explosifs partout !$B$BEt ces pièces valent de l''argent. Elles intéressent les gnomes et les gobelins. Ils cherchent toujours des pièces à monter sur leurs chariots.$B$BAlors allez-y et trouvez-moi des pièces. Apportez-m''en un tas et je vous paierai bien.'),
(1116,'frFR','Vous obtenir des informations sur Nazz est une grande faveur que je vous fais, $N. Oui, une grande faveur ! Mais vous avez fait tout le chemin depuis les Salines pour en avoir… Voulez-vous voyager encore un peu ?$B$BPendant que je contacte mes sources, pourquoi ne chercheriez-vous pas quelque chose pour moi, hein ?$B$BHmm... Qu''est-ce que ce sera ?... Et que diriez-vous de Poussière de rêve ? On en trouve chez les dragonnets et les wyrmides du marais des Chagrins... Oui, j''aimerais de la Poussière de rêve pour ma blague à tabac !$B$BTrouvez-m''en, $N, et je vous fournirai l''information que vous recherchez.'),
(1131,'frFR','Parfois, nous chassons pour vivre. Parfois, nous chassons pour l''honneur. Et parfois, nous chassons pour mériter le savoir de la Terre-mère.$B$BMais la chasse qui vous attend n''est pas de celles-là. Il s''agit de détruire une créature qui refuse les bénédictions de la Terre-mère.$B$BLes Mille pointes, au sud des Tarides, sont le terrain de chasse de la hyène Broie-l''acier. C''est un tyran, qui attire à lui les autres hyènes, répand la terreur et massacre les bêtes plus paisibles.$B$BTrouvez Broie-l''acier, $N. Trouvez-le et tuez-le.'),
(1133,'frFR','Si vous débarquez tout juste du bateau qui vient de Menethil, la première chose à faire est d''aller à Astranaar. Je suis sûr $Gqu''un:qu''une; fidèle membre de l''Alliance comme vous peut faire beaucoup de bien là-bas. Allez offrir vos services à Shindrell Switfire.$B$BInutile de mentionner le nom de la personne qui vous envoie, car Shindrell ne me connaît pas...'),
(1134,'frFR','Nous ne sommes pas en guerre ouverte avec la Horde, mais la paix est fragile. Leurs agents agissent clandestinement contre nous.$B$BLeurs incursions nous ont été révélées par des sources secrètes à Theramore : il semble que des orcs collectent du venin des wyvernes Ailes-fières du lac Mirkfallon, dans le sud des Serres-Rocheuses. Un venin utilisé ensuite par leurs assassins lors de raids secrets contre l''Alliance !$B$BS''il s''agit de la vérité, nous devons les stopper, $N ! Nous devons anéantir leur source d''approvisionnement en venin.'),
(1137,'frFR','L''Indurium est étonnamment résistant à la chaleur. Je suis certain que ce métal serait idéal pour les pistons de Fizzle. Mais il lui faudra du minerai d''Indurium naturel, pas uniquement quelques paillettes.$B$BOn ne trouve ce minerai que très profondément enfoui dans les terres d''Uldaman, en bordure septentrionale des Terres ingrates. C''est là que se trouve le véritable Indurium.$B$BEnvoyez mes amitiés à Fizzle Brassbolts et répétez-lui ce que je viens de vous dire.$B$BQue votre voyage soit paisible, $N. Je ne serais pas étonné que nous soyons appelés à nous rencontrer de nouveau... Dès que Fizzle recevra mon message au sujet de l''Indurium, il vous enverra certainement à Uldaman pour en chercher !'),
(1139,'frFR','Nous avons ralenti le clan Ombreforge en le coupant du pic Blackrock, mais la quête d''Hammertoe n''est toujours pas accomplie. Sa mort ne doit pas rester vaine. Il voulait trouver la Tablette de Volonté : un morceau de pierre que les Titans avaient gravé de caractères magiques pour les aider à donner la vie à leurs créations, leur communiquer une volonté propre. C''est ce que dit la légende en tout cas.$B$BIl nous faut retrouver cette tablette avant ceux du clan Ombreforge !$B$BRepartez pour Uldaman, trouvez la Tablette et revenez ici immédiatement.'),
(1140,'frFR','L''écriture des orcs est à peine plus lisible que le gribouillage d''un enfant. J''ai essuyé bien des moqueries lorsque j''ai décidé d''apprendre leur langue, mais il est toujours utile de connaître l''ennemi.$B$BSi j''en crois les griffonnages d''Ilkrud, il semble qu''Athrikus possède toujours deux gemmes d''âme captives, au défilé de la Nuit et à Satyrnaar, des régions tenues par les satyres au nord-est d''Ashenvale.$B$BFaites attention, $N, les temples baignés de sang des satyres peuvent être effrayants, même pour des $Cs aguerris !'),
(1142,'frFR','Il ne me reste plus beaucoup de temps... Tellement... Tellement faible...$B$BLe brave Lonebrow a été envoyé pour avertir Falfindel...$B$BMais avant que je ne m-m-meure...$B$B... Ma femme, Treshala... Son pendentif de mariage avec moi... V-v-volé... par un de ces sauv-v-vages agresseurs...$B$BTrouvez-le, j-j-je vous en prie... Et rapportez-le à Treshala, à Darnassus...$B$B... Et racontez-lui ma mort... solitaire.'),
(1144,'frFR','Enfin de l''aide !$B$BVous n''avez pas idée du temps que j''ai passé prisonnier ici ! Je n''arrive plus à me rappeler quand j''ai vu le monde extérieur pour la dernière fois.$B$BVous voyez, je suis un entrepreneur. Prêt à tout en échange d''un sou, si vous voyez ce que je veux dire. J''avais entendu dire que Mizzyrix payait bien pour les Racines de Feuillerouge locales, de ce trou à rats ! Je pensais que ce serait de l''argent facile. Je me trompais et pas qu''un peu !$B$BEnfin... Merci de m''avoir sorti de là, je vous le revaudrai...'),
(1145,'frFR','Bien des voyageurs qui sont passés par la Croisée m''ont aidé à ramasser des oeufs dans le Champ des géants, et nombreux sont ceux qui ont rapporté des récits effrayants sur les créatures. J''en ai assez entendu pour considérer ces insectes comme plus dangereux que ne l''avaient cru mes maîtres de prime abord.$B$BJ''ai besoin d''un courrier pour aller à Orgrimmar trouver Belgrom Rockmaul. Cela ne sera pas simple et celui qui ira devra prendre cette tâche au sérieux.$B$BOn trouve généralement Belgrom devant la maison des guerriers.'),
(1146,'frFR','Ainsi, Korran est arrivé aux mêmes conclusions que nous sur ces insectes... On dirait qu''il s''agit d''une menace plus grande que nous ne le pensions au départ.$B$BIl y a quelques jours, un chasseur est rentré à moitié mort des Mille pointes. Il accompagnait un groupe chargé de déloger une équipe de fouille naine hors des Salines. Une nuée de ces insectes a jailli d''une grotte pendant l''attaque et les a presque anéantis.$B$BIls étaient sous les ordres de Moktar Krin et ils se sont réfugiés à la lisière des Salines. Apportez-lui cette note.'),
(1147,'frFR','Hum... On dirait que Belgrom pense que ces monstres sont une menace. Il veut que nous les repoussions jusque dans les profondeurs abjectes d''où ils sont sortis.$B$BOn dirait que tuer les nains de la Ligue des Explorateurs ne leur a pas suffi... Et maintenant il va falloir que j''envoie une section à moitié anéantie mener une nouvelle bataille. Nous ne pourrons pas réaliser cette mission par nous-mêmes. Pas tant que nous serons dans cet état. Le site de fouilles est là-bas vers le sud. Envie de manier l''épée et de nous donner un coup de main ?'),
(1149,'frFR','Vous me cherchiez, ou peut-être est-ce le destin qui vous mène à moi ? Aucune importance. Vous voilà et un nouveau voyage commence pour vous.$B$BIl y a différents aspects dans un être : l''esprit, le corps, l''âme. Certains peuvent être améliorés par les traditions d''une culture. Pour d''autres... Nous pouvons simplement espérer qu''elles existent en nous. Si vous êtes d''accord, je vais mettre à l''épreuve quelques-unes de vos qualités.$B$BSi vous réussissez, vous y gagnerez en force. Si vous échouez, vous comprendrez l''immensité du Néant.$B$BLa première épreuve est l''Epreuve de la Foi.'),
(1151,'frFR','Au temps des Dieux très anciens, les élémentaires peuplaient ce monde. Ils adoraient les Dieux très anciens, et le pouvoir de ces derniers maintenait les élémentaires attachés à ce monde. Lorsque les Dieux très anciens furent bannis, les élémentaires disparurent de notre monde et ils n’y reviennent que s''ils sont appelés par de puissants mages.$B$BIl y a pourtant des exceptions. Certains élémentaires étaient suffisamment puissants pour rester. L''un d''eux est Rok''Alim.$B$BPour mettre votre force à l''épreuve, trouvez Rok''Alim dans les Mille pointes et tuez-le.'),
(1152,'frFR','Vous avez presque terminé votre apprentissage avec moi, mais l''Epreuve de la Connaissance n''est pas de mon ressort. Il y a des leçons que l''on apprend et des lieux que l''on visite pour lesquels il faut un autre guide que moi-même.$B$BSi vous vous sentez apte, cherchez Braug Dimspirit... C''est un chaman d''une grande sagesse. Il vous mettra à l''épreuve, alors prêtez attention à ses paroles, $N.$B$BLorsque vous vous estimerez apte, trouvez le tunnel qui relie les Serres-Rocheuses et Ashenvale : Braug habite près de là. Mais soyez $Gprudent:prudente;, $N. Les elfes de la nuit pourraient vouloir vous empêcher d''accomplir votre épreuve.'),
(1153,'frFR','Vous m''avez apporté une aide précieuse par le passé, $C. Le Chef de guerre apprécie, au moins jusque-là, ce que j''ai accompli, et me demande de continuer avec une nouvelle détermination. Mon honneur me commande de vous envoyer au Chef de guerre avec une recommandation pour tout ce que vous avez fait, mais avant je voudrais vous demander votre aide une nouvelle fois.$B$BDes voyageurs, récemment revenus d''un endroit appelé les Mille pointes, ont tué un kobold porteur d''un échantillon d''un minerai inhabituel. Ils n''ont pas voulu le vendre. Je voudrais que vous me rapportiez un échantillon de ce minerai.'),
(1154,'frFR','Vous avez réussi les épreuves de Dorn et vous cherchez à présent le défi suivant. Ce que vous avez réussi, un enfant aurait pu le réussir. Il est facile de mettre son corps à l''épreuve. Pour l''esprit, c''est tout autre chose.$B$BJe vais m''expliquer simplement : trouvez le livre dont je vais vous parler, étudiez-le et répondez à mes questions sur son contenu.$B$BQuel livre ? « L''Héritage des aspects ». On peut le trouver au pied de Dor''danil au sud d''Ashenvale, protégé par les druides morts et leurs assassins.'),
(1166,'frFR','Inclinez-vous devant le seigneur Mok''Morokk !$B$BRexxar faire de moi le puissant chef du clan Cognepierre !$B$BMoi bon chef. Moi garder clan en sûreté.$B$BGrands dragons venir et faire le feu avec anciennes maisons. Mais moi ogre malin. Trouver nouveau foyer pour clan ici.$B$BQuitté ancienne maison trop vite. Oublié truc. Minuscule $R, aller trouver mes trucs. Aller sud et trouver mon grog délicieux, mon tabac à priser et mon coffre. Moi apprécier vous après ça. Chercher dans Antre des flammes et dans ruines Cognepierres... Mes trucs là-bas, moi sûr !'),
(1168,'frFR','Mok''Morokk fait seigneur par Rexxar. Lui faire attention plus pouvoir que ogres.$B$BDragons noirs tuer beaucoup ogres. Tuer femme de Tharg. Mok''Morokk dire s''enfuir. Venir ici.$B$BOgres devoir combattre. Ogres pas bons pour fuite. Mok''Morokk seulement intéresse Mok''Morokk.$B$BMoi appeler maison "ruines Cognepierres". Moi mieux au sud. Ici pas maison.$B$BAider ogres à combattre armée des dragons noirs. Moi vouloir vengeance. Moi vouloir rentrer maison.'),
(1172,'frFR','L''engeance d''Onyxia s''est répandue dans tout le Cloaque aux dragons. Il est impératif d''empêcher les dragonnets d''éclore.$B$BHâtez-vous de rejoindre la tourbière du Ver, au sud du marécage d''Âprefange. Il est sûr qu''elle a laissé ses œufs là-bas. Trouvez-les tous et détruisez-les.$B$BNous ne pourrons jamais rebâtir le village des Cognepierres si les environs servent de nid aux dragons !$B$BQuant à Mok''Morokk, j''ai d''autres plans pour lui…'),
(1173,'frFR','Toi oser défier le Seigneur Mok''Morokk ?$B$BMorbleu !$B$BMoi écraser $R comme un insecte !$B$BToi me dire quand vouloir bonne raclée.'),
(1175,'frFR','Après le gros accrochage entre le Tonnerre rouge gobelin et un basilic, Kronkrider m''a embauché pour surveiller la piste. Je ne sais pas ce que mangent les animaux d’ici pour grossir comme ça, mais il faut réduire leur nombre si nous voulons éviter qu''ils ne se baladent sur la piste pendant une course.$B$BJe vais vous dire : si vous voulez gagner un peu d''argent sortez d''ici et faites dégager les basilics de la zone.'),
(1176,'frFR','Quand on veut vraiment courir, chaque détail compte. Il faut tout prendre en compte depuis la plus petite chute de puissance jusqu''au plus léger défaut dans la tension des fils des bobines, en passant par un trop grand allégement du châssis…$B$BNous utilisons des os de vautour pour fabriquer une grande partie des structures mineures de nos voitures, qui sont des modèles d''équilibre entre légèreté et solidité. Cela pourrait être encore amélioré si nous avions plus de ces os ! Ils sont faciles à obtenir : les plateaux salés sont littéralement infestés de vautours.$B$BRapportez-moi des os de vautour et vous recevrez une récompense en échange.'),
(1178,'frFR','Notre équipe de course est la fierté de tous les gobelins ! Vous seriez surpris si je vous disais les noms de tous ceux qui y participent, d''une manière ou d''une autre !$B$BVous connaissez Gazlowe ? Il voyage dans le monde entier pour nous rapporter nos pièces détachées. Il a même participé une fois à la construction d''un des engins !$B$BIl y a quelques semaines, il a dit qu''il nous enverrait un nouveau prototype de régulateur de carburant, mais il n''est pas encore arrivé. D''habitude, il est plus rapide que ça... Peut-être accepteriez-vous d''aller à Ratchet pour le lui demander ? Je sais que j''exagère un peu en vous le demandant, mais les gnomes sont en train de nous prendre de vitesse !'),
(1179,'frFR','Vous avez déjà entendu parler des Salines ? C''est une étendue plate et salée au-delà de Kalimdor, juste au sud du canyon des Mille pointes. C''est un endroit fabuleux pour les courses ; forcément, c''est complètement plat !$B$BUne paire de gnomes, des frères, des amis à moi, sont là-bas pour essayer leur nouvelle voiture à réaction. D''après ce qu''on m''a dit, elle dépote ! Elle dépote tellement que les pilotes se crashent tous l''un après l''autre. Et finissent avec le crâne en miettes.$B$BAlors, évidemment, ils m''ont demandé de fabriquer des casques, mais j''ai des contraintes ici ! Je ne peux pas faire le voyage !$B$BVous pouvez ?'),
(1180,'frFR','Bon, revenons à la raison de votre voyage. Je sais que j''ai promis à Pozzik un nouveau régulateur de carburant, mais je ne l''ai pas encore reçu. Revilgaz, à Baie-du-Butin, dit qu''il l''a envoyé par bateau, mais il s''est peut-être perdu en route.$B$BSi c''est le cas, nous ne pouvons pas faire grand-chose. Mais nous pouvons tout de même vérifier qu''il est bien parti de Baie-du-Butin.$B$BVérifiez avec Maître Lozgil, sur les quais, là-bas, il devrait être en mesure de vérifier les registres de chargement.'),
(1181,'frFR','Désolé, je ne vais pas être d''un grand secours, $N ! Si vous voulez d’autres informations, je vous suggère d''aller trouver le baron lui-même. S''il y a quelqu''un qui est en mesure de vous renseigner sur les affaires de Revilgaz, c''est Revilgaz lui-même.$B$BVous le trouverez à l’étage de la Taverne, de l''autre côté du port.'),
(1182,'frFR','Vous voyez, les déchiqueteurs de la KapitalRisk du lac Nazfériti (au nord de Strangleronce) sont équipés d''un nouveau régulateur de carburant. Je pensais que Pozzik serait en mesure de l''adapter s''il avait quelques détails précis à son sujet. Malheureusement, j''ai sous-estimé l''intelligence de Cozzle, le Surveillant du chantier.$B$BPeut-être aurez-vous plus de chance dans la recherche des plans. Je sais qu''il les garde chez lui, mais ils sont certainement sous clé.'),
(1186,'frFR','Je vais être très occupé avec l''intégration de ce nouveau Régulateur de carburant sur la structure de nos voitures de course, mais si vous voulez apporter une aide supplémentaire à l''équipe, adressez-vous à Razzeric. C''est notre pilote. En fait, c''est notre dix-huitième pilote... Et il aime bien apporter ses petites modifications personnelles à sa voiture.$B$BJe vous préviens, il est un peu à côté de ses pompes alors tâchez de ne pas manifester de surprise quand vous lui parlerez !'),
(1188,'frFR','Mais qu''est-ce que c''est que ça ? Shreev a laissé la sûreté enclenchée. Ça limite l''énergie que je peux en tirer à chaque fois. Je lui avais dit de l''enlever ! Ça ne va pas !$B$BVous devez rapporter ça au Bidulium de Gadgetzan dans le désert de Tanaris, et faire enlever ce truc par Shreev.'),
(1189,'frFR','Voilà ! J''ai fait selon les recommandations de Razzeric. Dites-lui simplement d''être prudent quand il installera ce truc. À la moindre erreur, il n''avancera pas : il explosera sur place.$B$BCe serait dommage, non ? Qui sait ce que vaudra notre dix-neuvième pilote !'),
(1190,'frFR','Les frères Brassbolts ont utilisé un nouveau matériau de construction, c''est la seule explication plausible. Leurs voitures avancent plus rapidement qu''avant, mais leur aspect et toutes les données que nous avons recueillies sur leurs courses restent identiques.$B$BCe que nous savons, c''est que Rizzle Brassbolts est branché à temps plein sur les plans de sa nouvelle découverte.$B$BZamek peut créer une diversion pour vous, ainsi vous pourrez dérober ces plans.'),
(1196,'frFR','Apportez la Fiole remplie à Rau Cliffrunner au Poste de Librevent dans le sud-est des Mille pointes. Vous pouvez atteindre les Mille pointes en empruntant la Grande élévation à la limite sud des Tarides.$B$BJe ne serais pas surpris que vous puissiez nous aider davantage.'),
(1200,'frFR','Mes forces me quittent. J''ai besoin de votre aide !$B$BIl y a longtemps, ce site était un grand temple d''Elune. Mais la malchance l''a conduit à sa ruine, quand un Dieu très ancien, en contaminant la terre, a corrompu le Puits de lune sacré.$B$BAku''Mai, serviteur du Dieu très ancien, est sorti des eaux.$B$BLes sectateurs du Marteau du crépuscule se sont alliés aux nagas pour occuper ces terres. Les sectateurs, conduits par Kelris, sacrifient des innocents à Aku''Mai pour augmenter son pouvoir.$B$BTuez Kelris et apportez sa tête à Selgorm, à Darnassus, je vous en prie, $N.'),
(1201,'frFR','La trêve entre la Horde et l''Alliance n''est pas toujours respectée. Des escarmouches et des actions secrètes sont menées par chacun des deux camps, et il est de notre devoir de nous assurer que la Horde garde l’avantage !$B$BNous avons maintenant l''occasion de démasquer les infiltrateurs de l''Alliance.$B$BIls sont en position à l''est du village de Mur-de-Fougères. Ils nous espionnent et rapportent nos mouvements à Theramore, ce que nous ne pouvons permettre.$B$BTraquez-les et tuez-les. Envoyons un message clair à leurs chefs : nous ne supporterons pas leur présence sur notre sol !')
INSERT INTO `quest_template_locale` (`ID`,`locale`,`QuestDescription`) VALUES
(1202,'frFR','$N, deux de nos espions ont été envoyés pour dérober des documents sur un bateau dans les docks de Theramore. Ils ont trouvé les papiers, mais ont été découverts et ils ont dû jeter les documents à la mer.$B$BL''un des deux a réussi à s''échapper par la suite, mais il n’a pas pu récupérer le paquet. Il a rendu compte de son échec et maintenant je vous confie cette mission.$B$BLes documents sont dans un coffret, quelque part dans les eaux des docks de Theramore. Trouvez ces documents, $N, et apportez-les-moi.'),
(1203,'frFR','Je dois découper. Je ne peux pas vous dire quel type de découpage je vais faire, mais j''ai besoin d''une lame… Mais pas n''importe quelle lame !$B$BIl y en a qui l''appellent Epée d''acier lunaire. Moi je l''appelle Epée à double tranchant.$B$BAllez-vous m''aider ? Peut-être que vous la trouverez en ville, peut-être que vous pourrez la faire faire chez un forgeron.$B$BMais ne traînez pas. Ce que je dois découper n''attendra pas des années.'),
(1205,'frFR','Mortebourbe est un ancien crocilisque du marécage d''Âprefange. Son heure est arrivée.$B$BSes vieux os grincent quand il extrait son énorme corps du marais, et pourtant il évolue avec la force et la vitesse de ses jeunes années. Son corps fatigué torture le grand esprit qui l''habite, un esprit dont la flamme ne faiblit pas.$B$BPourtant, il vit maintenant marqué par une douleur cruelle et permanente. Vous devez mettre un terme à la vie de cette noble créature, $N. Vous devez conduire Mortebourbe à la paix.'),
(1206,'frFR','Le jus d’œil est bon à boire. Malheureusement la plupart des monstres n''ont que deux yeux.$B$BMais les araignées, elles, ont beaucoup d''yeux. Plus que beaucoup. Et le jus d''oeil de Sombrebrume est fameux. Doux et salé ! Des yeux d''araignée entiers... J''ai l''impression de les savourer.$B$BLes araignées Sombrebrume se trouvent à l''ouest d''ici, dans la caverne de Sombrebrume. A votre avis, c''est cette grotte qui a donné son nom aux araignées, ou l''inverse ?'),
(1218,'frFR','J''aime la cuisine. La bonne cuisine du marais. Les cuisses de grenouille verte grillées par exemple.$B$BEt pour cuisiner j''ai besoin d''épices. Des épices apaisantes. Après je ferai un ragoût qui mijotera et qui mijotera et je le mangerai. Mais je vous en donnerai un peu aussi.$B$BVous aimez le ragoût ?'),
(1242,'frFR','Portez cette note à Elling Trias. Ne lui dites rien d''autre. Contentez-vous d''être $Gpoli:polie; et attendez la réponse. Et ne vous inquiétez pas, il répondra.$B$BQue ce soit bien clair, $N : c''est une affaire sérieuse, alors gardez votre clapet fermé.$B$BVous trouverez Trias dans son magasin de fromages, « Aux Fromages de Trias », dans le Quartier commerçant. Bonne chance !'),
(1244,'frFR','Les activités des Défias ? Il y a toujours de l''activité, même s''ils ne se vantent pas que nous les considérions comme une menace.$B$BMais pendant que j''y pense, il y a eu récemment quelque chose de bizarre. Cela s''est passé il y a environ deux semaines : certains de leurs agents se sont réunis près de la ferme des Addle. D''après le rapport, j''en ai déduit que quelque chose d''important était en préparation.$B$BPourquoi ne commenceriez-vous pas par vérifier cela et me rapporter tout ce que vous trouverez ?$B$BLa ferme est au sud de la route qui vient de la marche de l''Ouest, juste à l''endroit où vous rentrez dans le bois de la Pénombre.'),
(1245,'frFR','Ouais ! Cela semble bien trop compliqué pour quelque chose qui serait juste destiné à vous induire en erreur. Je ne devrais même pas être en train de regarder tout ça. Portez-le à Trias. Il sera capable de comprendre tout cela. Et ne laissez PERSONNE se mettre en travers de votre chemin. Ceci est trop gros pour moi. C''est peut-être même trop gros pour lui, mais il verra.$B$BEt faites-moi une faveur, $N, ne dites à personne que je vous ai fourni de l''aide. Si mes supérieurs apprennent que je savais quelque chose sur cette affaire et que je ne les ai pas prévenus, ils me pendront.'),
(1247,'frFR','Alors ouais… Hum !… Il se pourrait que je sache quelque chose à propos de cette rencontre à la ferme des Addle. Ça s''est passé il y a quelques semaines je crois. Je n''y ai pas participé. J''avais terminé ma part du travail lorsque le plan A a échoué… Maudits aventuriers !$B$BLa taupe que nous avions pour le plan B venait de Menethil, un type appelé Slim. C''est tout ce que je sais sur leur plan de rechange.'),
(1276,'frFR','Je me souviens ! Mosarn est un forgeron respecté de Thunder Bluff. Je savais que j''avais entendu son nom quelque part !$B$BEn remerciement, le Cercle terrestre m''a offert un équipement complet forgé par Mosarn. Du très beau travail !$B$BPeut-être pourrait-il vous en dire plus sur ce bouclier qu''il a forgé.$B$BCe n''est pas une grosse piste, mais c’est la seule et c’est Reethe qui l’a donnée.'),
(1284,'frFR','Des lignes d''empreintes de sabots partent des ruines encore fumantes de l''auberge du Repos ombragé. Il y a au moins quelques traces visibles avec d''autres empreintes peu marquées dans la boue du marais.'),
(1285,'frFR','Reddon… Redpath… Ah voilà ! Lieutenant Paval Reethe.$B$BA rejoint la garde de Theramore en même temps que la plupart des recrues ayant fait la traversée avec dame Proudmoore. Engagé dans les soldats de marine de Kul Tiras à seize ans. Etats de service brillants, promu...$B$BPorté disparu.'),
(1287,'frFR','Reethe ? Ce lâche ?$B$BNous l''avons éjecté du camp, car il insistait pour aller piller le ravitaillement des ogres de Mur-de-Fougères. Nous ne sommes pas suffisamment nombreux pour faire face à ces brutes sans cervelle.$B$BIl a franchi trop de fois les limites, alors nous l''avons envoyé paître.$B$BBon je vous ai aidé... Alors aidez-moi à votre tour en oubliant que vous nous avez trouvés !'),
(1302,'frFR','Mon frère James a accompagné Dame Proudmoore lorsqu''elle a traversé les océans. Les dernières nouvelles disaient que le calme était revenu là-bas et que James avait monté une auberge quelque part sur le continent. Où qu''il soit, je suis sûr qu''il fait de bonnes affaires. C''est un excellent chef cuisinier !$B$BJe suis sans nouvelles de lui depuis un bon moment. Trop de travail avec son auberge, je suppose. Mais le greffier à Theramore a peut-être plus de renseignements.'),
(1320,'frFR','Ah ! J''ai failli manquer ceci… Cette lanière de cuir au dos aurait dû brûler, et elle a été faite pour un grand gabarit. Je dirais même un tauren.$B$BC''est tout ce que je peux dire. Dites au capitaine Vimaire que je suis désolé de n''avoir pas pu l’aider plus.'),
(1322,'frFR','Hmmm ! Il y a quelque chose d''écrit sur le bord du bouclier, c''est dur à lire avec toutes ces traces de suie.$B$BJ''ai besoin d''acide pour le faire apparaître. Du venin d''araignée Sombrecroc des marais serait parfait. Rapportez-moi quelques glandes et je vous nettoie cela.'),
(1323,'frFR','Oh ! Je crois que j''ai mis trop d''acide sur le bouclier. Frottons un peu pour voir…$B$BHmm, difficile à lire, mais il me semble qu''il s''agit d''un nom : Mosarn. Jamais entendu parler de lui. Peut-être Krog le sait. Krog connaît tellement de monde.'),
(1363,'frFR','En tant que conservateur de la bibliothèque de l''Académie des arts et sciences des arcanes, il est de ma responsabilité de m''assurer que tous les livres magiques et les parchemins sont bien présents. Qui sait quelle folie pourrait survenir si l''un de ces textes enchantés tombait entre de mauvaises mains ?$B$BCela me fait penser : mon assistant, Dellis, a fait une terrible erreur la semaine dernière. Il est parfaitement à l''aise dans la bibliothèque, mais parfaitement incompétent dès qu''il franchit les portes de Stormwind. Soyez un exemple de ce temps et allez aider le vieux Dellis, voulez-vous ?'),
(1365,'frFR','Les Kolkar ne sont pas les seuls centaures de Désolace. De nombreux clans parcourent ces plaines sèches, combattant et mourant. Il est heureux qu’ils se battent entre eux, car ils sont forts et brutaux. Si les centaures s''unissaient contre nous, ils seraient un adversaire redoutable.$B$BNous devons nous occuper d''eux avant qu''ils ne s''allient.$B$BVotre première mission est de désorganiser le clan Kolkar. Vous y parviendrez en tuant son chef, le khan Dez''hepah.$B$BLe village des Kolkar est au nord-est. Allez et que les dieux soient avec vous !'),
(1366,'frFR','Maintenant que vous avez terrifié les clans centaures, il est temps de les saigner. Lorsque vous voyagerez à travers Désolace, chassez-les. Je me moque de savoir à quel clan ils appartiennent. Vous devez juste collectionner les oreilles. Je veux un monceau d''oreilles !$B$BEn diminuant leur nombre vous porterez un coup à leur résolution et sonnerez le glas de leurs envies d''expansion.$B$BBonne chasse, $N.'),
(1387,'frFR','Le peuple des centaures est divisé en nombreux clans. Chaque clan a son chef et ses propres buts, mais ils ont tous une « qualité » en commun : la cruauté.$B$BSi nous voulons avoir une chance de construire la paix, alors les centaures doivent être éradiqués. C''est exactement la tâche que je vous confie.$B$BPendant que vous serez en Désolace, chassez des centaures et prenez leurs oreilles. Apportez-moi de nombreuses, très nombreuses oreilles.$B$BŒuvrez au service de l''Alliance, $N, et nous nous rapprocherons de la fin de la guerre.'),
(1388,'frFR','Tout se déroule selon le plan, $N. Je veux que vous remettiez ce sérum de vérité au traqueur noir Zraedus et il vous montrera comment l''administrer… proprement.$B$BHa ! Ha !'),
(1437,'frFR','Je me nomme Vahlarriel, $N. Je suis ici pour retrouver deux nobles disparus, issus d''une famille marchande de Darnassus : la famille Malem. Le père craint le pire, et je dois tout tenter pour retrouver ses enfants disparus. J''ai commencé mes recherches pour retrouver Tyranis ou Dalinda, mais j''ai bon espoir que je ne serai pas ici longtemps.$B$BAux dernières nouvelles, ils passaient par les Serres-Rocheuses il y a quelques semaines.$B$BSi vous trouvez leur chariot, s''il vous plaît, veuillez revenir ici pour m''en informer.'),
(1439,'frFR','Nous avons été emmenés ici après le massacre de nos gardes et de nos serviteurs par les orcs. Oh ! Ils leur ont fait des choses si horribles ! J''ai cru qu''ils allaient également nous tuer, sur place, mais ils avaient visiblement d''autres plans.$B$BTyranis a essayé de leur parler. Je pense qu''il voulait les impressionner par sa connaissance des arcanes... Je ne suis pas sûre de savoir pourquoi.$B$BJe vous en prie, je ne peux pas quitter les lieux tant que j''ignore ce qu''il est advenu de mon frère. Retrouvez-le, et venez me dire quel a été son sort.'),
(1442,'frFR','Salutations, $N. Que puis-je faire pour quelqu''un qui suit la voie sacrée ?$B$BAh oui ! Stilwell, le forgeron… d''il y a longtemps. Je me souviens bien de lui, mais cela fait quelque temps que je n''ai pas entendu parler de lui.$B$BIl ne m''a jamais paru impudent, aussi je ne peux que supposer que son désir d''une gemme de Kor est noble.$B$BSi vous souhaitez réellement l''une de ces gemmes, alors vous devez vous diriger vers le nord-ouest d''Ashenvale. Vous y trouverez les Profondeurs de Brassenoire à l''intérieur de ruines anciennes. Les nagas qui utilisent toujours ces gemmes se trouvent en bas. Ne partez pas $Gseul:seule;, $C.'),
(1447,'frFR','Ouais ! De toute évidence, vous n''êtes pas le $C le plus malin à venir à Stormwind, mais vous êtes sur le point d''être l''un des plus stupides à n''en jamais repartir.$B$BJe vous ai présenté mes amis ?'),
(1450,'frFR','Ainsi, vous êtes un des fameux coursiers au service des vieux schnocks de la Ligue des Explorateurs, hein ?$B$BBien, écoutez-moi, $C. Je ne sais pas avec qui votre vieux pote faisait des ronds dans le ciel d’Azeroth. Est-ce que j''ai la tête du Maître des gryphons Talonaxe ? Hein ?$B$BSi vous êtes tellement $Gintéressé:intéressée; par les aléas du trafic aérien pourquoi n''allez-vous pas lui parler directement ? Si je vous prends à glandouiller dans le coin un peu plus longtemps, je vais vraiment vous faire transpirer.$B$BÀ présent, bougez de là !'),
(1451,'frFR','Rhapsody commençait vraiment à apprécier le goulot. Mais ne vous méprenez pas : tous les nains ici à la volière savent apprécier une bonne bière quand le bon moment arrive.$B$BMais le vieux Shindigger s''est habitué à la boisson comme le jour s''est habitué à la nuit. Quel dommage ! Personne ne savait voler comme lui.$B$BLes premiers signes du problème sont apparus quand il est revenu en titubant de cette mission avec votre pote, Brohann. Tout s''est écroulé peu de temps après. Nous avons dû le laisser partir.$B$BLa dernière fois que j''ai entendu parler de lui, il avait monté un camp de brassage à l''est d''ici...'),
(1452,'frFR','Hic !$B$BAlors c''est ce vieux fou de Brohann qui vous envoie ? Bon sang ! On a eu une de ces aventures… Hic !$B$BSi vous voulez que je vous raconte ce qui s''est passé au marais, je vais avoir besoin de quelque chose de costaud à boire. C''était pas beau à voir, vous comprenez ? Hic !$B$BJe vais vous dire... Apportez-moi de quoi concocter un Kocktail Kalimdor et je vous en parlerai.$B$BJe vais avoir besoin de gésiers de Roc de Tanaris... et voyons... de foies de Groddoc et de Ferpoil de Feralas...$B$BUn bon Kocktail Kalimdor bien costaud... ça m''f''ra causer !'),
(1457,'frFR','Rapportez les biens de Karnitol à Roetten à Ironforge, et il vous paiera pour ce travail bien accompli.$B$BHa ! Ha ! Si vous ne faites pas attention, il sera tellement satisfait de vous qu''il vous demandera de nous rejoindre à plein temps.$B$BMais à nouveau, bon travail, $N.$B$BSoyez $Gprudent:prudente; sur le chemin du retour, et ne prenez pas tout votre temps ; Karnitol n''est pas le plus patient des hommes, mais il reste très généreux néanmoins.'),
(1459,'frFR','Ensuite, sur la liste de Leftwitch, on trouve… on trouve… Oh !$B$BRelativement facile, mais il faut décrypter ses directives. Il a besoin de venin de scorpashi et de peau de kodo. Mais il est précisé que le venin doit provenir de n''importe quel scorpashi, et que la peau doit être celle d''un vieux kodo, pas d''un kodo mourant ou d''un ancien kodo.$B$BLes mages, je vous dis pas, les trucs qu''ils veulent parfois... c''est tout simplement bizarre.'),
(1469,'frFR','Avant le vol, je me suis bu un plein tonneau de bière. Hic !$B$BEt ça a été un de ces vols ! Volé de-ci de-là avec Brohann qui me suivait. Mais pas vu de temple en tout cas. Hic !$B$BJe veux dire, j''ai pas vu de temple, jusqu''à ce que je sois trop parti et que je tombe de ma monture. J''ai plongé directement dans la flotte et j’ai été aspiré. Me suis trouvé entouré par un tas de trolls à la mine patibulaire. Vous pensez bien que j''ai nagé très vite pour partir ! J''ai quand même ramassé un souvenir troll. Tenez, apportez ça à Brohann et dites-lui que son temple est là-bas, en bas, de fait. Hic !'),
(1472,'frFR','Les Sayaads dévorent les âmes, dominent les esprits et séduisent sans distinction. Ce sont des créatures machiavéliques à l’esprit très singulier.$B$BLes légendes, qu’il s’agisse de contes de fées ou de récits cauchemardesques, les désignent toutes par le même nom : succubes pour les femmes, incubes pour les hommes.$B$BCes démons ne viennent dans notre monde qu’en y étant attirés. Face à des cœurs d’êtres bons, purs et aimants, les Sayaads sont incapables de résister. Vous pourrez alors les soumettre et les contrôler à loisir.$B$BParlez à mon assistant, Godrick Farsan, dans le temple. Il vous aidera à trouver un appât.'),
(1480,'frFR','La peau déchirée sent le pourri. Malgré son aspect sec et fragile, elle est remarquablement souple.$B$BEn la déroulant, vous voyez clairement une sorte de langage écrit en rouge sur l''un des côtés. Un symbole est apposé en évidence en bas de la peau ; vous supposez qu’il s’agit d’une signature.$B$BPeut-être Maurin pourrait-il vous en dire plus ?'),
(1491,'frFR','Ainsi les cornes de raptors n''ont pas si bien marché que cela ! Mais ce n''est pas grave, personne ne devient riche au premier essai ! Et de plus, je pense avoir trouvé encore mieux pour mes potions d''intelligence !$B$BIl existe une substance appelée essence de lamentation, qui est sûrement responsable de l’état de certaines plantes et bêtes des Tarides. Trouvez-en, et je l''essaierai dans mes boissons !$B$BJ''ai entendu dire que cette essence apparaît sur des créatures à l''état d''ectoplasme vivant dans les Cavernes des lamentations, à l''ouest. Chassez ces créatures et récupérez l''essence.'),
(1506,'frFR','Vous là ! $N, c''est ça ?$B$BJ''espère que votre programme n''est pas trop chargé, car Gan''rul veut vous voir tout de suite. Vous le trouverez avec les démonistes seniors à la Faille de l''ombre.$B$BD''après mes souvenirs de Gan''rul, le fait qu''il vous appelle est soit une très bonne chose, soit une très mauvaise.'),
(1507,'frFR','Il est temps pour vous d’en apprendre plus sur la magie d’invocation. Vous allez apprendre à invoquer un Sayaad, une créature dotée de pouvoirs mentaux incroyables. Ce démon peut apaiser les esprits faibles jusqu’à ce qu’ils tombent en son pouvoir. Mais ne craignez rien ! Je sais que vous êtes capable de relever le défi.$B$BLes Sayaads peuvent être invoqués à la condition de les appâter avec un objet représentant l’amour et la dévotion.$B$BUne suggestion ? Parlez à Cazul… Il semble qu’il n’y ait pas grand-chose que le vieux démoniste ignore.'),
(1511,'frFR','Je pensais bien que quelqu''un d''autre viendrait prendre le breuvage, alors je l''ai préparé à toutes fins utiles.$B$BTenez, prenez, $N. N’oubliez pas : ne lui donnez que la moitié ! Cela lui donnera suffisamment de force pour qu''il puisse bouger sans perdre tout son sang. Laissez passer une nuit, puis donnez-lui l''autre moitié.$B$BVoilà, vous feriez bien de l''apporter à Logmar au Camp Taurajo. D''après ce que m''a dit l''autre qui est passé avant, il devrait avoir une idée de l''endroit où Dogran se trouve.'),
(1598,'frFR','Vous ici ! $N, c''est ça ?$B$BÊtes-vous $Gsûr:sûre; de votre vocation de démoniste, car si vous ne pouvez pas maîtriser ce que vous invoquez, vous finirez $Gaspiré:aspirée; dans le Néant.$B$BJe dois vous enseigner les arts du démoniste, mais je dois d''abord m''assurer que vous êtes suffisamment $Gfort:forte;.$B$BUn novice qui étudiait à l''abbaye s''est enfui pour rejoindre la Confrérie défias. Pourquoi est-ce que cela m''intéresse ? Eh bien, il a volé certains livres importants.$B$BL''un d''entre eux se trouve être un livre que je voulais pour mon usage personnel : « la Puissance du Vide ». Volez-le pour moi, il est caché dans sa tente dans les vignes.'),
(1638,'frFR','Vous avez montré que vous êtes $Gun guerrier:une guerrière; capable, $N. Mais vous êtes encore jeune et avez beaucoup à apprendre.$B$BParlez à Harry Burlguard, il est généralement à la taverne du « Cochon siffleur », dans la vieille ville de Stormwind. Harry est un vétéran et un excellent Maître. Il pourrait vous montrer quelques passes d’armes qui vous aideraient à vivre plus vieux.'),
(1639,'frFR','Ouais, je peux vous enseigner ! Mais d''abord je veux voir ce que vous savez déjà.$B$BVous voyez ce poivrot là-bas au bout du bar ? Bartleby ? Je veux que vous lui preniez sa chope.$B$BHa ! Et si vous connaissez Bartleby, alors vous savez qu''il ne vous la donnera pas gentiment.'),
(1650,'frFR','Bien ! Votre engouement est le signe que vous êtes $Gprêt:prête; et montre votre enthousiasme à commencer le test. Ainsi soit-il !$B$BA l''extrémité de Longrivage, dans la marche de l''Ouest, une petite maison donne sur l''océan. C’est la demeure du couple Stilwell. Jordan, un très bon forgeron, est parti à Ironforge voir les nains. Mais il a laissé Daphne, sa femme, seule et sans protection.$B$BDes rapports disent que les Défias ont envahi cette zone : Daphne aura peut-être besoin de protection. Allez là-bas.'),
(1652,'frFR','S''il vous plaît, retournez voir Duthorian et dites-lui que je suis saine et sauve. Et c''est grâce à vous et à l''Eglise.$B$BJe vais envoyer un mot à Jordan à Ironforge pour lui dire de ne pas s''inquiéter. Oh qu''il me manque ! J''ai hâte qu''il revienne.'),
(1655,'frFR','Ach, vous m''avez fait peur $Ghomme:femme; ! Vous ne pouviez pas remarquer que j''étais perdu dans mes pensées ?$B$BQu''est-ce que c''est ? La cargaison de Jordan... pour Ironforge. Ahhh, ouais, j''vois de quoi vous parlez ! Les ogres Mo''grosh... z''ont volé la cargaison de minerai d''mon vieil ami. La caravane venant des Paluns a été attaquée. Le garde qui avait survécu est mort il y a quelques jours : le soigneur n''est pas arrivé à temps.$B$BSi vous voulez la cargaison, faut que vous alliez au nord-est à travers le Loch. Elle est quelque part par là.'),
(1658,'frFR','J’ai besoin de personnes courageuses pour se rendre aux clairières de Tirisfal, et voir comment se déroule la Fête de l’homme d’osier. Je ne vais pas vous mentir, aller là-bas sera dangereux : les gardes de faction lors de la fête seront exceptionnellement brutaux. Cependant, nous devons absolument connaître l’ampleur des festivités, et la gravité des problèmes que les Réprouvés nous causeront durant la Sanssaint.$B$BSi vous vous sentez d’attaque, dirigez-vous vers Tirisfal et espionnez les Réprouvés. Revenez me voir avec des informations, et je m’assurerai que vous recevrez une compensation convenable.'),
(1665,'frFR','Ok, voilà ma tasse. Attendez ! Laissez-moi finir avant... Ok, allez-y !'),
(1678,'frFR','Si vous voulez rejoindre les rangs des guerriers, vous avez intérêt à être robuste. Je peux vous apprendre de nouvelles passes d''armes, mais avant prouvez-moi que vous pouvez vous débrouiller contre des adversaires réels.$B$BVejrek est le plus coriace des trolls du coin ; c''est lui que vous devez affronter. Il a une hutte dans les collines au sud du repaire des Frostmane$B$BRapportez-moi sa tête et je saurai que vous avez du courage.'),
(1684,'frFR','Bonjour, $Gguerrier:guerrière; ! Vos compétences progressent, mais il y a plus à savoir sur votre métier que vous ne le pensez. Pour continuer à progresser il vous faudra bientôt trouver un Maître.$B$BLa guerrière Elanaria réside à Darnassus, à la Terrasse des guerriers. Elle peut vous former.'),
(1685,'frFR','N''est-ce pas toujours ainsi ? Je vous ai $Gcherché:cherchée; partout aujourd''hui et je n''ai pas pu vous trouver, et maintenant que je n''ai plus besoin de vous, vous venez me voir. !$B$BJ''ai perdu assez de temps à vous chercher, je ne vais donc pas vous faire attendre plus longtemps. Maître Gakin vous convoque pour une autre leçon. Il me semble que vous devriez y aller immédiatement.$B$BVous le trouverez au sous-sol de « l''Agneau assassiné ». Au fait, pas un mot : je préférerai que l’endroit reste tranquille.'),
(1686,'frFR','Vous avez appris beaucoup, $N. Maintenant nous allons vous fabriquer une arme. Une arme de $Gguerrier:guerrière;.$B$BPour cela, vous devez aller à Sombrivage.$B$BIl y a bien longtemps, un bateau s''est brisé sur les rochers près du phare d''Auberdine, éparpillant ses caisses de minerai d''Elunite au fond de l''océan.$B$BTout d''abord, vous devez vaincre la gardienne de l''Elunite : l''Ombre d''Elura. C''était le capitaine du bateau, elle s''est condamnée elle-même à errer au fond de l''océan pour protéger la cargaison à jamais. Combattez-la, récupérez son médaillon, et remonter toutes les caisses de minerai.'),
(1708,'frFR','Je veux essayer la nouvelle technique de Furen Longbeard sur une de mes pièces d''armure. Et parce que vous avez aidé Furen et qu''il m''a aidé, je vous offrirai l''armure que j’aurai fabriquée !$B$BPour faire la pièce, j''ai besoin d''un corail spécial, du corail torride. Il pousse à un seul endroit : le long des côtes au sud du port de Menethil dans les Paluns.$B$BApportez-moi suffisamment de corail torride et je pourrai fabriquer l''armure. Et dépêchez-vous, $N. Je suis impatient de commencer !'),
(1715,'frFR','Hum ! Dans le temps, tous les démonistes de Khaz Modan étaient entraînés par les maîtres de Gnomeregan, mais maintenant que nous avons été forcés de nous réfugier dans ce trou à rats qu''est Ironforge, et que Magni a décidé de nous surveiller, nous sommes forcés d''envoyer les novices étudier à Stormwind.$B$BHeureusement, Gakin n''est pas un empoté, vous pourrez donc continuer à recevoir un enseignement, mais cela m''exaspère !$B$BEnfin, vous trouverez Gakin au sous-sol de « l''Agneau assassiné » à Stormwind.'),
(1785,'frFR','J''peux déjà voir l''visage d''ma femme s''illuminer de fierté. Vous devriez bouger vot''postérieur tout de suite et aller la voir. J''pense qu''elle aura des choses à vous dire.$B$BLa Lumière soit avec vous, $C ! Je vous reverrai sur l''champ de bataille contre le Fléau et ces damnés Sombrefer quand le temps viendra.'),
(1802,'frFR','Il a été perdu, mais j''ai une petite idée d’où il se trouve.$B$BIl n’en existe qu’un seul exemplaire, en très mauvais état : déchiré à plusieurs endroits et en grande partie arraché de la reliure. La rumeur dit que cette partie serait entre les mains des centaures des Mille pointes.$B$BL’autre partie a été perdue sur la côte ouest de Southshore, alors qu’elle était envoyée par bateau au port de Menethil. Elle n''est jamais arrivée à destination.$B$BEn échange de ces informations, tout ce que je demande c''est que vous le trouviez, et que vous me l''apportiez afin de le voir.'),
(1805,'frFR','C''est l''un des textes les plus intéressants que j''ai parcouru au cours de ces dernières années. Ici, il n''y a pas grand-chose, à part des livres de géographie, que j''ai déjà tous lus... Strahad m''en enverra peut-être une copie, quand il le pourra...$B$BÀ propos, il vous fait dire que pour remplir votre mission, il vous faudra trois bâtonnets de canalisation.$B$BPour vous remercier de m''avoir laissé regarder ce texte, laissez-moi vous confier un secret : vous trouverez ces bâtonnets sur les orcs du clan Dragonmaw dans les Paluns.'),
(1819,'frFR','Lorsque le Fléau s''est abattu sur les Clairières de Tirisfal, nous avons capturé l''un de ses serviteurs pour l''étudier. C''était un esprit libre, qui se nommait Ulag le Fendeur. Pourtant, malgré sa libre conscience, le roi-liche avait gardé son emprise sur lui.$B$BNous espérions trouver un moyen de le délivrer de cette influence, mais nous avons échoué. Il est temps de le libérer, maintenant...$B$BLibérez-le et tuez-le.$B$BEn actionnant le déclencheur de la Pierre du Crâne devant le Mausolée qui se trouve au nord, vous briserez le sceau magique qui le lie.$B$BAprès... Il faudra frapper vite et fort, $N !'),
(1820,'frFR','Vous avez prouvé votre valeur à la Dame noire, à présent vous pourrez peut-être la prouver à l''un de ses sujets.$B$BColeman Farthing cherche un guerrier pour être son bras vengeur contre les ennemis des Réprouvés.$B$BVous le trouverez à « la Taverne des Pendus » dans l''est de Brill.'),
(1821,'frFR','J''ai servi la famille Agamand tout le long de ma vie et ils ont été la cause de ma mort ! S''ils sont maintenant les esclaves du roi-liche, ce n''est que justice !$B$BÀ présent, je dois m''approprier les derniers vestiges de leur honneur perdu. Dans leur crypte, je veux que vous voliez leur héritage familial : une épée, une hache, une dague et une masse, et que vous me les apportiez.$B$BLa Crypte de la famille Agamand se trouve à la lisière nord des Moulins d''Agamand, sous la protection d''un Fléau errant et des Agamands morts.'),
(1842,'frFR','Je peux vous faire une paire de gantelets de brutalité, et ils seront porteurs d''une grande magie, mais pour cela, vous devez d''abord m''apporter cette magie.$B$BLes satyres parcourent le nord-est d''Ashenvale à cause du pouvoir de la forêt. Ils se nourrissent de sa pureté, ils aspirent son innocence comme des sangsues et la corrompent. Ceux d''entre eux ont des sabots fendus et abîmés. Ils ont volé plus de magie à la forêt que les autres.$B$BCes sabots détiennent un grand pouvoir. J''en aurai besoin pour façonner vos gantelets.'),
(1859,'frFR','Parlez moins fort, $N ! Ouais, je sais qui vous êtes ! On m''a fait un topo.$B$BD''après ce qu''on entend dire de vous, vous vous débrouillez au combat et vous employez la ruse à l''occasion.$B$BJ''ai raison ?$B$BDe toute façon, vous devriez aller voir Therzok à Orgrimmar. Il a quelque chose à vous proposer.'),
(1885,'frFR','$N ? Pas vraiment ce à quoi je m''attendais, compte tenu de l''intérêt que Carkad lui-même manifeste pour vous ! Comme quoi les apparences sont parfois trompeuses, non ?$B$BPeu importe, vous devez aller le voir dès que possible. Autant que vous ne sachiez pas ce qui est arrivé au dernier qui a ignoré ses sommations.'),
(1918,'frFR','Sur l''élémentaire vaincu, vous trouvez un globe d''eau, formidablement lumineux, dont le contenu semble proprement répugnant. Apparemment, l''essence qui a souillé les eaux du lac Mystral est également présente dans les eaux du globe.$B$BCe genre de découverte n''est pas en mesure d''intéresser le commun des mortels, et sans doute la personne qui vous a demandé de vous rendre au lac, Mastok Wrilehiss, au poste de Bois-brisé, pourrait bien avoir une idée plus précise à ce sujet.'),
(1920,'frFR','On nous a rapporté un incident qui est survenu à la taverne du « Solitaire bleu » dans le quartier des mages. Des créatures étranges et invisibles rôdent dans la taverne et je crains qu''une faille de mana ne se soit formée là-bas.$B$BIl faut que vous y alliez pour neutraliser ces créatures. Sur place, utilisez l''incantation de manifestation pour les rendre visibles, puis capturez-les avec un coffre de retenue. Quand vous en aurez suffisamment, revenez me voir avec les coffres remplis, les coffres vides et l''incantation.'),
(1921,'frFR','Vous avez bien servi les mages, et il est temps de vous attribuer votre robe de sorcier. Wynne Larson peut la réaliser pour vous, mais il faudra lui fournir les matériaux nécessaires.$B$BLa robe sera faite de lin, ce qui ne sera pas difficile à trouver, mais vous devrez aussi fournir des gemmes chargées de la faille. On ne peut les trouver que dans la mine du Ru d''argent à Loch Modan, dans les caisses laissés par la Ligue des mineurs nains.$B$BRassemblez le lin et les gemmes et apportez-les à Wynne Larson, chez les couturiers Larson, dans le quartier des mages.'),
(1945,'frFR','En remerciement de vos services, j''ai pris des dispositions pour vous faire confectionner de nouvelles robes, à condition que vous alliez chercher les matériaux nécessaires...$B$BPour ces robes, vous devez vous rendre à Ashenvale et prélever des boucles de cheveux sur les sœurs rieuses, les dryades qui se réunissent près de la retraite de Raynewood.$B$BUne fois en possession de leurs cheveux, apportez-les à Kil''hala, un tailleur troll qui se trouve à la Croisée, dans les Tarides. Il vous attend et coudra vos robes.'),
(1949,'frFR','Pour faire votre baguette magique, je dois lire des passages d''un certain livre. Ce livre, intitulé « les Rituels du pouvoir », a été écrit par le magus Tirth.$B$BJe n''ai pas d’exemplaire de ce livre et aucune des grandes bibliothèques de ce monde n''en possède un. Vous devez donc aller voir Tirth et l’obtenir de lui.$B$BBonne chance ! Tirth était un grand mage et un grand savant, mais maintenant il passe tout son temps aux courses des gnomes et des gobelins des Salines, à boire et à parier.'),
(1953,'frFR','Il est temps pour vous de parler à l''ermite Tabetha, $N. Elle vous donnera des indications sur la fabrication de l''un des objets les plus importants pour les mages.$B$BLa cabane de Tabetha est loin dans le marécage d''Âprefange à l''ouest de Theramore.'),
(1954,'frFR','D''abord, il faut acquérir un orbe puissant. Les démonistes de la Lame ardente ont des orbes splendides, de qualité... Dommage qu''ils soient liés à des démons ! Mais ça peut s''arranger.$B$BRendez-vous en Désolace et prenez un orbe infernal à un Invocateur démoniste. Ils se retrouvent au convent de Mannoroc.$B$BLorsque vous aurez cet orbe, rapportez-le.'),
(1956,'frFR','Le démon a été enlevé, et maintenant il nous faut une source d''énergie. Malheureusement, les plus puissantes sont les plus anciennes et les plus difficiles à acquérir ! Le destin n''est pas tendre avec nous, hein ?$B$BIl va falloir que vous alliez à Uldaman pour y vaincre la sentinelle d''obsidienne. Il est grand, il est fort, et sa source d''énergie est pleine... d''énergie !$B$BJe vous souhaite beaucoup de chance, $N. Et si vous n''avez pas cette chance, et bien... C''était un plaisir d''avoir pu faire votre connaissance.'),
(1978,'frFR','Le Syndicat ? Je ne m''en serais jamais douté. Il semble que ces messieurs d''Alterac soient tombés bien bas depuis leur trahison.$B$BLe Seigneur Varimathras aura plaisir à apprendre ça et comme vous avez contribué à cette découverte, il convient que ce soit vous qui la lui annonciez.$B$BAh comment pouvais-je oublier !$B$BBienvenue chez les Traqueurs noirs…'),
(2038,'frFR','Comme si le crash dans le Loch n''avait pas suffi, des troggs de l''île voisine m''ont attaqué et ont volé mes outils et mes capsuleurs soufflants Blastenheimer spéciaux ! Sans gyrocoptère et sans explosifs, le mouvement n''a aucune chance !$B$BRapportez-moi mes outils et mes capsuleurs soufflants, $N. Pour Gnomeregan !'),
(2039,'frFR','Nous avons perdu contact avec Bingles ! On l''a envoyé en mission de reconnaissance sur Gnomeregan et ça fait une semaine qu''il n''a pas envoyé de rapport. Je sais juste qu''il est parti et s''est envolé.$B$BLa dernière fois qu''on a vu son gyrocoptère, c''était au-dessus du Loch. Peut-être que vous pourriez enquêter, $N.'),
(2040,'frFR','Gnomeregan est tombé sous les contrôle de ces troggs maudits ! La situation est grave, mais vous pouvez peut-être nous aider, $N.$B$BAu plus profond des mortemines, il y a un Déchiqueteur gobelin en état de fonctionnement. Trouvez-le et rapportez sa source d''énergie intacte. Elle permettra à nos Excavateurs gyrodrilmatiques de percer les murailles pour l''assaut !'),
(2098,'frFR','La vie d''un pirate n''est pas facile, bouseux de terrien. C''est pas pillage et tafia à volonté ! Hélas ! Mon navire est à la baille, tout près du bord, à cause de ces saletés de battrodons.$B$BJ''ai b''soin que mon Premier Officier rapplique en ordre de marche !$B$BQuand j''me suis ramassé sur le rivage, la clé de contact de mon Premier Officier est tombée sur les rochers et a été chapardée par des bestioles du cru. Du coin de l''oeil, j''ai vu des clampants enragés, des trotteurs des forêts géants et des murlocs fouiller l''épave...'),
(2139,'frFR','La survie de notre peuple et de nos terres a exigé des sacrifices, $N.$B$BHélas, vous avez dû verser le sang des serviteurs de la nature et bien des animaux sont tombés sous vos coups. Le peuple d''Auberdine vous doit beaucoup, et la souffrance de la forêt est apaisée, au moins pour le moment.$B$BJ''ai une dernière tâche à vous confier mais sachez qu''il vous faudra tuer de nouveau. J''espère de tout coeur que ce sera la dernière fois, $N.$B$BÀ côté de Bashal''Aran, dans une caverne au nord-est d''ici, habite la Mère de la tanière. Faites-la disparaître.'),
(2158,'frFR','Tous les aventuriers doivent prendre du repos s''ils veulent éviter l''épuisement... Et pour cela, le meilleur endroit, c''est bien l''Auberge de la Fierté du lion !$B$BMon meilleur ami, l''aubergiste Farley, tient cette auberge. Si vous venez de ma part, il vous fera sûrement des réductions sur le prix de la nourriture et de la boisson !$B$BSuivez cette route vers le sud, vous ne pouvez pas la rater !'),
(2161,'frFR','Excusez-moi... Pouvez-vous m''aider ?$B$BVous voyez ce chargement ? J''ai suivi la route, j''ai bravé les scorpides, les araignées, que sais-je encore, tout ça pour apporter ces vivres à la vallée des Epreuves. Je pensais qu''ils en auraient besoin... Mais non, ils n''en ont pas voulu ! Maintenant, il ne me reste plus qu''à rapporter tout ça à Tranchecolline et ça me terrorise, à cause des bêtes...$B$BVous pourriez vous en charger pour moi ? Je ne suis qu''un malheureux péon mais vous... Vous n''avez peur de rien, vous avez l''habitude d''être héroïque !$B$BRapportez ce paquet à l''aubergiste Grosk à l''auberge de Tranchecolline. Merci !'),
(2178,'frFR','Sentez-vous cet arôme délicieux ? C''est ma recette secrète, $N : le brouet de trotteur frais. Délicieux !$B$BLa recette vous intéresse peut-être ?$B$BAvant de vous l''apprendre, je veux voir comment vous vous débrouillez avec les bêtes.$B$BJe ne m''attends pas à ce que vous sortiez en dompter un, mais si vous pouvez en abattre quelques-uns et rapporter leur succulente viande, ça suffira à me convaincre que je peux vous montrer comment cuisiner mon brouet de trotteur.'),
(2198,'frFR','Vous avez trouvé un Collier terni mais sur lequel on devine encore des entrelacs compliqués et des signes magiques. Il a été brisé et on voit qu''il manque trois Gemmes. Sous le collier, on peut reconnaître le sceau de la ville d''Ironforge et, sous le sceau, trois toutes petites lettres : "TdK".$B$BS''il y a quelque chose à tirer de ce Collier, il va falloir revenir à ses origines. Le sceau et les initiales sont déjà un début...'),
(2199,'frFR','Je suis un joaillier de renom, ici, à Ironforge. Enfin, je l''étais... Je suis la victime d''un concurrent déloyal ! Dans ce métier, c''est la réputation qui fait tout... Et résultat, je me retrouve sans un sous, uniquement propriétaire d''un nom traîné dans la boue !$B$BJe veux que vous me rapportiez cinq Barres d''argent pour terminer une commande qui m''a été faite - la première commande depuis des lustres !$B$BVous me rapportez ces barres d''argent et je répondrai à vos questions au sujet du Collier.'),
(2205,'frFR','L''insigne ? Rien... Rien qui soit pour vous... Si j''en juge par votre apparence, j''ai peur que Mathias vous prenne pour le livreur de fromage, mon enfant, au lieu du malandrin attendu. Enfin, on m''a donné un travail et j''ai promis de livrer ce travail.$B$BTiens, à propos, vous apporterez ce paquet à Mathias, et peut-être qu''il vous donnera un ou deux petits boulots à accomplir.$B$BAllez, du vent.'),
(2240,'frFR','Bon... Pour la tâche en cours...$B$BIl va falloir explorer une chambre secrète, la Chambre de Khaz''mul. Le problème, c''est qu''elle se trouve derrière une lourde porte fermée ! Il est heureux que je sache comment l''ouvrir !$B$BJ''ai tout écrit dans ce journal, là, sur la table. Pour l''instant nous sommes coincés ici. Trouvez la Chambre de Khaz''mul pour nous, $N !$B$BLisez mon journal, explorez la Chambre, puis rendez compte au Prospecteur Stormpike de la Ligue des Explorateurs à Ironforge.'),
(2258,'frFR','$N, je pourrais avoir l''usage de vos capacités. Je suis un alchimiste de quelque renom et j''ai besoin de votre aide pour acquérir des composants que l''on ne peut trouver que dans les Terres ingrates.$B$BJ''ai besoin des objets suivants pour réapprovisionner mon stock : cinq Gésiers de busards, dix Crocs de coyote des rochers et cinq Fragments d''élémentaire de roche. A prendre sur les bêtes elles-mêmes, bien entendu... Si vous n''êtes pas du genre batailleur, trouvez quelqu''un qui le soit !$B$BTrouvez-moi ces objets, et vous aurez quelques pièces en échange, ça vous va ?'),
(2260,'frFR','Le Service de Renseignement de Stormwind (SI:7) a entendu parler de vos exploits, $N, et il veut vous recruter.$B$BLe voyage est coûteux et périlleux, mais on ne rejette pas l''opportunité de s''entraîner pour le SI:7 !$B$BUn nouveau monde s''ouvre à vous, $N. Rendez-vous dans la vieille ville de Stormwind et adressez-vous à Renzik "le Kriss" " au QG du SI:7.'),
(2278,'frFR','Les pièces centrales de cette chambre au trésor sont quatre larges disques de platine ornés de sceaux d''origine inconnue. Lorsque vous les touchez, vous sentez un frémissement. Le visage d''un grand Gardien des pierres apparaît alors.$B$B"Salut à vous. Je suis le Gardien du Savoir. La synthèse des Créateurs de la Terre a été gravée et conservée dans les Disques de Norgannon."$B$BVous avez découvert une manne de savoir inconnu du monde entier !'),
(2279,'frFR','Votre main vibre de nouveau au contact des Disques de Norgannon. Cette fois, pourtant, c''est un étrange grincement qui se fait entendre.$B$BSoudain, votre sac paraît plus lourd. Vous y trouvez une version miniature des Disques !$B$BVoilà qui sera utile à tous ceux qui s''intéressent à l''histoire ancienne d''Azeroth. La Ligue des Explorateurs d''Ironforge est connue dans toute l''Alliance pour ses recherches sur le sujet ; ils devraient pouvoir faire bon usage de tout ceci.'),
(2280,'frFR','Votre main vibre de nouveau au contact des Disques de Norgannon. Cette fois, pourtant, c''est un étrange grincement qui émane des disques.$B$BSoudain, votre sac paraît plus lourd. Vous y trouvez une version miniature des Disques !$B$BVoilà qui sera utile à tous ceux qui s''intéressent à l''histoire ancienne d''Azeroth. Les Sages de Thunderbluff sont connus dans toute la Horde pour leurs recherches sur le sujet ; ils devraient pouvoir faire bon usage de tout ceci.'),
(2284,'frFR','Aussi vrai que Malton est un crétin, ces gemmes sont encore quêk part dans Uldaman. Va falloir y r''tourner.$B$BComme j''l''ai d''jà dit, si les informations que nous avons sont justes, il y a un rubis, un saphir et une topaze.$B$BOù elles sont, comment je l''saurais ? Si vous avez du bol et qu''vous trouvez l''corps du paladin, et qu''il a pas encore été nettoyé, elles s''ront p''têt encore là.'),
(2338,'frFR','Ceux de la Récupération Droffers et fils sont trop bêtes pour restaurer la magie du Collier. Moi, je peux le faire. Je veux l''étudier pour apprendre à le confectionner moi-même. Pour ce faire, j''aurai besoin de votre collier. Laissez-le-moi et en échange je vous traduirai le journal. Le temps que vous trouviez les Gemmes, j''aurai le loisir d''apprendre ce qui m''intéresse.$B$BUn marché simple et sans duperie... Alors, qu''en pensez-vous ?'),
(2340,'frFR','Un collier et des gemmes ordinaires marcheront aussi bien, du moment qu''ils sont faits du même matériau. Cette Source d''énergie, en revanche, c''est elle qui va donner sa magie au Collier... Enfin j''espère !$B$BJe fournirai volontiers les gemmes nécessaires pour la confection de votre version du Collier, si toutefois cette Source d''énergie fonctionne.$B$BRetournez à Orgrimmar, et terminez votre marché avec Droffers et Fils. Ne leur dites rien de notre rencontre et lorsque vous reviendrez, je pourrais bien avoir un cadeau pour vous.'),
(2342,'frFR','Balayer les enclos à chauve-souris avec ce balai, ce n''est pas digne d''un Garrett ! J''ai fait quelques économies avec ce boulot maudit, et je suis prêt à les dépenser pour améliorer mes conditions de travail.$B$BL''arme familiale des Garrett est restée enfermée dans notre Coffre, dans le Hall commun sud d''Uldaman, où nous avons trimé comme mineurs. Sans elle, je suis coincé ici pour toujours, à balayer derrière ces immondes chauve-souris !$B$BRapportez-moi ce trésor de famille ! Aidez-moi à retrouver ma dignité !'),
(2360,'frFR','Pas trop tôt, $N. Les éléments de reconnaissance du SI:7 nous apprennent les Défias sont inhabituellement actifs dans la marche de l''Ouest.$B$BOn dirait qu''ils ont pris une ancienne Tour de guet de l''Alliance abandonnée au sud-est de la Colline des sentinelles, et qu''ils s''en servent comme base d''opérations pour leurs trafics à partir de la route d''approvisionnement des Carmines.$B$BAllez dans la marche et contactez l''Agent Kearnen. Elle est cachée à proximité de la tour.$B$B... Oh, $N, si vous veniez à être $Gcapturé:capturée;, le SI:7 nierait avoir eu connaissance, etc.'),
(2378,'frFR','Vous avez bien servi les Traqueurs de ténèbres, $N, mais il est temps d''étendre votre expérience. Vous avez montré vos capacités en matière de ruse et de traîtrise, mais votre entraînement n''est pas terminé.$B$BLes Traqueurs de ténèbres ont des alliés au sein de la Main brisée. Cherchez ceux qui viennent à notre aide : trouvez Shenthul à Orgrimmar.'),
(2379,'frFR','Votre seule détermination ne suffira pas pour affronter les obstacles qui nous attendent.$B$BAdressez-vous à Zando''zan pour commencer votre entraînement comme opérationnel de la Main brisée.$B$BLorsque vous maîtriserez le noble art du vol et de la tricherie vous pourrez faire un pas de plus vers votre destinée.'),
(2380,'frFR','Spécialiste de la forfaiture et de la tricherie, vous ne l''êtes pas, mais ça peut changer. Il semble que vous ayez impressionné les chefs avec vos maigres talents, puisque le grand Shenthul lui-même vous réclame.$B$BPrenez la route vers le nord jusqu''à Orgrimmar et adressez-vous à Shenthul à la Faille de l''ombre.'),
(2541,'frFR','Les chamans Pins-tordus qui habitent cet endroit ont découvert comment séparer l''esprit d''un druide dormant de son corps physique. Les furbolgs ont ranimé ma forme physique et l''utilisent pour attaquer ceux qui essaient d''explorer le Refuge des saisons de Ban''ethil. Je suis impuissant, pris au piège dans le Rêve d''émeraude.$B$BVous devez m''aider. Les chamans Pins-tordus portent un charme étrange qu''ils utilisent pour exécuter ce rituel et je voudrais l''examiner. Je vous en prie, $N, il m’en faut un.'),
(2606,'frFR','Beurk ! Cette substance a un goût épouvantable ! Trop pour mon idée...$B$BAttendez, qu''est-ce que c''est que ça ? Oh, je sais ! Vous pensez que je dois continuer de croire en cette substance. Bon alors...$B$BJ''ai une idée brillante ! Apportez cette rosée à mon amie Sprinkle, c''est un excellent chef. Dites-lui où nous en sommes et ce que nous voulons faire.$B$BJe veux dire, si c''est aussi mauvais, il y a sûrement quelque chose à en faire... C''est juste que moi, je ne le sens pas...'),
(2609,'frFR','Le diagnostic est unanime, $N. Vous êtes $Gatteint:atteinte; de “itis”.$B$BHeureusement, j''ai un remède.$B$BVoilà ce dont j''ai besoin : une brassée de fleurs sauvages simples, une fiole plombée, un tube en bronze et une bobine de fil de soie chartreuse. La vieille Emma en a laissé pour moi au "Fil le plus fin”. Le magasin se trouve le long des canaux.$B$BDépêchez-vous $N, et ne touchez personne jusqu''à votre guérison. Oh ! Montgomery dit que vous devriez prendre une douche – c''est lui qui le dit, pas moi.'),
(2756,'frFR','Aux temps légendaires, Aturk aurait écrasé les crânes de ses ennemis et réduit leurs os en poudre comme combustible de lampe. Ces jours sont loin, $N. Le chef de guerre appelle à la paix parmi les clans. Les vieux ennemis ne sont plus observés que par des yeux fatigués !$B$BC''est incroyable, je sais, mais telle est la volonté de Thrall.$B$BAssez ! Vous êtes ici pour apprendre et vous allez apprendre ! Apportez-moi quatre cuirasses en acier et quatre heaumes en plaques d''acier et vous aurez un avant-goût de la guerre !'),
(2927,'frFR','Vous ne pensiez quand même pas que j’aie toujours été chauve ? Non $Gm’sieur:ma''am; ! C''est la fuite radioactive à Gnomeregan qui a causé cette tragique perte de cheveux. Avant cela, j''avais la seule coiffure afrognome de tout Azeroth.$B$B<Gnoarn brandit le poing vers le ciel>$B$BMaudits soient ces troggs crasseux, qu''ils soient tous maudits !$B$BPeut-être qu''il n''est pas trop tard, $N. Nous pouvons peut-être encore la sauver, je parle de la ville ! Allez voir Ozzie Togglevolt à Kharanos. Lui et Razzle, son partenaire, travaillent à résoudre ce problème.'),
(3064,'frFR','I need pirate hats for my shop. Get me lots!'),
(3090,'frFR','Ah, pendant que vous n’étiez pas là un parchemin est arrivé pour vous, $N.$B$BJ''évite normalement de traiter avec des démonistes, si c''est possible, mais je pense que vous devriez le lire, quand vous en aurez le temps. Si je ne me trompe pas, il provient du maître qui vous a été récemment assigné, Nartok. Il souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu.'),
(3091,'frFR','Il y a quelques instants, une messagère était à votre recherche, $N. Je crois qu''elle était envoyée par le Maître des guerriers, Harutt. Si ce message est bien de Harutt, je ne tarderais pas à le lire, à votre place.'),
(3094,'frFR','Il y a quelques instants, une messagère était à votre recherche, $N. Je crois qu''elle était envoyée par le Maître des druides, Gart. Si ce message est bien de Gart, je ne tarderais pas à le lire, à votre place.'),
(3385,'frFR','Ils se sont donnés le nom de Sous-marché : des commerçants sans vergogne qui vendront, intimideront, commerceront, ou feront à peu près n''importe quoi contre la bonne somme d''argent.$B$BMais les choses empirent, $N. Ils ont établi une base d''opérations ici dans la gorge des Vents brûlants. Kovic dirige les opérations et entretient des liens étroits avec les nains Sombrefer dans la région.$B$BNous devons frapper fort et envoyer un message clair à leurs dirigeants. Tuez Kovic, ainsi que son agent Clonk. Apportez-moi sa Sacoche du marchand lorsque vous en aurez terminé.$B$BPartez pour le Chaudron à présent !'),
(3504,'frFR','Une traîtresse, une voleuse ! C''est ce qu''elle sera toujours !$B$BJ''ai fait une terrible erreur, $N. J''ai fait confiance à une elfe de sang !$B$BElle prétendait qu''Azshara renfermait de grandes richesses… Je n''avais qu''à envoyer quelques guerriers avec elle pour la protéger et j''en serais récompensé. Elle les a tous tués !$B$BJe réclame vengeance, $N, mais je ne peux pas envoyer quelqu''un d''autre. Allez voir Ag''tor à Valormok, au nord du campement des Haldarr. Il vous en dira plus.'),
(3702,'frFR','Est-ce que vous aimeriez entendre une petite histoire sur les nains Sombrefer ?'),
(3824,'frFR','Ils faiblissent, je vous assure ! Nous devons à présent porter un coup décisif.$B$BLe seigneur-brute Gor''tesh doit être tué. Plus important encore, vous devez me rapporter sa tête afin que je puisse préparer la troisième partie de notre attaque sur les ogres Brûlentrailles.$B$BAttention, soldat : Gor''tesh n''est pas établi au rocher des Cognepeurs lui-même, mais dans un bâtiment des orcs Blackrock, à l''ouest du rocher des Cognepeurs.$B$BVos ordres sont simples : trouvez Gor''tesh et décapitez-le. Revenez me voir une fois votre travail accompli.$B$BSILENCE, WINKY !'),
(4021,'frFR','La Horde loue vos victoires contre les Kolkar, mais ils sont à présent fous furieux. On me rapporte qu''un contingent, épris de vengeance, a quitté leur patrie en Désolace pour arriver dans les Tarides. Aux dernières nouvelles, ils prennent d''assaut les fortins depuis l''ouest !$B$BCombattez les envahisseurs, et mettez un terme à la menace qu''ils représentent pour les Tarides. Tuez-en jusqu''à ce que leur chef de guerre, Krom''zar, apparaisse. Battez-le et apportez-moi un morceau de sa bannière comme preuve de votre exploit.$B$BNous comptons sur vous, $N.'),
(4223,'frFR','< Le Magistrat Solomon soupire. >$B$BVous devez retourner dans les Steppes ardentes, $N. En tant qu’Adjoint de Stormwind, votre présence est exigée pour faire votre rapport au maréchal Maxwell. Bonne chance !'),
(4282,'frFR','<Le maréchal Windsor agite la note avec enthousiasme.>$B$BEst-ce que vous réalisez ce que cela veut dire, $N ?$B$BPeut-être que tout n''est pas perdu ! D''après ce que je peux comprendre, les renseignements sont en ce moment même détenus par deux nains Sombrefer : le général Forgehargne et le Seigneur des golem Argelmach. Je ne crois pas qu''ils nous les donneront même si on leur demande poliment.$B$BJ''espère que vous êtes $Gprêt:prête; à combattre.$B$BAllez-y, trouvez ces deux scélérats et rapportez-moi ces renseignements.'),
(4402,'frFR','La situation est, en effet, assez tendue dans la Vallée des épreuves.$B$B<Galgar s’éponge le front.>$B$BSi seulement j''avais quelques pommes de cactus, je pourrais faire ma fameuse surprise aux pommes de cactus ! Rien ne vous rafraîchit aussi vite qu’une part de ce délice.$B$BJe vais vous dire, $N, si vous me rapportez 10 pommes de cactus, je vous donnerai quelques parts de surprise aux pommes de cactus en guise de provisions pour vos aventures. Si cela vous intéresse, vous trouverez des pommes de cactus à côté des cactus, tout autour d’ici.'),
(4449,'frFR','Hé vous ! Oui, vous ! Venez donc ici !$B$BVous allez m’aider. J’étais poursuivi par les nains Sombrefer, et je me suis planqué ici, hors de vue. Ces maudits géologues et leur magie ! Ils ont dû me repérer quand même, parce qu’ils ont verrouillé la porte avant que je ne puisse réagir. Je suis coincé à l’intérieur.$B$BDonnez-leur une bonne leçon ! oh… et puis si vous pouviez récupérer de l’étoffe de soie pour... euh… pour rien, ce serait parfait.'),
(4521,'frFR','Le Berceau-de-l''Hiver se trouve juste après Grumegueule, au nord-est de Gangrebois. Vous connaissez ?$B$BJ’ai entendu dire que la région est peuplée de créatures appelées des Indomptables. On dit que ces bêtes gardent des secrets ; les secrets des elfes de la nuit.$B$BIl faut que nous découvrions ce qu’il se cache dans le Berceau-de-l''Hiver.$B$BIl paraît que les Chouettards éreintés se trouvent juste au sud de la route, et que d’autres appelés Chouettards enragés se trouvent au centre du Berceau-de-l''Hiver. Supprimez-les et accédez à cette terre.'),
(5064,'frFR','$N, vous nous avez bien servi par le passé, je peux donc vous confier une importante mission. Le Clan du Totem sinistre prépare quelque chose en secret. Trois agents d''origine inconnue ont été vus chez eux ces dernières semaines. Nous avons découvert que ces messages sont conservés dans plusieurs coffres de la cime de Noir-nuage.$B$B$N, si vous réussissez cette dangereuse mission, je vous récompenserai.'),
(5087,'frFR','Très intéressant, $N…$B$BLorsque cette substance toxique est mélangée à l''eau des sources chaudes, elle perd sa toxicité, mais reste dangereuse temporairement pour ceux qui l''ingèrent. Voilà donc pourquoi les Tombe-hiver protègent les sources chaudes aussi ardemment : ils en ont besoin pour purifier leur eau de feu.$B$BNous devons arrêter ça. Coupez le contact entre les Tombe-hiver et les Noir-bois. Un groupe de messagers fait le chemin entre leur village et Gangrebois. Trouvez-les et éliminez-les en vous appropriant ce qu''ils transportaient.'),
(5517,'frFR','$GFrère:Soeur; $N – les services que vous avez rendu à l’Aube d''argent sont trop nombreux pour être résumés facilement. En récompense, je vais me séparer de l’un de nos mantelets de l’Aube chromatique – une version qui protège le porteur de toutes les formes de magie auxquelles il est possible de résister. Les mantelets chromatiques ne sont octroyés qu’aux plus grands héros de notre organisation ! Ramenez-moi vingt-cinq marques de valeur de l’Aube d''argent en signe de tribut et je vous donnerai le meilleur de nos mantelets.'),
(5518,'frFR','Si vous devez combattre le roi de cette décharge – et je pense que vous n’avez pas le choix – vous devrez vous occuper du capitaine Kromcrush. Oh, vous pouvez vous en « occuper » en le tuant, bien sûr. Mais vous pouvez aussi le laisser en vie.$B$BComment ? Eh bien, depuis le temps que je moisis ici, je pense que je saurais préparer un déguisement d’ogre qui durerait juste assez longtemps pour tromper ces clowns. Le seul problème est la stabilité. Il ne durera pas plus de dix minutes. Amenez-moi ce qu’il me faut, et je vous en ferai un. Je ne vais nulle part, de toute façon…'),
(5521,'frFR','$GFrère:Soeur; $N – les services que vous avez rendu à l’Aube d''argent sont trop nombreux pour être résumés facilement. En récompense, je vais me séparer de l’un de nos mantelets de l’Aube chromatique – une version qui protège le porteur de toutes les formes de magie auxquelles il est possible de résister. Les mantelets chromatiques ne sont octroyés qu’aux plus grands héros de notre organisation ! Ramenez-moi vingt-cinq Marques de valeur de l’Aube d''argent en signe de tribut et je vous donnerai le meilleur de nos mantelets.'),
(5524,'frFR','$GFrère:Soeur; $N – les services que vous avez rendu à l’Aube d''argent sont trop nombreux pour être résumés facilement. En récompense, je vais me séparer de l’un de nos mantelets de l’Aube chromatique – une version qui protège le porteur de toutes les formes de magie auxquelles il est possible de résister. Les mantelets chromatiques ne sont octroyés qu’aux plus grands héros de notre organisation ! Ramenez-moi vingt-cinq Marques de valeur de l’Aube d''argent en signe de tribut et je vous donnerai le meilleur de nos mantelets.'),
(5541,'frFR','Hegnar Rumbleshot vend des armes à feu sur la route d''Anvilmar. Les fusiliers et les équipes de mortier passent beaucoup de temps à s''entraîner près de son magasin et il a toujours besoin de munitions fraîches.$B$BMais... D''après mon messager, la dernière caisse de munitions que je lui ai envoyée s''est perdue quand il a été chassé de son camp, près de l''antre Gris par les Wendigos... L''imbécile a laissé les munitions de Rumbleshot derrière lui !$B$B$N, pouvez-vous les retrouver et les apporter à Rumbleshot ? Il les attend et je suis sûr que ses stocks seront bientôt épuisés.'),
(5629,'frFR','Encore bonjour, $N. Je sais que votre temps a été bien rempli à aider les gens, mais vous devez prendre du temps pour vous. La prêtresse Alathea a envoyé quelqu''un ici pour vous chercher. Il semble que vous ayez attiré l''attention de nos aînés et ils pensent que vous pouvez accomplir de grandes choses. Allez au temple de la Lune et cherchez Alathea. Elle vous y attendra. Bonne chance et qu''Elune soit avec vous.'),
(5662,'frFR','Tous mes respects, $N. En général, je n''enseigne qu''aux gens de ma tribu. Vos connaissances vous viennent d''Aelthalyste qui vit dans une ville appelée autrefois Lordaeron.$B$BRetournez la voir si vous voulez apprendre les compétences qui vous distingueront des autres croyants.$B$BAllez au Quartier des guerriers d''Undercity, vous y trouverez votre Maîtresse.'),
(5673,'frFR','Vous savez que vous avez accès à n''importe lequel de nos Maîtres, $N mais il y a des choses que nous ne pourrons pas vous enseigner et que seule votre déesse Elune est en mesure de faire. Elle donne des compétences spéciales à ses croyants et je pense d''ailleurs qu''il est temps pour vous de retourner au temple de la Lune pour subir un test.$B$BRendez-vous la-bas dès que possible et parlez à la prêtresse Alathea.'),
(5730,'frFR','Vous êtes l’un de mes lieutenants ! Préparez-vous, $C. Je ferai bientôt appel à vous.$B$BLe temps que j’ai passé sur la Lame brûlante est peut-être du temps perdu maintenant, mais cela ne veut pas dire que les plans du Conseil des ombres ailleurs doivent en pâtir. Je vais faire mon possible pour limiter les dégâts ici dans le Gouffre de Ragefeu. Pendant ce temps, mes agents dans les Tarides et Ashenvale vont commencer à travailler à nos nouveaux plans. Revenez vite me voir.'),
(5761,'frFR','La tâche première qui m’a été assignée par notre grand chef de guerre est d’éliminer les créatures responsables de l’infection de la grande cité de notre seigneur par des influences démoniaques. La Lame ardente est une menace, mais il y en a d’autres ; la Lame brûlante par exemple, qui est basée dans le gouffre de Ragefeu, essaie de subvertir en secret des membres innocents de la Horde.$B$BPour les arrêter, il faut tuer leur chef, un gangregarde appelé Taragaman l''Affameur.$B$BTuez-le, et son cœur apaisera Thrall, j’en suis sûr.'),
(5762,'frFR','J’ai un colis pour un vieux client. C’est un nain qui répond au nom de Hemet Nesingwary. Le colis a mis deux semaines à arriver, et Hemet est déjà reparti depuis longtemps. Il a dit qu’il allait à Strangleronce pour y chasser ; il a toutefois pris soin de laisser un peu d’argent pour que je lui fasse livrer son colis, dès que celui-ci arriverait.$B$BHemet est un nain fortuné ; il est bon de le garder comme un client fidèle. Vous voyez ce que je veux dire, n’est-ce pas ? Bon, acceptez-vous de lui livrer son colis pour moi ?$B$BJ’ai entendu dire que Hemet possède un camp à Strangleronce, au nord de Grom''gol.'),
(5821,'frFR','En temps normal, Rigger et moi conduirions nos kodos à travers le territoire des centaures Kolkar. Mais depuis quelque temps, nous entendons résonner les tambours de guerre des centaures. Comme il n’est jamais bon pour les affaires d’être mort, nous préférons ne pas nous aventurer plus avant sur leurs terres !$B$BSi vous acceptiez de nous protéger, $C, et nous aidiez à passer au-delà du village des Kolkar, nous vous récompenserions en conséquence.$B$BCela ne représente pas une si grande distance ; vous devrez simplement sécuriser la caravane, puis vous pourrez toucher votre dû des mains de Smeed Scrabblescrew, qui est un peu plus bas sur la route. Nous faisons souvent des affaires ensemble.'),
(5901,'frFR','Ainsi, afin que la Croisade écarlate connaisse la douleur et la lutte, je veux lui prendre sa précieuse scierie. Je suis sûr que la perte d''une telle ressource va rendre beaucoup plus difficiles la défense et la reconstruction de la ville. Allez-vous m''aider, $N ?$B$BCommencez par vous rendre à Pestebois dans les Maleterres de l''Est. Remplissez cette fiole avec les termites que vous trouverez dans leurs monticules disséminés dans les bois. Revenez quand vous en aurez assez.'),
(5942,'frFR','Papa m’a dit de vous donner cette clé. Il prétend qu’elle ouvre un coffre, derrière la maison.$B$BIl voulait aussi que je vous remercie. Vous l''avez aidé ? Vous lui avez dit que vous aviez retrouvé ma poupée ?$B$BEnfin, voici la clé. Et merci, $N. Merci ! Vous êtes $Gun très gentil monsieur:une très gentille dame; !'),
(5943,'frFR','Vous semblez compétent, $R. Peut-être voudriez-vous gagner un peu d’argent ? Cork et moi avons monté cette caravane pour faire fortune, mais nous ignorions les dangers que recélait cette entreprise !$B$BDevant nous se trouve le convent de Mannoroc… En temps normal, les démons nous ignorent mais quelque chose a effrayé les kodos, ce coup-ci. Je vous paierai pour protéger la caravane lorsque nous passons près du convent de Mannoroc. Quand nous aurons traversé ce coin, vous pourrez aller chercher votre récompense auprès de notre associé, Smeed, au camp de Scrabblescrew.'),
(6004,'frFR','On m’a envoyée en reconnaissance, pour affaiblir et juger les défenses de Hearthglen. Certaines personnes, dans l’Alliance, pensent que l’importance de la petite ville n’est pas seulement d’ordre historique. Je ne suis pas là pour poser des questions quant à ce qui fait l’importance de cette ville ; je suis de toute façon bien trop épuisée pour l’instant pour pouvoir continuer. Je dois me reposer.$B$BSi vous le voulez, je vous paierai largement en échange de votre aide. Commencez au sud, par l’un de leurs camps, près de petit rempart qu’ils ont érigé. Si vous faites vos preuves, je vous emploierai pour m’aider dans ma mission principale.'),
(6026,'frFR','Ces agents de l’Aube d''argent ont chargé le vieux Smokey de réaliser un petit travail de démolition. La maman du vieux Smokey n’a pas élevé un simplet : dès que des écus tintent, Smokey est disponible et prêt à rendre service. C’est mon mot d’ordre !$B$BJe serais maintenant disposé à partager la commission avec vous, si vous êtiez d’accord pour exécuter un petit travail sur le terrain. Voici l’idée : je vais me diriger vers Pestebois et marquer tous les bâtiments qui sont destinés à être détruits. Pendant ce temps, vous collecterez les composants qui sont nécessaires à la confection des bombes. Qu’en dites-vous ?'),
(6028,'frFR','Je suis à la recherche d’une personne sérieuse qui voudrait m’aider pour une petite affaire qui n’est pas sans importance. Je suis ici en tant que représentant de l’Aube d''argent, auprès des dirigeants de Long-guet. J’ai besoin d’obtenir un rapport et de le transmettre à l’officier de l''Aube d''argent, Pureheart, au camp du Noroît. L’endroit se trouve le long de la lisière sud des Maleterres de l’ouest.$B$BL’occasion serait trop belle de vous présenter à ma supérieure, et peut-être d’en obtenir du travail !'),
(6030,'frFR','Umbranse, une médium qui vit en recluse dans la région, a offert à l’Aube d''argent un chef-d’œuvre de littérature... un de ceux qui comprennent une quantité indécente de blabla en prose.$B$BL''un des chefs les plus respectés de l''Aube, le duc Nicholas Zverenhoff, est aussi un brillant linguiste. Pourriez-vous lui apporter cela de ma part, contre une récompense ? La chapelle de l''Espoir de Lumière, c’est là qu’il réside en ce moment. L’endroit se trouve loin à l’est, à l''intérieur des Maleterres de l’est.'),
(6031,'frFR','À Grumegueules, nous sommes satisfaits d''être entre nous. Nous n’aimons pas les étrangers, ce qui n’arrange malheureusement pas le commerce.$B$BIl n’y a pas longtemps, une de nos rares amis elfe de la nuit est arrivée à Grumegueules, portant une cape en étoffe runique. L’étoffe runique est un textile que l’on ne voit pas souvent par ici, et mes frères ont été séduits par sa perfection. Ils désirent que je leur procure des vêtements taillés dans cette étoffe.$B$BVoudriez-vous m’apporter de l’étoffe runique ? Si vous m’en apportez suffisamment, je vous donnerai quelque chose en échange.'),
(6082,'frFR','La dernière créature qu’il vous faut dompter est l’une de celles que vous devriez vous efforcer d’imiter : le scorpide blindé. Il frappe rapidement et avec une grande assurance ; le contrôle d’une force telle que celle-ci fait partie de votre destin de chasseur.$B$BQuand vous reviendrez, je vous offrirai les compétences qui vous permettront de dompter l’animal de votre choix. Cette créature sera à vos côtés et sous votre commandement. Elle gagnera de l’expérience de concert avec vous. Je vous montrerai également comment l''appeler et la renvoyer à volonté.'),
(6084,'frFR','Ces sangliers des rochers sont assez massifs ; peut-être préféreriez-vous quelque chose de plus raffiné ? Bon d’accord, je sais maintenant… Au sud et à l’ouest, vous verrez de grands félins blancs qu’on appelle des léopards des neiges. A l’instar d’une arme ouvragée, ils sont élégants et mortels. Vous les trouverez bien plus agiles que le sanglier que vous avez dompté.$B$BPrenez ce Bâtonnet de domptage, et allez voir si vous ne préférez pas les félins.'),
(6085,'frFR','Peut-être préférez-vous une créature qui possède une véritable force brute ? Les ours Griffeglace font d''excellents familiers pour le chasseur débutant. Ces animaux redoutables vivent à l’est de Kharanos. Voici le Bâtonnet de domptage ; essayez cet animal comme familier, pour voir s’il vous convient !$B$BQuand vous reviendrez, je vous montrerai comment dompter un animal de votre choix. Cette créature affrontera les dangers à vos côtés et gagnera de l’expérience en même temps que vous. Je vous montrerai aussi comment l''appeler et la renvoyer à volonté.'),
(6128,'frFR','L’eau sera l''ingrédient de base du baume curatif que je vais faire pour les gazelles. Pour y adjoindre des propriétés proprement curatives, j’aurai besoin de Terrestrine. Les herboristes savent où et comment trouver ce composant ; aussi, si vous n’êtes pas vous-même herboriste, vous faudra-t-il trouver quelqu’un qui le soit et qui veuille bien nous aider.$B$BEnfin, pour que le remède révèle toutes ses vertus, il faudra intégrer à sa préparation des cornes de kodos. De simples fragments de corne ne suffiront pas. Des kodos à votre portée hantent le nord des Tarides. Sacrifiez-en quelques-uns, $N, et rapportez-moi leurs cornes.'),
(6135,'frFR','Vous avez, pour l’instant, réussi toutes les missions que je vous ai confiées ; même si vous ne l’avez pas fait de la manière la plus opportune qui soit.$B$BJe suppose que vous vous sentez en mesure d’affronter de nouveaux défis. Oui, oui, imbécile, peut-être que vous avez en effet les moyens de réussir une nouvelle série d’épreuves.$B$BLa chauve-souris démoniaque albinos, Crépuscaile, ravage la contrée, plus au nord. Traquez-la et exécutez-la. Revenez me voir ensuite avec une touffe de sa fourrure blanche. Vous recevrez une récompense en cas de réussite.'),
(6148,'frFR','Demetria est la Conseillère en chef du Grand Croisé. On l''appelle l''Oracle en raison de ses sens un peu "irréels". Elle a aidé efficacement la Croisade à remporter plusieurs victoires contre le Fléau.$B$BMême si la ruse qui consiste à l''exposer est couronnée de succès, vu ses pouvoirs psychiques, elle s''attendra sans doute à avoir des ennuis. C''est vous qui allez provoquer ces ennuis.$B$BPoursuivez l''Oracle et tuez-la. Ils doivent être en train de quitter la Main de Tyr pendant que nous parlons. Faites ma fierté, petit ver.'),
(6341,'frFR','Les pêcheurs du village de Rut''theran savent très bien y faire ; de plus, le poisson, là-bas, y est extrêmement abondant et on y pêche des spécimens d’une taille étonnante. Je voudrais juste comparer la manne de cet endroit avec celle du continent.$B$BJe possède une importante collection d’os et d’écailles de poisson que je souhaiterais faire porter à l''un de mes collègues, à Sombrivage. Il s’appelle Laird, il vend des poissons au village d’Auberdine.$B$BApportez ma collection à notre Maître des hippogryphes, Vesprystus, et discutez avec lui des conditions d’un voyage vers Auberdine.'),
(6364,'frFR','Pour vous rendre dans une ville, par la voie des airs, vous devez déjà avoir visité cette ville et avoir parlé avec le Maître des Cavaliers célestes local. Vous avez déjà été à la Croisée et parlé avec le Maître des Cavaliers célestes, Devrak ; par conséquent, vous pouvez prendre un Cavalier céleste, ici, pour vous y rendre, moyennant un modeste paiement.$B$BRevenez me voir, lorsque vous souhaiterez partir. Une fois à la Croisée, vous pourrez livrer les Marchandises en cuir à Jahan Hawkwing.'),
(6386,'frFR','Mes Cavaliers célestes sont entraînés pour se rendre à maints endroits différents, à la seule condition que vous ayez déjà visité l’endroit de destination, au moins une fois, et que vous ayez parlé avec le Maître des Cavaliers célestes local.$B$BVous avez déjà visité la Croisée et parlé avec son Maître des Cavaliers, Devrak ; vous pouvez donc y voler directement, à partir d’ici. Un fois à la Croisée, vous donnerez la lettre de Gryshka à Zargh.$B$BRevenez me voir dès que vous voudrez partir.'),
(6388,'frFR','Voici les pioches d''honneur pour les étudiants de Brock. Si vous avez déjà visité Thelsamar, vous devriez prendre un gryphon pour y retourner !$B$BPrenez les pioches et apportez-les à notre Maître des gryphons, Gryth Thurden ; parlez-lui du voyage vers Thelsamar.'),
(6461,'frFR','Nous, les trolls de Malaka''Jin, nous avons prospéré sur cette terre. Les Serres-Rocheuses nous permettent de chasser pour vivre.$B$BDernièrement, nous avons eu la visite de pique-assiette... À la nuit, les araignées des montagnes ont fait un raid sur nos camps pour voler le fruit de notre chasse.$B$BSi vous nous aidez à éliminer ces bêtes horribles, les trolls de Malaka''Jin vous en seront reconnaissants à jamais. Les araignées vivent partout dans les Serres-Rocheuses. Dirigez-vous simplement vers le nord et vous pourrez le constater.'),
(6482,'frFR','Hein ? Qui êtes-vous ?$B$B$N ? Vous n’êtes pas un furbolg. Ils sont maudits ! Ils m’ont pris pour un ours et m’ont capturé, et maintenant ils m’affament et mes forces sont en train de m’abandonner...$B$BAidez-moi à m’échapper, puis allez parler à ma soeur, Yama, au poste de Bois-brisé, à l’est.$B$B$N ! Je dois m’échapper !'),
(6521,'frFR','Malcin prétend qu’il se trouve à l’extérieur des Souilles de Tranchebauge. Cet ambassadeur doit être tué ; sa mission est un échec aux yeux du roi-liche.$B$BSa présence là-bas en dit long sur ce que nous avons découvert dans la région. La force et la sauvagerie de certains hurans ont crû de manière débridée, tandis qu’ils présentaient des signes indéniables de la Peste. C’est certainement le signe d’un arrangement qu’ils ont dû contracter avec quelqu’un.$B$BRetrouvez Malcin et exécutez-le, $N. Revenez me voir une fois que cela sera fait.'),
(6541,'frFR','Avez-vous déjà été à Ashenvale, au nord ? La Horde a récemment établi un Avant-poste sur la grève de Zoram. Nous nous réjouissons toujours d’accueillir de nouvelles recrues pour nous aider à livrer bataille.$B$BSi vous avez confiance en vous et que vous voulez nous aider, allez voir Kadrak, dans le nord des Tarides, à la tour de guet. C’est lui qui dirige la campagne d’Ashenvale ; c’est lui aussi qui vous dira quoi faire.'),
(6542,'frFR','Avez-vous déjà été à Ashenvale, au nord ? La Horde a récemment établi un Avant-poste sur la grève de Zoram ; nous nous réjouissons toujours d’accueillir de nouvelles recrues pour nous aider à livrer bataille.$B$BSi vous avez confiance en vous et que vous voulez nous aider, allez voir Kadrak, dans le nord des Tarides, à la tour de guet. C’est lui qui dirige la campagne d’Ashenvale ; c’est lui également qui vous dira quoi faire.'),
(6544,'frFR','Hé ! $C ! Venez par ici !$B$BMes soldats et moi sommes sur le point d’attaquer l’avant-poste d''Aile-argent, plus à l’ouest. Notre cible, cette fois, est leur chef, Duriel Moonfire. Des éclaireurs ont rapporté que l’avant-poste était lourdement défendu par des sentinelles et des guerriers. La bataille sera splendide !$B$BQue diriez-vous de participer, à nos côtés, et de vous couvrir de gloire, $N ? Si vous venez avec nous, vous pourrez par la suite faire état de notre victoire auprès de mon supérieur, Ertog Ragetusk, à Bois-brisé.$B$BAlors, qu’en dites-vous, êtes-vous de notre côté ?'),
(6563,'frFR','Dans les premiers tunnels des Profondeurs de Brassenoire, on trouve de grosses grappes de saphirs le long des murs. Récemment, on a constaté que les nagas ramassaient les cristaux. Jusqu''à ce qu''on sache pourquoi, il vaudrait mieux empêcher les nagas de continuer. Les cristaux ont un grand pouvoir élémentaire et s''ils sont mal utilisés, ils peuvent entrer dans la composition d''un arcane puissant.$B$BVoulez-vous m''aider, $N ? Les Profondeurs de Brassenoire se trouvent le long de la grève de Zoram au nord de notre avant-poste.'),
(6603,'frFR','Il y a du grabuge au Berceau-de-l''Hiver !$B$BSûr, je passe du temps dans les étendues sauvages et je connais des choses... Je suis toujours très fière de le dire. Je considère que les heures que je passe là-bas dans les collines sont comme de l''or. Elles aident à avoir des réflexes rapides, une tête fraîche et un œil aiguisé...$B$BIl faut du jugement, de l''intelligence et de la maturité pour apprécier la solitude de ces chemins.$B$BBon, de quoi j''étais en train de parler ?$B$BAh oui, du grabuge ! Allez voir Donova Snowden aux sources chaudes, elle vous en dira plus.'),
(6681,'frFR','$N, Ravenholdt porte un certain intérêt à vos capacités de jeune $Gvoleur:voleuse;. Nous avons observé : votre style est un peu maladroit, mais rien d''irréparable.$B$BSi vous souhaitez vous engager dans une carrière de disciple de maître Ravenholdt et de membre de la Ligue des Assassins, vous n''avez qu''à apporter le Cachet de Ravenholdt (attaché à cette lettre) au manoir de Ravenholdt.$B$BVotre première tâche est de localiser le manoir, caché dans les collines d''Hillsbrad, afin de démontrer votre ruse.$B$BMes respects,$B$BFahrad.'),
(6985,'frFR','Les nains Stormpike se servent de la mine de Gouffrefer pour stocker leurs réserves. Pillez-la, rapporter-moi leurs fournitures. Cela ralentira leurs efforts dans la vallée d’Alterac, et nous donnera l’équipement dont nous avons besoin !$B$BFaites attention, $N. La mine de Gouffrefer se trouve loin dans le territoire de l’Alliance, et elle a changé de mains maintes et maintes fois.'),
(7081,'frFR','Les cimetières de la vallée d’Alterac sont des territoires de choix. La Horde et l’Alliance se battent sauvagement pour conserver le contrôle de ces terres consacrées. Êtes-vous $Gprêt:prête; à vous joindre à ce combat, $N ?$B$BJe veux que vous attaquiez un cimetière ennemi. Trouvez un cimetière sur lequel flotte la bannière de la Horde et arrachez-la ! Si vous y parvenez, la tâche que je vous ai fixé sera achevée…$B$BMais si vous le tenez pour quelques minutes supplémentaires, nos troupes viendront vous relever.'),
(7082,'frFR','Dans cette vallée, la ligne de front fluctue sans cesse. Les territoires avancent et reculent au gré des affrontements avec nos adversaires. Il se trouve que les cimetières sont l’endroit où le conflit est le plus intense, $N.$B$BPrenez un cimetière à l’Alliance ! Trouvez un cimetière avec une bannière de l’Alliance plantée en son centre et arrachez-la !$B$BSi vous y parvenez, la tâche que je vous ai fixé sera achevée, mais si vous tenez le cimetière pendant quelques minutes supplémentaires, il nous appartiendra et nos troupes viendront vous relever.'),
(7101,'frFR','Les tours et les fortins sont des positions défensives de très grande valeur, et nous devons tous les prendre. Je veux que vous attaquiez un fortin ou une tour détenu par l’ennemi.$B$BPour cela, entrez dans une tour ou un fortin sur lequel flotte la bannière de l’Alliance. A l’intérieur, vous trouverez une autre bannière ennemie. Prenez-la, et la bannière blanche de la Horde apparaîtra à sa place. Bien joué !$B$BA ce stade, votre mission sera achevée, mais si vous tenez assez longtemps et si l’Alliance ne contre-attaque pas, la zone tombera entre nos mains !'),
(7102,'frFR','Les tours et les fortins sont des positions défensives de très grande valeur, et nous devons en tenir autant que possible. Je veux que vous attaquiez un fortin ou une tour détenue par l’ennemi.$B$BPour cela, entrez dans une tour ou un fortin sur lequel flotte la bannière de la Horde. A l’intérieur, vous trouverez une autre bannière ennemie. Prenez-la, et la bannière blanche de l’Alliance apparaîtra à sa place. Bien joué !$B$BA ce stade, votre mission sera achevée, mais si vous tenez assez longtemps et si la Horde ne contre-attaque pas, la zone tombera entre nos mains !'),
(7122,'frFR','Les mines de la vallée d’Alterac renferment bien davantage que du minerai. Les Frostwolf et les Stormpike ont dissimulé du matériel dans les mines de Gouffrefer et de Froide-dent… ce ne serait pas une mauvaise idée, si seulement nous pouvions en garder le contrôle !$B$BPrenez une mine, puis revenez me voir. Pour prendre une mine, entrez dans une de celles que nous ne contrôlons pas et tuez son chef. Lorsque ce sera fait, la mine sera à nous et nous enverrons des troupes pour la protéger !'),
(7124,'frFR','La bataille fait rage dans la vallée d’Alterac, mais aussi dans les mines de Froide-dent et de Gouffrefer. Ces deux exploitations sont riches en minerais, et sont toutes deux utilisées pour y stocker du matériel ; ce n’est pas étonnant qu’elles soient autant appréciées !$B$BContribuez à notre effort de guerre, $N ! Capturez une mine pour la Horde ! Pour y parvenir, entrez dans une mine que nous ne contrôlons pas et tuez son chef. La mine sera alors à nous, et nous enverrons des troupes pour la protéger !'),
(7141,'frFR','La Ligue des Explorateurs soupçonne la présence d’artefacts dans la vallée d’Alterac, mais les orcs Frostwolf nous empêchent de l’explorer. Nous ne pouvons pas laisser la Horde faire obstacle à la poursuite du savoir ! Abattez Drek’Thar, leur général. Sans lui, les Frostwolf perdront leur mordant.$B$BDrek’Thar est au donjon Frostwolf, au sud de la vallée d''Alterac. Tuez-le et revenez me voir.'),
(7162,'frFR','Vous arrivez juste à temps, $C. Ces sauvages de Frostwolf refusent d’abandonner ! Nous devons leur montrer la puissance des Stormpike. Ils doivent s’incliner devant notre supériorité.$B$BAvant de vous risquer sur le champ de bataille, vous devrez rejoindre les rangs des Stormpike.$B$BLes cavernes de l''Aile de glace se trouvent au sud-ouest. Dans leurs tréfonds, vous trouverez une bannière Stormpike. Allez-y et récupérez-la. Ramenez-la moi et vous aurez bien mérité un insigne d’initié Stormpike.'),
(7181,'frFR','Les envahisseurs Stormpike ne sont pas la seule menace dans la région, soldat. La guerre dans la Vallée se livre sur deux fronts. Les trolls cannibales des Winterax ont leurs propres ambitions.$B$BIls sont dirigés par Korrak le Ragesang, une bête cruelle et rusée.$B$BLa mort de Korrak serait un grand coup porté aux Winterax. Tuez cet animal, et vous serez récompensé !'),
(7202,'frFR','Les indigènes de la région, les trolls Winterax, sont des sauvages cruels qui rêvent d’ajouter nos os à leurs infâmes ragoûts.$B$BNous devons leur montrer notre force !$B$BNous avons récupéré dans leurs cavernes des livres qui détaillent leur hiérarchie. Ils indiquent que leur chef, Korrak le Ragesang, a tendance à rester caché jusqu’à ce qu’il ait une raison de faire connaître sa présence.$B$BLa mort de Korrak signerait la mort du clan Winterax ! Tuez-le et revenez.'),
(7221,'frFR','Ah, $N, $Gprêt:prête; à prendre votre service ? Très bien, les Stormpike ont besoin de tous les bras disponibles !$B$BDiscutez avec la prospectrice Stonehewer à Dun Baldar. Elle cherche des volontaires pour une mission très importante en territoire ennemi. Vous la trouverez dans les profondeurs de la garnison de Dun Baldar.$B$BEt gardez l’œil ouvert quand vous traverserez Dun Baldar. Il y a beaucoup à faire pour un $C travailleur et qui n’a pas peur de se salir les mains.'),
(7223,'frFR','Les combats font sans cesse rage dans la vallée d’Aterac, et le matériel que nous recevons d’Ironforge est insuffisant pour équiper nos troupes.$B$BSi vous trouvez des morceaux d’armure sur le champ de bataille, contribuez à l’effort de guerre et ramenez-les-moi !'),
(7224,'frFR','Lorsque vous combattez l’ennemi, ramassez les morceaux de leurs armures et amenez-les-moi. Je m’en servirai pour fabriquer des armures pour nos propres troupes !'),
(7241,'frFR','Les tambours de guerre résonnent dans des terres lointaines, $C. Le clan favori de votre Chef de guerre est attaqué par l''infâme garde Stormpike d''Ironforge.$B$BA vous voir, je pense que vous êtes endurci et prêt à vous battre pour la cause du clan Frostwolf.$B$BC''est vous qui devez faire ce nouveau pas dans votre évolution.$B$BVous trouverez l''entrée de la vallée d''Alterac dans les contreforts d''Hillsbrad. Entrez-y et allez trouver le maître de guerre Laggrond. Faites vites, $C, la bataille est commencée !'),
(7302,'frFR','Notre soutien aérien n’existe plus, $N. Nos chefs d’escadrille ont été abattus au-dessus du territoire ennemi. Vous devez découvrir ce qui leur est arrivé, afin que nous puissions mener une expédition de secours ! Guse a été vu pour la dernière fois au-dessus du fortin de l''Aile de glace. Le Chevaucheur de guerre de Jeztor a été vu près de la scierie Stormpike. Quant à Mulverick… on a vu ce crétin téméraire s’écraser près du fortin nord de Dun Baldar.$B$BJe n’ai pas d’autres informations. Allez-y et passez la région au peigne fin !'),
(7321,'frFR','Qui prétend que les morts-vivants n’y connaissent rien en cuisine ? Tenez, par exemple, prenez ma recette secrète de Bisque de tortue apaisante, par exemple. Je connais des gens qui sont revenus d’entre les morts rien que pour en déguster un bol ! Hé hé…$B$BA ce propos, je n’ai pas eu l’occasion d’en préparer dernièrement. Autrefois, j’allais jusqu''au lac de Lordamere pour chasser les gueules d’acier – ces sales bêtes – mais à présent, j’ai trop de travail.$B$BSi vous m''apportiez de la Viande de tortue venant des gueules d''acier et des Epices apaisantes, je vous mitonnerai un bon petit plat.'),
(7367,'frFR','Les Frostwolf ont piégé leurs lignes et leurs bases, $C. Lorsque vous entrez dans leur territoire, vous devez faire attention où vous mettez les pieds.$B$BSi vous lancez une frappe massive contre eux, vous devez détruire leur source de munitions antipersonnel – je parle de leur spécialiste en explosifs. Si vous le tuez, vous pourrez désamorcer les mines sans danger. Tant qu’il est à terre, les mines sont inoffensives.$B$BVous le trouverez probablement dans une tour près de la garnison de Glace-sang. Bonne chance !'),
(7461,'frFR','En avez-vous entendu assez ? Êtes-vous $Gun homme:une femme; d’action ?$B$BCette folie doit s’achever. L’âge des immortels est révolu depuis longtemps. Détruisez les gardiens qui entourent les pylônes pour abattre le champ de force. Lorsque ce sera fait, détruisez Immol’thar. Le pouvoir du prince sera très diminué. Attaquez-le et mettez un terme à son existence. Il est temps que les esprits de cette ville trouvent le repos.'),
(7463,'frFR','Un $R mage ! C’est merveilleux ! Je n’avais vu personne de votre espèce depuis… attendez, laissez-moi réfléchir… cinq cents ans !$B$BJ’ai quelque chose qui pourrait apaiser votre soif, mais vous devrez d’abord me rendre un service.$B$B<Lydros ricane.>$B$BUne anomalie hante Eldre’Thalas. Un élémentaire d’eau s’est installé dans l’aile est. Sa présence doit être cataloguée !$B$BRendez-vous dans le quartier de Crochebois et emparez-vous d’une partie de l’essence élémentaire de l’Hydrogénos. Revenez me voir ensuite et je vous apprendrai un sort utile.'),
(7483,'frFR','Maître Cherche-Rêve a perdu le Libram de Rapidité dans l’aile est. Le Libram permet de placer un sorcelet de rapidité mineur sur votre équipement. À peine mieux qu’un tour de passe-passe, en vérité…$B$BMais s’il vous intéresse, vous pourrez m’apporter le Libram avec quelques composants de base.$B$BJe crois qu’il faut aussi du sang de héros, un diamant noir sans défauts et de grands éclats brillants. Mais je peux me tromper.$B$B<Lydros hausse les épaules.>'),
(7485,'frFR','Il a pleuré comme un enfant lorsqu’il a perdu ce libram. De vous à moi, il m’est arrivé de pleurer sur des textes disparus, car il n’est pas de plus grande perte que celle du savoir et de l’histoire, mais verser des larmes sur ce méli-mélo d’incantations quasiment inutilisables ? Grotesque ! Cela m’a convaincu que le prince lui a fait une faveur le jour où il a séparé sa chair de ses os.$B$BApportez-moi le libram avec un diamant noir en parfait état, de grands éclats brillants et une couture d''abomination effilochée et je recréerai l''arcanum.$B$BOh, il doit être dans l’aile nord.'),
(7494,'frFR','$N, nous avons besoin de votre aide en Feralas !$B$BUne magicienne renégate, Lethtendris, se cache dans les anciennes ruines elfiques d’Eldre’Thalas, que l’on appelle aujourd’hui Hache-tripes. On suppose qu’elle a avec elle un objet qui concentre de dangereuses énergies magiques. Il doit être récupéré.$B$BLatronicus Moonspear a besoin d’agents pour entrer dans Hache-tripes et prendre cet objet à Lethtendris.$B$BServez l’Alliance ! Allez voir Latronicus au bastion de Feathermoon, en Feralas.'),
(7562,'frFR','$N, vous avez approfondi les arts ténébreux. Votre maîtrise des habitants d’outremonde est impressionnante… Vous êtes peut-être prêt à lier l’un des redoutables destriers de l’effroi.$B$BLe rituel qui permet d’appeler la bête consomme énormément de puissance et de ressources, mais si vous désirez dominer cette monture épique, allez voir Mor''zul Bloodbringer. Il campe près de l’Autel des tempêtes dans les Steppes ardentes.$B$BAllez, $N. Cette quête sera périlleuse, mais un démoniste de votre puissance ne recule pas devant le danger !'),
(7583,'frFR','La prison est prête, mais le plus difficile reste à faire.$B$BVous devez trouver un Commandant de la garde funeste dans la Balafre impure, puis le capturer grâce à cette prison de cristal.$B$BPrenez garde ! Les gardes funestes sont des adversaires aussi dangereux que rusés. Votre gibier tentera de vous détruire dès que vous aurez commencé le rituel d’emprisonnement. Il se débattra et fera tout pour éviter la captivité.$B$BIl se concentrera sur vous et sur vous $Gseul:seule;, $N. Pour cette raison, je vous conseille de partir avec des compagnons capables de vous garder en vie !'),
(7623,'frFR','Mor’zul me dit que vous voulez ouvrir un portail vers Xoroth. Pour cela, vous aurez besoin de Poussière d’étoiles xorothienne. Ce n’est pas simple à trouver sur Azeroth !$B$BMais une créature pourrait pour aider : le seigneur Banehollow, à Jaedenar, le siège du Conseil des ombres. Allez lui parler, et il se séparera peut-être d’un peu de poussière.$B$BMais si vous allez à Jaedenar, vous aurez sans doute besoin de porter sur vous le parfum maléfique du Conseil des ombres. Pour cela, je vous propose mes potions des ténèbres, mais elles ne sont pas bon marché…'),
(7624,'frFR','Vous voulez entrer dans mes bonnes grâces ? Tuez pour moi.$B$BMon serviteur, Ulathek, ne cesse de ramper devant moi, tout en complotant avec le seigneur Hel’nurath sur Xoroth. Hel’nurath compte usurper mon pouvoir ici, et Ulathek est son espion…$B$BProuvez que vous êtes à mon service et pas à celui de mes rivaux. Allez trouvez Ulathek dans ses quartiers du Fort des Ombres, à l’ouest d’ici. Dites-lui que je connais son secret et regardez la terreur l’envahir. Ensuite, apportez-moi son cœur !'),
(7625,'frFR','Vous cherchez de la poussière d’étoiles xorothienne ? Vous voulez ouvrir un portail vers Xoroth, le domaine de mon rival, Hel’nurath ? Seriez-vous en train de vous préparer à voler l’un de ses précieux destriers de l’effroi ?$B$BTrès bien. Mon serviteur, Ur’dan, a une réserve de poussière d’étoile xorothienne. Vous pouvez en disposer… Si vous en payez le prix.'),
(7628,'frFR','Une Chandelle de l’apocalypse conserve du feu et le dirige contre ceux qui voudraient interrompre le rituel. Lorsque vous créerez votre Cercle de lien supérieur, si votre chandelle est allumée, tous les démons vagabonds seront brûlés par ses flammes !$B$BContenir le feu n’est pas simple, et nécessite l’essence que recèlent les écailles d’un dragon noir. Récupérez de telles écailles et apportez-les à Gorzeeki.'),
(7629,'frFR','Il reste une étape pour réaliser le parchemin de Mor’zul. J’ai besoin de papier imprégné de Poussière d’étoiles xorothienne. Et… j’ai peur de ne pas pouvoir la fabriquer ici. Je n’ai pas l’équipement nécessaire !$B$BMais il existe un laboratoire d’alchimie qui contient tout ce qu’il nous faut. C’est à la Scholomance, sur l’île de Caer Darrow dans les Maleterres.$B$BJe ne peux pas faire le voyage, mais tenez, prenez cette bouteille. Elle contient un diablotin très intelligent. Libérez-le dans le laboratoire d’alchimie et il préparera le papier.'),
(7630,'frFR','À présent que la Cloche, la Roue et la Chandelle sont prêtes, vous avez besoin de quelqu’un pour les préparer au rituel. J’ai un diablotin qui connaît les procédures… Il vous faudra juste un récipient pour le transporter sur place.$B$BJe peux vous en vendre un, mais pour le fabriquer, il me faut de l’arcanite. En avez-vous ? Sinon, vous devriez trouver un alchimiste pour vous en faire.$B$BRevenez me voir quand vous aurez l’arcanite, et je vous vendrai le diablotin en bocal !'),
(7632,'frFR','La surface de la feuille brille d’un vert vif. Sa surface est extrêmement rugueuse, avec de nombreuses rides et nervures.$B$BVous estimez qu’elle vient de quelque chose d’ancien et de puissant.$B$BVous devriez peut-être trouver son premier propriétaire ?'),
(7635,'frFR','Vartus vous offre le bâton nécessaire pour créer un Arc des anciens ? Très bien, mais je suis le seul à pouvoir enchanter la corde indispensable pour l''achever.$B$BC’est une tâche simple, petit être. Tuez un dragon noir adulte et prenez l''un de ses tendons. Ramenez-le-moi, et je l’enchanterai de manière à en faire une corde d’arc presque indestructible.'),
(7638,'frFR','$N, le temps est venu d’apprendre ce que vous devrez faire pour vous procurer quelque chose que vous attendez sans doute depuis un moment… votre destrier !$B$BAllez parler au seigneur Grayson Shadowbreaker, ici même, dans le Quartier de la cathédrale, à Stormwind. Il vous apprendra à maîtriser la monture favorite des paladins. Et auparavant, il vous chargera de toutes les tâches que vous devrez accomplir pour vous en procurer un.$B$BJ’espère que votre épreuve se passera bien. Pour la Lumière, noble $Gfrère:sœur; !'),
(7644,'frFR','Une fois posé sur le dos de l’Ancien esprit équin, le caparaçon se met à luire faiblement. L’air se charge de puissance pendant un bref instant, puis le caparaçon se téléporte, en toute sécurité, dans votre sac.$B$BIl semble qu’il ait été béni. Il ne vous reste plus qu’à suivre les instructions du seigneur Shadowbreaker : retourner le voir à Stormwind.'),
(7645,'frFR','À la Main d’argent, ils ont dit que j’étais FOLLE lorsque j’ai dit que je pouvais préparer un fourrage qui pourrait nourrir des esprits de chevaux. Ils ont TOUS pensé que j’avais perdu la tête !$B$BMais maintenant, je tiens ma revanche !$B$BJe ferais ce que vous me demandez, PALADIN… soi-disant CHAMPION… mais cela va vous coûter cher. J’ai besoin de biscuit spéciaux… Des Biscuits enrichis en manne qui ne sont vendus que par l’Aube d’argent. Et pour cette fois, j’exige – parfaitement, j’EXIGE de l’or en compensation des souffrances que j’ai endurées !$B$BVous n’arrêtez pas de vous gargariser de votre sens du sacrifice, PALADIN ? Il est temps maintenant de le mettre en pratique !'),
(7646,'frFR','L’épreuve qui vous permettra de sauver le destrier déchu commence par l’assemblage d’un Clairvoyant. En fait, le vôtre est pratiquement prêt. L’Encensoir d’exorcisme que vous avez utilisé à Val-Terrreur en sera le catalyseur, et je vais lui fabriquer un réceptacle.$B$BIl nous faut néanmoins nous procurer deux composants : deux diamants. Ils doivent tous deux être d’une eau bien précise – un diamant d’Azeroth et un diamant noir en parfait état. Tous deux formeront le phare grâce auquel le Clairvoyant percera les ombres !'),
(7667,'frFR','$N, j’espère que vous pourrez m’aider dans une affaire urgente… à la fois matériellement et spirituellement. Laissez-moi vous expliquer.$B$BDans les profondeurs de la Scholomance, en Lordaeron, se trouve une chambre appelée le Grand ossuaire. Je suis en train de terminer un objet qui permettra de percer les ombres de cet horrible endroit. Pour le terminer, j’ai besoin de deux diamants : un diamant d’Azeroth et un diamant noir en parfait état. Je sais que cela ne se trouve pas facilement, et je n’ai pas les moyens de les acheter.$B$BPourriez-vous me les procurer ?'),
(7670,'frFR','$N, le temps est venu d’apprendre ce que vous devrez faire pour vous procurer quelque chose que vous attendez sans doute depuis longtemps… votre destrier !$B$BAllez parler au seigneur Grayson Shadowbreaker, dans le Quartier de la cathédrale, à Stormwind. Il vous apprendra à maîtriser la monture favorite des paladins. Et auparavant, il vous chargera de toutes les tâches que vous devrez accomplir pour vous en procurer un.$B$BJ’espère que votre épreuve se passera bien. Pour la Lumière, noble $Gfrère:sœur; !'),
(7721,'frFR','Si je dois rester ici à gérer cette boutique en pleine Côte oubliée, j’aurais besoin que l’on s’occupe de ces fichus élémentaires. La puissance déchaînée des éléments, quelle plaie !$B$BHeureusement pour moi, et aussi pour vous, mon cher et nouvel agent provocateur, les élémentaires représentent une source d’énergie idéale pour mon Ultra-réducteur perfectionné ! Donnez-leur ce qu’ils méritent ! Sans oublier de me garder leurs noyaux élémentaires, bien sûr !'),
(7722,'frFR','Quand ce bâtard de Maltorius a quitté notre clan, il a emporté avec lui quelque chose de plus précieux qu''un cristal des arcanes en parfait état : notre recette du Flux embrasé ! Je mettrais ma main à couper que la recette faisait partie de son marché avec les Sombrefer pour sa promotion.$B$BJe veux que vous nous rapportiez nos plans secrets, $N. Je suis certain qu''ils se trouvent près de Maltorius, loin dans les profondeurs de la Fosse aux scories.'),
(7733,'frFR','J’ai une piste qui pourrait nous conduire à une source de peaux encore MEILLEURES. Incroyable, non ? Au nord de Feralas, loin dans le repaire des Griffes féroces, vit un autre groupe de yétis. Ils sont beaucoup plus coriaces que ceux que vous avez déjà combattus. Si vous aimez les défis, celui-là devrait vous combler !$B$BJe vous récompenserai généreusement pour dix de leurs peaux. Apportez-les ici, et nous ferons affaire.'),
(7734,'frFR','J’ai une piste qui pourrait nous conduire à une source de peaux encore MEILLEURES. Incroyable, non ? Au nord de Feralas, loin dans le repaire des Griffes féroces, vit un autre groupe de yétis. Ils sont beaucoup plus coriaces que ceux que vous avez déjà combattus. Si vous aimez les défis, celui-là devrait être à la hauteur de vos attentes !$B$BJe vous récompenserai généreusement pour dix de leurs peaux. Amenez-les ici, et nous ferons affaire.'),
(7761,'frFR','Imbécile,$B$BJe n’ai aucune confiance dans votre capacité à empêcher les intrus de pénétrer dans le repaire du maître. Dans l’éventualité très probable de votre décès, cet orbe comporte une sécurité incorporée, destinée à empêcher les intrus de se téléporter directement dans le repaire de l''Aile noire.$B$BSeuls ceux qui portent dans leur chair la Marque de Drakkisath peuvent s’en servir. Et heureusement, Drakkisath n’est pas aussi incompétent que vous. Il garde la marque lui-même !$B$BChef de guerre Rend Blackhand.$B$BP.S. : Détruisez cette lettre, idiot.'),
(7815,'frFR','Faut pas se laisser prendre à leurs grands yeux, v’savez ? Ces gueules d’acier des mers, c’est la plaie des plaies ! Je peux pas pêcher cinq minutes sans qu’un de ces gros aspirateurs à poissons me vole mes appâts.$B$BRendez-nous service, à moi et tous les gens du village des Revantusk, tuez-les.$B$BTuez-les, tous autant qu’ils sont !')
INSERT INTO `quest_template_locale` (`ID`,`locale`,`QuestDescription`) VALUES
(7816,'frFR','Yo ! Y a une tortue qu’est pas comme les autres. Elle, c’est la Gammerita, la patronne des gueules d’aciers des mers – un sale reptile voleur.$B$BLà, elle s’est sauvée avec mon meilleur appât. L’a tranché la ligne, comme ça, net ! Et depuis, les poissons, y mordent plus pareil.$B$BTrouvez Gammerita et récupérez mon appât. Oui, dans son estomac.'),
(7828,'frFR','Les Hinterlands sont un endroit dur, $R. On y a perdu beaucoup de braves trolls. Les loups Crins-d''argent sont l’une des pires menaces qu’affrontent nos chasseurs. Ces animaux se cachent dans les buissons et les fourrés, attendant l’occasion de bondir.$B$BCette férocité ne doit pas rester impunie !$B$BVous devez penser comme les Crins-d''argent. Traquez les Traqueurs ! Tuez-les tous !'),
(7839,'frFR','Ces vermines de Vilebranch ont envahi notre village et volé mes outils ! J’ai des outils de rechange, mais ceux qu’ils m’ont volé m’avaient été offerts par un bon gnome, qui m’a sauvé la vie dans ma jeunesse.$B$BJe veux les récupérer, $N. J’y tiens énormément.$B$BMarkhor m’a dit qu’ils avaient été vus près des temples d’Agol’watha et de Shaol’watha.$B$BCes temples sont au nord-est des Hinterlands.$B$BRetrouvez mes outils !'),
(7841,'frFR','Les Wildhammer sont en train de passer des marchés avec nos ennemis, de forger de nouvelles alliances. Cette fois, ils travaillent avec les hauts elfes !$B$B<Otho crache.>$B$BIl faut qu’on leur envoie un message, à ces nains. Un message écrit avec le sang de nos ennemis. Tuez tous les hauts elfes du Haut-val que vous pourrez trouver, et exposez leurs cadavres en guise d''avertissement.$B$BOn ne joue pas avec les trolls !'),
(7844,'frFR','Trois tribus de trolls habitent les Hinterlands, $N. En vérité, cela résume tout ce qui nous rassemble : nous sommes des trolls et nous vivons dans les Hinterlands.$B$BLes bien nommés Vilebranch sont des dégénérés qui n’hésitent pas à manger d’autres trolls et d’autres humanoïdes.$B$BSi Zul’jin était là, il les détruirait tous d’un revers de main, mais hélas, Zul’jin n’est pas revenu, et nous sommes livrés à nous-mêmes.$B$BIl vous revient d’anéantir ces nuisibles !'),
(7861,'frFR','Par ordre de l’Aînée Torntusk, la vile prêtresse Maléficia et ses sbires doivent être mis à mort !$B$BUne forte récompense est offerte à tous ceux qui parviendront à tuer la vile prêtresse Maléficia et la totalité de sa garde d’élite Aman''zasi.'),
(7862,'frFR','Suite à la mort du capitaine Malkhor, le poste de capitaine de la garde de Revantusk est à pourvoir. Si vous désirez devenir capitaine de la garde de Revantusk, accomplissez les tâches suivantes avant de présenter votre candidature à l’Aînée Tornstusk :$B$BExterminer des Berserkers Vilebranch.$B$BExterminer des Chasseurs des ombres Vilebranch.$B$BExterminer des Sanguinaires Vilebranch.$B$BExterminer des Mangeurs d’âmes Vilebranch.'),
(7875,'frFR','La sauvagerie de la forêt d''Ashenvale succombera devant la puissance de la Horde, $R. Aile-argent ne pourra rien dire ou faire pour arrêter nos obligations souveraines. Kalimdor appartient à la Horde. Comment osent-ils tenter de nous empêcher de récolter ce qui nous appartient de droit !$B$BQue la fierté gonfle votre poitrine lorsque vous repousserez leurs futiles efforts pour ralentir notre progression. Détruisez les Sentinelles d''Aile-argent, et vous gagnerez une marque d''honneur Warsong. Revenez me voir avec l''une de ces marques, $N, et je vous récompenserai.'),
(7876,'frFR','La sauvagerie de la forêt d''Ashenvale succombera devant la puissance de la Horde, $R. Aile-argent ne pourra rien dire ou faire pour arrêter nos obligations souveraines. Kalimdor appartient à la Horde. Comment osent-ils tenter de nous empêcher de récolter ce qui nous appartient de droit !$B$BQue la fierté gonfle votre poitrine lorsque vous repousserez leurs futiles efforts pour ralentir notre progression. Détruisez les Sentinelles d''Aile-argent, et vous gagnerez une marque d''honneur Warsong. Revenez me voir avec l''une de ces marques, $N, et je vous récompenserai.'),
(7905,'frFR','La foire de Sombrelune arrive ! Ne manquez pas d’admirer ses merveilles lorsqu’elle sera en ville !$B$BMieux, si vous le prenez maintenant, vous pourrez échanger ce coupon contre des bons gratuits ! Il vous suffira de le donner à Gelvas Grimgate, à l’intérieur de la foire !$B$BLa foire est juste à côté de Goldshire, c’est une occasion exceptionnelle, à saisir dès aujourd’hui !'),
(7926,'frFR','La foire de Sombrelune arrive ! Ne manquez pas d’admirer ses merveilles lorsqu’elle sera en ville !$B$BMieux, si vous le prenez maintenant, vous pourrez échanger ce coupon contre des bons gratuits ! Il vous suffira de le donner à Gelvas Grimgate, à l’intérieur de la foire !$B$BLa foire est juste à côté de Thunder Bluff, c’est une occasion exceptionnelle, à saisir dès aujourd’hui !'),
(8054,'frFR','Vos croyances nous sont étrangères, $Gpaïen:païenne;. Autrefois, des Zandalar furent qualifiés d’hérétiques, au temps de la puissance de l’empire Gurubashi. Ces incroyants osèrent défier les prêtres d’Hakkar. Ils furent traqués et exterminés comme de la vermine. Mais ils n’ont jamais faibli, ni renoncé à se battre contre le Dieu sanglant. Nous honorons le prix qu’ils ont payé. Ils étaient les libres-penseurs.$B$BDétruisez les séides d’Hakkar à Zul’Gurub. Ramenez-moi le Parangon de puissance que je recherche. Votre succès sera généreusement récompensé.$B$BAllez.'),
(8056,'frFR','Les augures de notre tribu sont révérés pour leur don de seconde vue. Ce ne sont pas des sorciers-docteurs qui passent leur temps à lancer des os ou à lire des feuilles pour comprendre le monde – et ils ne lancent pas de maléfices à tort et à travers, eux. Vous êtes chaman, vous connaissez déjà une partie des pouvoirs de l’augure. Nous autres Zandalar, nous attachons un grand prix à la sagesse que les augures apportent à la tribu.$B$BFaites-moi offrande d''un Parangon de puissance de Zul’Gurub, et prouvez-nous votre valeur. Si vous y parvenez, je vous donnerai des brassards que nos augures apprécient par-dessus tout !'),
(8060,'frFR','Dans notre tribu, les mages sont appelés “illusionnistes”. Leurs incantations emploient des mojos puissants, semant la confusion et le trouble parmi les ennemis de la tribu.$B$B<Al''tabim éclate d’un rire mauvais.>$B$BQuel beau spectacle que celui d’un illusionniste au travail, mettant ses ennemis à genoux en les engloutissant sous leur propre folie !$B$BPour apprendre la voie de l’illusionniste, rendez-vous à Zul’Gurub et ramenez-moi un Parangon de puissance. Si vous y parvenez, je vous donnerai les couvre-bras dont nos illusionnistes se servent pour tisser leurs sorts.'),
(8063,'frFR','Nos insensés ressemblent aux voleurs, mais avant toutes choses, ils savourent la folie… le chaos… l’imprévisibilité de l’existence. Sur le champ de bataille, ils sont terrifiants. Aux temps sauvages, lorsque les tribus se sont divisées, ils ont semé les graines de la confusion et de la démence parmi nos ennemis. Sans eux, nous ne serions pas là aujourd’hui.$B$BRamenez-moi le Parangon de puissance de Zul’Gurub que je recherche, et je vous remettrai la première pièce d’une précieuse armure d’insensé. Plongez dans la folie !'),
(8068,'frFR','La magie est une force brute, primitive, que seuls les plus forts peuvent modeler. Le mojo est une extension de notre pouvoir, et l’un de ses emplois les plus puissants est l’illusion. Comment peut-on espérer vaincre un ennemi qui n’est pas réellement là ? Nous, les Zandalar, nous apprécions ce pouvoir, et les illlusionnistes ont une place d’honneur au sein de la tribu.$B$BPrenez le Parangon de puissance dont nous avons besoin à Zul’Gurub. Si vous y parvenez, vous serez $Ghonoré:honorée; par la tribu, et nous vous remettrons un mantelet puissant, utilisé par nos meilleurs illusionnistes !'),
(8069,'frFR','Notre puissance et notre rang au sein de la tribu sont indiqués par ce que nous portons. Nos tenues sont faites à partir des matériaux les plus fins, et imprégnés du mojo dont nous nous servons pour devenir puissants. Les illusionnistes ne font pas exception. À ce que l’on dit, leurs robes matérialisent l’essence de l’illusion. D’après les légendes, les robes les plus anciennes n’ont jamais deux fois la même apparence.$B$BJe vous donnerai une robe d’illusionniste, $N… mais vous devez d’abord mériter que la tribu vous révère ! Ramenez-moi un Parangon de puissance de Zul’Gurub !'),
(8072,'frFR','Khar’vaxal le Fêlé fut l’un des insensés les plus fameux qu’aient comptés les Zandalar. D’après la légende, lorsqu’il a affronté les ennemis de la tribu pour la première fois, Khar''vaxal s’est servi d’un mantelet tissé dans « l’étoffe de la folie ». Celui-ci dissimulait sa forme, mais aussi l’éclat de ses dagues jumelles. Les insensés d’aujourd’hui chérissent leurs mantelets comme signe de leur place dans la tribu.$B$BRamenez-moi le Parangon de puissance que je recherche, et vous aurez l’un de ces mantelets. Ainsi, vous pourrez tisser la démence de vos ennemis.'),
(8074,'frFR','Les augures connaissent le mojo des éléments. Ils s’en servent pour guider la tribu vers la gloire. Dans les jours sombres qui ont suivi l’éclatement de l’empire Gurubashi, nos augures nous ont conduits à l’abri dans les mers du Sud. Et puis ils nous ont ramenés ici, dans la vallée, tout près du mal qui grandit au cœur de Zul’Gurub.$B$BFaites-moi offrande d''un Parangon de puissance de Zul’Gurub, et prouvez-nous votre valeur. Si vous y parvenez, je vous donnerai une ceinture d’augure contenant un puissant mojo !'),
(8075,'frFR','Tous les augures des Zandalar portent une pièce d’amure caractéristique, un haubert. Il est orné des plus belles soieries imaginables, mais il est fait de solides chaînes. C’est un symbole de leur contact avec le divin… et de leur autorité. Il n’est jamais sage de contrarier ceux qui ont voué leur vie au contact avec les esprits…$B$BRamenez-moi en offrande un Parangon de puissance de Zul’Gurub, et prouvez-nous votre valeur. Si vous y parvenez, je vous donnerai l’un de nos plus beaux hauberts, digne des plus grands augures !'),
(8080,'frFR','Une guerre se fait avec des soldats - tous les soldats pourront vous le confirmer. Ils vous diront aussi que livrer bataille l’estomac vide, avec un mauvais équipement, est une garantie de défaite !$B$BC’est pour cette raison que le bassin d’Arathi est si important. Certains endroits clés de cette région contiennent des ressources essentielles. Des métaux, des armes, de la nourriture, du bois… Tout ce dont nous avons besoin se trouve là-bas !$B$BVoici ce que je veux que vous fassiez, $N. Entrez dans le bassin d’Arathi, remportez la bataille en contrôlant plus de bases que l’ennemi, et revenez me voir avec une caisse de ressources.'),
(8105,'frFR','La bataille pour le bassin d’Arathi est un combat pour les ressources et les terres, $N. Les points clés de la région doivent être protégés et maintenus en état de fonctionner pour qu’ils continuent à fournir à nos troupes les matériaux bruts et les approvisionnements qui leur sont si nécessaires Je vous charge d’attaquer les points les plus éloignés de notre base du bassin d’Arathi.$B$BAttaquez la ferme, la mine, la scierie et la forge quand elles sont contrôlées par l’ennemi. Trouvez la bannière de l’adversaire et arrachez-là de son mât !$B$BQuand vous aurez réussi ces objectifs pour ces quatre points clés, revenez me voir.'),
(8120,'frFR','Comme vous l’avez sûrement entendu, la Ligue d’Arathor envoie un grand nombre de troupes dans le bassin d’Arathi. Avides de nourriture et de matières premières, ces fous de l’Alliance ont l’intention de prendre et de contrôler les riches ressources de cette région. Nous devons leur montrer qu’Arathi ne sera plus jamais le foyer de pitoyables humains !$B$BAllez dans le bassin d’Arathi et attaquez la mine, la scierie, la forge et l’écurie. Mettez à bas la bannière de l’ennemi, et emparez-vous de ces territoires pour la Horde.$B$BAllez, $N. Revenez me voir quand vous aurez accompli votre tâche.'),
(8121,'frFR','Alors que les combats pour le bassin d’Arathi font rage, le récit de vos exploits est parvenu à de nombreuses oreilles, $N. Vous êtes très bien $Gconsidéré:considérée; dans nos rangs, et je suis certain que vous réussirez la mission que je vais vous confier.$B$BIl est temps d’envoyer un message à la Ligue d’Arathor. Nous devons leur démontrer que leurs installations dans le bassin d’Arathi sont précaires, et qu’ils peuvent les perdre rapidement. Et nous allons le faire en prenant le contrôle, d’un coup, de quatre points stratégiques du bassin d’Arathi.$B$BSi vous réussissez cette mission, $N, vous acquerrez un grand respect chez les Profanateurs.'),
(8122,'frFR','Il est difficile de se rendre compte de la situation, tant le conflit est intense. Mais nos espions nous ont signalé un certain affaiblissement de la détermination de la Ligue d’Arathor. Nous devons profiter de cette opportunité et lancer une attaque brutale ! Retournez dans le bassin d’Arathi et chargez nos ennemis. Maudissez-les, tuez-les, et contrôlez les cinq bases stratégiques ! Que sous vos coups leurs soldats ensanglantés s’enfuient du front en hurlant, pour répandre partout l’histoire de votre cruauté.$B$BAllez, et remportez une grande victoire pour les Profanateurs !'),
(8154,'frFR','Une guerre se fait avec des soldats - tous les soldats pourront vous le confirmer. Ils vous diront aussi que livrer bataille l’estomac vide, avec un mauvais équipement, est une garantie de défaite !$B$BC’est pour cette raison que le bassin d’Arathi est si important. Certains endroits clés de cette région contiennent des ressources essentielles. Des métaux, des armes, de la nourriture, du bois… Tout ce dont nous avons besoin se trouve là-bas !$B$BVoici ce que je veux que vous fassiez, $N. Entrez dans le bassin d’Arathi, remportez la bataille en contrôlant plus de bases que l’ennemi, et revenez me voir avec une caisse de ressources.'),
(8155,'frFR','Une guerre se fait avec des soldats - tous les soldats pourront vous le confirmer. Ils vous diront aussi que livrer bataille l’estomac vide, avec un mauvais équipement, est une garantie de défaite !$B$BC’est pour cette raison que le bassin d’Arathi est si important. Certains endroits clés de cette région contiennent des ressources essentielles. Des métaux, des armes, de la nourriture, du bois… Tout ce dont nous avons besoin se trouve là-bas !$B$BVoici ce que je veux que vous fassiez, $N. Entrez dans le bassin d’Arathi, remportez la bataille en contrôlant plus de bases que l’ennemi, et revenez me voir avec une caisse de ressources.'),
(8156,'frFR','Une guerre se fait avec des soldats - tous les soldats pourront vous le confirmer. Ils vous diront aussi que livrer bataille l’estomac vide, avec un mauvais équipement, est une garantie de défaite !$B$BC’est pour cette raison que le bassin d’Arathi est si important. Certains endroits clés de cette région contiennent des ressources essentielles. Des métaux, des armes, de la nourriture, du bois… Tout ce dont nous avons besoin se trouve là-bas !$B$BVoici ce que je veux que vous fassiez, $N. Entrez dans le bassin d’Arathi, remportez la bataille en contrôlant plus de bases que l’ennemi, et revenez me voir avec une caisse de ressources.'),
(8166,'frFR','La bataille pour le bassin d’Arathi est un combat pour les ressources et les terres, $N. Les points clés de la région doivent être protégés et maintenus en état de fonctionner pour qu’ils continuent à fournir à nos troupes les matériaux bruts et les approvisionnements qui leur sont si nécessaires Je vous charge d’attaquer les points les plus éloignés de notre base du bassin d’Arathi.$B$BAttaquez la ferme, la mine, la scierie et la forge quand elles sont contrôlées par l’ennemi. Trouvez la bannière de l’adversaire et arrachez-là de son mât !$B$BQuand vous aurez réussi ces objectifs pour ces quatre points clés, revenez me voir.'),
(8167,'frFR','La bataille pour le bassin d’Arathi est un combat pour les ressources et les terres, $N. Les points clés de la région doivent être protégés et maintenus en état de fonctionner pour qu’ils continuent à fournir à nos troupes les matériaux bruts et les approvisionnements qui leur sont si nécessaires Je vous charge d’attaquer les points les plus éloignés de notre base du bassin d’Arathi.$B$BAttaquez la ferme, la mine, la scierie et la forge quand elles sont contrôlées par l’ennemi. Trouvez la bannière de l’adversaire et arrachez-là de son mât !$B$BQuand vous aurez réussi ces objectifs pour ces quatre points clés, revenez me voir.'),
(8168,'frFR','La bataille pour le bassin d’Arathi est un combat pour les ressources et les terres, $N. Les points clés de la région doivent être protégés et maintenus en état de fonctionner pour qu’ils continuent à fournir à nos troupes les matériaux bruts et les approvisionnements qui leur sont si nécessaires Je vous charge d’attaquer les points les plus éloignés de notre base du bassin d’Arathi.$B$BAttaquez la ferme, la mine, la scierie et la forge quand elles sont contrôlées par l’ennemi. Trouvez la bannière de l’adversaire et arrachez-là de son mât !$B$BQuand vous aurez réussi ces objectifs pour ces quatre points clés, revenez me voir.'),
(8169,'frFR','Comme vous l’avez sûrement entendu, la Ligue d’Arathor envoie un grand nombre de troupes dans le bassin d’Arathi. Avides de nourriture et de matières premières, ces fous de l’Alliance ont l’intention de prendre et de contrôler les riches ressources de cette région. Nous devons leur montrer qu’Arathi ne sera plus jamais le foyer de pitoyables humains !$B$BAllez dans le bassin d’Arathi et attaquez la mine, la scierie, la forge et l’écurie. Mettez à bas la bannière de l’ennemi, et emparez-vous de ces territoires pour la Horde.$B$BAllez, $N. Revenez me voir quand vous aurez accompli votre tâche.'),
(8170,'frFR','Comme vous l’avez sûrement entendu, la Ligue d’Arathor envoie un grand nombre de troupes dans le bassin d’Arathi. Avides de nourriture et de matières premières, ces fous de l’Alliance ont l’intention de prendre et de contrôler les riches ressources de cette région. Nous devons leur montrer qu’Arathi ne sera plus jamais le foyer de pitoyables humains !$B$BAllez dans le bassin d’Arathi et attaquez la mine, la scierie, la forge et l’écurie. Mettez à bas la bannière de l’ennemi, et emparez-vous de ces territoires pour la Horde.$B$BAllez, $N. Revenez me voir quand vous aurez accompli votre tâche.'),
(8171,'frFR','Comme vous l’avez sûrement entendu, la Ligue d’Arathor envoie un grand nombre de troupes dans le bassin d’Arathi. Avides de nourriture et de matières premières, ces fous de l’Alliance ont l’intention de prendre et de contrôler les riches ressources de cette région. Nous devons leur montrer qu’Arathi ne sera plus jamais le foyer de pitoyables humains !$B$BAllez dans le bassin d’Arathi et attaquez la mine, la scierie, la forge et l’écurie. Mettez à bas la bannière de l’ennemi, et emparez-vous de ces territoires pour la Horde.$B$BAllez, $N. Revenez me voir quand vous aurez accompli votre tâche.'),
(8181,'frFR','Les tablettes Mosh’aru contiennent de mauvaises nouvelles, $N. La véritable forme d’Hakkar, le dieu lui-même, peut renaître par l’intermédiaire de l’œuf dans lequel vous l’avez enfermé. Yeh’kinya vous avait dit que c’était pour contenir sa malfaisance, mais c’était pour la recréer ! Le troll s’est trompé – ou nous a trompés !$B$BRetournez voir Yeh’kinya et demandez-lui l’œuf. Espérons qu’il n’est pas trop tard pour empêcher Hakkar de revenir !'),
(8182,'frFR','$N, nos pires craintes se réalisent. Les légendes racontent que l’Écorcheur d’âmes régnait naguère sur les trolls par le mal et la terreur, et il exerçait un pouvoir sans partage. Si nous ne l’arrêtons pas maintenant, son royaume risque de s’étendre à tout Azeroth !$B$BLes envoyés des trolls zandalariens nous aideront peut-être à interrompre la montée des ténèbres. Ils se sont installés sur l''île de Yojamba, sur la côte de Strangleronce, à l’ouest des ruines de Zul’Kunda. Parlez à leur chef, Molthor, et prions pour qu’il sache comment vaincre Hakkar.'),
(8227,'frFR','Au milieu d’un tas de lignes et de moulinets se trouve un mètre ruban en soie, auquel est attaché une étiquette :$B$B« Nat Pagle, marécage d’Âprefange ».'),
(8251,'frFR','Les elfes de sang d’Azshara ont développé une méthode pour pulvériser les objets magiques qu’ils se procurent. La poussière lumineuse qu’ils produisent diffère des composants obtenus par les sorts de désenchantement normaux.$B$BLorsque j’ai envoyé mon apprenti pour qu’il négocie un peu de leur poussière, ils l’ont tué sans hésitation. Ils doivent payer pour cela.$B$BLe temps des discussions est révolu, $N. Trouvez les elfes de sang le long des falaises d’Azshara, et procurez-vous leur poussière lumineuse par des moyens plus « persuasifs ».'),
(8274,'frFR','Got some time to spare? Kill me some Murlocs and I''ll give you something shiny!'),
(8286,'frFR','L’étreinte de la mort avait presque achevé son œuvre lorsqu’il est intervenu. Il a soufflé sur mon corps ravagé, et il a attendu patiemment que les sables du temps nettoient mes blessures.$B$B« S’il le faut, vous resterez éternellement », a-t-il dit, et ces mots ont fait de moi un Guetteur.$B$BContemplez le désert. La deuxième guerre arrive. Vous devez trouver le lieu où reposent les dragons de bronze. Rendez-vous dans les grottes du Temps et voyez si le maître est revenu. Je dois m’en assurer avant de continuer.'),
(8287,'frFR','Bon, nous y sommes… une information sacrément intéressante, je dois dire. J’ai vu les forces du Cercle cénarien arriver en Silithus. Ils veulent chasser le Marteau du crépuscule, c’est ça ? Ceci les aidera.$B$BDonnez ce parchemin à leur chef, le commandant Mar’alith. Le Marteau du crépuscule sera vaincu, et j’échapperai à leurs griffes pour toujours !'),
(8288,'frFR','Nous n’avons pas de temps à perdre. Nous devons trouver un héros ! La tâche que je vais vous confier nécessite une armée, mais de la foule des aspirants, un seul se lèvera pour endosser le fardeau et la responsabilité qui pèsent sur les alliés de la Progéniture.$B$BUne bête cruelle vit dans le repaire du Seigneur de Blackrock. Le seigneur des couvées Lashlayer garde les Halls des conflits, bloquant le passage vers le sanctuaire de Nefarian. Tuez cette vile aberration et ramenez-moi sa tête. Si vous y parvenez, vous pourrez progresser vers l’étape suivante de votre voyage.'),
(8294,'frFR','La sauvagerie de la forêt d''Ashenvale succombera devant la puissance de la Horde, $R. Aile-argent ne pourra rien dire ou faire pour arrêter nos obligations souveraines. Kalimdor appartient à la Horde. Comment osent-ils tenter de nous empêcher de récolter ce qui nous appartient de droit !$B$BQue la fierté gonfle votre poitrine lorsque vous repousserez leurs futiles efforts pour ralentir notre progression. Détruisez les Sentinelles d''Aile-argent, et vous gagnerez une marque d''honneur Warsong. Revenez me voir avec l''une de ces marques, $N, et je vous récompenserai.'),
(8295,'frFR','La sauvagerie de la forêt d''Ashenvale succombera devant la puissance de la Horde, $R. Aile-argent ne pourra rien dire ou faire pour arrêter nos obligations souveraines. Kalimdor appartient à la Horde. Comment osent-ils tenter de nous empêcher de récolter ce qui nous appartient de droit !$B$BQue la fierté gonfle votre poitrine lorsque vous repousserez leurs futiles efforts pour ralentir notre progression. Détruisez les Sentinelles d''Aile-argent, et vous gagnerez une marque d''honneur Warsong. Revenez me voir avec l''une de ces marques, $N, et je vous récompenserai.'),
(8297,'frFR','Une guerre se fait avec des soldats - tous les soldats pourront vous le confirmer. Ils vous diront aussi que livrer bataille l’estomac vide, avec un mauvais équipement, est une garantie de défaite !$B$BC’est pour cette raison que le bassin d’Arathi est si important. Certains endroits clés de cette région contiennent des ressources essentielles. Des métaux, des armes, de la nourriture, du bois… Tout ce dont nous avons besoin se trouve là-bas !$B$BVoici ce que je veux que vous fassiez, $N. Entrez dans le bassin d’Arathi, remportez la bataille en contrôlant plus de bases que l’ennemi, et revenez me voir avec une caisse de ressources.'),
(8302,'frFR','Choisissez vos adjoints avec soin, $Gmortel:mortelle;. À chaque fois que vous reviendrez en ayant achevé votre tâche, vous aurez le droit d’en choisir un nouveau.$B$BCela dit, j’ai besoin de davantage de morceaux de carapace. Ne perdez pas de temps !'),
(8307,'frFR','S’adapter à la vie du désert a été difficile, et c’est un euphémisme. Les arbres et les oiseaux d’Auberdine me manquent. Quant à la nourriture, dans cet environnement aride, nos choix sont considérablement limités. J’essaye d’apprendre à connaître les herbes du désert, mais elles sont si peu nombreuses !$B$BJ’ai vu que dans leur camp à l’ouest d’ici, les sectateurs du Marteau du crépuscule chassaient les vers des sables pour les manger. La chair de ces créatures est très amère, je ne sais vraiment pas comment ils la rendent mangeable. Si vous allez dans leur camp, gardez les yeux ouverts et faites-moi part de vos éventuelles découvertes.'),
(8308,'frFR','A ceux que cela intéresse,$B$BSi vous lisez ceci, je suis mort ou je ne tarderai pas à l’être, c’est difficile à dire. Presque toute l’équipe y est déjà passée.$B$BTrouvé des informations sur un titan. De grandes batailles entre lui et un Dieu très ancien. Oui, un authentique Dieu très ancien. Trouvé d’antiques tunnels allant vers Ahn’Qiraj. Je les ai pris.$B$BApportez cette lettre à mon ancien camp. Veillez à ce que mon singe ait à manger, à boire, et des câlins.$B$BBrann Bronzebeard, explorateur de l’extrême.$B$BPS : Faites gaffe à l’elfe de la nuit folle qui adore le Dieu très ancien.'),
(8310,'frFR','Je pense être en mesure de préparer un élixir qui vous permettrait de déchiffrer plus facilement les glyphes, ainsi que le langage des silithides et des Qiraji. Ce qu’il me faut ? Bonne question ! Des cerveaux ! Plus précisément, un cerveau pris sur les sous-espèces de silithide de chaque ruche. Si vous me les rapportez, Rutgar n’aura pas travaillé en vain.'),
(8311,'frFR','J’aimerais bien faire la tournée des bonbons et des blagues, mais je ne peux pas, car je suis malade. Si vous voulez y aller pour moi, je vous échangerai les bonbons que vous gagnerez contre celui que j’ai déjà ! Je pense que vous l’aimerez beaucoup - il vous transforme en des trucs rigolos et effrayants !$B$BTous les aubergistes dans les grandes villes ont des bonbons qu’ils donnent pour la Sanssaint. Parlez-leur et faites les blagues qu’ils vous demanderont ! Ah, et il y a aussi un petit gnome nommé Talvash à Ironforge qui donne des bonbons. Quand vous aurez tous les bonbons, rapportez-les-moi ici !'),
(8312,'frFR','J’aimerais bien faire la tournée des bonbons et des blagues, mais je ne peux pas, car je suis malade. Si vous voulez y aller pour moi, je vous échangerai les bonbons que vous gagnerez contre ceux que j’ai déjà ! Je pense que vous les aimerez beaucoup - ils vous transforment en des trucs rigolos et effrayants !$B$BTous les aubergistes dans les grandes villes ont des bonbons qu’ils donnent pour la Sanssaint. Parlez-leur et faites les blagues qu’ils vous demanderont ! Ah, et il y a aussi une trollesse qui s''appelle Kali Remik au village de Sen''jin qui donne des bonbons. Quand vous aurez tous les bonbons, rapportez-les-moi ici !'),
(8314,'frFR','Nous sommes sur le point de faire une grande découverte, $N ! Vos reproductions nous ont permis de recréer les glyphes de ce prisme cristallin. Apparemment, les Qiraji, et d’autres entités inconnues, s’en servaient pour transmettre des messages aux silithides.$B$BMalheureusement, c’est tout ce que nous en avons tiré. Nous devons trouver un moyen d’accéder aux messages que renferme le cristal.$B$BPrenez le Prisme cristallin orné de glyphes et amenez-le à la géologue Larksbane au Fort cénarien. Elle pourra peut-être vous aider.'),
(8318,'frFR','Certains sectateurs du Marteau du crépuscule transportent des bouts de papiers couverts de gribouillis incompréhensibles. Je veux que vous m’en rameniez une pile, $C !$B$BJe suis incapable de les déchiffrer, mais ce n’est pas la question ! Leurs différents groupes s’en servent pour communiquer secrètement. Plus nous en retirons de la circulation, moins ils pourront communiquer !'),
(8320,'frFR','Le Marteau du crépuscule, un culte de fous avides de destruction, a installé des camps en Silithus, et y accomplit des rituels jour et nuit. Nous ne connaissons pas encore leurs plans, mais nous pensons qu’ils doivent être liés d’une manière ou d’une autre aux cristaux rouges qui pulsent dans le désert.$B$BMême si le mystère qu’ils représentent sera peut-être un jour résolu, nous devons d’abord nous préoccuper de la menace immédiate qu’ils représentent. Allez dans leurs camps à l''ouest et cherchez les géoseigneurs du crépuscule. Ce sont les chefs de ces serpents ; c’est eux que nous devons frapper !'),
(8321,'frFR','Nous avons découvert une autre base du Marteau du crépuscule. Elle s’appelle le Défilé du crépuscule ; c’est une caverne nichée dans le coin nord-est de Silithus. Le dirigeant local du culte, Vyral le Vil, la hante - c’est lui que vous devez vaincre, maintenant. Quand vous aurez réussi, apportez-moi sa chevalière.$B$BQue la fortune vous accompagne, $N. Et n’oubliez pas : les horreurs du Défilé du crépuscule sont redoutables !'),
(8322,'frFR','Les humains de Southshore adorent la bière, et tout particulièrement celle qui est servie à l’auberge de Southshore. Nous pouvons profiter du chaos provoqué par la Sanssaint pour gâter leur dernière cuvée de boissons pour des semaines… voire des mois !$B$BPrenez ces œufs pourris et allez les placer dans le tonneau de bière principal de l’auberge de Southshore. Votre simple présence déclenchera des combats, alors attendez-vous à vous battre !$B$BQuand vous aurez laissé à Southshore un goût qu’ils ne risquent pas d’oublier, revenez me voir ici, à la fête !'),
(8341,'frFR','Les seigneurs du Conseil abyssal ne peuvent être invoqués qu’en utilisant les pierres des vents supérieures, et seuls les plus hauts dirigeants du Conseil du crépuscule peuvent leur parler. Mais… j’ai trouvé un moyen d’améliorer votre déguisement et de tromper les seigneurs abyssaux !$B$BVous aurez besoin pour cela d’un anneau d’autorité, qui n’est porté que par les plus grands membres du culte. Je vous en fabriquerai un si vous m’apportez de grands éclats brillants et des chevalières abyssales.'),
(8348,'frFR','Huum m’a dit que vous avez trouvé comment invoquer les ducs abyssaux ? C’est un sacré succès !$B$BVous savez ce qui serait un succès encore plus grand ? En coincer un et lui botter les fesses très, très fort. Ça impressionnerait beaucoup ses subordonnés, si vous voyez ce que je veux dire. Ramenez-moi sa chevalière comme preuve de votre succès.'),
(8353,'frFR','Ah, vous faites les blagues de la Sanssaint pour un enfant malade, c’est cela ? Je me disais aussi, vous êtes un peu $Gvieux:vieille; pour quémander des bonbons…$B$BEh bien, pour que je vous donne un bonbon - un véritable bonbon à la menthe d’Ironforge - vous devrez… caqueter comme un poulet ! Oui, oui, les poulets adorent les bonbons à la menthe… Bon, d’accord, peut-être qu’ils ne les ADORENT pas… mais je ne vous en donnerai pas si vous n’imitez pas le poulet pour moi !$B$BAlors, $C, vous êtes $Gprêt:prête; à relever le défi ? C’est le moment de gagner votre bonbon !'),
(8354,'frFR','Ah, vous faites les blagues de la Sanssaint pour une petite fille malade, c’est cela ? Je me disais aussi, vous êtes un peu $Gvieux:vieille; pour quémander des bonbons…$B$BEh bien, pour que je vous donne un bonbon - un véritable bonbon à la menthe d’Undercity - vous devrez… caqueter comme un poulet ! Oui, oui, les poulets adorent les bonbons à la menthe… Bon, d’accord, peut-être qu’ils ne les ADORENT pas… mais je ne vous en donnerai pas si vous n’imitez pas le poulet pour moi !$B$BAlors, $C, vous êtes $Gprêt:prête; à relever le défi ? C’est le moment de gagner votre bonbon !'),
(8355,'frFR','$GUn quémandeur:une quémandeuse; de bonbons ! Hourra !$B$BBon, même si vous faites quelque chose de noble en récupérant des bonbons pour un enfant malade, je ne peux pas vous laisser vous en sortir si facilement. J’ai une délicieuse boule de gomme de Gnomeregan pour le gamin, que je vous donnerai si… vous imitez le bruit du train pour moi ! Haha, oui, c’est une bonne blague ! Le prix de cette boule de gomme est d’imiter le train ! Tchou-tchou, $C !'),
(8356,'frFR','C’est un costume très... intéressant, que vous avez là, dites-moi. Même si vous vous montrez sympa et que vous aidez cette année un enfant malade à faire ses blagues de la Sanssaint, j’ai bien peur d’être obligée de vous demander d’accomplir un petit tour pour moi !$B$BVoyons… Vous semblez si $Gfort:forte; et si $Gmis:mise; en valeur dans ce… costume… Faites donc un peu jouer vos muscles ! Allez, ne soyez pas timide, frimez un peu pour moi, jeune $Ghomme:femme; !$B$BQuand je vous aurai vu bander vos muscles, je vous donnerai de cet excellent nougat de Stormwind. C’est un fameux bonbon de la Sanssaint.'),
(8357,'frFR','Même si vous faites la tournée de la Sanssaint pour un enfant malade, vous devez quand même faire un petit tour pour obtenir un bonbon ! Nous ne pouvons pas déroger aux traditions, n’est-ce pas ?$B$BJe crois que le prix d’un morceau de massepain aujourd’hui est de se remuer un peu et de DANSER ! C’est ça, voyons donc vos pas de danse ! Dansez pour moi, et je vous donnerai un excellent massepain !'),
(8358,'frFR','$GUn quémandeur:Une quémandeuse; de bonbons ! Cool, $Gl''ami:l''amie; !$B$BBon, même si vous faites quelque chose de noble en récupérant des bonbons pour une petite fille malade, je ne peux pas vous laisser vous en sortir si facilement. J’ai une délicieuse boule de gomme de Darkspear pour la gamine, que je vous donnerai si… vous imitez le bruit du train pour moi ! Haha, oui, c’est une bonne blague ! Le prix de cette boule de gomme est d’imiter le train ! Tchou-tchou, $C !'),
(8359,'frFR','C’est un costume très... intéressant, que vous avez là, dites-moi. Même si vous vous montrez sympa et que vous aidez cette année une petite fille malade à faire ses blagues de la Sanssaint, j’ai bien peur d’être obligée de vous demander d’accomplir un petit tour pour moi !$B$BVoyons… Vous semblez si $Gfort:forte; et si $Gmis:mise; en valeur dans ce… costume… Faites donc un peu jouer vos muscles ! Allez, ne soyez pas timide, frimez un peu pour moi, jeune $Ghomme:femme; !$B$BQuand je vous aurai vu bander vos muscles, je vous donnerai de cet excellent nougat d''Orgrimmar. C’est un fameux bonbon de la Sanssaint.'),
(8360,'frFR','Même si vous faites la tournée de la Sanssaint pour une petite fille malade, vous devez quand même faire un petit tour pour obtenir un bonbon ! Nous ne pouvons pas déroger aux traditions, n’est-ce pas ?$B$BJe crois que le prix d’un morceau de massepain aujourd’hui est de se remuer un peu et de DANSER ! C’est ça, voyons donc vos pas de danse ! Dansez pour moi, et je vous donnerai un excellent massepain !'),
(8361,'frFR','Nous avons vu les sectateurs du Marteau du crépuscule invoquer de puissants nobles élémentaires. Nous ne savons pas si ce sont les créatures qu’ils adorent, ou si elles servent juste d’intermédiaires pour des forces plus redoutables. En revanche, nous sommes certains que ce sont ces élémentaires qui leur donnent des ordres.$B$BJe veux que vous trouviez un moyen de contacter un Templier abyssal… et que vous lui cassiez ce qui lui tient lieu de figure ! Si vous voulez désorganiser des soldats, rien de tel que de s’en prendre à leur structure de commandement. Quand ce sera fait, n’oubliez pas de me ramener une preuve.'),
(8365,'frFR','C’est vous, l’aide que nous envoie le Cartel ? Bon, je suppose que vous ferez l’affaire. Écoutez-moi attentivement, $C. Comme vous le savez, je suis la pourvoyeuse des plus belles tenues de l’élite de la société azérothienne. Les rois et les reines, les chefs de guerre et… euh, quel que soit le nom que la Horde donne à ses reines..., tous portent ce que je juge être à la pointe de la mode. Et ils payent rubis sur l’ongle, ce qui n’est pas pour me déplaire.$B$BVoilà ce qui va se passer. Vous allez vous rendre à la crique des Gréements et vous procurer plein de chapeaux de pirate, par tous les moyens à votre disposition. Vous pensez que vous y arriverez ?'),
(8366,'frFR','Argh ! Mais ils veulent l’impossible !$B$BLe cartel Gentepression veut que je donne une leçon aux pirates des Mers du sud. Le problème est que je ne peux pas être à deux endroits à la fois ; je dois rester ici pour maintenir la paix.$B$BCes derniers temps, les pirates se moquent complètement de l’argent des rackets que le cartel engrange régulièrement. J’aimerais donc vous déléguer provisoirement là-bas, pour que vous leur fassiez entendre raison.$B$BVous les trouverez à la crique des Gréements, qui se trouve non loin d’ici, au sud. Merci, $N, je vous devrai une faveur !'),
(8367,'frFR','Servir la Horde dans les grandes batailles contre l’Alliance est la source d’un grand honneur ! Cependant, les rares combattants qui ont servi la Horde sur TOUS les fronts actifs sont véritablement nos plus grands guerriers. Nous vaincrons nos adversaires, non en nous engageant dans des escarmouches isolées, mais en menant une guerre bien coordonnée.$B$BAllez au combat, et écrasez l’Alliance dans le bassin d’Arathi, la vallée d’Alterac et le goulet des Warsong ! Pour l’honneur ! Pour la Horde !'),
(8368,'frFR','La bataille dans le goulet des Warsong contre les Sentinelles d’Aile-argent est d’une grande importance. Sous le prétexte de protéger une forêt qui ne lui appartient pas, l’Alliance cherche à refuser à la Horde l’une de ses plus grandes ressources en bois.$B$BNe la laissez pas faire, $N ! Revenez me voir quand vous aurez la preuve que vous avez bien servi la Horde !'),
(8369,'frFR','Écoutez, $N. Malgré tout ce que vous avez pu entendre sur la bataille qui fait rage dans la vallée d’Alterac, une chose reste vraie : l’expédition Stormpike a envahi le territoire des Frostwolf ! Le jour où nous permettrons à l’Alliance d’envahir les terres de la Horde sans réagir énergiquement est le jour où je raccrocherai ma hache et où je passerai le reste de ma vie dans la honte. Allez combattre, et chassez les envahisseurs !'),
(8370,'frFR','Notre conflit contre l’Alliance est devenu une véritable guerre. Plus personne n’a besoin de faux prétextes pour aller au combat, ni l’Alliance, ni la Horde.$B$BLa bataille pour le bassin d’Arathi est une guerre économique, ni plus ni moins. Soit l’Alliance obtient ces ressources et les utilise contre nous, soit nous nous en emparons pour soutenir notre effort de guerre. Aidez les Profanateurs à assurer notre approvisionnement, $N !'),
(8371,'frFR','Nous ne menons plus des combats isolés contre la Horde, jeune $Ghomme:fille;. La victoire sur un front signifie que nous enlevons à notre adversaire les ressources qu’il utiliserait contre nous dans une autre bataille. De la même façon, perdre un engagement pourrait donner l’avantage à la Horde en un autre point du monde.$B$BL’Alliance a besoin de combattants ayant compris cette vérité… De vrais vétérans expérimentés ! $N, revenez me voir quand vous aurez combattu la Horde sur tous les champs de bataille.'),
(8372,'frFR','Les sentinelles d’Aile-argent sont en guerre contre les voltigeurs Warsong, à cause des destructions perpétrées par les orcs. Cependant, nous avons d’autres raisons pour défendre tout particulièrement cette forêt que le simple amour de la nature.$B$BLa forêt constitue une barrière stratégique qui protège Ashenvale contre une attaque à grande échelle. Sans elle, Astranaar serait annexée aux Tarides en moins de deux jours.$B$BFaites votre part dans le combat contre les voltigeurs Warsong, $N ! Pour l’Alliance !'),
(8374,'frFR','Pour gagner une guerre, il ne suffit pas de battre l’adversaire, ou de déjouer ses ruses. Souvent, la victoire est remportée tout simplement en produisant plus de ressources que l’ennemi.$B$BLe bassin d’Arathi n’est ni plus ni moins qu’un océan de ressources potentielles pour le camp qui parviendra à s’en emparer le premier.$B$BSi l’Alliance l’emporte, cela signifie que nous aurons plus d’épées et de piques pour nos troupes. Si c’est la Horde qui gagne, ces épées et ces piques seront tout de même fabriquées, mais elles seront pointées sur nous ! Il est temps, maintenant, d’aider l’Alliance dans le bassin d’Arathi, $N.'),
(8375,'frFR','Ne vous trompez pas, $N. La Horde a parfaitement raison quand elle dit que la vallée d’Alterac est un territoire frostwolf. Vous voyez, l’expédition Stormpike est venue dans la région pour une visite pacifique, pour chercher du minerai et des reliques. Les Frostwolf ont réagi par l’acte d’agression le plus brutal et le plus barbare que l’Alliance ait jamais connu.$B$BN’oublions jamais les nains courageux qui ont péri dans cette attaque lâche et traîtresse. Allez, $C, faites votre part dans la bataille d’Alterac. Pour l’Alliance !'),
(8393,'frFR','Pour gagner une guerre, il ne suffit pas de battre l’adversaire, ou de déjouer ses ruses. Souvent, la victoire est remportée tout simplement en produisant plus de ressources que l’ennemi.$B$BLe bassin d’Arathi n’est ni plus ni moins qu’un océan de ressources potentielles pour le camp qui parviendra à s’en emparer le premier.$B$BSi l’Alliance l’emporte, cela signifie que nous aurons plus d’épées et de piques pour nos troupes. Si c’est la Horde qui gagne, ces épées et ces piques seront tout de même fabriquées, mais elles seront pointées sur nous ! Il est temps, maintenant, d’aider l’Alliance dans le bassin d’Arathi, $N.'),
(8394,'frFR','Pour gagner une guerre, il ne suffit pas de battre l’adversaire, ou de déjouer ses ruses. Souvent, la victoire est remportée tout simplement en produisant plus de ressources que l’ennemi.$B$BLe bassin d’Arathi n’est ni plus ni moins qu’un océan de ressources potentielles pour le camp qui parviendra à s’en emparer le premier.$B$BSi l’Alliance l’emporte, cela signifie que nous aurons plus d’épées et de piques pour nos troupes. Si c’est la Horde qui gagne, ces épées et ces piques seront tout de même fabriquées, mais elles seront pointées sur nous ! Il est temps, maintenant, d’aider l’Alliance dans le bassin d’Arathi, $N.'),
